<#
========================================================================
 원격지원 툴킷  v3.6.20 - 실측 기반
 v3.6.20: (2026-10-14) 메뉴4 확장 목록이 McAfee WebAdvisor 를 '지워야 할 것'으로 짚어주지 못했다.
       (2026-10-14 일일 제거 건 - 프로그램 추가/제거에서 WebAdvisor 본체를 지워도 크롬 확장은 따로 남는다.)
       메뉴1 은 레지스트리 기반이라 확장을 아예 못 본다 → 메뉴4 에 이름 패턴 그물($RemoveExtPatterns)을 넣는다.
       [1] 백신·보안모듈·쇼핑/쿠폰·툴바·VPN·광고차단 확장에 ★제거 표시 + 표 아래에 제거 권장 목록 따로 출력.
       [2] '브라우저기본'(location 5/10)으로 분류돼도 ★제거 로 걸리면 목록에서 빼지 않는다.
       [3] 표시만 한다. 스크립트가 확장 폴더를 지우지는 않는다(크롬 '손상된 확장' 경고 - 미검증).
 v3.6.19: (2026-10-07) 교사 PC 첫 실측(화상수업앱 마이크 건)에서 나온 메뉴10 표시 문제 3건.
       [1] 녹음 볼륨 30% 가 경고에 안 걸렸다(기준 10% 미만). 가이드 p.24 는 80 이상으로 테스트하게 한다
         → [1-1] 녹음 장치 80% 미만을 노란색 표시, [6] 마이크 판정에도 한 줄. 재생 볼륨 기준은 그대로.
       [2] 내장 웹캠이 장치 관리자 [사용 안 함](코드 22)인데 [3] '물리 문제'·[6] '카메라 미연결'로 나왔다
         → 코드 22 는 [2] 에 '사용 안 함'으로 표시하고 [3] 오류 목록에서 뺀다. [6] 에 '사용 안 함' 판정 추가
           (선생님이 일부러 꺼 둔 것일 수 있어 확인 후 [장치 사용] 안내 - 자동으로 켜지 않는다).
       [3] PRISM Lens 같은 DirectShow 가상카메라가 메뉴10 에 안 보였다(메뉴6 에만 있음)
         → [2-1] 신설: 이름만 나열(소유 프로그램·해제는 메뉴6). 실제 카메라 없이 가상카메라만 있으면
           [6] 이 '웹캠 꽂혀 있는지' 대신 '가상카메라만 있음 - 선생님이 쓰는 카메라 확인'으로 안내.
 v3.6.18: (2026-10-06) 메뉴10 [1-2] 첫 Windows 실측(담당자 PC) 오판 수정.
       실측: mmsys.cpl 녹음 탭에서 Stereo Mix 가 [사용 안 함]인데 [1-2] 가 [사용]으로 세어 '녹음 장치 2개' 경고.
         원인: 레지스트리 DeviceState 하위 4비트만 봤다. 사용 안 함 장치는 0x10000001 처럼 하위 비트가 1(ACTIVE)로
         남고 상위 비트로 표시되는 것으로 보인다(가정 - 같은 실행의 [1] PnP 목록에는 Stereo Mix 가 아예 없었다).
         → [1] 과 같은 근거(Get-PnpDevice AudioEndpoint, Status OK)로 센다. 녹음 쪽은 InstanceId 가
           SWD\MMDEVAPI\{0.0.1.* 인 것. PnP 조회가 실패할 때만 레지스트리 DeviceState = 정확히 1 로 대체.
 v3.6.17: (2026-10-06) 외부 QA 3차(v3.6.16 대상) 반영.
       [H] Stop-TargetBrowser 가 종료 실패를 숨기고 $true 를 돌려줘 캐시·설정 정리로 넘어갔다(모의 재현)
         → 종료 후 최대 5초 동안 선생님 세션에 남은 프로세스를 다시 보고, 남아 있으면 $false.
         호출부(메뉴5 정리 / 업데이트 재시작)는 기존대로 $false 면 수동 종료 안내 → 재확인 → 남으면 중단.
 v3.6.16: (2026-10-06) 외부 QA 재검수(v3.6.15 대상) 반영.
       [H] 세션 식별 실패 시 모든 세션의 브라우저를 닫던 대체 동작 제거 → 종료하지 않고 선생님 화면에서
         직접 닫게 한 뒤 다시 확인. 업데이트 재시작 경로도 같은 함수로 바꿨다.
       [H] 메뉴10 권한: 레지스트리 조회 오류를 '값 없음'으로 처리해 정상 판정으로 이어질 수 있었다
         → 키 없음(설정 안 됨)과 조회 오류를 구분, 오류는 미검증 목록에 넣는다.
       [H] [5-1] 브라우저 마이크: Preferences 를 하나도 못 읽어도 '검사 완료'로 쳐서 '브라우저 차단 없음'을 띄웠다
         → 읽기에 성공하고 실패가 없을 때만 검사 완료.
       [M] 확장 관리(메뉴4)·강의채널 자동 HTTPS(메뉴11) 화면도 Open-BrowserPage 로 통일(계정 불일치 시 대신 안 엶).
       유지(재검수 지적): 엣지 업데이트 로그는 스로틀 줄보다 과거 서버 응답을 고른다. 스로틀 줄에는 서버 버전이
         없어서 그걸 고르면 유일한 버전 정보를 버리게 된다. v3.6.15 의 48시간 기준이 '오래된 응답으로 최신 단정'을
         막으므로 판독 순서는 그대로 둔다.
       유지(결정): 전역 팝업 허용 - 선생님들이 LMS 외 다른 사이트도 써야 해서 전역 허용이 맞다(2026-10-06 결정).
         v3.6.12 부터 '효과 확인 후 별도 결정'으로 남아 있던 항목을 이것으로 종결.
 v3.6.15: (2026-10-06) 외부 QA/QC(v3.6.14 배포본 대상) 반영. 지적 8건 중 7건 수정, 1건(전역 팝업) 기존 결정 유지.
       [H] 메뉴18 회선 구간: 공유기 무응답(none) + 외부 불량을 '공유기까지 정상 = 통신사 회선'으로 단정했다
         → 공유기 응답이 없으면 구간 판정 보류.
       [H] 메뉴10 카메라: 선생님 계정 레지스트리를 못 읽어 권한이 '미검증'인데도 Camera OK 면
         '장치·드라이버·권한 모두 정상'을 띄웠다 → 권한 미검증을 따로 표시. Deny 안내 문구도 카메라/마이크 구분.
         같은 유형이 v3.6.14 마이크 판정에도 있었다([5-1] 을 건너뛰어도 '브라우저 차단 없음') → 같이 수정.
       [H] 메뉴5 브라우저 종료가 프로세스 이름으로 모든 사용자 세션을 닫았다 → 선생님 세션만 종료
         (세션을 못 가리면 예전처럼 전체 + 안내). 계정 불일치일 때 브라우저를 대신 열면 관리자 프로필로
         열리므로 열지 않고 주소만 안내(클립보드 복사).
       [M] 메뉴5 업데이트: 로그의 마지막 서버 응답이 오래된 것이어도 '최신'으로 확정하고 대기를 건너뛰었다
         → 응답 시각이 48시간 넘었거나 시각을 못 읽으면 '최신' 단정 안 함(help 페이지 검사 대기).
         엣지 로그 시각 형식(MM/dd/yy)은 가정 - 못 읽으면 보수적으로 오래된 것으로 본다.
       [M] 메뉴2 제거: 명령에 GUID 만 있으면 exe 언인스톨러도 msiexec /X 로 바꿨다 → msiexec 명령일 때만.
       [M] 메뉴5 IE모드 정책: 기존 값을 덮어쓰고 복구는 삭제만 안내했다 → 변경 전 값을 읽어 복원 명령 출력.
       [M] Get-NativeText: 출력 읽기가 먼저 막혀 10초 제한이 안 먹었다 → 비동기 수집 + 시간 초과 시 종료.
       유지: 전역 팝업 허용(v3.6.12 부터 '효과 확인 후 별도 결정' 항목). 배포본 UTF-8 무BOM(Build-SingleFile 설계).
 v3.6.14: (2026-10-06) 원격 처리 현황 2025(377건)·2026(1~10월 191건) 처리내역 집계 반영 - 메뉴10 마이크 보강.
       근거: 2025 마이크 건 51건 중 32건(약 63%, 키워드 집계)이 '기본 마이크 변경 + 안 쓰는 마이크 [사용 안 함]'
         (웹캠 마이크·헤드셋 마이크가 같이 켜진 상태, 크롬 기본 마이크 변경 포함)으로 끝났다.
         원격지원가이드(20260629) p.19 경고와 같다: 여러 개를 [사용]으로 두면 화상수업앱 중 장치가 바뀐다.
         [1-1] 은 '기본 장치' 하나만 봐서 마이크가 2개 켜져 있어도 드러나지 않았다.
       [1-2] 신설: [사용] 상태 녹음 장치 목록·개수. 2개 이상이면 경고(조회만 - 사용 안 함 처리는 사람이 한다).
       [5-1] 신설: 크롬·엣지 마이크 기본값 차단 / lms 사이트 마이크 차단 / 브라우저가 고른 마이크 표시.
         메뉴5 는 lms 마이크 허용을 넣기만 하고 현재 상태를 보여주지 않았다(가이드 p.22 ②).
         브라우저가 고른 마이크 값(media.default_audio_capture_device)의 형식은 미검증 - 안 맞으면 '직접 확인'만 띄운다.
       [6] 판정에 마이크 줄 추가(카메라 판정과 별개). [7] 녹음 장치 2개 이상이면 mmsys.cpl 을 녹음 탭으로 연다.
       S1 요약에 마이크 줄 추가. 기존 동작(카메라 판정·음소거 해제 질문)은 그대로.
 v3.6.13: (2026-10-02) 외부 QA/QC 보고서(v3.6.12 대상) 반영.
       [H4 ★] 계정 불일치 시 HKCU 를 직접 읽던 곳 전부를 선생님 계정 하이브(HKEY_USERS\SID)로 교체.
         $script:TargetHKCU / Get-UserRegPath 신설. 하이브를 못 찾으면 $null → 각 메뉴가 '미검증' 표시.
         대상: 메뉴1·2 제거목록·보존목록, 메뉴6 DLL 소유자, 메뉴10 카메라/마이크 권한, 메뉴11 Agent,
         메뉴16 자동시작, 메뉴17 하이웍스 레지스트리. 계정이 다르면 선생님 '사용자별 설치' 프로그램은
         메뉴2 자동 제거에서 빼고 목록만 보여준다(승격 계정으로 남의 언인스톨러를 돌리지 않게).
       [H5] 카메라/마이크 권한: 값이 없는 키(NonPackaged 등)를 Deny 로 셌다 → 명시적 Deny 만 거부.
       [H6] 브라우저 Preferences 백업 Copy-Item 에 -ErrorAction Stop + 존재 확인. 백업 실패 시 원본을 안 건드린다.
       [H3] 네트워크 스택 리셋을 winsock reset + DNS 캐시 삭제로 좁혔다. int ip reset(고정 IP·DNS 초기화),
         winhttp reset proxy(업무망 프록시 삭제)는 LSP 잔재 대응에 근거가 없어 뺐다. 종료코드 확인.
       [H2] 메뉴6: 보안모듈(nProtect·TouchEn 등) 잔존 드라이버·서비스에 pnputil/sc delete 를 안내하던 것
         → '직접 삭제 금지, 프로그램 추가/제거로 정식 제거' 로 변경. 가상카메라 드라이버만 pnputil 안내 유지.
       [H1] 메뉴13 eISP: 삭제 전 Uninstall 레지스트리 키를 .reg 로 백업(reg import 로 되돌리기).
         자동 정리 자체는 유지 - eISP 는 언인스톨러가 없고, 폴더는 정확히 VP/eISP* 이름만 지운다(v3.6.2 F01).
       [M1] 메뉴2: 개별 제거 질문 전에 보안 프로세스를 일괄 종료했다 → 첫 'y' 에서 종료.
       [M4] 메뉴15: chkdsk 종료코드를 보고 기록(코드 3 이상이면 완료로 단정하지 않음).
       [M5] 메뉴9: '443 성공 → 네트워크 정상' 단정 완화. hosts/winsock 이상이 나왔는데도 '로컬 이상 없음'을
         찍던 것 수정. 메뉴18 '회선 품질 문제 없음' → ICMP 기준임을 명시.
       [M6] 메뉴8: 디스크 하위계층 이벤트를 Provider·ID 별 상위 5개로 보여주고 '근거 확인 후 메뉴15'로.
       [M7] 메뉴17: 로그 개인정보 경고를 로그 출력 '앞'으로.
       [L2] 메뉴5: 브라우저 선택에서 c/e 외 입력은 취소(엔터·오타가 Chrome 으로 처리되던 것).
       [L3] 세션 로그 파일명에 초·PID 추가(같은 분 재실행 시 로그 꺼짐 방지).
       [L4] 메뉴12: 시간 동기화 성공을 종료코드 우선으로 판정.
       [문구] 메모리 90% '스왑 발생' → '메모리 압박', TCP 30개 '1순위 원인' → '우선 확인 후보'.
       유지: M2 MAC 변경 안내(2026-07 CRM 공인IP 차단 실사례 기반, 안내만 하고 실행 안 함),
         M3 IE 모드 정책·업데이트 서비스(교사 개인 PC 대상, 질문 후 적용),
         M8 배포본 UTF-8(Build-SingleFile 설계), L1 '<# :' 헤더(배치 파일 안에서는 레이블로 처리되는
         알려진 폴리글롯 방식 - cmd /c 단독 실행 테스트와 다르다).
 v3.6.12: (2026-10-02) 외부 코드 리뷰(v3.6.7 대상) 지적 중 v3.6.11 에도 남아 있던 것 수정.
       [메뉴15 ★] chkdsk 에 'echo Y' 를 항상 붙였다. 시스템 드라이브는 '다음 부팅 때 예약?' 에 Y 라
         맞지만, 그 외 드라이브는 같은 Y 가 '지금 강제 분리(dismount)?' 의 답이 된다 → 열린 파일 핸들이
         끊겨 저장 안 된 작업이 날아갈 수 있다. 시스템 드라이브만 자동 Y, 나머지는 질문을 보고 직접 답한다.
       [메뉴1·2 ★] 계정 불일치(승격 계정 ≠ 선생님)인데도 HKCU 제거 목록을 읽었다. 그 HKCU 는 승격
         계정 것이라 선생님 것이 아닌 프로그램을 탐지·제거할 수 있었다 → 불일치면 HKCU 를 빼고 안내.
       [브라우저 실행파일] 승격 계정 %LOCALAPPDATA% 크롬을 선생님 사용자 설치본보다 먼저 찾았다
         → 선생님 쪽을 먼저 본다(승격 계정 크롬 업데이트 + 선생님 프로필 정리 혼합 처리 방지).
       [메뉴3] 보안센터 등록 서드파티 백신을 '켜짐' 여부 확인 없이 세서, 꺼진 백신만 있어도
         'Defender passive = 정상'으로 안내할 수 있었다 → productState 로 꺼짐이면 보호 중으로 안 센다
         (productState 해석은 널리 쓰이는 방식이나 MS 공식 문서 없음 - 가정).
       [메뉴8] SideBySide 오류를 시스템 파일 손상(→DISM)으로 셌다. 대개 개별 앱의 VC++ 런타임·
         매니페스트 문제라 따로 참고 표시. Get-PhysicalDisk 조회 실패를 '디스크 상태 정상'으로
         표시하던 것 → '조회 실패(미검증)'.
       [메뉴17] 설치본 '크기 일치'를 '검증 OK'로 표시 → '크기만 일치(해시 미검증)'.
         MessengerHistory.txt 는 업데이트 때 바뀌는 파일이라 ★핵심 파일 표시에서 뺐다.
       [메뉴9] 사설 대역 판정에 100.64.0.0/10(통신사 CGNAT) 추가 - 공인IP 직결로 오판해 MAC 변경을
         안내하지 않게.
       검토 후 유지: 설정 초기화(v3.6.8 부터 'reset' 입력해야만 실행 + 시각 백업 + 원복 명령 표시),
         네트워크 스택 리셋(v3.6.5 부터 LSP 잔재 확인 시에만 제안), 전역 팝업 허용(LMS 예외는 선택 등록
         - 전역 허용을 빼는 건 효과 확인 후 별도 결정), 배포본 UTF-8(무 BOM) - Build-SingleFile 설계대로
         (CP949 규칙은 구 2파일 방식 Run-Toolkit.bat 용. 배포본엔 CP949 에 없는 문자도 있다).
 v3.6.11: (2026-10-02) 강의채널 '스타플레이어를 구동하려면 설치 프로그램을 다운로드' 건 반영.
       원인: 강의 창이 http 로 열림. Agent(1.3.19.8)·버전 정상이었고 주소만 https 로 바꾸자 즉시 재생.
         CRM 서버는 첫 화면(/)만 https 로 보내고 강의 창 경로는 http 를 그대로 받는다(실측).
