         https 로 열린다(실측). 정책 HttpsUpgradesEnabled=1 은 스위치도 안 켰고 동작도 안 바꿨다(실측)
         → 정책을 쓰지 않고 설정 페이지를 열어 스위치를 직접 켜게 한다.
