           설치 목록에 이름이 안 보여 메뉴1 이 못 잡았다 → 프로세스로 본다. y 면 종료.
       [메뉴5] Edge 마지막 단계 [6] '자동 HTTPS 켜기' 설정 페이지 열기 추가.
       [메뉴5] [0] 정책 목록에서 포털 새 탭·홈 강제(zum.com) 값을 찾아 삭제 선택.
         실측: Edge\Recommended\NewTabPageLocation = http://zum.com/?af=gt (+ NewTabPageSetFeedType=0).
         알툴즈·알매니저가 남아 있으면 다시 써 넣을 수 있음(가정).
       [메뉴1] 패턴 '*알캡처*' / '*ALCapture*' 추가(설치 목록에 있을 때 대비).
