 v3.6.10: (2026-10-02) 메뉴18 첫 실전 투입(유아 화상수업 끊김 건)에서 나온 버그 수정 + 메모리 항목.
       [버그 ★] 실제 통신 경로를 잘못 골랐다. 교사 PC 는 USB 유선 랜으로 통신 중이었고 와이파이는
         '연결되어 있지 않음'이었는데, 메뉴18 [1] 이 와이파이를 경로로 표시했다(실측 - Find-NetRoute
