       [버그] netsh wlan 출력 한글이 깨졌다(UTF-8 바이트를 CP949 로 읽은 형태). 그래서 항목을 하나도
         못 읽었다. → 출력을 바이트로 받아 UTF-8(엄격) 실패 시 CP949 로 해석한다.
       [메뉴18] 경로가 유선이면 와이파이 어댑터 상태를 따로 보여주고 '이번 측정은 유선 기준'을 명시.
       [메뉴18] 메모리 항목 추가 - 총량·사용률·프로그램별 사용량 상위 5.
         같은 건 노트북이 RAM 4GB(Win11 최소)였는데 v3.6.9 는 메모리를 안 봐서 [확인 필요] 없음으로
         끝났다. 4GB 이하 또는 사용률 85% 이상이면 [확인 필요]에 올린다(기준은 가정).
         수업 부하에서 재야 의미가 있어, 시작 화면에 '화상수업앱 테스트방을 띄운 상태에서 실행' 안내 추가.
 v3.6.9: (2026-10-01) 화상수업 끊김·지연 진단 추가 (유아 화상수업 '화면 전달 느림·소리 끊김' 건).
       [메뉴18 신설] 화상수업 품질 진단 (조회 전용, 약 25초).
         연결 방식(유선/무선/테더링·VPN 동시 활성) / 와이파이 신호·대역·채널·링크 속도 /
         회선 구간(공유기까지 vs 외부까지 ping 40회씩 - 손실·평균·지터) /
         전원(배터리 구동·전원 구성표·Win11 전원 모드) / CPU(현재 부하·정격 대비 실제 성능·상위 5) /
         동기화 프로그램 실행 여부를 한 화면에 모으고, 캡처용 요약과 [확인 필요] 목록을 낸다.
         근거: 메뉴9 는 443 이 붙으면 '정상'으로 끝나서 '연결은 되는데 품질이 나쁜' 경우를 못 봤다.
         교사가 통신사 점검 '이상 없음' 후 통신사 변경을 예정한 상태였는데, 공유기까지 구간이
         나쁘면 통신사를 바꿔도 안 풀린다 → 그 구간을 가르는 것이 이 메뉴의 핵심이다.
       [S6 신설] 화상수업 끊김·지연 시나리오 = 메뉴18 → 메뉴16(업로드·자원 점유) → 메뉴10(소리).
       미검증: netsh wlan 위치 권한(Win11 24H2+), 전원 모드 GUID 대조, 성능% 카운터 - 첫 실사용 때 확인.

 v3.6.8: (2026-09-28) 화상수업앱 '학생 목소리 안 들림' 건과 브라우저 작업 메모 반영.
       [메뉴10] 기본 재생/녹음 장치의 '음소거·볼륨'을 Core Audio 로 직접 읽는다.
         실측: 재생 장치(Headphones) 자체가 음소거라 1차 수업부터 소리가 안 났는데, 기존 메뉴10 은
         장치 목록(OK)만 보여줘서 mmsys.cpl > 속성 > 수준 탭을 사람이 열어봐야 알 수 있었다.
         기본 장치가 무엇인지도 안 보여줘서 매번 재생 탭 캡처가 필요했다.
         → 기본 장치 이름 + 음소거 + 볼륨% 를 출력하고, 음소거면 y 로 해제한다.
       [메뉴1] [보존] 에 보험사 업무 프로그램 세트 추가(메리츠화재 XPLATFORM/TPLSvc/TNWLIB/
         OZWebAgent/MAWS_MERITZ/FSSADK, 정체 미확인 MatrixBrowser/MatrixGear).
         FSSADK(메리츠 DRM)는 이름에 Fasoo 가 없어 '*Fasoo*' 에도 안 걸렸다. 삭제 대상이 아니라
         교사의 다른 업무용이라 '탐지'가 아니라 '보존'에 넣는다(전부 제거 흐름에 휩쓸리지 않게).
       [메뉴5] y 연타 사고 방지 - 설정 초기화는 'reset' 을 입력해야만 실행한다.
         실측: 다른 질문이 전부 y=진행이라 y 를 이어 누르다 [권장 아님]인 초기화가 크롬·엣지 둘 다
         실행됐다. 초기화는 카메라·마이크 사이트 권한까지 날린다.
       [메뉴5] [*.]lms.example.com 사이트 권한 자동 등록(팝업·안전하지 않은 콘텐츠·카메라·마이크·소리·
         알림). 초기화 뒤에도 다시 넣는다. {setting:1} 최소 형식 인식 여부는 미검증 - 첫 사용 시 확인.
       [메뉴5] 시작 시 브라우저 정책(HKLM) 강제 항목 표시 - 정책으로 막힌 건 자동 정리로 안 풀린다.
       [메뉴5] 하드웨어 가속 끄기(강의채널 재생 불가용) - 'off' 입력 시에만. Local State 원문 치환.
       [메뉴5] 업데이트: help 페이지를 연 뒤 최대 120초 동안 새 버전 다운로드를 기다렸다가,
         교체 대기가 생기면 브라우저 종료 → 교체 → 재실행까지 한 번에 한다.
         기존엔 help 페이지만 열고 끝나서 [다시 시작] 클릭과 버전 재확인이 매번 수동이었다.

 v3.6.7: (2026-09-17) 배포본 화면 출력에 다른 선생님 실명이 남아 있던 것 제거.
       Build-SingleFile.ps1 이 '주석'은 전부 걷어내지만 Write-Host 문자열에 박아넣은
       실명은 못 걷는다. 메뉴17 을 만들면서 근거 사례를 화면 문구에 그대로 적었고,
       빌드 결과 .bat 에서 4곳이 선생님 PC 화면에 출력되는 상태였다(실측).
       → 화면 문구에서는 실명을 빼고 내용만 남긴다. 주석에는 남긴다(배포본에서 걷힌다).
       → 재발 방지: deploy-blocklist.txt 를 두고 빌드 검증이 배포본 전체를 훑어
         목록의 단어가 하나라도 남으면 빌드를 실패시킨다.

 v3.6.6: (2026-09-17) R9 - 지원 대상 계정 판별의 '부분 실패' 경로 수정.
       v3.6.5 에서 explorer 소유자를 전부 모으도록 고쳤지만, 개별 조회 실패를 빈 catch 로
       버렸다. 그래서 다른 사용자 조회만 성공하고 선생님 쪽 조회가 실패하면 owners 가
       1건이 되어 State='ok' 로 그 사람을 지원 대상으로 확정했다(메뉴5 가 남의 프로필 정리).
       같은 판에서 카메라 쪽(R2)은 probeFail 을 셌으면서 여기는 빠뜨린, 같은 유형의 실수다.
       → 열거 실패 / 개별 조회 실패 / GetOwner ReturnValue 비정상을 전부 추적한다.
         하나라도 실패하면 '전부 봤다'고 말할 수 없으므로 unknown 으로 내려 변경을 막는다.
         실패 사유를 배너에 출력한다. explorer 가 0개라 콘솔 세션 사용자로 대체한 경우도
         '추정'임을 화면에 남긴다(예전엔 조용히 ok 로 처리했다).
       [QC] 카메라 진단의 'WIA(Image) 클래스로 오등록됨' 단정 문구를 완화했다.
         Image 는 스캐너·디지털카메라의 정상 분류이기도 하다 - 사실만 적고 판단은 사람이 한다.

 v3.6.5: (2026-09-16) 재검토 리포트 R1~R8 전건 수정.
       [R1 P1] 지원 대상 계정 조회가 실패하면 $null 을 돌려줬고, 호출부가 그걸 '계정 일치'로
         처리해 변경 작업을 허용했다. explorer.exe 도 첫 번째 것만 봐서 빠른 사용자 전환 시
         엉뚱한 사용자를 대상으로 잡았다.
         → 상태를 5가지(same/mapped/noprofile/unknown/multi)로 나눈다.
           소유자를 전부 모아 unique 로 세고, 0명=unknown / 2명 이상=multi 로 구분한다.
           same·mapped 만 사용자별 '변경'을 허용하고 나머지는 메뉴5 진입을 막는다.
       [R2 P1] Image 클래스라는 이유만으로 오등록을 확정하고 제거 명령을 만들었다.
         Image 에는 정상 스캐너·디지털카메라가 들어간다. 경고만 띄우고 명령은 그대로 나갔다.
         공유 INF 조회도 개별 장치의 속성 조회 실패를 삼켜, 두 장치가 공유하는데 한쪽 조회가
         실패하면 '1개 확인 - 이 장치에만 영향'으로 강제 제거를 안내했다.
         → 장치명·InstanceId 를 보여주고 '이게 문제인 그 카메라가 맞냐'를 물어 y 일 때만 진행.
           조회 실패 건수를 세서 하나라도 실패하면 공유 여부를 미확인으로 두고 명령을 만들지 않는다.
       [R3 P2] 'corrected' 가 'uncorrected' 안에, '정정' 이 '정정할 수 없는' 안에 들어 있어
         치명적 오류(ID18)가 '정정됨'으로 분류됐다.
         → 부정 표현(un-corrected/uncorrectable/정정할 수 없/치명)을 먼저 걸러낸다.
       [R4 P2] UNC 차단으로 넣은 StartsWith 인자가 '역슬래시 4개' 리터럴이라 실제 UNC
         (역슬래시 2개)와 절대 일치하지 않았다. 차단이 아예 동작하지 않았다.
         → 화이트리스트로 교체: 로컬 드라이브 문자로 시작하는 경로만 통과시킨다.
       [R5 P2] tracert 무응답을 'PC 로컬 문제'로 단정하고 winsock 리셋을 권했다.
         3홉 이상 분기만 고쳤고 1홉·중간 분기는 그대로였다.
         → 모든 무응답 분기를 미확인으로 처리한다. 리셋 제안은 LSP 잔재가 실제로
           확인됐을 때만 띄운다(기존엔 lastGood=0 만으로도 떴다).
       [R6 P2] 최근 2일 'Check Update' 5회만으로 루프를 확정했다. 정상적으로 5번 켜고
         로그인해도 5회가 찍힌다.
         → 같은 기간의 로그인 성공 기록을 같이 본다. 0건일 때만 '루프 의심',
           로그인도 있으면 '반복 확인, 루프 미확정'으로 출력한다.
       [R7 P2] 메시지에 'denied' 가 있으면 로컬 실패로 몰아, HTTP 403 Access Denied 가
         '네트워크 문제가 아니다'로 나갔다.
         → 예외 유형으로 먼저 가른다(WebException/HttpRequestException 은 무조건 네트워크).
           HTTP 상태코드를 같이 출력하고 403/407 은 프록시 가로채기 가능성을 안내한다.
       [R8 P2] 쿠키 삭제 결과를 확인하지 않고 '완료'로 기록했다(F10 에서 캐시만 고쳤다).
         → 삭제 후 잔존을 확인해 완료/부분/없음을 나누고 처리내역에도 그대로 기록한다.

 v3.6.4: (2026-09-16) 기업 VPN 탐지 누락 수정.
       v3.0 주석에 "기업 VPN(FortiClient, AnyConnect, GlobalProtect, Pulse Secure)도
       포괄패턴 '*VPN*' 에 걸린다"고 적혀 있었으나 사실이 아니었다. 제품 DisplayName 에
       'VPN' 글자가 없어 -like 매칭이 안 된다. 2026-09-15 교사D 교사 PC 의 FortiClient
       6.0.9.0277 이 메뉴1에 안 잡힌 것이 이 때문이다.
       대표 17개로 확인: 14개가 '*VPN*' 에 안 걸린다(FortiClient VPN·OpenVPN·NordVPN 만 걸림).
       → 제품명 기반 패턴 19개를 포괄패턴 앞에 추가. 전부 '확인' 라벨(교육청 VPN 주의).
       → FortiClient 제거 실측(NoRemove=1, msiexec /x, 3010/1605, wmic 부재)도 주석에 기록.

 v3.6.3: (2026-09-16) 재검토 리포트 F01~F12 + QC 전건 처리 완료.
       [F03 ★ 구조 변경] 실행 계정과 지원 대상(선생님) 계정 분리.
         UAC 에서 별도 관리자 계정으로 승격하면 $env:LOCALAPPDATA·$env:APPDATA·HKCU·
         MyDocuments 가 전부 관리자 것이 된다. 브라우저 정리(메뉴4·5)는 엉뚱한 프로필을
         지우고, 하이웍스 점검(메뉴17)은 남의 레지스트리를 읽는다.
         952행 주석에 같은 문제를 이미 적어뒀는데 브라우저 '업데이트'에만 대응돼 있었다.
         → 시작 시 explorer.exe 소유자로 실제 로그인 사용자를 찾고, ProfileList 에서
           그 계정의 프로필 경로를 구해 $script:Target* 로 고정한다.
           불일치면 시작 배너로 알리고, 사용자별 '변경' 작업은 대상 프로필을 쓴다.
           프로필을 못 찾으면 Test-UserScopeWritable 이 메뉴5 진입 자체를 막는다.
           HKCU·OneDrive 리다이렉트는 그 계정 하이브를 못 읽으므로 한계를 명시한다.
       [F05] 로그 전체에서 'Check Update' 를 세어 루프로 단정했다. appendToFile 이라
         몇 달치가 한 파일에 쌓이므로 서로 다른 달의 5줄로도 '루프'가 됐다.
         → 오늘·어제 기록만 센다. 과거 기록이 섞이면 그 사실을 표시하고 단정하지 않는다.
       [F07] 3.4.0.2 전용 파일 해시 기준선을 버전 확인 없이 적용했다. 다른 버전이면
         정상 파일이 전부 '다름'으로 나와 멀쩡한 PC 재설치를 안내하게 된다.
         → 버전 게이트 추가. 해시를 '못 읽은 것'과 '달라진 것'도 분리(잠긴 파일 ≠ 변조).
       [F09] DISM/SFC 종료코드만 보고 '복구 완료'로 기록했다. SFC 는 복구 실패해도 0 으로
         끝나는 경우가 있어, 화면에는 그 경고를 띄우면서 로그엔 '완료'를 남기는 모순이었다.
         → 실행 완료와 복구 결과를 분리하고, 화면에 나온 결과를 사람이 골라 기록한다.
       [F10] 삭제 전 크기를 그대로 '확보량'으로 더했다. 파일이 잠겨 하나도 안 지워져도
         'N MB 확보'가 찍혔다. → 삭제 후 남은 크기를 다시 재서 실제 감소분만 센다.
           잔존 폴더는 목록으로 보여주고 처리내역에도 '일부 잔존'으로 기록한다.
       [F11] WHEA ID 19 를 치명적으로 분류했다. 19 는 '정정된(corrected) 오류'로 기록되는
         경우가 많고, 정정됐다는 건 시스템이 스스로 처리했다는 뜻이다. 최근 1건만으로
         제조사 안내까지 갔다. → ID 대신 정정 표기와 이벤트 수준을 함께 본다.
       [F12] tracert 무응답을 '회선 차단'으로 단정했다. 보안상 ICMP 에 응답하지 않는
         라우터가 흔해 무응답 홉이 곧 서비스 트래픽의 차단 지점은 아니다.
         → 확실한 근거는 [5]의 443 실패임을 명시하고, tracert 는 참고로만 쓴다.
           다른 회선(테더링) 비교를 대응 순서 0번으로 올렸다.
       [QC] 메뉴17 표기를 '조회 전용'→'진단 전용'으로 바꾸고 실제로 쓰는 세 가지
         (TEMP 임시 다운로드·설치 폴더 쓰기 테스트·클립보드)를 첫 화면에 명시.
         Defender 단독을 '차단 아님'으로 배제하던 문구를 '서드파티 충돌 아님'으로 좁히고
         Defender 자체 격리·제어된 폴더 액세스 확인 명령을 추가.
         로그 미검출을 '한 번도 기록 못 함'으로 단정하던 문구를 '못 찾았다'로 정정.
         v3.6.2 변경 이력의 카메라 메뉴 번호 오기(메뉴6→메뉴10 계열) 수정.

 v3.6.2: (2026-09-16) 재검토 리포트 F01·F02·F04·F06·F08 수정.
       - [F01 ★] v3.6.1 에 넣은 eISP 안전장치가 실제로는 안전하지 않았다.
         정규화한 경로로 검사해놓고 삭제는 '원본 문자열'을 Remove-Item -Path 로 넘겼다.
         · 검사 대상과 삭제 대상이 서로 다른 값이었다
         · -Path 라 와일드카드가 해석된다. 'C:\QA\VP[12]' 는 검사를 통과하고
           VP1·VP2 에 매칭된다(리포트 재현, 이쪽에서도 WildcardPattern 으로 확인)
         · 접두사 매칭이라 VPNClient 같은 무관한 제품 폴더도 통과했다
         → Resolve-SafeDeleteDir 로 교체. 정규화된 단일 절대경로를 반환하고 그 값을
           -LiteralPath 로 삭제한다. 와일드카드 문자가 든 경로·UNC 는 거부하고,
           폴더명은 'VP' 단독 또는 'eISP…' 전체 일치일 때만 허용한다.
       - [F02] 카메라 오등록 분기에서 badInfList 에 Camera 클래스의 정상 웹캠까지 들어와
         멀쩡한 드라이버까지 제거 대상으로 안내했다. 그리고 공유 장치 조회가 실패(0건)했을 때
         '단독 사용'으로 처리해 /force 제거 명령을 그대로 찍었다.
         → 제거 안내 대상을 Image 클래스로 한정하고, 조회 실패 시 명령을 만들지 않는다.
           Image 에는 스캐너·디지털카메라도 포함되므로 장치 이름 확인 경고를 같이 띄운다.
       - [F04] 크기를 확인하기 전에 dlOk=true 를 세우고, 요약에는 실제 수신량과 무관하게
         '8MB 수신 성공'을 찍었다(123바이트를 받아도 같은 문장). 로컬 디스크 부족 실패도
         네트워크·백신부터 보라고 안내했다.
         → 전송 성공(dlOk)과 설치본 검증(dlVerified)을 분리하고 실제 바이트를 출력한다.
           IOException·권한 거부는 로컬 쓰기 실패로 따로 안내한다.
       - [F06] 이벤트 조회 예외를 조용히 삼키고 '크래시가 아니다'로 넘어갔다.
         → 조회 실패 / 검출 0건 / 검출됨 을 나눈다. 조회 실패는 '미확인'으로 표시한다.
       - [F08] 버전을 문자열 -eq 로만 비교해 '같지 않으면 exe 가 낮다'고 단정했다.
         3.5.0.0 vs 3.4.0.2 에서도 '낮다'가 나왔다.
         → [version] 파싱 후 같음/낮음/높음/미확정 네 갈래로 나눈다.

 v3.6.1: (2026-09-16) 코드 리뷰 지적 4건 수정. 전부 타당한 지적이었다.
       - [★위험] 메뉴13 eISP 폴더 삭제가 레지스트리 InstallLocation 을 검증 없이
         Remove-Item -Recurse -Force 했다. Test-Path 만 통과하면 지웠으므로 그 값이
         'C:\' 나 'C:\Program Files' 면 그 폴더를 통째로 날린다.
         드라이브 루트로 등록된 프로그램이 실재한다는 건 v3.0 Get-DllOwnerName 주석에
         이미 실측으로 적혀 있었다 - 조회 함수만 막고 삭제 함수는 안 막은 셈이었다.
         → Test-SafeDeleteDir 신설(드라이브 루트·시스템 상위 폴더 금지, 최소 2단계 깊이,
           폴더명이 VP/eISP 계열일 때만 허용). 제외된 경로는 화면에 사유와 함께 표시.
         → 삭제 실패 시 무조건 '사용중'이라고 찍던 것도 실제 예외 메시지 출력으로 교체.
       - 카메라 진단(메뉴10 Show-AudioDevices 계열) 드라이버 제거 안내가 $badInf 를 단일 변수로 덮어써서 카메라가
         여러 대면 마지막 것만 남았고, 그 INF 를 다른 장치가 공유하는지 확인하지 않았다.
         pnputil /delete-driver /uninstall /force 는 그 패키지를 쓰는 모든 장치에 적용된다.
         → 장치명과 짝지어 수집하고, 안내 전에 해당 INF 사용 장치를 전수 조회한다.
           2개 이상이 공유하면 제거 대신 장치관리자 드라이버 교체를 먼저 안내.
       - 메뉴17 [6] 다운로드 성공을 '메신저 쪽 문제다', 실패를 '차단 확정'으로 단정했다.
         이 요청은 관리자로 승격된 PowerShell 것이라 메신저 컨텍스트를 대변하지 못한다.
         → '이 세션에서는 된다'로 사실만 적고 배제하지 않는다.
       - 메뉴17 [7] 쓰기 성공을 '권한 문제 아님'으로 배제했다. 툴킷은 관리자 권한을
         강제하므로 Program Files 쓰기는 거의 항상 성공한다 - 교사 계정 권한의 증명이 아니다.
         → 관리자 세션임을 명시하고 icacls 로 교사 계정을 별도 확인하도록 안내.
 v3.6: (2026-09-16) 메뉴17 하이웍스 점검 신설.
       ※ 출발점: 하이웍스 업데이트 실패가 8/27 교사E · 8/28 교사F · 9/15 교사B ·
         9/15 교사C2 · 9/16 교사A 로 5건째다. 9/16 건은 원인 규명에 2시간이 걸렸고,
         그 시간 대부분을 계정·UAC·백신·네트워크·레지스트리·exe버전·로그를
         따로따로 조회하는 데 썼다. 한 화면에 모으면 30초다.
       - [메뉴17 신설] 조회 전용. 판정하지 않고 사실만 모은다.
         계정/UAC · HKCU 값+서브키 · exe · 폴더 파일 · 로그 · 서버 Messenger.txt ·
         8MB 다운로드 실증 · 설치폴더 쓰기 실증 · 백신 · 이벤트 · 파일세트 무결성 ·
         표본 한 줄(클립보드).
       - [로그 경로 확정] HiworksMessenger.exe.config 의 log4net 섹션이 실제 설정이다.
         <내 문서>\LogFile\MessengerLog.txt / MinimalLock / level=INFO /
         포맷 [MM/dd-HH:mm:ss][level]-메시지.  교사B 건에서 본 포맷과 일치.
         별도 log4net.config(C:\LogFile\Messenger.log)도 있으나 다른 컴포넌트용으로 보인다.
         MyDocuments 는 OneDrive 백업 시 리다이렉트되므로 GetFolderPath 로 구한다.
       - [파일세트 기준선] 담당자 PC(정상, exe 3.4.0.2) 39개 파일 크기+MD5 를 박아뒀다.
         교사B 건에서 '설치본 손상' 가설을 확인할 방법이 없어 재설치로 뭉갰던 자리.
         하이웍스가 3.4.0.2 위로 올라가면 기준선을 새로 떠야 한다.
       - [가설 정정] 교사B 노트의 'HKCU ProgDir/ProgVer 공란이 원인'은 보류 상태다.
         9/16 실측에서 정상 담당자 PC(알림 안 뜸)에도 그 두 값이 없었다.
         즉 '값이 없으면 반드시 루프가 돈다'는 거짓. 다만 값이 있을 때 판정에 쓰이는지는
         미검증이고 표본이 정상 PC 1대뿐이라 폐기가 아니라 보류다. 표본을 쌓을 것.
       - [오판 기록] 9/16 교사A 건에서 인텔 그래픽 서비스의 .NET Runtime 1023
         ('You must install or update .NET')을 하이웍스 원인으로 엮었는데 무관했다.
         하이웍스는 .NET Framework 4.0 Client Profile 기반이다(dotNetFx40_Client_setup.exe
         동봉, supportedRuntime v4.0). .NET Core 계열 이벤트와 섞지 말 것.
 v3.5: (2026-09-08) 선생님 화면 노출 정리.
       출발점: 애니서포트 원격 중에는 선생님이 같은 화면을 본다. 여기 뜨는 문구는
       전부 선생님이 읽는다. 내부용 문구를 '순화'한 게 아니라 화면에서 '뺐다'.
       - [제거] 메뉴 P(판정 순서·손 떼는 기준) 통째로. "1건에 30분 넘으면 중단하고
         재접수", "재발 2회면 더 붙잡지 않는다" 같은 내부 판단 기준이 선생님 화면에
         그대로 떴다. → 툴킷 밖 '판정순서_담당자용.txt' 로 분리(배포본에 문구 자체가 없다).
       - [제거] 접수 건수·비율 표기 17곳(548건 / 144건 26% 등). 메뉴 헤더, S1~S4 라벨,
         각 시나리오 안내문. 선생님 입장에선 자기 건이 통계 한 줄로 보인다.
       - [제거] 3인칭 '교사' 지칭 6곳. 선생님 본인 앞에서 3인칭으로 부르는 자리였다.
       - [제거] '이관'·'재접수' 사내 용어 4곳. 떠넘긴다는 뜻으로 읽힌다.
       - [제거] 나에게 하는 지시문 3곳("선생님께 사전 안내 필수" 등).
       ※ 기능·판정 로직은 하나도 안 건드렸다. 화면에 뜨는 문구만 뺐다.
 v3.4: (2026-09-08) v3.3 QA/QC 반영. 실행으로 재현한 것만 고쳤다.
       - [P0·빌더] 단일파일 배포본이 무한 루프였다(실행해 보고 발견). Build-SingleFile.ps1
         헤더가 IsInRole 에 문자열 'Administrator' 를 넘겼는데, 문자열 오버로드는 그룹
         이름을 글자 그대로 찾고 실제 그룹명은 'Administrators'(복수)다. 그래서 승격한
         뒤에도 계속 False → 자기를 또 RunAs 로 띄우고, 이미 관리자라 UAC 창도 안 뜨니
         즉시 반복. v2.9(2026-08-24) 이후 단일파일은 한 번도 동작한 적이 없었다
         (2파일 경로만 써서 안 드러났다. 빌더 검증은 인코딩·파싱만 봤지 실행은 안 봤다).
         실측 근거: IsInRole('Users')=True / IsInRole('User')=False = 이름 그대로 찾음.
         → 헤더도 [WindowsBuiltInRole]::Administrator 로 통일(본문은 원래 맞았다)
           + '-elevated' 재진입 가드(판별이 또 어긋나도 두 번째 실행에서 멈춘다)
           + 빌더에 회귀 검증 3종 추가(문자열 판별 / enum 누락 / 가드 누락).
       - [P1] 메뉴 S1~S5·P 가 매번 두 번 실행됐다. PowerShell switch 는 대소문자를
         안 가리는데 's1' 과 'S1' 을 둘 다 써서 두 분기가 모두 돌았다(실측 2회).
         S1 이면 mmsys.cpl 이 2개 뜨고 S2 는 y/n 4단계가 통째로 반복됐다.
         → 소문자 분기만 남긴다. 숫자 메뉴는 중복이 없어 영향 없었다.
       - [P1] 메뉴 제목이 v3.2 로 박혀 있었다(v2.9 에서 이미 한 번 고친 자리).
         Build-SingleFile.ps1 이 이 제목에서 버전을 읽어 검증하므로 빌드 검증까지 무력화됐다.
       - [P2] BugCheck(WER-SystemErrorReporting 1001)이 [손상]에 섞여 DISM+SFC 로
         안내됐다. 블루스크린은 시스템파일 손상이 아니다 → [블루스크린] 으로 분리해
         미니덤프로 보낸다. Kernel-Power 41(비정상 종료)도 [노이즈]에서 빼서 같이 묶는다.
         (S5 는 "BugCheck·Kernel-Power 41 이면 느림 문제가 아니다"라고 안내하는데
          메뉴8 이 정반대로 분류하고 있었다)
       - [P2] 자기삭제가 실행 중인 런처 .bat 을 그 자리에서 지웠다. 그러면 cmd 가 다음
         줄을 못 읽어 Run-Toolkit.bat 끝의 pause 가 날아가고 "배치 파일을 찾을 수
         없습니다"가 뜬다(실측. 삭제 시점이 마지막 줄이어도 EOF 에서 똑같이 난다).
         → 부모 cmd 가 끝난 뒤에 지우도록 지연 삭제 프로세스에 태운다.
         + 대상은 우리가 실행한 Run-Toolkit.bat 하나로 좁힌다. v3.3 은 같은 폴더의
           원격지원.bat(단일파일 배포본)까지 지워 빌드 산출물이 날아갔다.
       - [P3] 메뉴6 이 Get-PnpDevice -Class 'Camera','Image' 를 아직 쓰고 있었다.
         v3.2 가 메뉴10 에서 고친 그 자리다(클래스 미등록 PC 에서 에러 레코드).
         전체 조회 후 필터로 통일 - 메뉴6 과 메뉴10 이 다른 목록을 내던 것도 같이 해소.
       - [P3] eISP: sc.exe delete 종료코드를 본다. 성공(0)인데 서비스가 남아 있으면
         '삭제 표시됨'(재부팅하면 사라짐)이지 부분실패가 아니다 → 오기록 방지.
       - [P3] SFC 초록불 문구 완화. 종료코드 0 은 '돌았다'까지만 보장한다.
       - [P3] 'Windows Virtual Camera Device'(Win11 기본 구성요소)가 이름에 Virtual 이
         있다는 이유로 [유령의심(수동삭제 검토)] 빨간불로 떴다. 메뉴10 에 원래 있던
         오탐인데 위 메뉴6 통일로 같이 퍼지므로 양쪽 다 예외 처리했다. 메뉴10 [4] 가
         Windows 내장 INF(c_swdevice.inf)를 '서드파티 드라이버'로 찍던 것도 같이 정정.
       - [정리] Show-EventLog 의 $hit 은 대입만 하고 아무도 안 읽는 죽은 변수라 제거.
 v3.3: (2026-09-08) v3.2 QA/QC 지적 5건 반영.
       - [P1] DISM/SFC 가 실패해도 '완료'로 찍고 처리내역까지 남기던 것 수정.
         $LASTEXITCODE 로 판정(DISM 0/3010 성공, SFC 0 성공). 실패면 코드와 로그 경로를
         찍고 처리내역에도 '미완료'로 기록한다.
       - [P1] chkdsk 드라이브 입력 검증. 콜론/역슬래시만 걷어내고 cmd 문자열에 넣던 자리라
         'C&calc' 같은 입력이 명령 연결로 실행될 수 있었다 → 영문 한 글자만 허용 + 존재 확인.
       - [P2] eISP 제거 후 서비스/폴더/레지스트리를 재조회해 부분 실패를 구분한다.
       - [P2] Get-Targets 에 KeyPath(Uninstall 레지스트리 경로) 추가. 이름만으로 Unique 하면
         32비트/64비트 동명 항목이 숨겨지고 제거 후 재확인도 오판정된다 → KeyPath 기준으로.
       - [P2] 2파일 배포에서 런처 .bat 이 남던 것 수정.
 v3.2: (2026-09-08) 2025-01~2026-09 처리 현황 548건 집계 반영.
       - [추가] 증상별 시나리오 진입점 S1~S5. 기능은 기존 메뉴 함수를 그대로 호출하고
         '순서'만 정해준다. 2026-09-07 교사H 교사 건에서 카메라 미인식에 표준 시퀀스
         (보안프로그램 31종 정리 + 브라우저 초기화)를 먼저 돌려 2시간을 버렸다.
         실제 원인은 USB 열거 실패(코드43)와 드라이버 WIA 오등록이었다.
       - [추가] 메뉴 P: 판정 순서와 '손 떼는 기준'. 재발 2회면 하드웨어 판정,
         1건 30분 상한, 업무종료 30분 전 비가역 조치 금지.
       - [개선] 메뉴10 오디오/카메라. Class(Camera/Image) 표시, Status=Error·VID_0000
         탐지, 드라이버 Service(usbvideo 여부)와 INF 추출, ConsentStore 권한,
         FrameServer 확인. 마지막에 계층 판정과 다음 조치를 출력한다.
         pnputil 명령은 oem 번호까지 완성해서 찍어준다.
       - [버그] Get-PnpDevice -Class 'Camera','Image' 는 Camera 클래스가 등록된 적 없는
         PC에서 에러가 났다(실측: DESKTOP-XXXXXXX). 전체 조회 후 필터로 변경.
 v3.0: (2026-08-26) 화면 캡쳐 운용에 맞춰 정리.
       - [제거] 메뉴1 CSV 저장. 보고는 화면 캡쳐로 하므로 안 쓴다. 선생님 바탕화면에
         파일을 안 남긴다는 방침과도 맞다.
       - [제거] 메뉴7 재부팅 안내. 재부팅은 애니서포트 [재부팅] 기능으로 하므로
         메뉴 한 칸을 차지할 이유가 없다. 뒤 항목을 한 칸씩 당겼다(8~17 → 7~16).
         본문 안내의 메뉴 번호도 같이 갱신.

 v2.9: (2026-08-24) QA 후 버그 수정 + 단일파일 배포.
       ※ 배포 형태가 바뀐다. 지금까지는 애니서포트로 .bat + .ps1 두 개를 보냈는데,
         빌드하면 .bat 하나로 합쳐진다(Build-SingleFile.ps1). 파일전송 1회로 끝난다.
         이 .ps1 은 계속 '편집용 마스터'다. 폴리글롯 .bat 을 직접 손대면 인코딩/줄바꿈이
         틀어져 cmd 가 줄을 잘라먹는다(실측 확인) → 반드시 여기를 고치고 다시 빌드할 것.
       - [버그] Get-DllOwnerName 폴백 정규식이 깨져 있었다(v2.8 신규 기능의 그 자리).
         '\Program' 의 \P 가 불완전 \p{} 이스케이프, '[^\]' 가 미종결 문자클래스 →
         .NET 이 "Unterminated [] set" 예외. 실측: InstallLocation 이 등록 안 된
         프로그램마다 선생님 화면에 빨간 예외 덤프가 뜨고 '(설치등록 없음·폴더명)'
         라벨은 한 번도 안 붙었다. 백슬래시 이스케이프로 수정.
       - [버그] 메뉴 제목이 v2.7 로 박혀 있었다. 파일은 v2.8 인데 화면엔 v2.7 →
         .bat 이 최신본을 고르는 구조라 "구버전 실행됐나?" 오판을 부른다.
       - [버그] 자기삭제가 .ps1 만 지웠다. Run-Toolkit.bat 은 그대로 남아 '흔적 안 남김'
         방침 위반이었고, 단일파일 모드에선 $PSCommandPath 가 비어 아무것도 안 지워진다
         → $env:RST_SELF 우선. 실행 중인 자신은 직접 못 지우므로 지연 삭제로 떼어낸다.
       - [버그] 언인스톨러 파일이 없는 잔재 키에서 쓰레기 경로로 실행을 시도했다.
         (실측: SecuKit NX - UninstallString 은 있는데 NXUnInst.exe 가 이미 없음
          → 'C:\Program' 으로 잘려 "파일을 찾을 수 없습니다"만 뜸. 진짜 원인이 안 드러남)
         → 실행 전에 갈라내고 '이미 제거된 잔재 키'라고 명시한다.
       - [버그] '.exe' 경계 탐색이 대소문자를 가렸다(Setup.EXE 미매칭) → (?i).
       - [버그] 메뉴10 이 메뉴8 에서 고친 배열 처리를 안 따라갔다. 어댑터에 IPv4 가 2개면
         $cfg.IPv4Address.IPAddress 가 배열이 되고 -not 이 뒤집혀, 공인IP 직결인데
         '공유기 뒤'로 판정 → MAC 변경 대신 공유기 재부팅을 안내했다.
       - 메뉴2 '완료' 를 실제로 확인한다. 종료코드만 보고 초록불을 띄우던 자리라,
         언인스톨러가 즉시 취소·실패해도 완료로 찍혔다 → 제거 후 목록 재조회로 판정.
       - 화면에 ? 로 깨지던 글자 3개 교체(✔/⚠ 는 cp949 에 없다). 엑셀 요약의 '•' 는
         클립보드로는 정상 전달되므로 그대로 둔다.
 v2.8: (2026-08-20) 교사K 교사(teacher0000) 건에서 나온 것 반영.
       ※ 출발점: "화상수업앱 초대가 안 됩니다" 로 접수됐지만 실제 원인은 웹캠 미연결이었다.
         그리고 카메라 목록의 'OBS Virtual Camera' 는 OBS Studio 가 아니라 PengcaStudio 가
         등록한 것이었다(DLL: C:\Program Files\PengcaStudio\obs-virtualcam-module64.dll).
         OBS 는 GPL 이라 파생 프로그램이 이 모듈을 그대로 재배포한다 → 이름으로 소유자를 단정하면 틀린다.
       - [메뉴6 보강] DirectShow 비디오 입력 장치 열거 추가. 메뉴6은 Get-PnpDevice(PnP)만 봤기 때문에
         DirectShow 필터인 가상카메라를 원리적으로 못 봤다(실측: XSplit VCam 은 잡히고
         OBS Virtual Camera 는 안 잡혔다). 각 항목의 InprocServer32 DLL 경로로 진짜 소유 프로그램을
         같이 찍고, 유령 등록(파일 없음)과 현역 등록(파일 있음)을 구분한다.
       - [보존 목록 신설] $ProtectMap. 이름이 보안모듈처럼 보이지만 지우면 안 되는 것을
         탐지·제거 대상에서 아예 빼고 [보존]으로만 표시한다.
         AxCrypt(파일암호화 - 지우면 암호화한 파일을 못 연다), lms, StarPlayer.
       - $PatternMap 6건 추가: FileViewPro(PUP), NIASpeedMeter(잔재),
         NtasPlugin / SmartA 국세청(전자문서·확인), SDAgent / StreamDocs(ePapyrus·확인).
         ※ SDAgent 는 이파피루스 StreamDocs 에이전트다(공공기관 PDF 뷰어·출력용). 같은 PC에서
           PapyrusNtas·NtasPlugin 과 같은 날 설치된 한 세트였고, 기존 '*Papyrus*' 패턴은
           이름에 Papyrus 가 없어 못 잡았다. 이름이 흔한 편이라 '확인' 라벨로 둔다.
       - 메뉴2 '확인' 라벨 항목에 이유 한 줄 추가. 라벨만으론 왜 확인이 필요한지 안 드러났다.
 v2.7: (2026-08-14) 교사 PC 실전 투입에서 나온 것을 반영.
       ※ 이번 판의 출발점: 교사 PC에서 메뉴1이 보안모듈 42건을 잡았는데
         '느림'의 실제 원인은 하나도 못 잡았다. 원인은 토렌트 2개(µTorrent + uTorrent Web)와
         하이재커·PUP 9종이었고 전부 $PatternMap 에 없었다. 프로그램 추가/제거를
         눈으로 훑어서 찾아냈다. → 이름 기반 탐지의 한계가 실증된 것이라 두 갈래로 대응함.
       - [메뉴17 신설] 느림 진단. 이름을 몰라도 잡히는 축을 만든다(조회 전용, 삭제 없음).
         디스크 여유 / 메모리 / 자원 상위 프로세스 / ★프로세스별 TCP 연결 수 /
         자동시작(Run·서비스) / 설치목록 중 PUP 계열.
         핵심은 TCP 연결 수다 - 토렌트·그리드는 수십~수백 연결을 유지하므로 이름을 몰라도 튄다.
       - $PatternMap 20건 추가(위 실측 전수). 토렌트·하이재커·PUP·전자문서·GPKI 등.
         전자문서(ePapyrus/VOICEYE/GPKI)는 업무 필수일 수 있어 전부 '확인' 라벨.
         ※ 알집·알PDF·알씨 등 교사가 실제로 쓰는 도구는 의도적으로 제외(오탐 방지).
           알매니저도 기존 방침대로 제외 유지. 알툴즈 업데이터만 추가(알툴바를 되살리므로).
       - 메뉴5 서버응답 판정을 'nolog'(로그 자체가 없음)와 'noresponse'(로그는 있는데
         응답 기록 없음)로 분리. v2.6.2는 둘 다 같은 문장이라 재설치가 필요한 상황인지
         구분이 안 됐다. noresponse 는 대개 스로틀이라 재설치 대상이 아니다.
         + 최근 4000줄에 없으면 파일 전체를 다시 훑는 폴백 추가.
         (실측: 크롬 updater.log 는 자주 로테이션돼 2750줄 전체에 응답이 0건인 상태가 흔하다)
       - 메뉴9 디스크 판정에 계층 대조 추가. disk(상위)만 있고 Ntfs·stornvme·storahci·
         Storport(하위)가 0건이면 스토리지 하드웨어 근거가 아니므로 chkdsk 를 막는다.
         (2026-08-12 교사I 건에서 disk ID 7 대량을 하드웨어로 오독할 뻔한 자리)
         + 디스크 신호는 ProviderName 지정으로 따로 조회 → 노이즈 상한에 안 밀린다.
         + 진단 대상 상한 500 → 3000, 상한 도달 시 표시.
       - 메뉴1 CSV 저장 경로를 GetFolderPath('Desktop')으로. OneDrive 바탕화면 백업을 켠
         PC는 $env:USERPROFILE\Desktop 이 없어 저장이 실패했다.
 v2.6.2: (2026-08-13) 실행 검증(QA) 후 버그 수정. 전부 이 PC 실측으로 재현·확인함.
       - 메뉴5 [5] 브라우저 업데이트 전면 재작성. v2.6 은 '이미 최신' 오진을 냈다:
         · 실측 상태 - chrome.exe=151.0.7922.76 인데 new_chrome.exe/pv/DisplayVersion 은 .109.
           8/6에 다운로드·설치가 끝났는데 크롬을 완전히 종료한 적이 없어 실행파일 교체
           (new_chrome.exe→chrome.exe)가 8일째 안 된 상태였다.
         · 서버는 pv(.109)를 보고 noupdate 를 답하므로 기다려도 절대 안 풀린다.
         · v2.6 은 DisplayVersion 과 pv 만 비교 → 둘 다 .109 → 초록불. 정작 돌아가는 .76 을
           한 번도 안 봤다. → 판정 기준을 '실행파일 파일버전'으로 교체.
         · 교체 대기면 setup.exe --rename-chrome-exe 로 마무리(브라우저 종료 시에만).
         · 성공 판정: 로그 mtime → 서버 응답 본문(updatecheck.status) 파싱으로 교체.
           (크래시핸들러가 뜨기만 해도 mtime 은 갱신되므로 근거가 못 됨)
         · '예약작업 0건 → 재설치' 경고는 오탐이라 제거. 최신 크롬/엣지는 서비스로도 돈다
           (GoogleUpdaterService<버전>, edgeupdate). 작업·서비스가 둘 다 없을 때만 경고.
         · 로그 경로를 후보 탐색으로(사용자 설치 / 크롬 117 미만 레거시 Omaha 대응).
         · 업데이터 실행 시 작업디렉터리를 TEMP 로 고정 - 안 그러면 스크립트 폴더에
           debug.log 를 떨군다(Run-Toolkit.bat 이 cd 하므로. '흔적 안 남김' 방침 위반).
       - 메뉴2 제거 실패의 진짜 원인 수정: 따옴표 없는 UninstallString 을 첫 공백에서
         잘라 exe='C:\Program' 이 되어 무조건 실패했다. '.exe' 경계로 끊고 실재를 확인한다.
         실측: 비-MSI 70건 중 경로해석 52건 → 67건. 새로 살아난 15건에 CROSSCERT·SecuKit NXS·
         iniLINE CrossEX·APS Engine·SignKorea 등 이 툴킷의 탐지 대상이 그대로 들어있었다.
         + 실패 시 사유와 제거명령을 같이 출력(기존엔 "실패: 이름" 한 줄뿐이라 원인 불명).
       - 메뉴5 [3] 백업이 Preferences.bak 을 -Force 로 덮어써서 두 번 돌리면 원본이 소실됐다
         → 실행마다 타임스탬프 백업(Preferences.<yyyyMMdd_HHmmss>.bak), 되돌리는 명령도 출력.
         + 초기화해도 mixed_script(안전하지 않은 콘텐츠 허용) 예외는 보존한다. CRM 이 HTTP 로
           열려서 이 예외를 날리면 되레 악화된다(2026-08-12 교사J 건).
       - 메뉴4 보호 목록에 엣지판 드래그프리 ID 추가(스토어마다 ID가 달라 [보호]가 안 붙었음)
         + 이름 패턴 2차 그물($KeepExtNamePatterns). 잘못 지우는 것보다 과보호가 안전.
       - 메뉴8 IP 가 가상 어댑터를 집던 문제(실측: 172.19.32.1 vEthernet 이 나오고 실제
         LAN 192.168.0.3 은 안 나옴) → 기본 게이트웨이를 가진 어댑터에서 뽑고, 어댑터명·GW 병기.
       - Run-Toolkit.bat: 최신 스크립트 선택을 이름 역순 → 수정시각순(/o-d)으로. 이름 역순이면
         v2.6.2 보다 v2.6 이 먼저 와서 구버전이 실행됐다.
