         제거 직후 Defender 실시간보호 자동복귀 검증(무방비 상태면 경고+복구 명령 출력).
         ※ MS PC Manager는 백신 아님 - 청소 UI 필요 시에만 선택 설치 안내.
       - 메뉴5 [5] 브라우저 업데이트 실제화: 기존엔 help 페이지만 열어 자동업데이트에 의존 →
