 v2.6: (2026-08-05) 실제 실행 검증(QA) 후 버그 수정
       - 메뉴5 [5] 브라우저 업데이트 전면 재작성. 실측으로 확인된 문제:
         · 크롬 117+ 는 신형 GoogleUpdater 사용. 기존 코드는 레거시 GoogleUpdate.exe만 실행
         · 시스템 설치 크롬에 --system 없이 실행하면 사용자 스코프로 헛돌면서 종료코드는 0
           (실측: CoCreateInstance 80040154 실패 후 "returned 0" → 성공으로 오판)
         · 예약작업 이름 하드코딩(GoogleUpdateTaskMachineUA/Core)은 신형에 존재하지 않음
           → 실제 등록된 작업을 패턴으로 찾아 실행. 하나도 없으면 '최적화툴이 지움' 경고
         · 성공 판정을 업데이터 로그 갱신 여부로 변경(종료코드 신뢰 불가)
         · 지난 설치 실패 사유(LastInstallerResultUIString)를 한글 원문 그대로 출력
         · 앱별 차단 정책 / AutoUpdateCheckPeriodMinutes=0 도 점검
         · 서버가 noupdate로 답하면 '이미 최신(단계적 배포)'임을 명시
       - 메뉴4 확장 목록이 항상 비어 나오던 문제 수정 (2가지 원인 실측 확인):
         · 최신 크롬/엣지는 확장 정보를 Preferences가 아닌 'Secure Preferences'에 저장
           (실측: Preferences 1건 / Secure Preferences 15~41건) → 두 파일 다 읽어 ID로 병합
         · Get-Content에 -Encoding UTF8 누락 → PS5.1이 cp949로 읽어 한글 확장명에서
           ConvertFrom-Json 예외 → catch{}로 조용히 묻힘. 인코딩 명시로 해결
         · location 해석 정정: 10은 정책강제가 아니라 브라우저 내장(EXTERNAL_COMPONENT).
           7/9=정책강제, 2/3/6=외부 프로그램이 심은 확장(보안모듈·애드웨어 의심), 5/10=내장(목록 제외)
       - 메뉴9 자동진단이 신호를 놓치던 문제: -MaxEvents 50을 노이즈 필터 '전에' 걸어
         DCOM 소음이 50건을 다 채우면 옛 disk/손상 오류가 조회조차 안 됨
         → 진단은 500건 대상, 화면 표시만 최근 50건
       - 메뉴3 유령 백신 오판 수정: SecurityCenter에는 제거된 백신 등록이 남음
         (실측: 알약 등록 있으나 AYRunSC.exe 없음) → 실행파일 존재 확인 후 서드파티로 계산
       - 메뉴1 탐지 0건일 때 메뉴6 안내 추가 (Uninstall 미등록 모듈은 서비스로만 잡힘.
         실측: AhnLab Safe Transaction 서비스 Running인데 메뉴1 미탐지)
       - Run-Toolkit.bat: 관리자 권한 자동 승격 + 종료 시 pause(에러 확인) + 최신 버전 선택
 근거 : 2025+2026 처리내역 509건 중 보안삭제 152건(29%) 빈도 분석
 원칙 : 확실한 것만 실제 수행(레지스트리 제거) / 불안정한 것은 페이지만 열기
 실행 : 원격 접속한 선생님 PC에서 관리자 PowerShell로 실행
 정정 : 회사 표준 백신/DRM/DLP/NAC 없음 → 전부 서드파티(안전)
        백신 "비활성화"는 자기보호로 스크립트 불안정 → UI 수동
        OTP(Authenticator) 확장은 절대 삭제 금지(아래 whitelist)
========================================================================
#>

# ── 관리자 권한 체크 (HKLM 제거에 필수) ─────────────────────────────
$principal = New-Object Security.Principal.WindowsPrincipal([Security.Principal.WindowsIdentity]::GetCurrent())
if (-not $principal.IsInRole([Security.Principal.WindowsBuiltInRole]::Administrator)) {
    Write-Host "관리자 권한으로 실행해야 합니다. PowerShell을 '관리자 권한으로 실행' 후 다시 시도하세요." -ForegroundColor Red
    Read-Host "Enter를 누르면 종료"; exit
}

# ── 지원 대상 계정 확정 (v3.6.3 F03) ────────────────────────────────
#  UAC 창에서 '별도 관리자 계정'으로 승격하면 실행 계정과 선생님 계정이 달라진다.
#  그러면 $env:LOCALAPPDATA·$env:APPDATA·HKCU·MyDocuments 가 전부 관리자 것을 가리키고,
#  브라우저 정리는 엉뚱한 프로필을 지우며 하이웍스 점검은 남의 레지스트리를 읽는다.
#  (952행 주석에 같은 문제를 이미 적어뒀는데 브라우저 업데이트에만 대응돼 있었다)
#  → 실제 화면에 로그인해 있는 사용자를 찾아 그 프로필을 기준으로 삼는다.
# v3.6.5 R1: 첫 번째 explorer.exe 소유자만 봤다. 빠른 사용자 전환 등으로 세션이 여러 개면
#  엉뚱한 사용자를 지원 대상으로 잡는다. 그리고 조회에 실패하면 $null 을 돌려줬는데,
#  호출부가 그걸 '계정 일치'로 처리해 관리자 프로필을 그대로 건드렸다.
#  → 소유자를 전부 모아서 '1명 / 0명(미확인) / 2명 이상(다중 세션)' 을 구분해 돌려준다.
function Get-SupportTargetUser {
    # v3.6.6 R9: v3.6.5 는 소유자를 전부 모으긴 했지만 '개별 조회 실패'를 빈 catch 로 버렸다.
    #  그래서 다른 사용자 조회만 성공하고 정작 선생님 쪽 조회가 실패하면 owners 가 1건이 되어
    #  State='ok' 로 그 사람을 지원 대상으로 확정했다. 메뉴5 가 남의 프로필을 정리하게 된다.
    #  (같은 판에서 카메라 쪽[R2]은 probeFail 을 셌으면서 여기는 빠뜨렸다)
    #  → 열거 실패·개별 조회 실패·GetOwner ReturnValue 비정상을 전부 추적한다.
    #    하나라도 실패가 있으면 '전부 봤다'고 말할 수 없으므로 unknown 으로 내려 변경을 막는다.
    $owners = @(); $probeFail = 0; $enumOk = $false; $procCount = 0
    try {
        $procs = @(Get-CimInstance Win32_Process -Filter "Name='explorer.exe'" -ErrorAction Stop)
        $enumOk = $true; $procCount = $procs.Count
        foreach ($exp in $procs) {
            try {
                $o = Invoke-CimMethod -InputObject $exp -MethodName GetOwner -ErrorAction Stop
                # GetOwner 는 예외 없이 ReturnValue 로 실패를 알리는 경우가 있다.
                if ($o.ReturnValue -ne 0 -or [string]::IsNullOrWhiteSpace([string]$o.User)) { $probeFail++; continue }
                $owners += ('{0}\{1}' -f $(if ($o.Domain) { $o.Domain } else { $env:COMPUTERNAME }), $o.User)
            } catch { $probeFail++ }
        }
    } catch { }
    $owners = @($owners | Select-Object -Unique)

    if (-not $enumOk) {
        return [PSCustomObject]@{ State='unknown'; User=$null; All=@(); Reason='explorer 프로세스 열거 실패' }
    }
    if ($probeFail -gt 0) {
        # ★ 부분 실패. 확인된 소유자가 1명이어도 그 사람이 지원 대상이라고 단정할 수 없다.
        return [PSCustomObject]@{ State='unknown'; User=$null; All=$owners
                                  Reason=("explorer {0}개 중 {1}개의 소유자 조회 실패(확인된 사용자: {2})" -f `
                                          $procCount, $probeFail, $(if ($owners) { $owners -join ', ' } else { '없음' })) }
    }
    if ($owners.Count -eq 1) { return [PSCustomObject]@{ State='ok';    User=$owners[0]; All=$owners; Reason=$null } }
    if ($owners.Count -gt 1) { return [PSCustomObject]@{ State='multi'; User=$null;      All=$owners; Reason='로그인 세션 다수' } }

    # explorer 가 한 개도 없다(= 아무도 데스크톱을 쓰고 있지 않음). 콘솔 세션 사용자로 대체하되
    # 이건 '추정'이므로 그 사실을 남긴다.
    try {
        $u = (Get-CimInstance Win32_ComputerSystem -ErrorAction Stop).UserName
        if ($u) {
            return [PSCustomObject]@{ State='ok'; User=$u; All=@($u)
                                      Reason='explorer 프로세스가 없어 콘솔 세션 사용자로 대체(추정)' }
        }
    } catch {}
    return [PSCustomObject]@{ State='unknown'; User=$null; All=@(); Reason='로그인 사용자를 찾지 못함' }
}
function Get-ProfilePathByAccount([string]$acct) {
    if (-not $acct) { return $null }
    try {
        $sid = (New-Object System.Security.Principal.NTAccount($acct)).Translate(
                   [System.Security.Principal.SecurityIdentifier]).Value
        $pp = (Get-ItemProperty ("HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\ProfileList\" + $sid) `
               -ErrorAction Stop).ProfileImagePath
        if ($pp) { return [Environment]::ExpandEnvironmentVariables($pp) }
    } catch {}
    return $null
}

$script:RunAsUser          = "$env:USERDOMAIN\$env:USERNAME"
$script:TargetProfile      = $env:USERPROFILE
$script:TargetLocalAppData = $env:LOCALAPPDATA
$script:TargetAppData      = $env:APPDATA
$script:UserMismatch       = $false
# UserScope: 사용자별 '변경' 작업을 해도 되는지의 상태
#   same    = 실행 계정 = 선생님 계정. 안전
#   mapped  = 계정은 다르지만 선생님 프로필을 찾았다. 그 경로로 작업
#   noprofile = 계정이 다른데 프로필을 못 찾음 → 변경 차단
#   unknown = 누가 쓰는지 조회 실패 → 변경 차단(예전엔 '일치'로 처리해 관리자 것을 건드렸다)
#   multi   = 로그인 세션이 여러 개 → 변경 차단(누구 것인지 확정 못 함)
$script:UserScope = 'same'
$tu = Get-SupportTargetUser
$script:TargetUser = $tu.User
if ($tu.State -eq 'ok' -and $tu.Reason) {
    Write-Host ("`n ※ 지원 대상 계정 판별: {0}" -f $tu.Reason) -ForegroundColor DarkYellow
}
switch ($tu.State) {
    'multi'   { $script:UserScope = 'multi';   $script:UserMismatch = $true }
    'unknown' { $script:UserScope = 'unknown'; $script:UserMismatch = $true }
    default {
        if ($tu.User -ine $script:RunAsUser) {
            $script:UserMismatch = $true
            $tp = Get-ProfilePathByAccount $tu.User
            if ($tp -and (Test-Path -LiteralPath $tp)) {
                $script:UserScope          = 'mapped'
                $script:TargetProfile      = $tp
                $script:TargetLocalAppData = Join-Path $tp 'AppData\Local'
                $script:TargetAppData      = Join-Path $tp 'AppData\Roaming'
            } else {
                $script:UserScope = 'noprofile'
            }
        }
    }
}
# v3.6.13 (외부 QA H4): 사용자 레지스트리(HKCU) 대상 확정.
#  계정이 다르면 HKCU: 는 승격 계정 것이다. 선생님이 로그인해 있으면 HKEY_USERS\<SID> 에 하이브가
#  올라와 있으므로 그걸 쓴다. 못 찾으면 $null → 각 메뉴가 '미검증'으로 표시한다(다른 계정 값을 읽지 않는다).
$script:TargetSid  = $null
$script:TargetHKCU = 'HKCU:'
if ($script:UserMismatch) {
    $script:TargetHKCU = $null
    if ($script:UserScope -eq 'mapped' -and $script:TargetUser) {
        try {
            $script:TargetSid = (New-Object System.Security.Principal.NTAccount($script:TargetUser)).Translate(
                                    [System.Security.Principal.SecurityIdentifier]).Value
        } catch {}
        if ($script:TargetSid -and (Test-Path -LiteralPath ("Registry::HKEY_USERS\" + $script:TargetSid))) {
            $script:TargetHKCU = "Registry::HKEY_USERS\$($script:TargetSid)"
        }
    }
}
function Get-UserRegPath([string]$sub) {
    if (-not $script:TargetHKCU) { return $null }
    return ($script:TargetHKCU.TrimEnd('\') + '\' + $sub.TrimStart('\'))
}
if ($script:UserMismatch) {
    Write-Host ""
    Write-Host " ★ 지원 대상 계정 확인 필요 " -ForegroundColor Black -BackgroundColor Yellow
    Write-Host ("   실행 계정   : {0}" -f $script:RunAsUser) -ForegroundColor Yellow
    switch ($script:UserScope) {
        'mapped' {
            Write-Host ("   선생님 계정 : {0}" -f $script:TargetUser) -ForegroundColor Yellow
            Write-Host ("   대상 프로필 : {0}  ← 사용자별 작업은 이 경로를 씁니다" -f $script:TargetProfile) -ForegroundColor Cyan
            if ($tu.Reason) { Write-Host ("   ※ {0}" -f $tu.Reason) -ForegroundColor DarkYellow }
        }
        'noprofile' {
            Write-Host ("   선생님 계정 : {0}" -f $script:TargetUser) -ForegroundColor Yellow
            Write-Host  "   프로필 경로를 못 찾았습니다 - 사용자별 '변경' 작업(메뉴5)은 중단됩니다." -ForegroundColor Red
        }
        'multi' {
            Write-Host ("   로그인 세션이 여러 개입니다: {0}" -f ($tu.All -join ', ')) -ForegroundColor Red
            Write-Host  "   누구 프로필인지 확정할 수 없어 사용자별 '변경' 작업(메뉴5)은 중단됩니다." -ForegroundColor Red
            Write-Host  "   다른 사용자를 로그오프시킨 뒤 다시 실행하세요." -ForegroundColor Yellow
        }
        'unknown' {
            Write-Host  "   지금 이 PC 를 쓰는 사용자를 확정하지 못했습니다." -ForegroundColor Red
            if ($tu.Reason) { Write-Host ("   사유: {0}" -f $tu.Reason) -ForegroundColor DarkYellow }
            Write-Host  "   실행 계정 것을 건드릴 위험이 있어 사용자별 '변경' 작업(메뉴5)은 중단됩니다." -ForegroundColor Red
        }
    }
    if ($script:TargetHKCU) {
        Write-Host "   사용자 레지스트리는 선생님 계정 것(HKEY_USERS)으로 읽습니다. 문서 폴더는 실행 계정 기준일 수 있어 메뉴17 해석에 주의." -ForegroundColor DarkYellow
    } else {
        Write-Host "   선생님 계정 레지스트리(HKCU)를 못 읽습니다 - 사용자 레지스트리 항목은 '미검증'으로 표시됩니다." -ForegroundColor DarkYellow
    }
    Write-Host "   선생님 계정으로 UAC 를 통과하면(비밀번호 입력 없이 [예]) 이 경고가 사라집니다." -ForegroundColor DarkGray
    Write-Host ""
}
# 사용자별 변경 작업을 해도 되는지 판정한다. 대상 프로필을 못 찾았으면 막는다.
function Test-UserScopeWritable {
    if ($script:UserScope -eq 'same' -or $script:UserScope -eq 'mapped') { return $true }
    $why = switch ($script:UserScope) {
        'noprofile' { '선생님 계정은 확인했지만 프로필 경로를 찾지 못했습니다.' }
        'multi'     { '로그인 세션이 여러 개라 누구 프로필인지 확정할 수 없습니다.' }
        default     { '지금 이 PC 를 쓰는 사용자를 확인하지 못했습니다(조회 실패).' }
    }
    Write-Host ("`n  ★ {0}" -f $why) -ForegroundColor Red
    Write-Host  "     이대로 진행하면 실행 계정(관리자)의 브라우저를 정리하게 됩니다 - 중단합니다." -ForegroundColor Red
    Write-Host  "     선생님 계정으로 UAC 를 통과한 뒤 다시 실행하세요.`n" -ForegroundColor Yellow
    return $false
}

# v3.6.15 (외부 QA): 브라우저 종료·열기를 선생님 세션으로 한정한다.
#  Stop-Process -Name 은 모든 사용자 세션의 같은 이름 프로세스를 닫는다.
#  계정 불일치(승격 계정 ≠ 선생님)에서 Start-Process 로 브라우저를 열면 승격 계정 프로필로 열린다.
function Get-TargetSessionId {
    if ($script:UserScope -eq 'same') {
        try { return [int](Get-Process -Id $PID -ErrorAction Stop).SessionId } catch { return $null }
    }
    if ($script:UserScope -ne 'mapped' -or -not $script:TargetUser) { return $null }
    try {
        foreach ($ex in @(Get-CimInstance Win32_Process -Filter "Name='explorer.exe'" -ErrorAction Stop)) {
            $o = $null
            try { $o = Invoke-CimMethod -InputObject $ex -MethodName GetOwner -ErrorAction Stop } catch { continue }
            if (-not $o -or $o.ReturnValue -ne 0 -or -not $o.User) { continue }
            $acct = '{0}\{1}' -f $(if ($o.Domain) { $o.Domain } else { $env:COMPUTERNAME }), $o.User
            if ($acct -ieq $script:TargetUser) { return [int]$ex.SessionId }
        }
    } catch {}
    return $null
}
function Get-TargetBrowserProcess([string]$proc) {
    $all = @(Get-Process -Name $proc -ErrorAction SilentlyContinue)
    $sid = Get-TargetSessionId
    if ($null -eq $sid) { return $all }
    return @($all | Where-Object { $_.SessionId -eq $sid })
}
# 반환: $true = 선생님 세션 브라우저를 종료함 / $false = 세션을 특정 못 해 종료하지 않음
#  v3.6.16 (외부 QA 재검수): 세션을 모를 때 '전체 종료'로 대체하면 다른 사용자 브라우저까지 닫는다 → 하지 않는다.
function Stop-TargetBrowser([string]$proc) {
    $sid = Get-TargetSessionId
    if ($null -eq $sid) {
        Write-Host "  ※ 선생님 세션을 특정하지 못해 브라우저를 종료하지 않습니다(다른 사용자 세션 보호)." -ForegroundColor DarkYellow
        return $false
    }
    $all   = @(Get-Process -Name $proc -ErrorAction SilentlyContinue)
    $mine  = @($all | Where-Object { $_.SessionId -eq $sid })
    $other = @($all | Where-Object { $_.SessionId -ne $sid })
    if ($other) { Write-Host ("  ※ 다른 사용자 세션의 {0} {1}개는 닫지 않습니다." -f $proc, $other.Count) -ForegroundColor DarkGray }
    $mine | Stop-Process -Force -ErrorAction SilentlyContinue
    # v3.6.17 (외부 QA 3차): 종료 실패를 숨기고 $true 를 돌려줬다 → 실제로 사라졌는지 확인한다.
    $left = @()
    for ($w = 0; $w -lt 10; $w++) {
        $left = @(Get-Process -Name $proc -ErrorAction SilentlyContinue | Where-Object { $_.SessionId -eq $sid })
        if (-not $left) { break }
        Start-Sleep -Milliseconds 500
    }
    if ($left) {
        Write-Host ("  ★ 선생님 세션의 {0} {1}개가 종료되지 않았습니다(응답 없음·권한 부족 가능)." -f $proc, $left.Count) -ForegroundColor Red
        return $false
    }
    return $true
}
function Open-BrowserPage([string]$exe, [string]$url) {
    if ($script:UserMismatch) {
        Write-Host "  ※ 실행 계정이 선생님 계정과 달라 브라우저를 대신 열지 않습니다(열면 관리자 계정 프로필로 열림)." -ForegroundColor DarkYellow
        Write-Host ("     선생님 브라우저 주소창에 직접 입력: {0}" -f $url) -ForegroundColor Yellow
        try { Set-Clipboard -Value $url; Write-Host "     (주소를 클립보드에 복사함)" -ForegroundColor DarkGray } catch {}
        return
    }
    Start-Process $exe $url
}

# ── 처리내역 자동 요약용 로그 (자동 수행 조치만 기록) ────────────────
$script:ActionLog = New-Object System.Collections.Generic.List[string]
function Log-Action([string]$msg) { $script:ActionLog.Add($msg) }

# ── 세션 트랜스크립트 (이관 증거용, 종료 시 경로 안내/삭제 선택) ──────
$script:TranscriptPath = Join-Path $env:TEMP ("RST_세션로그_{0}_{1}.txt" -f (Get-Date -Format yyyyMMdd_HHmmss), $PID)
try { Start-Transcript -Path $script:TranscriptPath -ErrorAction Stop | Out-Null }
catch { $script:TranscriptPath = $null }

# ── 강의채널 StarPlayer 검증 버전 (실측 해결 사례 기반. 바뀌면 여기만 수정) ──
$VerifiedStarPlayer = '1.3.19.8'

# ── 보안/입력간섭 프로그램: 패턴 => 카테고리 (실측 빈도순) ────────────
$PatternMap = [ordered]@{
    'nProtect*'         = '금융보안(54)'      # 최다
    '*VCam*'            = '카메라간섭(확인)'       # XSplit VCam - 실측 2위(50). 교사 화상수업앱 배경변경 도구일 수 있음 → 확인 후 종료/제거(무단삭제 금지)
    'XSplit*'           = '카메라간섭(확인)'       # 상동 - 삭제 전 선생님께 확인
    '*OBS Studio*'      = '카메라간섭(방송툴·확인)'   # 2026-08-12 교사J 교사 PC. 가상카메라 생성 → 화상수업앱 장치 충돌. 교사 수업장비일 수 있어 무단삭제 금지
