# 보호 패턴이 먼저다. OTP·드래그프리는 여기까지 오지 않는다.
function Get-ExtVerdict([string]$name) {
    foreach ($p in $RemoveExtPatterns.Keys) {
        if ($name -like $p) { return ('★제거 ' + $RemoveExtPatterns[$p]) }
    }
    return ''
}


function Get-BrowserExe($which) {
    $c = @{
        chrome = @("$env:ProgramFiles\Google\Chrome\Application\chrome.exe",
                   "${env:ProgramFiles(x86)}\Google\Chrome\Application\chrome.exe",
                   # v3.6.3 F03: 계정이 다르면 선생님의 '사용자 설치' 크롬을 못 찾는다.
                   # v3.6.12: 선생님 쪽을 승격 계정($env:LOCALAPPDATA)보다 먼저 본다.
                   (Join-Path $script:TargetLocalAppData 'Google\Chrome\Application\chrome.exe'),
                   "$env:LOCALAPPDATA\Google\Chrome\Application\chrome.exe")
        edge   = @("${env:ProgramFiles(x86)}\Microsoft\Edge\Application\msedge.exe",
                   "$env:ProgramFiles\Microsoft\Edge\Application\msedge.exe")
    }
    ($c[$which] | Where-Object { Test-Path $_ } | Select-Object -First 1)
}

# ── 1) 보안프로그램 탐지 ────────────────────────────────────────────
# ── 보존 목록: 이름이 보안모듈처럼 보이지만 삭제하면 안 되는 것 ──────────
#  2026-08-20 교사K 교사 건에서 나온 자리. 탐지·제거 대상에서 빼고 [보존]으로만 표시한다.
#  AxCrypt 는 특히 위험 - 프로그램만 지워도 암호화해 둔 파일을 다시 열 수 없다.
$ProtectMap = [ordered]@{
    'AxCrypt*'    = '파일암호화 - 삭제하면 암호화해 둔 파일을 못 연다'
    '*lms*'     = 'LMS 업무 프로그램'
    'StarPlayer*' = '강의채널 재생 에이전트 - 버전 확인은 메뉴11'
    # ── 교사의 다른 업무(보험사) 프로그램 세트 (v3.6.8, 2026-09-28 실측) ──────
    #  같은 날(7/8) 한꺼번에 설치된 메리츠화재 업무 세트. 증명서 발급 시스템까지 있어
    #  지우면 교사의 그쪽 업무가 막힌다. 고객사 업무와 무관하고 증상과도 무관했다.
    #  '*Meritz*' 가 FSSADK Client for MERITZFIRE / MAWS_MERITZ / XPLATFORM ..._MeritzFireBSR 를 잡는다.
    '*Meritz*'        = '보험사 업무 프로그램(메리츠화재) - 교사 다른 업무용. 확인 없이 삭제 금지'
    '*메리츠*'        = '보험사 업무 프로그램(메리츠화재) - 교사 다른 업무용. 확인 없이 삭제 금지'
    'XPLATFORM*'      = '업무화면 엔진(투비소프트) - 기업 업무시스템용. 확인 없이 삭제 금지'
    'TPLSvc*'         = 'XPLATFORM 런처 서비스(투비소프트) - 확인 없이 삭제 금지'
    'TNWLIB*'         = 'XPLATFORM 과 함께 설치되는 구성요소(추정) - 확인 없이 삭제 금지'
    'OZWebAgent*'     = 'OZ 리포트 에이전트(포시에스) - 업무 서식 출력용. 확인 없이 삭제 금지'
    #  정체 미확인(검색 결과 없음). 8/28 설치, 'NEXT_UI Prod' 표기로 보아 기업 전용 브라우저 추정.
    'MatrixBrowser*'  = '정체 미확인 전용 브라우저 - 교사에게 용도 확인'
    'MatrixGear*'     = '정체 미확인 전용 브라우저 구성요소 - 교사에게 용도 확인'
}
function Test-Protected([string]$name) {
    foreach ($p in $ProtectMap.Keys) { if ($name -like $p) { return $true } }
    return $false
}
function Get-Protected {
    $paths = @(
        'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Uninstall\*',
        'HKLM:\SOFTWARE\WOW6432Node\Microsoft\Windows\CurrentVersion\Uninstall\*',
        (Get-UserRegPath 'SOFTWARE\Microsoft\Windows\CurrentVersion\Uninstall\*')
    ) | Where-Object { $_ }
    $r = foreach ($p in $paths) {
        Get-ItemProperty $p -ErrorAction SilentlyContinue |
        Where-Object { $_.DisplayName } |
        ForEach-Object {
            $reg = $_
            foreach ($pat in $ProtectMap.Keys) {
                if ($reg.DisplayName -like $pat) {
                    [PSCustomObject]@{ 이름=$reg.DisplayName; 버전=$reg.DisplayVersion; 사유=$ProtectMap[$pat] }
                    break
                }
            }
        }
    }
    $r | Sort-Object 이름 -Unique
}

function Get-Targets {
    $paths = @(
        'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Uninstall\*',
        'HKLM:\SOFTWARE\WOW6432Node\Microsoft\Windows\CurrentVersion\Uninstall\*'
    )
    # v3.6.12: 계정 불일치면 HKCU: 는 승격 계정 것이라 뺐다.
    # v3.6.13: 선생님 계정 하이브(HKEY_USERS\SID)에서 읽는다. 못 읽으면 빠지고 화면에 미검증 안내.
    $uPath = Get-UserRegPath 'SOFTWARE\Microsoft\Windows\CurrentVersion\Uninstall\*'
    if ($uPath) { $paths += $uPath }
    $result = foreach ($p in $paths) {
        Get-ItemProperty $p -ErrorAction SilentlyContinue |
        Where-Object { $_.DisplayName } |
        ForEach-Object {
            $reg = $_
            $n = $reg.DisplayName
            if (Test-Protected $n) { return }   # 보존 목록은 탐지·제거 대상에서 제외
            foreach ($pat in $PatternMap.Keys) {
                if ($n -like $pat) {
                    # NoRemove=1(제거버튼 회색) 또는 SystemComponent=1(목록 숨김) → UI로 못 지움 = CMD 필요
                    $cmdOnly = ($reg.NoRemove -eq 1 -or $reg.SystemComponent -eq 1)
                    # v3.3: KeyPath 를 고유 식별자로 함께 보관한다. 이름만으로 Unique 하면
                    #  32비트/64비트에 같은 이름으로 깔린 항목이나 버전만 다른 중복 설치가
                    #  목록에서 사라지고, 제거 후 재확인도 엉뚱하게 판정된다.
                    [PSCustomObject]@{
                        이름=$n; 분류=$PatternMap[$pat]; 버전=$reg.DisplayVersion
                        Quiet=$reg.QuietUninstallString; Uninstall=$reg.UninstallString
                        CmdOnly=$cmdOnly; 제거=if($cmdOnly){'CMD'}else{'UI'}
                        KeyPath=$reg.PSPath
                    }; break
                }
            }
        }
    }
    # 같은 KeyPath 만 중복 제거(경로가 다르면 서로 다른 설치본이다)
    $result | Sort-Object KeyPath -Unique | Sort-Object 이름
}

# 보안센터(SecurityCenter2)에 등록된 백신 전수 조회.
# PatternMap은 이름 기반이라 모르는 백신을 계속 놓친다(2026-08-12 네이버/다음 백신 미탐지).
# 백신은 설치 시 보안센터에 자기를 등록하므로 이름을 몰라도 여기선 무조건 잡힌다.
function Get-RegisteredAV {
    try {
        Get-CimInstance -Namespace 'root\SecurityCenter2' -ClassName AntiVirusProduct -ErrorAction Stop |
            Select-Object @{n='이름';e={$_.displayName}}, @{n='실행파일';e={$_.pathToSignedProductExe}}
    } catch { $null }
}

function Invoke-Detect {
    if ($script:UserMismatch -and -not $script:TargetHKCU) {
        Write-Host "`n※ 선생님 계정 레지스트리를 못 읽어 사용자별 설치(HKCU) 프로그램은 탐지·제거에서 빠졌습니다(미검증)." -ForegroundColor Yellow
        Write-Host "   선생님 계정의 '설정 > 앱'에서 직접 확인하세요." -ForegroundColor DarkGray
    }
    $av = Get-RegisteredAV
    if ($av) {
        Write-Host "`n[보안센터 등록 백신] - 이름 패턴과 무관하게 전수 조회" -ForegroundColor Cyan
        $av | Format-Table 이름,실행파일 -AutoSize
        Write-Host "※ Windows Defender 외 항목 = 제거 대상. 제거 후 메뉴3으로 Defender 실시간보호 복귀 검증 필수.`n" -ForegroundColor DarkGray
    }
    $prot = Get-Protected
    if ($prot) {
        Write-Host "`n[보존] 삭제하면 안 되는 항목 - 수동 삭제 중에도 건너뛸 것" -ForegroundColor Cyan
        $prot | ForEach-Object { Write-Host ("  {0} {1}  → {2}" -f $_.이름, $_.버전, $_.사유) -ForegroundColor Cyan }
        Write-Host ""
    }
    $t = Get-Targets
    if (-not $t) {
        Write-Host "`n탐지된 보안프로그램 없음." -ForegroundColor Green
        # 이 탐지는 '프로그램 추가/제거' 등록(Uninstall 레지스트리) 기준.
        # 등록 없이 서비스만 도는 모듈(예: AhnLab Safe Transaction)은 여기 안 잡힘.
        Write-Host "※ 단, 프로그램 목록에 등록 안 되는 모듈은 여기서 안 잡힙니다 → 메뉴6(서비스/드라이버)도 확인.`n" -ForegroundColor DarkGray
        return
    }
    $t | Format-Table 분류,이름,버전,제거 -AutoSize
    Write-Host ("탐지 {0}개  (제거열: UI=프로그램추가/제거에서 직접삭제 / CMD=UI버튼 비활성→메뉴2로 명령줄 제거)`n" -f $t.Count) -ForegroundColor Yellow
}

# 언인스톨 전 관련 보안 프로세스 강제 종료 (제거 성공률 ↑)
function Kill-SecurityProcess {
    $names = @('nProtect','npk*','TouchEn*','NXISAS*','nxKey*','TKAgent','AhnLab*','ASDSvc','V3*','Veraport',
               'wizvera*','INISAFE*','iniLINE*','Delfino*','IPinside*','ipinside*','MarkAny*',
               'KeySharp*','MagicLine*','MyEncrypt*','XSplit*','VCam*','Interezen*','INNORIX*')
    Get-Process -ErrorAction SilentlyContinue | Where-Object {
        $p = $_.ProcessName; ($names | Where-Object { $p -like $_ })
    } | ForEach-Object {
        try { Stop-Process -Id $_.Id -Force -ErrorAction SilentlyContinue; Write-Host "  프로세스 종료: $($_.ProcessName)" -ForegroundColor DarkGray } catch {}
    }
}

# UninstallString 을 [실행파일][인자] 로 쪼갠다.
# v2.6까지는 따옴표가 없으면 '첫 공백'에서 잘랐는데, 레지스트리에는 따옴표 없이
# 'C:\Program Files (x86)\KICA\SecukitNX\NXUnInst.exe' 처럼 등록된 항목이 많다
# (실측: 이 PC 한 대에만 18건, 그중 SecuKit NX·CROSSCERT 가 이 툴킷의 탐지 대상).
# 그러면 exe='C:\Program' 이 되어 "지정된 파일을 찾을 수 없습니다"로 무조건 실패했다.
# → '.exe' 경계마다 끊어보고 실제로 존재하는 경로를 채택한다.
function Split-UninstallCommand($cmd) {
    if ($cmd -match '^\s*"([^"]+)"\s*(.*)$') { return @($matches[1], $matches[2].Trim()) }
    foreach ($m in [regex]::Matches($cmd, '(?i)\.exe\b')) {   # (?i): 'Setup.EXE' 표기도 잡는다
        $exe = $cmd.Substring(0, $m.Index + 4).Trim()
        if (Test-Path $exe) { return @($exe, $cmd.Substring($m.Index + 4).Trim()) }
    }
    # .exe 가 아니거나(배치·rundll32) 실행파일이 이미 지워진 경우 - 종래 방식으로 넘긴다.
    # 이때 실패하면 catch 가 사유를 찍으므로 원인 파악은 된다.
    if ($cmd -match '^\s*(\S+)\s*(.*)$') { return @($matches[1], $matches[2].Trim()) }
    return @($cmd, '')
}

function Invoke-Remove {
    if ($script:UserMismatch -and -not $script:TargetHKCU) {
        Write-Host "`n※ 선생님 계정 레지스트리를 못 읽어 사용자별 설치(HKCU) 프로그램은 탐지·제거에서 빠졌습니다(미검증)." -ForegroundColor Yellow
        Write-Host "   선생님 계정의 '설정 > 앱'에서 직접 확인하세요." -ForegroundColor DarkGray
    }
    $t = Get-Targets
    if (-not $t) { Write-Host "`n제거 대상 없음.`n" -ForegroundColor Green; return }
    # v3.6.13: 계정이 다르면 선생님 '사용자별 설치' 언인스톨러를 승격 계정으로 돌리게 된다 → 자동 제거에서 뺀다.
    if ($script:UserMismatch) {
        $userInst = @($t | Where-Object { "$($_.KeyPath)" -match 'HKEY_USERS' })
        if ($userInst) {
            Write-Host "`n※ 선생님 계정 사용자별 설치 - 여기서 제거하지 않음(선생님 계정 '설정 > 앱'에서 제거):" -ForegroundColor Yellow
            $userInst | ForEach-Object { Write-Host ("      {0}  [{1}]" -f $_.이름, $_.분류) -ForegroundColor Yellow }
            $t = @($t | Where-Object { "$($_.KeyPath)" -notmatch 'HKEY_USERS' })
            if (-not $t) { Write-Host "`n나머지 제거 대상 없음.`n" -ForegroundColor Green; return }
        }
    }

    # UI로 안 지워지는 것(NoRemove=제거버튼 회색) vs UI로 지울 수 있는 것 구분
    $cmdOnly = @($t | Where-Object { $_.CmdOnly })
    $uiOk    = @($t | Where-Object { -not $_.CmdOnly })
    Write-Host "`n[ 제거 방식 구분 ]" -ForegroundColor Cyan
    Write-Host ("  ● UI 제거 가능 ({0}개) → '프로그램 추가/제거'에서 직접 하나씩 삭제 권장:" -f $uiOk.Count) -ForegroundColor Gray
    if ($uiOk) { $uiOk | ForEach-Object { Write-Host ("      {0}  [{1}]" -f $_.이름, $_.분류) -ForegroundColor DarkGray } } else { Write-Host "      (없음)" -ForegroundColor DarkGray }
    Write-Host ("  ● CMD 필요 ({0}개) → UI 제거버튼 비활성(NoRemove). 명령줄로만 제거 가능:" -f $cmdOnly.Count) -ForegroundColor Yellow
    if ($cmdOnly) { $cmdOnly | ForEach-Object { Write-Host ("      {0}  [{1}]" -f $_.이름, $_.분류) -ForegroundColor Yellow } } else { Write-Host "      (없음)" -ForegroundColor DarkGray }

    $sel = Read-Host "`n제거 대상? (y=CMD필요한 것만[권장] / a=전체 / n=취소)"
    if ($sel -ne 'y' -and $sel -ne 'a') { Write-Host "취소됨.`n"; return }
    $targets = if ($sel -eq 'a') { $t } else { $cmdOnly }
    if (-not $targets) { Write-Host "`n  CMD 제거 대상 없음 - UI 가능한 건 직접 삭제하세요.`n" -ForegroundColor Green; return }

    # 강제 종료 위험 경고 후 확인 (은행/인증서 작업 중이면 중단됨)
    Write-Host "`n[주의] 관련 보안 프로세스를 강제 종료합니다." -ForegroundColor Yellow
    Write-Host "       은행/공공기관 로그인·인증서 작업 중이면 끊길 수 있습니다." -ForegroundColor Yellow
    if ((Read-Host "계속할까요? (y/n)") -ne 'y') { Write-Host "취소됨.`n"; return }
    # v3.6.13 (외부 QA M1): 개별 질문 전에 일괄 종료했었다 → 전부 n 이어도 이미 종료된 상태. 첫 y 에서 종료한다.
    $killed = $false
    foreach ($i in $targets) {
        $ans = Read-Host ("제거? -> [{0}] {1}  (y/n)" -f $i.분류, $i.이름)
        if ($ans -ne 'y') { continue }
        if (-not $killed) { Kill-SecurityProcess; $killed = $true }
        $cmd = if ($i.Quiet) { $i.Quiet } else { $i.Uninstall }
        if (-not $cmd) { Write-Host "  제거명령 없음(수동): $($i.이름)" -ForegroundColor DarkYellow; continue }
        try {
            # MSI 명령(msiexec ... {GUID})이면 msiexec 무인 제거, 아니면 원본 언인스톨러 실행
            # v3.6.15 (외부 QA): GUID 만 보고 바꿨다 → InstallShield 등 exe 언인스톨러 경로의 GUID 도 msiexec 로 갔다.
            if ($cmd -match '(?i)\bmsiexec(\.exe)?\b' -and $cmd -match '\{[0-9A-Fa-f\-]{36}\}') {
                $guid = $matches[0]
                $p = Start-Process 'msiexec.exe' "/X $guid /qn /norestart" -PassThru
            } else {
                $exe, $arg = Split-UninstallCommand $cmd
                # 언인스톨러 파일 자체가 없는 잔재 키를 먼저 갈라낸다.
                # v2.8 은 그냥 실행을 시도해서 "지정된 파일을 찾을 수 없습니다: C:\Program" 만 뱉었다
                # (실측 2026-08-24 SecuKit NX: UninstallString 은 남았는데 NXUnInst.exe 는 이미 없음).
                # PATH 로 도는 것(winget 등)이 있으므로 Get-Command 도 같이 본다.
                if (-not (Test-Path $exe) -and -not (Get-Command $exe -ErrorAction SilentlyContinue)) {
                    Write-Host ("  건너뜀: {0}" -f $i.이름) -ForegroundColor DarkYellow
                    Write-Host ("     언인스톨러 파일이 없습니다 = 이미 제거되고 레지스트리 키만 남은 잔재입니다.") -ForegroundColor DarkGray
                    Write-Host ("     등록된 제거명령: {0}" -f $cmd) -ForegroundColor DarkGray
                    Write-Host  "     → 프로그램 목록에서만 지우려면 해당 Uninstall 레지스트리 키를 직접 삭제." -ForegroundColor DarkGray
                    continue
                }
                $p = if ($arg) { Start-Process $exe -ArgumentList $arg -PassThru -ErrorAction Stop }
                     else      { Start-Process $exe -PassThru -ErrorAction Stop }
            }
            # Timeout 120초: 초과 시 팝업 수동 처리 안내 (콘솔 프리징 방지)
            if ($p.WaitForExit(120000)) {
                # 종료코드도 '프로세스가 끝났다'도 제거 성공의 근거가 못 된다.
                # 언인스톨러가 팝업에서 취소돼도 정상 종료로 보인다 → 목록에서 실제로 사라졌는지 다시 본다.
                Start-Sleep 1
                if (@(Get-Targets | Where-Object { $_.KeyPath -eq $i.KeyPath })) {
                    Write-Host ("  아직 남아 있음: {0}" -f $i.이름) -ForegroundColor Yellow
                    Write-Host  "     언인스톨러가 취소됐거나 재부팅 후 완료되는 유형입니다. 메뉴1로 재확인하세요." -ForegroundColor DarkGray
                } else {
                    Write-Host "  완료: $($i.이름)" -ForegroundColor Green
                    Log-Action ("{0} 제거" -f $i.이름)
                }
            } else {
                Write-Host "  120초 초과 - 원격 화면에서 언인스톨 팝업 수동 처리 필요: $($i.이름)" -ForegroundColor Yellow
            }
        } catch {
            # 실패 사유를 반드시 찍는다. v2.6까지는 "실패: <이름>" 한 줄뿐이라
            # 경로 파싱이 깨져서 실패한 건지 언인스톨러가 거부한 건지 구분할 수 없었다.
            Write-Host ("  실패: {0}" -f $i.이름) -ForegroundColor Red
            Write-Host ("     사유: {0}" -f $_.Exception.Message) -ForegroundColor DarkRed
            Write-Host ("     제거명령: {0}" -f $cmd) -ForegroundColor DarkGray
        }
    }
    Write-Host "`n※ AhnLab Safe Transaction·nProtect는 은행/공공 사이트 접속 시 자동 재설치됨.`n" -ForegroundColor Cyan
}

# ── 2) 백신 진단 (비활성화·삭제는 수동) ─────────────────────────────
function Show-AntiVirus {
    Write-Host "`n[ 등록된 백신 (SecurityCenter) ]" -ForegroundColor Cyan
    $thirdParty = @()
    try {
        $av = Get-CimInstance -Namespace root/SecurityCenter2 -ClassName AntiVirusProduct -ErrorAction Stop
        $av | Select-Object displayName, @{n='상태';e={'{0:X}' -f $_.productState}} | Format-Table -AutoSize
        # SecurityCenter에는 이미 제거된 백신 등록이 유령으로 남는다(실측: 알약 등록만 남고 실행파일 없음).
        # 유령을 서드파티로 세면 "서드파티 때문에 Defender가 passive = 정상"이라고 잘못 안내하게 됨.
        foreach ($a in @($av | Where-Object { $_.displayName -notmatch 'Defender' })) {
            $exe = [Environment]::ExpandEnvironmentVariables([string]$a.pathToSignedProductExe)
            if ($exe -and $exe -notmatch '://' -and -not (Test-Path $exe)) {
                Write-Host ("  ※ '{0}'은 등록만 남고 실행파일 없음(제거 잔재) → 백신으로 계산 안 함" -f $a.displayName) -ForegroundColor DarkGray
            } elseif ((([int64]$a.productState) -band 0x1000) -eq 0) {
                # v3.6.12: productState 가운데 바이트 0x10 = 켜짐(널리 쓰이는 해석, MS 공식 문서 없음 - 가정).
                #  꺼진 백신을 서드파티로 세면 'Defender passive = 정상'으로 오판해 무방비를 놓친다.
                Write-Host ("  ※ '{0}'은 등록돼 있지만 꺼짐(productState {1:X}) → 보호 중인 백신으로 계산 안 함" -f $a.displayName, ([int64]$a.productState)) -ForegroundColor Yellow
            } else { $thirdParty += $a }
        }
    } catch { Write-Host "조회 실패(서버 OS이거나 권한 부족)" -ForegroundColor DarkYellow }

    # Defender 실가동 상태 (알약/V3 제거 후 자동 복귀 확인 - 새 방침 핵심)
    Write-Host "`n[ Windows Defender 실가동 상태 ]" -ForegroundColor Cyan
    try {
        $mp = Get-MpComputerStatus -ErrorAction Stop
        $rt = $mp.RealTimeProtectionEnabled
        Write-Host ("  백신:{0} / 실시간보호:{1} / 서비스:{2}" -f $mp.AntivirusEnabled, $rt, $mp.AMServiceEnabled) -ForegroundColor Gray
        if ($rt) {
            Write-Host "  → Defender 정상 가동 중 (무방비 아님)" -ForegroundColor Green
        } elseif ($thirdParty.Count -gt 0) {
            Write-Host ("  → 실시간보호 꺼짐: 서드파티 백신({0}) 때문에 대기(passive)상태 = 정상" -f (($thirdParty.displayName) -join ', ')) -ForegroundColor DarkYellow
            Write-Host "     이 백신 제거하면 Defender 자동 복귀 (제거 후 이 메뉴로 재확인)" -ForegroundColor DarkGray
        } else {
            Write-Host "  → ★경고: 서드파티 백신도 없는데 실시간보호 꺼짐 = 무방비 상태!" -ForegroundColor Red
            Write-Host "     복구: 재부팅 후 재확인 → 그래도 꺼졌으면 아래 실행" -ForegroundColor Yellow
            Write-Host "     Set-MpPreference -DisableRealtimeMonitoring `$false" -ForegroundColor DarkGray
        }
    } catch { Write-Host "  Defender 상태 조회 실패(미탑재 서버 OS 가능)" -ForegroundColor DarkYellow }

    Write-Host "`n※ [방침] 서드파티 백신(알약/V3/McAfee 등)은 제거 → Windows Defender로 일원화" -ForegroundColor Cyan
    Write-Host "   - 제거는 자기보호로 스크립트 불가 → 각 백신 UI/제어판에서 수동 제거" -ForegroundColor DarkGray
    Write-Host "   - 제거 직후 위 [Defender 실가동 상태] 실시간보호=True 반드시 확인(자동복귀 실패 대비)" -ForegroundColor DarkGray
    Write-Host "   - 청소 UI 필요하면 MS PC Manager 선택 설치(백신 아님), 아니면 저장소 센스로 충분`n" -ForegroundColor DarkGray
}

# ── 3) 확장 프로그램 목록 (OTP는 🔒삭제금지 표시) ───────────────────
function Show-Extensions {
    # location(설치경로) 코드: 브라우저가 확장을 '어떻게' 설치했는지. 삭제 가능 여부가 갈림.
    $locName = @{ 1='사용자설치'; 2='★외부설치'; 3='★외부설치(레지스트리)'; 4='개발자모드'
                  5='브라우저기본'; 6='★외부설치'; 8='명령줄'; 7='★정책강제'; 9='★정책강제'; 10='브라우저기본' }
    # v3.6.3 F03: 실행 계정이 아니라 '선생님 계정'의 프로필을 본다.
    $roots = @{ Chrome=(Join-Path $script:TargetLocalAppData 'Google\Chrome\User Data')
                Edge  =(Join-Path $script:TargetLocalAppData 'Microsoft\Edge\User Data') }
    if ($script:UserMismatch) { Write-Host ("  대상 프로필: {0}" -f $script:TargetProfile) -ForegroundColor Cyan }
    foreach ($b in $roots.Keys) {
        $root = $roots[$b]; if (-not (Test-Path $root)) { continue }
        Write-Host "`n[ $b 확장 프로그램 ]" -ForegroundColor Cyan
        $rows = @(
            Get-ChildItem $root -Directory -ErrorAction SilentlyContinue |
            Where-Object { $_.Name -eq 'Default' -or $_.Name -like 'Profile*' } |
            ForEach-Object {
                $profName = $_.Name; $dir = $_.FullName; $seen = @{}
                # 확장 정보 본체는 'Secure Preferences'에 있음. Preferences는 보조(구버전·일부 항목).
                foreach ($file in 'Secure Preferences','Preferences') {
                    $pref = Join-Path $dir $file
                    if (-not (Test-Path $pref)) { continue }
                    # -Encoding UTF8 필수: 빠지면 PS5.1이 cp949로 읽어 한글 확장명에서 JSON 파싱이 깨짐
                    try { $s = (Get-Content $pref -Raw -Encoding UTF8 | ConvertFrom-Json).extensions.settings }
                    catch { Write-Host ("  [{0}] {1} 읽기 실패" -f $profName, $file) -ForegroundColor DarkYellow; continue }
                    if (-not $s) { continue }
                    foreach ($id in $s.PSObject.Properties.Name) {
                        if ($seen.ContainsKey($id)) { continue }
                        $e = $s.$id
                        $name = $e.manifest.name
                        if ($name -like '__MSG_*') { $name = $e.manifest.short_name }   # 다국어 확장은 이름이 치환자
                        if (-not $name) { continue }
                        $seen[$id] = $true
                        $loc = [int]$e.location
                        [PSCustomObject]@{
                            프로필 = $profName; 이름 = $name; ID = $id
                            설치 = $(if ($locName.ContainsKey($loc)) { $locName[$loc] } else { '?' })
                            표시 = $(if ($KeepExtIds.ContainsKey($id)) { '[보호]삭제금지' }
                                     elseif ($KeepExtNamePatterns | Where-Object { $name -like $_ }) { '[보호]이름일치' }
                                     else { Get-ExtVerdict $name })   # v3.6.20
                        }
                    }
                }
            }
        )
        # v3.6.20: ★제거 로 걸린 건 '브라우저기본'으로 분류돼도 숨기지 않는다.
        $show = @($rows | Where-Object { $_.설치 -ne '브라우저기본' -or $_.표시 -like '★제거*' })
        if ($show) { $show | Sort-Object 프로필, 설치 | Format-Table 프로필,이름,ID,설치,표시 -AutoSize }
        else { Write-Host "  (사용자/외부 설치 확장 없음)" -ForegroundColor DarkGray }
        $builtin = $rows.Count - $show.Count
        if ($builtin -gt 0) { Write-Host ("  ※ 브라우저 내장 구성요소 {0}개는 목록에서 제외(삭제 불가)" -f $builtin) -ForegroundColor DarkGray }

        # v3.6.20: 표는 행별로 색을 못 준다 → 제거 권장만 아래에 다시 모아 노란색으로 뿌린다.
        $danger = @($show | Where-Object { $_.표시 -like '★제거*' })
        if ($danger) {
            Write-Host ("  ▶ 제거 권장 확장 {0}개 - 메뉴1(프로그램 목록)에는 안 잡힌다. 확장은 따로 지워야 한다." -f $danger.Count) -ForegroundColor Yellow
            foreach ($d in $danger) {
                Write-Host ("     · [{0}] {1}" -f $d.프로필, $d.이름) -ForegroundColor Yellow
                Write-Host ("       {0} / 설치={1} / ID={2}" -f $d.표시.Replace('★제거 ',''), $d.설치, $d.ID) -ForegroundColor DarkYellow
            }
        }
    }
    Write-Host "→ [보호](OTP·드래그프리)와 복붙용 1개만 남기고 chrome://extensions 에서 삭제." -ForegroundColor DarkGray
    Write-Host "   ★정책강제=수동삭제 불가 / ★외부설치=다른 프로그램이 심은 확장(보안모듈·애드웨어 의심)" -ForegroundColor DarkGray

    # 직접 확인/수동 삭제용: 확장 관리 페이지 바로 열기
    switch (Read-Host "확장 관리 페이지를 열까요? (c=Chrome / e=Edge / b=둘다 / n=안열기)") {
        'c' { $ce=Get-BrowserExe chrome; if($ce){ Open-BrowserPage $ce 'chrome://extensions' } else { Write-Host "  Chrome 실행파일 없음" -ForegroundColor DarkYellow } }
        'e' { $ee=Get-BrowserExe edge;   if($ee){ Open-BrowserPage $ee 'edge://extensions' }   else { Write-Host "  Edge 실행파일 없음" -ForegroundColor DarkYellow } }
        'b' {
            $ce=Get-BrowserExe chrome; if($ce){ Open-BrowserPage $ce 'chrome://extensions' }
            $ee=Get-BrowserExe edge;   if($ee){ Open-BrowserPage $ee 'edge://extensions' }
        }
        default { }
    }
    Write-Host ""
}


# ── 브라우저 업데이트 상태 수집 (v2.6.2) ────────────────────────────
# 실측(2026-08-13)으로 확인한 것: 레지스트리 버전은 믿을 수 없다.
#   chrome.exe = 151.0.7922.76 인데 pv / Uninstall\DisplayVersion 은 둘 다 151.0.7922.109.
#   new_chrome.exe(.109)가 8/6부터 교체를 기다린 채 방치돼 있었고, 서버는 pv를 보고
#   noupdate 를 답하므로 이 상태는 저절로 안 풀린다.
# → 판정 기준은 '실행파일의 파일버전' 하나뿐이다. 나머지는 어긋남을 찾는 참고값.
function Get-BrowserVersionState($isEdge) {
    $exe = if ($isEdge) { Get-BrowserExe edge } else { Get-BrowserExe chrome }
    if (-not $exe) { return $null }
    $appDir = Split-Path $exe -Parent
    $newExe = Join-Path $appDir $(if ($isEdge) { 'new_msedge.exe' } else { 'new_chrome.exe' })
    $stKey  = if ($isEdge) { 'HKLM:\SOFTWARE\WOW6432Node\Microsoft\EdgeUpdate\ClientState\{56EB18F8-B008-4CBD-B6D2-8C97FE7E9062}' }
              else         { 'HKLM:\SOFTWARE\WOW6432Node\Google\Update\ClientState\{8A69D345-D564-463c-AFF1-A69D9E530F96}' }

    # ProductVersion 에 ' (64-bit)' 같은 꼬리가 붙는 경우가 있어 숫자만 뽑는다
    function Norm($v) { if ($v -and ($v -match '(\d+(?:\.\d+){2,3})')) { $matches[1] } else { $null } }

    $running = Norm ([System.Diagnostics.FileVersionInfo]::GetVersionInfo($exe).ProductVersion)
    $staged  = if (Test-Path $newExe) { Norm ([System.Diagnostics.FileVersionInfo]::GetVersionInfo($newExe).ProductVersion) } else { $null }
    # 새 버전은 Application\<버전>\ 폴더로 먼저 풀린다. new_*.exe 가 없어도 여기서 잡힌다.
    $dirs = @(Get-ChildItem $appDir -Directory -ErrorAction SilentlyContinue |
              Where-Object { $_.Name -match '^\d+(\.\d+){3}$' } |
              ForEach-Object { [version]$_.Name } | Sort-Object)
    $newestDir = if ($dirs) { $dirs[-1].ToString() } else { $null }
    $st = Get-ItemProperty $stKey -ErrorAction SilentlyContinue

    $runV = $null; if ($running) { $runV = [version]$running }
    # 교체 대기 = 실행 중인 것보다 높은 버전이 이미 디스크에 있는 상태
    $pending = $null
    if ($runV) {
        $pending = @($staged, $newestDir) | Where-Object { $_ -and ([version]$_) -gt $runV } |
                   Sort-Object { [version]$_ } | Select-Object -Last 1
    }
    [PSCustomObject]@{
        Exe = $exe; AppDir = $appDir
        Running = $running; RunningV = $runV
        Pending = $pending; Staged = $staged; NewestDir = $newestDir
        Pv = Norm $st.pv; State = $st
        # 사용자 설치 판정에 $env:LOCALAPPDATA 를 쓰면 안 된다. 원격지원은 관리자로 승격해서
        # 도는데, 선생님 계정이 아닌 별도 관리자 계정으로 승격했으면 $env:LOCALAPPDATA 가
        # 선생님 것이 아니라서 사용자 설치 크롬을 시스템 설치로 오판한다(--system-level 오적용).
        SystemLevel = ($exe -notmatch '\\Users\\')
        Proc = $(if ($isEdge) { 'msedge' } else { 'chrome' })
    }
}

# 업데이터 로그 위치는 설치 형태마다 다르다. 한 대 기준으로 박아두면 선생님 PC
# (사용자 설치 / 크롬 117 미만 레거시)에서 그대로 빗나간다. 후보를 훑어 가장 최근 것을 쓴다.
function Get-UpdaterLogPath($vs, $isEdge) {
    if ($isEdge) {
        $c = @("$env:ProgramData\Microsoft\EdgeUpdate\Log\MicrosoftEdgeUpdate.log")
    } else {
        $c = @("${env:ProgramFiles(x86)}\Google\GoogleUpdater\updater.log",
               "$env:ProgramFiles\Google\GoogleUpdater\updater.log",
               "$env:LOCALAPPDATA\Google\GoogleUpdater\updater.log",
               (Join-Path $script:TargetLocalAppData 'Google\GoogleUpdater\updater.log'),   # v3.6.3 F03
               "$env:ProgramData\Google\Update\Log\GoogleUpdate.log")   # 크롬 117 미만(레거시 Omaha)
        # 사용자 설치면 그 사용자 프로필 밑에 있다. 승격 계정이 다를 수 있으므로
        # $env: 가 아니라 찾아낸 exe 경로에서 프로필을 직접 유도한다.
        if ($vs -and $vs.Exe -match '^(.*\\Users\\[^\\]+)\\') {
            $c += (Join-Path $matches[1] 'AppData\Local\Google\GoogleUpdater\updater.log')
        }
    }
    $hit = @($c | Where-Object { Test-Path $_ } | Get-Item | Sort-Object LastWriteTime)
    if ($hit) { $hit[-1].FullName } else { $null }
}

# 다운로드는 끝났는데 실행파일 교체(rename)가 안 끝난 상태를 강제로 마무리한다.
# 이 교체는 브라우저가 완전히 종료돼야만 일어나므로, 프로세스가 살아 있으면 시도하지 않는다.
function Invoke-PendingRename($vs, $isEdge) {
    if (Get-Process -Name $vs.Proc -ErrorAction SilentlyContinue) {
        Write-Host "  브라우저가 아직 실행 중입니다 - 완전히 종료해야 교체됩니다." -ForegroundColor Red
        return $false
    }
    # setup.exe 는 새 버전 폴더 안에 들어 있다
    $target = @($vs.Pending, $vs.NewestDir, $vs.Pv) | Where-Object { $_ } |
              Sort-Object { [version]$_ } | Select-Object -Last 1
    $setup = Join-Path $vs.AppDir "$target\Installer\setup.exe"
    if (-not (Test-Path $setup)) {
        Write-Host ("  setup.exe 를 못 찾음: {0}" -f $setup) -ForegroundColor Red
        Write-Host "  → 브라우저를 완전히 종료했다가 다시 실행하는 것으로도 교체됩니다." -ForegroundColor DarkYellow
        return $false
    }
    $swx = @('--rename-chrome-exe','--verbose-logging')
    if ($isEdge)         { $swx += '--msedge' }
    if ($vs.SystemLevel) { $swx += '--system-level' }
    Write-Host ("  실행: setup.exe {0}" -f ($swx -join ' ')) -ForegroundColor DarkGray
    try { $p = Start-Process $setup -ArgumentList $swx -PassThru -WindowStyle Hidden -ErrorAction Stop }
    catch { Write-Host ("  실행 실패: {0}" -f $_.Exception.Message) -ForegroundColor Red; return $false }
    if (-not $p.WaitForExit(60000)) { Write-Host "  60초 초과 - 교체 결과를 아래에서 확인하세요." -ForegroundColor Yellow }

    # 판정은 종료코드가 아니라 실행파일 버전이 실제로 올라갔는지로 한다
    $after = $null
    if ($vs.Running -and ([System.Diagnostics.FileVersionInfo]::GetVersionInfo($vs.Exe).ProductVersion -match '(\d+(?:\.\d+){2,3})')) { $after = $matches[1] }
    if ($after -and $vs.RunningV -and ([version]$after) -gt $vs.RunningV) {
        Write-Host ("  √ 교체 완료: {0} → {1}" -f $vs.Running, $after) -ForegroundColor Green
        return $true
    }
    Write-Host ("  교체 안 됨 (여전히 {0})" -f $after) -ForegroundColor Red
    Write-Host "  → 브라우저를 완전히 종료(작업관리자에서 잔여 프로세스까지)한 뒤 다시 실행해 보세요." -ForegroundColor DarkYellow
    return $false
}

# 업데이터 로그에서 '서버가 실제로 뭐라고 답했는지'를 읽는다.
# v2.6은 로그 파일 수정시각만 봤는데, 크래시핸들러가 뜨기만 해도 mtime 은 갱신되므로
# "업데이터가 반응함"의 근거가 못 된다. 응답 본문을 봐야 한다.
# v2.7: 결과를 못 낼 때 '로그가 없음'과 '로그는 있는데 응답 기록이 없음'을 구분한다.
#       v2.6.2는 둘 다 $null 이라 같은 문장을 뱉었는데, 원인이 달라서 대응도 다르다
#       (2026-08-14 교사 PC에서 실제로 이 메시지가 떴고 어느 쪽인지 알 수 없었다).
#       + 최근 4000줄에 없으면 파일 전체를 다시 훑는다. 로그가 수다스러우면 4000줄이
#         몇 분치밖에 안 돼서 응답을 지나칠 수 있다.
function Get-UpdateCheckResult($logPath, $isEdge) {
    if (-not $logPath -or -not (Test-Path $logPath)) {
        return [PSCustomObject]@{ Status='nolog'; ServerVersion=$null; Time=$null; LogPath=$null; Deep=$false }
    }
    foreach ($deep in $false, $true) {
        $lines = if ($deep) { @(Get-Content $logPath -ErrorAction SilentlyContinue) }
                 else       { @(Get-Content $logPath -Tail 4000 -ErrorAction SilentlyContinue) }
        $r = Read-UpdateResponse $lines $isEdge
        if ($r) {
            $r | Add-Member -NotePropertyName LogPath -NotePropertyValue $logPath -Force
            $r | Add-Member -NotePropertyName Deep    -NotePropertyValue $deep    -Force
            return $r
        }
    }
    [PSCustomObject]@{ Status='noresponse'; ServerVersion=$null; Time=$null; LogPath=$logPath; Deep=$true }
}

# v3.6.15 (외부 QA): 로그 시각 → DateTime. 형식을 못 읽으면 $null(호출부는 '오래된 응답'으로 본다).
#  크롬 = 'MM-dd HH:mm:ss'(Read-UpdateResponse 가 만든 값), 엣지 = '[MM/dd/yy HH:mm:ss.fff' 계열(가정).
function ConvertFrom-UpdateLogTime([string]$t) {
    if (-not $t) { return $null }
    $s = ($t.Trim() -replace '\.\d+$', '')
    $fmts = [string[]]@('MM/dd/yy HH:mm:ss', 'MM/dd/yyyy HH:mm:ss', 'yyyy/MM/dd HH:mm:ss', 'MM/dd HH:mm:ss', 'MM-dd HH:mm:ss')
    $d = [datetime]::MinValue
    if (-not [datetime]::TryParseExact($s, $fmts, [Globalization.CultureInfo]::InvariantCulture,
                                       [Globalization.DateTimeStyles]::None, [ref]$d)) { return $null }
    if ($d -gt (Get-Date).AddDays(1)) { $d = $d.AddYears(-1) }   # 연도 없는 형식: 12월 기록을 1월에 읽은 경우
    return $d
}

# 주어진 로그 줄 배열에서 서버 응답 1건을 뽑는다(못 찾으면 $null).
function Read-UpdateResponse($lines, $isEdge) {
    if (-not $lines) { return $null }

    if ($isEdge) {
        # [Send response received] ... "Name":"msedge-stable-win-x64","Version":"151.0.4129.78"
        for ($i = $lines.Count - 1; $i -ge 0; $i--) {
            if ($lines[$i] -notmatch 'Send response received') { continue }
            if ($lines[$i] -match 'msedge-stable-win-x64","Version":"([\d.]+)"') {
                # 버전을 먼저 확정할 것. 아래 시각 -match 가 $matches 를 덮어쓴다.
                $ver = $matches[1]
                $t = if ($lines[$i] -match '^\[([\d/]+\s[\d:.]+)\]') { $matches[1] } else { $null }
                # 엣지 로그에는 noupdate 같은 판정이 없다. 서버가 알려준 최신 버전을
                # 실행 중 버전과 대조해야 하므로 판정은 호출부로 넘긴다.
                return [PSCustomObject]@{ Status='checked'; ServerVersion=$ver; Time=$t }
            }
        }
        # 검사 자체를 안 한 경우(스로틀). Edge 는 매시간 돌면서 대부분 이 상태다.
        for ($i = $lines.Count - 1; $i -ge 0; $i--) {
            if ($lines[$i] -match 'Update check not needed at this time') {
                $t = if ($lines[$i] -match '^\[([\d/]+\s[\d:.]+)\]') { $matches[1] } else { $null }
                return [PSCustomObject]@{ Status='throttled'; ServerVersion=$null; Time=$t }
            }
        }
        return $null
    }

    # 크롬: 서버 응답이 JSON 한 줄로 남는다. appid 로 크롬 항목만 골라 status 를 읽는다.
    for ($i = $lines.Count - 1; $i -ge 0; $i--) {
        if ($lines[$i] -notmatch '"updatecheck"') { continue }
        $b = $lines[$i].IndexOf('{'); if ($b -lt 0) { continue }
        try { $r = ($lines[$i].Substring($b) | ConvertFrom-Json).response } catch { continue }
        if (-not $r) { continue }
        $app = @($r.apps | Where-Object { $_.appid -eq '{8a69d345-d564-463c-aff1-a69d9e530f96}' })[0]
        if (-not $app) { continue }
        # 응답 줄에는 시각이 없으므로 바로 앞뒤 줄의 타임스탬프(MMDD/HHMMSS)를 빌린다
        $t = $null
        for ($k = $i; $k -ge [Math]::Max(0, $i - 40); $k--) {
            if ($lines[$k] -match '(\d{2})(\d{2})/(\d{2})(\d{2})(\d{2})\.') {
                $t = '{0}-{1} {2}:{3}:{4}' -f $matches[1],$matches[2],$matches[3],$matches[4],$matches[5]; break
            }
        }
        return [PSCustomObject]@{ Status=$app.updatecheck.status; ServerVersion=$app.updatecheck.manifest.version; Time=$t }
    }

    # 크롬 117 미만 = 레거시 Omaha(GoogleUpdate.exe). 응답이 XML 이라 위 JSON 파서에 안 걸린다.
    # 선생님 PC 중에 업데이트가 오래 멈춘 것일수록 이쪽일 가능성이 높다.
    for ($i = $lines.Count - 1; $i -ge 0; $i--) {
        $idx = $lines[$i].IndexOf('8A69D345')
        if ($idx -lt 0) { $idx = $lines[$i].IndexOf('8a69d345') }
        if ($idx -lt 0) { continue }
        if ($lines[$i].Substring($idx) -match 'updatecheck[^>]*?status="([^"]+)"') {
            $stt = $matches[1]
            $t = if ($lines[$i] -match '^\[([\d/]+\s[\d:.]+)\]') { $matches[1] } else { $null }
            return [PSCustomObject]@{ Status=$stt; ServerVersion=$null; Time=$t }
        }
    }
    return $null
}
# ── LMS 사이트 권한 예외 (v3.6.8) ────────────────────────────────
#  CRM(HTTP)·화상수업앱(scoaching)·익스트라넷이 서브도메인이 달라 [*.]lms.example.com 하나로 건다.
#  Preferences 의 profile.content_settings.exceptions.<종류>['[*.]lms.example.com,*'].setting = 1(허용)
#   mixed_script        = '안전하지 않은 콘텐츠' - CRM 이 HTTP 라 필수
#   media_stream_camera = 카메라 / media_stream_mic = 마이크 - 화상수업앱
#  ※ 초기화 뒤에도 다시 넣는다. 초기화가 사이트 예외를 날리는 게 가장 흔한 부작용이었다.
#  ※ {setting:1} 최소 형식을 크롬/엣지가 인식하는지는 실측 전(미검증).
#    처음 쓸 때 사이트 정보(자물쇠)에서 권한이 '허용'으로 보이는지 확인할 것.
$LmsPattern = '[*.]lms.example.com,*'
$LmsExTypes = [ordered]@{
    'popups'              = '팝업'
    'mixed_script'        = '안전하지 않은 콘텐츠'
    'media_stream_camera' = '카메라'
    'media_stream_mic'    = '마이크'
    'sound'               = '소리'
    'notifications'       = '알림'
}
function Add-LmsExceptions($root) {
    if (-not $root.PSObject.Properties['profile']) {
        $root | Add-Member -NotePropertyName profile -NotePropertyValue ([PSCustomObject]@{}) }
    $p = $root.profile
    if (-not $p.PSObject.Properties['content_settings']) {
        $p | Add-Member -NotePropertyName content_settings -NotePropertyValue ([PSCustomObject]@{}) }
    $cs = $p.content_settings
    if (-not $cs.PSObject.Properties['exceptions']) {
        $cs | Add-Member -NotePropertyName exceptions -NotePropertyValue ([PSCustomObject]@{}) }
    $ex = $cs.exceptions
    foreach ($tp in $LmsExTypes.Keys) {
        if (-not $ex.PSObject.Properties[$tp]) {
            $ex | Add-Member -NotePropertyName $tp -NotePropertyValue ([PSCustomObject]@{}) }
        $bucket = $ex.$tp
        $cur = $bucket.PSObject.Properties[$LmsPattern]
        if ($cur -and $cur.Value -is [System.Management.Automation.PSCustomObject]) {
            if ($cur.Value.PSObject.Properties['setting']) { $cur.Value.setting = 1 }
            else { $cur.Value | Add-Member -NotePropertyName setting -NotePropertyValue 1 }
        } else {
            if ($cur) { $bucket.PSObject.Properties.Remove($LmsPattern) }
            $bucket | Add-Member -NotePropertyName $LmsPattern -NotePropertyValue ([PSCustomObject]@{ setting = 1 })
        }
    }
}

# ── 4) 브라우저 자동 정리 (v2.2: 페이지 열기 → 실제 수행으로 업그레이드) ──
# 자동: 캐시 삭제 / 쿠키 삭제(확인) / 팝업 허용(Preferences 백업 후 수정) / IE모드(정책, 확인)
# 수동 유지: 설정 초기화 마지막 클릭 1회 (실수 방지), 확장 프로그램(메뉴 4에서 별도)
function Browser-Menu {
    Write-Host "`n어느 브라우저? (c=Chrome / e=Edge / 그 외=취소)" -ForegroundColor Cyan
    $bsel   = ("" + (Read-Host)).Trim().ToLower()
    # v3.6.13 (외부 QA L2): e 가 아니면 전부 Chrome 으로 처리했다(엔터·오타 포함). 설정을 바꾸는 메뉴라 취소로 둔다.
    if ($bsel -ne 'c' -and $bsel -ne 'e') { Write-Host "  취소됨.`n" -ForegroundColor DarkGray; return }
    $isEdge = ($bsel -eq 'e')
    $name   = if ($isEdge) { 'Edge' } else { 'Chrome' }
    $proc   = if ($isEdge) { 'msedge' } else { 'chrome' }
    $prefix = if ($isEdge) { 'edge://' } else { 'chrome://' }
    $exe    = if ($isEdge) { Get-BrowserExe edge } else { Get-BrowserExe chrome }
    # v3.6.3 F03: 캐시·쿠키·Preferences 를 '변경'하는 메뉴다. 대상 프로필을 반드시 가려야 한다.
    if (-not (Test-UserScopeWritable)) { return }
    $root   = if ($isEdge) { Join-Path $script:TargetLocalAppData 'Microsoft\Edge\User Data' }
              else         { Join-Path $script:TargetLocalAppData 'Google\Chrome\User Data' }
    if ($script:UserMismatch) { Write-Host ("  대상 프로필: {0}" -f $script:TargetProfile) -ForegroundColor Cyan }
    if (-not $exe)              { Write-Host "브라우저 실행파일 못 찾음." -ForegroundColor Red; return }
    if (-not (Test-Path $root)) { Write-Host "프로필 폴더 없음: $root" -ForegroundColor Red; return }

    $profiles = @(Get-ChildItem $root -Directory -ErrorAction SilentlyContinue |
                  Where-Object { $_.Name -eq 'Default' -or $_.Name -like 'Profile *' })
    if (-not $profiles) { Write-Host "프로필 없음." -ForegroundColor Red; return }
    Write-Host ("  대상 프로필: {0}" -f (($profiles | ForEach-Object { $_.Name }) -join ', ')) -ForegroundColor DarkGray

    # [0] 정책 강제 여부 (v3.6.8) - 조치 전에 본다. 정책으로 막힌 건 아래 자동 정리로 안 풀린다.
    #  HKLM 만 본다. HKCU 는 승격 계정이 선생님과 다를 수 있어 엉뚱한 사용자를 읽는다.
    $polRoot = if ($isEdge) { 'HKLM:\SOFTWARE\Policies\Microsoft\Edge' } else { 'HKLM:\SOFTWARE\Policies\Google\Chrome' }
    $polRows = @()
    if (Test-Path $polRoot) {
        $keys = @(Get-Item $polRoot -ErrorAction SilentlyContinue) + @(Get-ChildItem $polRoot -Recurse -ErrorAction SilentlyContinue)
        foreach ($k in $keys) {
            foreach ($vn in $k.GetValueNames()) {
                $val = $k.GetValue($vn)
                if ($val -is [array]) { $val = $val -join ',' }
                $sub = ($k.Name -replace '^HKEY_LOCAL_MACHINE\\SOFTWARE\\Policies\\', '')
                $tag = if ($vn -eq 'InternetExplorerIntegrationLevel') { '  (툴킷 IE모드 차단 - 정상)' } else { '' }
                $polRows += ('{0}\{1} = {2}{3}' -f $sub, $vn, $val, $tag)
            }
        }
    }
    if ($polRows) {
        Write-Host ("`n[0] 정책 강제 {0}건 - 이 값들은 아래 자동 정리로 안 바뀝니다" -f $polRows.Count) -ForegroundColor Yellow
        $polRows | Select-Object -First 20 | ForEach-Object { Write-Host ("  {0}" -f $_) -ForegroundColor Gray }
        if ($polRows.Count -gt 20) { Write-Host ("  ... 외 {0}건 → {1}policy 에서 전체 확인" -f ($polRows.Count - 20), $prefix) -ForegroundColor DarkGray }
        Write-Host "  ※ ExtensionInstallForcelist = 확장 강제설치(지워도 되살아남) / *Blocklist = 차단 목록" -ForegroundColor DarkGray
    } else {
        Write-Host "  정책 강제 항목 없음(HKLM)" -ForegroundColor DarkGray
    }

    # [0-1] 포털 새 탭·홈 강제 정책 (v3.6.11)
    #  실측 2026-10-02: Edge\Recommended\NewTabPageLocation = http://zum.com/?af=gt, NewTabPageSetFeedType=0.
    #  선생님이 넣은 게 아니라 설치 프로그램이 심은 값(알툴즈 계열 추정 - 가정). 위 자동 정리로는 안 지워진다.
    #  값 '내용'이 포털 주소인 것만 고른다. 기관이 정한 정상 정책을 이름만 보고 지우지 않게.
    if ($polRows) {
        $hjPat  = 'zum\.com'
        $hjHits = @()
        foreach ($k in $keys) {
            $names = @($k.GetValueNames())
            foreach ($vn in $names) {
                $hv = [string]$k.GetValue($vn)
                if ($hv -match $hjPat) {
                    $hjHits += [pscustomobject]@{ Path = $k.PSPath; Name = $vn; Value = $hv }
                    if ($vn -eq 'NewTabPageLocation' -and ($names -contains 'NewTabPageSetFeedType')) {
                        $hjHits += [pscustomobject]@{ Path = $k.PSPath; Name = 'NewTabPageSetFeedType'; Value = [string]$k.GetValue('NewTabPageSetFeedType') }
                    }
                }
            }
        }
        if ($hjHits) {
            Write-Host "`n  ★ 포털 새 탭·홈 강제 정책 - 선생님이 아니라 설치 프로그램이 넣은 값" -ForegroundColor Red
            foreach ($h in $hjHits) {
                Write-Host ("    {0}\{1} = {2}" -f ($h.Path -replace '^.*?\\Policies\\', ''), $h.Name, $h.Value) -ForegroundColor Gray
            }
            Write-Host "    ※ 알툴즈·알매니저 등이 남아 있으면 다시 써 넣을 수 있음 → 메뉴1 정리와 같이 할 것" -ForegroundColor DarkGray
            if ((Read-Host "  이 값들 삭제? (y/n)") -eq 'y') {
                $hjOk = 0
                foreach ($h in $hjHits) {
                    try {
                        Remove-ItemProperty -LiteralPath $h.Path -Name $h.Name -ErrorAction Stop
                        Write-Host ("    삭제: {0}" -f $h.Name) -ForegroundColor Green; $hjOk++
                    } catch { Write-Host ("    실패: {0} ({1})" -f $h.Name, $_.Exception.Message) -ForegroundColor Red }
                }
                if ($hjOk) { Log-Action ("{0} 포털 새 탭 강제 정책 삭제(zum.com)" -f $name) }
            }
        }
    }

    # 자동 작업 전제: 브라우저 종료 (파일 잠금 해제)
    if (Get-TargetBrowserProcess $proc) {
        if ((Read-Host "$name 실행 중 - 종료해야 진행 가능. 종료? (열린 탭 사라짐) (y/n)") -ne 'y') {
            Write-Host "취소됨.`n"; return
        }
        if (-not (Stop-TargetBrowser $proc)) {
            Read-Host "  선생님 화면에서 $name 창을 모두 닫은 뒤 Enter" | Out-Null
            if (Get-TargetBrowserProcess $proc) {
                Write-Host "  아직 $name 이(가) 실행 중입니다(다른 세션 포함일 수 있음) - 취소합니다.`n" -ForegroundColor Yellow
                return
            }
        }
        Start-Sleep 2
    }

    # [1] 캐시 삭제 (북마크/비밀번호/확장 미접촉 - 안전)
    Write-Host "`n[1] 캐시 삭제" -ForegroundColor Yellow
    $freed = 0; $stuck = @()
    foreach ($pf in $profiles) {
        foreach ($sub in 'Cache','Code Cache','GPUCache') {
            $d = Join-Path $pf.FullName $sub
            if (Test-Path $d) {
                try {
                    # v3.6.3 F10: 삭제 전 크기를 그대로 '확보량'으로 더했다. 파일이 잠겨
                    #  하나도 안 지워져도 'N MB 확보'가 찍혔다. 삭제 후 남은 크기를 다시 재서
                    #  실제 줄어든 만큼만 센다.
                    $before = (Get-ChildItem $d -Recurse -File -ErrorAction SilentlyContinue |
                               Measure-Object Length -Sum).Sum
                    if (-not $before) { $before = 0 }
                    Remove-Item $d -Recurse -Force -ErrorAction SilentlyContinue
                    $after = 0
                    if (Test-Path $d) {
                        $after = (Get-ChildItem $d -Recurse -File -ErrorAction SilentlyContinue |
                                  Measure-Object Length -Sum).Sum
                        if (-not $after) { $after = 0 }
                        if ($after -gt 0) { $stuck += ('{0}  ({1:N0} MB 남음)' -f $d, ($after/1MB)) }
                    }
                    $freed += [Math]::Max(0, $before - $after)
                } catch { $stuck += ('{0}  ({1})' -f $d, $_.Exception.Message) }
            }
        }
    }
    if ($stuck) {
        Write-Host ("  일부 삭제 안 됨 - 실제 확보 약 {0:N0} MB" -f ($freed/1MB)) -ForegroundColor Yellow
        $stuck | ForEach-Object { Write-Host ("     {0}" -f $_) -ForegroundColor DarkYellow }
        Write-Host  "     브라우저 잔여 프로세스가 파일을 잡고 있을 수 있습니다(작업관리자 확인)." -ForegroundColor DarkGray
        Log-Action ("{0} 캐시 {1:N0}MB 삭제(일부 잔존)" -f $name, ($freed/1MB))
    } elseif ($freed -gt 0) {
        Write-Host ("  완료 - 약 {0:N0} MB 확보" -f ($freed/1MB)) -ForegroundColor Green
        Log-Action ("{0} 캐시 {1:N0}MB 삭제" -f $name, ($freed/1MB))
    } else {
        Write-Host "  지울 캐시가 없었습니다 (확보 0 MB)" -ForegroundColor DarkGray
    }

    # [2] 쿠키 삭제 (모든 사이트 로그아웃 - 확인 후)
    Write-Host "`n[2] 쿠키 삭제" -ForegroundColor Yellow
    if ((Read-Host "  쿠키도 삭제? 모든 사이트 재로그인 필요 (y/n)") -eq 'y') {
        # v3.6.5 R8: 삭제 결과를 확인하지 않고 '완료'로 기록했다(F10 에서 캐시만 고쳤다).
        #  브라우저가 파일을 잡고 있으면 하나도 안 지워져도 처리내역에 '쿠키 삭제'가 남는다.
        $ckDel = 0; $ckLeft = @()
        foreach ($pf in $profiles) {
            foreach ($f in 'Network\Cookies','Network\Cookies-journal') {
                $cp = Join-Path $pf.FullName $f
                if (-not (Test-Path -LiteralPath $cp)) { continue }
                Remove-Item -LiteralPath $cp -Force -ErrorAction SilentlyContinue
                if (Test-Path -LiteralPath $cp) { $ckLeft += $cp } else { $ckDel++ }
            }
        }
        if ($ckLeft) {
            Write-Host ("  일부만 삭제됨 ({0}개 삭제 / {1}개 잔존)" -f $ckDel, $ckLeft.Count) -ForegroundColor Yellow
            $ckLeft | ForEach-Object { Write-Host ("     남음: {0}" -f $_) -ForegroundColor DarkYellow }
            Write-Host  "     브라우저 잔여 프로세스가 잡고 있을 수 있습니다(작업관리자 확인)." -ForegroundColor DarkGray
            Log-Action ("{0} 쿠키 삭제(일부 잔존)" -f $name)
        } elseif ($ckDel -gt 0) {
            Write-Host ("  완료 ({0}개 삭제)" -f $ckDel) -ForegroundColor Green
            Log-Action ("{0} 쿠키 삭제" -f $name)
        } else {
            Write-Host "  지울 쿠키 파일이 없었습니다" -ForegroundColor DarkGray
        }
    } else { Write-Host "  건너뜀" -ForegroundColor DarkGray }

    # [3] 설정 초기화 + 팝업 허용 (통합 - 순서 모순 제거)
    #  y: Preferences 백업 후 삭제 → 팝업 허용만 담은 최소 파일 재생성 (완전 자동 초기화)
    #     ※ 북마크/비밀번호/방문기록은 별도 파일이라 유지됨. 검색엔진 하이재킹은
    #        Secure Preferences 소관이라 이 방식으로 초기화 안 됨(그건 UI 초기화 필요)
    #  n: 기존 Preferences에 팝업 허용만 주입
    Write-Host "`n[3] 설정 초기화 + 팝업 허용" -ForegroundColor Yellow
    Write-Host "  ※ 초기화는 사이트별 예외(마이크·카메라·'안전하지 않은 콘텐츠 허용')를 날립니다." -ForegroundColor DarkYellow
    Write-Host "     팝업이 목적이면 팝업허용만으로 충분합니다. 초기화 반복은 증상을 악화시킨 전례가 있습니다." -ForegroundColor DarkYellow
    # v3.6.8: y 가 '초기화'였다. 다른 질문이 전부 y=진행이라 y 를 이어 누르면 권장이 아닌 쪽이 실행됐다
    #  (2026-09-28 실측: 크롬·엣지 둘 다 초기화됨). 되돌리기 어려운 쪽은 단어를 입력해야만 실행한다.
    $ansReset = Read-Host "  설정 초기화까지 하려면 reset 입력 / 그 외(엔터·y)=팝업허용만[권장]"
    $doReset  = ("$ansReset".Trim() -eq 'reset')
    if ($doReset) { Write-Host "  → 초기화 진행" -ForegroundColor Yellow } else { Write-Host "  → 팝업허용만" -ForegroundColor DarkGray }
    $addLms = ((Read-Host ("  LMS 사이트 권한도 등록? [*.]lms.example.com = {0} 허용 (y/n)" -f ((@($LmsExTypes.Values)) -join '·'))) -eq 'y')
    $lmsOk  = 0
    # 백업은 실행할 때마다 새 파일로 남긴다. v2.6까지는 Preferences.bak 을 -Force 로 덮어써서
    # 같은 PC에서 두 번 돌리면 '초기화된 파일'이 백업 자리를 차지해 원본이 영영 사라졌다.
    $stamp   = Get-Date -Format yyyyMMdd_HHmmss
    $madeBak = @()
    foreach ($pf in $profiles) {
        $pref = Join-Path $pf.FullName 'Preferences'
        if (-not (Test-Path $pref)) { continue }
        $bak = "$pref.$stamp.bak"
        try {
            Copy-Item -LiteralPath $pref -Destination $bak -ErrorAction Stop
            if (-not (Test-Path -LiteralPath $bak)) { throw '백업 파일 생성 실패' }   # v3.6.13: 백업 없으면 원본을 안 건드린다
            $madeBak += $bak
            if ($doReset) {
                # 초기화하되 mixed_script(안전하지 않은 콘텐츠 허용) 예외는 살린다.
                # CRM 이 HTTP(⚠안전하지 않음)로 열리기 때문에 이 예외를 날리면 되레 증상이 악화된다
                # (2026-08-12 교사J 건: 초기화 3회가 전부 헛수고였고 부작용만 남았음).
                $keepEx = $null
                try { $keepEx = (Get-Content $bak -Raw -Encoding UTF8 | ConvertFrom-Json).profile.content_settings.exceptions.mixed_script } catch {}
                $newObj = [PSCustomObject]@{ profile = [PSCustomObject]@{
                              default_content_setting_values = [PSCustomObject]@{ popups = 1 } } }
                if ($keepEx) {
                    $newObj.profile | Add-Member -NotePropertyName content_settings `
                        -NotePropertyValue ([PSCustomObject]@{ exceptions = [PSCustomObject]@{ mixed_script = $keepEx } })
                }
                if ($addLms) { Add-LmsExceptions $newObj }
                $out = $newObj | ConvertTo-Json -Depth 100 -Compress
                [System.IO.File]::WriteAllText($pref, $out, (New-Object System.Text.UTF8Encoding($false)))
                $exN = if ($keepEx) { @($keepEx.PSObject.Properties).Count } else { 0 }
                Write-Host ("  {0}: 초기화+팝업허용 완료 (안전하지않은콘텐츠 예외 {1}건 보존)" -f $pf.Name, $exN) -ForegroundColor Green
                Log-Action ("{0} 설정 초기화+팝업 허용" -f $name)
                if ($addLms) { $lmsOk++ }
            } else {
                $j = Get-Content $bak -Raw -Encoding UTF8 | ConvertFrom-Json
                if (-not $j.PSObject.Properties['profile']) {
                    $j | Add-Member -NotePropertyName profile -NotePropertyValue ([PSCustomObject]@{})
                }
                if (-not $j.profile.PSObject.Properties['default_content_setting_values']) {
                    $j.profile | Add-Member -NotePropertyName default_content_setting_values -NotePropertyValue ([PSCustomObject]@{})
                }
                $dcsv = $j.profile.default_content_setting_values
                if ($dcsv.PSObject.Properties['popups']) { $dcsv.popups = 1 }
                else { $dcsv | Add-Member -NotePropertyName popups -NotePropertyValue 1 }
                if ($addLms) { Add-LmsExceptions $j }
                $out = $j | ConvertTo-Json -Depth 100 -Compress
                [System.IO.File]::WriteAllText($pref, $out, (New-Object System.Text.UTF8Encoding($false)))
                Write-Host ("  {0}: 팝업 허용 적용" -f $pf.Name) -ForegroundColor Green
                Log-Action ("{0} 팝업 허용" -f $name)
                if ($addLms) { $lmsOk++ }
            }
        } catch {
            Write-Host ("  {0}: 실패 → 백업 원복, 설정 페이지에서 수동 처리" -f $pf.Name) -ForegroundColor Red
            Write-Host ("     사유: {0}" -f $_.Exception.Message) -ForegroundColor DarkRed
            if (Test-Path $bak) { Copy-Item $bak $pref -Force }
        }
    }
    # 되돌리는 방법을 화면에 남긴다. 원격 중엔 이걸 못 찾아서 못 되돌리는 경우가 생긴다.
    if ($madeBak) {
        Write-Host ("  백업 {0}개 생성 (되돌리려면 브라우저 종료 후 아래 실행):" -f $madeBak.Count) -ForegroundColor DarkGray
        foreach ($b in $madeBak) { Write-Host ("     Copy-Item '{0}' '{1}' -Force" -f $b, ($b -replace '\.\d{8}_\d{6}\.bak$','')) -ForegroundColor DarkGray }
    }
    $resetUrl = if ($isEdge) { 'edge://settings/resetProfileSettings' } else { 'chrome://settings/reset' }
    Write-Host "  ※ [하이재킹 PC만] 주소창 검색이 낯선 사이트로 가거나 시작페이지가 이상하게 바뀌었으면" -ForegroundColor Yellow
    Write-Host ("     이 자동초기화로는 안 됩니다 → {0} 열어 [재설정] 1회 필요" -f $resetUrl) -ForegroundColor Yellow

    if ($addLms) {
        if ($lmsOk -gt 0) {
            Write-Host ("  LMS 사이트 권한 등록: 프로필 {0}개 ([*.]lms.example.com)" -f $lmsOk) -ForegroundColor Green
            Write-Host "     첫 접속 때 자물쇠 > 사이트 설정에서 카메라·마이크가 '허용'인지 한 번 확인" -ForegroundColor DarkGray
            Log-Action ("{0} LMS 사이트 권한 허용({1})" -f $name, ((@($LmsExTypes.Values)) -join '·'))
        } else {
            Write-Host ("  LMS 사이트 권한 등록 실패 → {0}settings/content 에서 수동 추가" -f $prefix) -ForegroundColor Red
        }
    }

    # [3-1] 하드웨어 가속 끄기 (v3.6.8, 강의채널 재생 불가용) - 'off' 입력 시에만
    #  Local State 의 hardware_acceleration_mode.enabled. 이 파일에는 저장 비밀번호 복호화 키
    #  (os_crypt)가 들어 있어 JSON 전체를 다시 쓰지 않고 해당 값만 원문 치환한다.
    Write-Host "`n[3-1] 하드웨어 가속 (강의채널 재생 불가일 때만 끔)" -ForegroundColor Yellow
    if ((Read-Host "  끄려면 off 입력 / 그 외(엔터·y)=건너뜀") -eq 'off') {
        $ls = Join-Path $root 'Local State'
        if (-not (Test-Path -LiteralPath $ls)) { Write-Host ("  Local State 없음 → {0}settings/system 에서 수동" -f $prefix) -ForegroundColor Red }
        else {
            $lsBak = "$ls.$stamp.bak"
            try {
                Copy-Item -LiteralPath $ls $lsBak -ErrorAction Stop
                $txt = [IO.File]::ReadAllText($ls, [Text.Encoding]::UTF8)
                $rx  = '("hardware_acceleration_mode"\s*:\s*\{[^{}]*?"enabled"\s*:\s*)(true|false)'
                if ($txt -match $rx) { $txt2 = [regex]::Replace($txt, $rx, '${1}false') }
                elseif ($txt.TrimStart().StartsWith('{')) {
                    $i = $txt.IndexOf('{')
                    $txt2 = $txt.Substring(0, $i + 1) + '"hardware_acceleration_mode":{"enabled":false},' + $txt.Substring($i + 1)
                } else { throw 'Local State 형식이 예상과 다름' }
                [IO.File]::WriteAllText($ls, $txt2, (New-Object System.Text.UTF8Encoding($false)))
                Write-Host "  하드웨어 가속 끔 (다음 실행부터 적용)" -ForegroundColor Green
                Write-Host ("     되돌리기: 브라우저 종료 후 Copy-Item '{0}' '{1}' -Force" -f $lsBak, $ls) -ForegroundColor DarkGray
                Log-Action ("{0} 하드웨어 가속 끔" -f $name)
            } catch {
                Write-Host ("  실패 → {0}settings/system 에서 수동 ({1})" -f $prefix, $_.Exception.Message) -ForegroundColor Red
                if (Test-Path -LiteralPath $lsBak) { Copy-Item -LiteralPath $lsBak $ls -Force }
            }
        }
    } else { Write-Host "  건너뜀" -ForegroundColor DarkGray }

    # [4] IE모드 비활성화 (Edge 전용 - 정책 레지스트리, 확인 후)
    if ($isEdge) {
        Write-Host "`n[4] IE모드 비활성화" -ForegroundColor Yellow
        Write-Host "  정책 적용 시 Edge에 '조직에서 관리' 표시가 남습니다 (동작엔 무해)" -ForegroundColor DarkGray
        $a = Read-Host "  적용? (y=정책으로 확실히 차단 / n=설정 페이지만 열기)"
        if ($a -eq 'y') {
            try {
                $iePol = 'HKLM:\SOFTWARE\Policies\Microsoft\Edge'
                # v3.6.15 (외부 QA): 기존 값을 덮어쓰고 복구는 '삭제'만 안내했다 → 변경 전 값을 읽어 둔다.
                $iePrev = $null
                try { $iePrev = (Get-ItemProperty -LiteralPath $iePol -Name 'InternetExplorerIntegrationLevel' -ErrorAction Stop).InternetExplorerIntegrationLevel } catch {}
                if ($null -ne $iePrev -and [string]$iePrev -eq '0') {
                    Write-Host "  이미 정책값 0(IE모드 꺼짐) - 변경 없음" -ForegroundColor DarkGray
                } else {
                    if (-not (Test-Path $iePol)) { New-Item $iePol -Force | Out-Null }
                    Set-ItemProperty $iePol -Name 'InternetExplorerIntegrationLevel' -Value 0 -Type DWord
                    Write-Host "  적용 완료. 되돌리려면:" -ForegroundColor Green
                    if ($null -ne $iePrev) {
                        Write-Host ("  (변경 전 값 {0})" -f $iePrev) -ForegroundColor DarkGray
                        Write-Host ("  Set-ItemProperty '{0}' -Name InternetExplorerIntegrationLevel -Value {1} -Type DWord" -f $iePol, $iePrev) -ForegroundColor DarkGray
                        Log-Action ("Edge IE모드 비활성화(정책, 이전값 {0})" -f $iePrev)
                    } else {
                        Write-Host ("  Remove-ItemProperty '{0}' -Name InternetExplorerIntegrationLevel" -f $iePol) -ForegroundColor DarkGray
                        Log-Action "Edge IE모드 비활성화(정책)"
                    }
                }
            } catch { Write-Host "  실패 → 설정 페이지에서 수동 처리" -ForegroundColor Red }
        } else { Open-BrowserPage $exe 'edge://settings/defaultBrowser' }
    }

    # [5] 브라우저 업데이트
    #  v2.6.2 전면 재작성. v2.6의 오진을 실측(2026-08-13, 이 PC)으로 확인해 고침:
    #   · chrome.exe=151.0.7922.76 인데 pv/DisplayVersion 은 둘 다 151.0.7922.109.
    #     new_chrome.exe(.109)가 8/6부터 교체를 기다린 채 8일째 방치. 크롬을 완전히 안 꺼서
    #     new_chrome.exe → chrome.exe 리네임이 일어나지 않은 상태였다.
    #   · 서버는 pv(.109)를 보고 noupdate 를 답하므로 기다려도 절대 안 풀린다.
    #   · v2.6은 버전을 Uninstall\DisplayVersion 에서만 읽어 pv와 비교 → 둘 다 .109 →
    #     "이미 최신" 초록불. 정작 돌아가는 .76 은 한 번도 안 봤다. 완전한 오진.
    #   → 기준을 '실행파일 파일버전'으로 바꾸고, 대기 상태면 setup.exe 로 교체를 끝낸다.
    #   → 성공 판정도 로그 mtime → 서버 응답(updatecheck.status) 파싱으로 교체.
    Write-Host "`n[5] 브라우저 업데이트" -ForegroundColor Yellow
    $res = $null   # v3.6.8: 아래 (i) 대기 판단에 쓴다. 상위 스코프 값이 새어 들어오지 않게 비워 둔다
    $vs = Get-BrowserVersionState $isEdge
    if (-not $vs -or -not $vs.Running) {
        Write-Host "  실행파일 버전을 못 읽어 건너뜁니다." -ForegroundColor Red
    } else {

    Write-Host ("  실행 중  : {0}   ← 지금 쓰는 버전(유일하게 믿을 값)" -f $vs.Running) -ForegroundColor Gray
    if ($vs.Pv)      { Write-Host ("  업데이터 : {0}   ← 서버는 이 값을 보고 최신 여부를 답함" -f $vs.Pv) -ForegroundColor Gray }
    if ($vs.Pending) { Write-Host ("  교체 대기: {0}   ← 다운로드는 이미 끝남" -f $vs.Pending) -ForegroundColor Cyan }

    # (a) ★ 최빈 케이스 - 재시작 대기 고착.
    #     다운로드/설치는 끝났는데 실행파일 교체만 안 된 상태. 브라우저를 며칠씩 안 끄면 이렇게 된다.
    #     이때 서버는 이미 최신이라 답하므로 '기다리면 되겠지'로는 영원히 안 올라간다.
    if ($vs.Pending) {
        Write-Host "`n  ★ 업데이트가 '재시작 대기' 상태로 멈춰 있습니다." -ForegroundColor Red
        Write-Host ("     {0} 로 올릴 파일은 이미 받아놨는데, 브라우저를 완전히 종료한 적이 없어" -f $vs.Pending) -ForegroundColor Yellow
        Write-Host "     실행파일 교체가 미뤄졌습니다. 서버는 이미 최신이라 답하므로 저절로 안 풀립니다." -ForegroundColor Yellow
        if ((Read-Host "  지금 교체를 끝낼까요? (y/n)") -eq 'y') {
            if (Invoke-PendingRename $vs $isEdge) {
                Log-Action ("{0} 업데이트 적용({1})" -f $name, $vs.Pending)
                $vs = Get-BrowserVersionState $isEdge
            }
        }
    }
    # (b) 교체 대기도 아닌데 업데이터 기록이 더 높다 = 설치가 중간에 깨진 흔적
    elseif ($vs.Pv -and ([version]$vs.Pv) -gt $vs.RunningV) {
        Write-Host ("`n  ★ 업데이터는 {0} 설치를 기록했는데 실제 실행파일은 {1} 입니다." -f $vs.Pv, $vs.Running) -ForegroundColor Red
        Write-Host "     설치가 중간에 끊긴 흔적 - 남은 파일이 없으므로 재설치가 빠릅니다." -ForegroundColor Yellow
    }

    # (c) 지난 설치 실패 기록 (한글 원문이 있으면 그대로 - 제일 빠른 단서)
    if ($vs.State -and $vs.State.LastInstallerError -and [int]$vs.State.LastInstallerError -ne 0) {
        Write-Host ("  ※ 지난 설치 오류 기록: {0} (과거 기록이며 현재 상태와 다를 수 있음)" -f $vs.State.LastInstallerError) -ForegroundColor DarkGray
        if ($vs.State.LastInstallerResultUIString) { Write-Host ("     └ {0}" -f $vs.State.LastInstallerResultUIString) -ForegroundColor DarkYellow }
    }

    # (d) 업데이트 서비스 복구(사용안함 → 수동). 최적화툴이 꺼놓는 대표 항목.
    $svcNames = if ($isEdge) { @('edgeupdate','edgeupdatem') }
                else { @('gupdate','gupdatem') + @(Get-Service -Name 'GoogleUpdater*' -ErrorAction SilentlyContinue | Select-Object -ExpandProperty Name) }
    $svcFound = @()
    foreach ($s in $svcNames) {
        $svc = Get-Service -Name $s -ErrorAction SilentlyContinue
        if (-not $svc) { continue }
        $svcFound += $s
        if ($svc.StartType -eq 'Disabled') {
            try { Set-Service $s -StartupType Manual -ErrorAction Stop
                  Write-Host "  서비스 복구: $s (사용안함→수동)" -ForegroundColor DarkYellow
                  Log-Action ("{0} 업데이트서비스 복구" -f $name) } catch {}
        }
        try { Start-Service $s -ErrorAction SilentlyContinue } catch {}
    }

    # (e) 자동업데이트 차단 정책
    $polPath = if ($isEdge) { 'HKLM:\SOFTWARE\Policies\Microsoft\EdgeUpdate' } else { 'HKLM:\SOFTWARE\Policies\Google\Update' }
    $appPol  = if ($isEdge) { 'Update{56EB18F8-B008-4CBD-B6D2-8C97FE7E9062}' } else { 'Update{8A69D345-D564-463c-AFF1-A69D9E530F96}' }
    if (Test-Path $polPath) {
        $pol = Get-ItemProperty $polPath -ErrorAction SilentlyContinue
        foreach ($pn in @('UpdateDefault', $appPol, 'AutoUpdateCheckPeriodMinutes')) {
            if ($null -eq $pol.$pn -or [int]$pol.$pn -ne 0) { continue }
            Write-Host ("  ★ 자동업데이트 차단 정책: {0} = 0" -f $pn) -ForegroundColor Red
            Write-Host ("     {0}" -f $polPath) -ForegroundColor DarkGray
            if ((Read-Host "     해제할까요? (y/n)") -eq 'y') {
                try {
                    # 점검주기 0 = '검사 안 함'. 기본값으로 되돌리려면 값 자체를 지우는 게 맞다.
                    if ($pn -eq 'AutoUpdateCheckPeriodMinutes') { Remove-ItemProperty $polPath -Name $pn -ErrorAction Stop }
                    else { Set-ItemProperty $polPath -Name $pn -Value 1 -Type DWord -ErrorAction Stop }
                    Write-Host "     해제 완료" -ForegroundColor Green
                    Log-Action ("{0} 업데이트 차단정책 해제({1})" -f $name, $pn)
                } catch { Write-Host "     실패" -ForegroundColor Red }
            }
        }
    }

    # (f) 자동 실행 경로 점검.
    #     v2.6은 예약작업이 0건이면 무조건 '최적화툴이 지움 → 재설치'를 띄웠는데 오탐이다.
    #     최신 크롬/엣지는 예약작업 대신 서비스로도 돈다(실측: GoogleUpdaterService152.x, edgeupdate).
    #     둘 다 없을 때만 경고한다.
    $taskPat = if ($isEdge) { 'EdgeUpdate' } else { 'GoogleUpdate' }
    $tk = @()
    try { $tk = @(Get-ScheduledTask -ErrorAction Stop | Where-Object { $_.TaskName -like "*$taskPat*" } | ForEach-Object { $_.TaskPath + $_.TaskName }) }
    catch { $tk = @(schtasks /query /fo csv /nh 2>$null | ConvertFrom-Csv -Header T | Where-Object { $_.T -like "*$taskPat*" } | ForEach-Object { $_.T }) }
    if (-not $tk -and -not $svcFound) {
        Write-Host "  ★ 예약작업도 서비스도 없음 - 자동 업데이트 경로가 통째로 사라졌습니다." -ForegroundColor Red
        Write-Host "     (최적화툴이 지운 경우) 강제 실행이 되더라도 '자동'은 계속 안 됨 → 재설치 권장" -ForegroundColor DarkYellow
    } elseif (-not $tk) {
        Write-Host ("  예약작업 없음 - 단, 업데이트 서비스({0})가 있으므로 정상입니다." -f ($svcFound -join ', ')) -ForegroundColor DarkGray
    }

    # (g) 서버 검사 강제 실행.
    #     종료코드는 못 믿는다(실측: CoCreateInstance 실패 후에도 0 반환). 아래 (h)에서 응답으로 판정.
    $updLog = Get-UpdaterLogPath $vs $isEdge
    $tried = @()
    # 업데이터는 자기 로그를 못 쓰면 '현재 작업 디렉터리'에 debug.log 를 떨군다.
    # Run-Toolkit.bat 이 스크립트 폴더로 cd 하므로 그냥 두면 선생님 PC에 찌꺼기가 남는다
    # (이 툴킷은 흔적을 안 남기는 게 방침). 작업 디렉터리를 TEMP 로 고정해서 막는다.
    $wd = $env:TEMP
    if ($isEdge) {
        foreach ($b in @("${env:ProgramFiles(x86)}\Microsoft\EdgeUpdate\MicrosoftEdgeUpdate.exe","$env:ProgramFiles\Microsoft\EdgeUpdate\MicrosoftEdgeUpdate.exe")) {
            if (Test-Path $b) { try { Start-Process $b -ArgumentList '/ua','/installsource','scheduler' -WorkingDirectory $wd -ErrorAction Stop; $tried += 'MicrosoftEdgeUpdate /ua' } catch {}; break }
        }
    } else {
        # 크롬 117+ 는 신형 GoogleUpdater. 시스템 설치인데 --system 을 빼면 사용자 스코프로 헛돈다.
        # 사용자 설치 크롬은 업데이터도 그 사용자 프로필 밑에 있으므로 exe 경로에서 유도해 같이 훑는다.
        $updRoots = @("${env:ProgramFiles(x86)}\Google\GoogleUpdater","$env:ProgramFiles\Google\GoogleUpdater")
        if ($vs.Exe -match '^(.*\\Users\\[^\\]+)\\') { $updRoots += (Join-Path $matches[1] 'AppData\Local\Google\GoogleUpdater') }
        $nu = Get-ChildItem $updRoots -Filter updater.exe -Recurse -ErrorAction SilentlyContinue |
              Sort-Object LastWriteTime | Select-Object -Last 1
        if ($nu) {
            $wk = @('--wake'); if ($vs.SystemLevel) { $wk += '--system' }
            try { Start-Process $nu.FullName -ArgumentList $wk -WindowStyle Hidden -WorkingDirectory $wd -ErrorAction Stop; $tried += ('updater.exe ' + ($wk -join ' ')) } catch {}
        }
        foreach ($b in @("${env:ProgramFiles(x86)}\Google\Update\GoogleUpdate.exe","$env:ProgramFiles\Google\Update\GoogleUpdate.exe")) {
            if (Test-Path $b) { try { Start-Process $b -ArgumentList '/ua','/installsource','scheduler' -WorkingDirectory $wd -ErrorAction Stop; $tried += 'GoogleUpdate.exe /ua' } catch {}; break }
        }
    }
    foreach ($t in $tk) { schtasks /run /tn $t 2>$null | Out-Null; if ($LASTEXITCODE -eq 0) { $tried += ('작업:' + $t.TrimStart('\')) } }
    if ($tried) { Write-Host ("  검사 실행: {0}" -f ($tried -join ' / ')) -ForegroundColor DarkGray; Start-Sleep 10 }
    else        { Write-Host "  업데이터를 못 찾음 → 재설치 필요" -ForegroundColor Red }

    # (h) 서버가 실제로 뭐라고 답했는지로 판정
    $res = Get-UpdateCheckResult $updLog $isEdge
    # v3.6.15 (외부 QA): 로그의 '마지막 서버 응답'이 몇 주 전 것이어도 최신으로 확정했다.
    #  방금 검사를 깨웠는데 새 응답이 안 남았다면 그 옛 응답으로 지금 최신인지 말할 수 없다.
    $resFresh = $false; $resAge = '시각 판독 불가'
    if ($res -and $res.Time) {
        $rtm = ConvertFrom-UpdateLogTime ([string]$res.Time)
        if ($rtm) {
            $ah = ((Get-Date) - $rtm).TotalHours
            $resFresh = ($ah -le 48)
            $resAge = if ($ah -lt 24) { '{0:N0}시간 전' -f $ah } else { '{0:N0}일 전' -f ($ah / 24) }
        }
    }
    if ($res.Deep) { Write-Host "  (최근 로그엔 없어 파일 전체를 다시 훑었습니다)" -ForegroundColor DarkGray }
    if (-not $res -or $res.Status -eq 'nolog') {
        # 업데이터가 아예 안 돌았거나 로그 위치가 예상 밖 = 업데이터 자체를 의심할 자리
        Write-Host "  → 업데이터 로그 파일을 못 찾음. 업데이터가 한 번도 안 돌았을 수 있습니다." -ForegroundColor Red
        Write-Host "     찾은 위치가 없으므로 재설치가 가장 빠릅니다. (help 페이지에서 먼저 확인)" -ForegroundColor DarkYellow
    } elseif ($res.Status -eq 'noresponse') {
        # 로그는 있으니 업데이터는 산다. 서버에 안 물어봤을 뿐 = 대개 스로틀. 재설치 대상 아님.
        Write-Host "  → 로그는 있는데 서버 응답 기록이 없음 = 아직 서버에 안 물어본 상태(스로틀)." -ForegroundColor DarkYellow
        Write-Host ("     로그: {0}" -f $res.LogPath) -ForegroundColor DarkGray
        Write-Host "     help 페이지를 열면 브라우저가 즉시 검사합니다. 재설치할 상황은 아닙니다." -ForegroundColor DarkGray
    } elseif ($res.Status -eq 'throttled') {
        Write-Host ("  → 아직 검사 주기가 안 됨(마지막 확인 {0}). help 페이지를 열면 즉시 검사합니다." -f $res.Time) -ForegroundColor DarkYellow
    } elseif ($res.Status -eq 'noupdate') {
        if ($vs.Pending) {
            # 여기서 초록불을 띄우면 안 된다. 서버는 pv 기준으로 답한 것이고 실제 실행 버전은 그보다 낮다.
            Write-Host ("  → 서버 응답 'noupdate' - 단 이건 업데이터 기록({0}) 기준입니다." -f $vs.Pv) -ForegroundColor DarkYellow
            Write-Host ("     실제 실행 버전은 여전히 {0} 이므로 답은 업데이트가 아니라 위의 '교체'입니다." -f $vs.Running) -ForegroundColor Red
            Log-Action ("{0} 업데이트 교체대기 확인({1})" -f $name, $vs.Pending)
        } else {
            if ($resFresh) {
                Write-Host ("  → 서버 응답 'noupdate' = 이 PC는 최신 (확인 시각 {0})" -f $res.Time) -ForegroundColor Green
                Log-Action ("{0} 업데이트 확인(최신)" -f $name)
            } else {
                Write-Host ("  → 마지막 서버 응답 'noupdate' 는 {0} ({1}) 기록 - 지금도 최신인지는 help 페이지 검사로 확인" -f $res.Time, $resAge) -ForegroundColor DarkYellow
            }
        }
    } elseif ($res.Status -eq 'ok') {
        Write-Host ("  → 새 버전 {0} 있음. 백그라운드 다운로드 30~90초 후 재시작하면 적용됩니다." -f $res.ServerVersion) -ForegroundColor Cyan
        Log-Action ("{0} 업데이트 다운로드 시작({1})" -f $name, $res.ServerVersion)
    } elseif ($res.Status -eq 'checked') {
        # 엣지: 서버가 알려준 최신 버전을 실행 중 버전과 직접 대조
        if ($res.ServerVersion -and ([version]$res.ServerVersion) -gt $vs.RunningV) {
            Write-Host ("  → 서버 최신 {0} > 현재 {1}. 업데이트 대상입니다(재시작 필요)." -f $res.ServerVersion, $vs.Running) -ForegroundColor Cyan
            Log-Action ("{0} 업데이트 대상 확인({1})" -f $name, $res.ServerVersion)
        } else {
            if ($resFresh) {
                Write-Host ("  → 서버 최신 {0} = 현재 버전. 최신입니다. (확인 시각 {1})" -f $res.ServerVersion, $res.Time) -ForegroundColor Green
                Log-Action ("{0} 업데이트 확인(최신)" -f $name)
            } else {
                Write-Host ("  → 마지막 서버 응답({0}, {1})의 최신 {2} = 현재 버전 - 오래된 응답이라 지금도 최신인지는 help 페이지 검사로 확인" -f $res.Time, $resAge, $res.ServerVersion) -ForegroundColor DarkYellow
            }
            if ($vs.Pending) { Write-Host "     ※ 단, 위 '교체 대기'가 남아 있으면 실제로는 옛 버전이 돌아갑니다." -ForegroundColor Red }
        }
    } else {
        Write-Host ("  → 서버 응답: {0}  (오류면 보안프로그램 차단/프록시 확인)" -f $res.Status) -ForegroundColor DarkYellow
    }

    }

    # (i) help 페이지 = 브라우저가 스스로 즉시 검사. 스로틀을 무시하는 가장 확실한 방법.
    # v3.6.8: 여기서 끝내면 [다시 시작] 클릭과 버전 재확인이 매번 사람 몫이었다(2026-09-28 지적).
    #  help 페이지를 연 뒤 5초 간격으로 최대 120초 동안 본다.
    #   · 실행파일 버전이 올라감 = 브라우저가 꺼져 있던 사이 바로 설치됨 → 완료
    #   · 교체 대기(new_*.exe / 새 버전 폴더) 생김 = 다운로드 끝 → 종료·교체·재실행
    #  서버가 이미 '최신'이라 답했고 교체 대기도 없으면 기다리지 않는다.
    Open-BrowserPage $exe ($prefix + 'settings/help')
    $latestKnown = $false
    if ($vs -and $vs.RunningV -and -not $vs.Pending -and $res) {
        if ($res.Status -eq 'noupdate' -and $resFresh) { $latestKnown = $true }
        elseif ($res.Status -eq 'checked' -and $resFresh -and $res.ServerVersion -and ([version]$res.ServerVersion) -le $vs.RunningV) { $latestKnown = $true }
    }
    if ($latestKnown) {
        Write-Host "  → settings/help 열림. 서버가 최신이라 답했으므로 기다리지 않습니다." -ForegroundColor Green
        Write-Host "     help 페이지에 [다시 시작] 버튼이 보일 때만 누르면 됩니다." -ForegroundColor DarkGray
    } else {
        Write-Host "  → settings/help 열림 - 새 버전 다운로드를 최대 120초 기다립니다 (Ctrl+C 로 중단)" -ForegroundColor Green
        $base = Get-BrowserVersionState $isEdge
        $done = $false
        if ($base -and $base.RunningV) {
            for ($w = 1; $w -le 24; $w++) {
                Start-Sleep 5
                Write-Host ("`r  대기 {0,3}초" -f ($w * 5)) -NoNewline -ForegroundColor DarkGray
                $cur = Get-BrowserVersionState $isEdge
                if (-not $cur -or -not $cur.RunningV) { continue }
                if ($cur.RunningV -gt $base.RunningV) {
                    Write-Host ""
                    Write-Host ("  √ 설치 완료: {0} → {1}" -f $base.Running, $cur.Running) -ForegroundColor Green
                    Log-Action ("{0} 업데이트 적용({1})" -f $name, $cur.Running)
                    $done = $true; break
                }
                if ($cur.Pending) {
                    Write-Host ""
                    Write-Host ("  새 버전 {0} 다운로드 완료 - 재시작해야 적용됩니다." -f $cur.Pending) -ForegroundColor Cyan
                    if ((Read-Host "  지금 브라우저를 재시작해 적용할까요? (y/n)") -eq 'y') {
                        if (Stop-TargetBrowser $cur.Proc) {
                            for ($z = 0; $z -lt 10 -and (Get-TargetBrowserProcess $cur.Proc); $z++) { Start-Sleep 1 }
                            if (Invoke-PendingRename $cur $isEdge) {
                                Log-Action ("{0} 업데이트 적용({1})" -f $name, $cur.Pending)
                            }
                            Open-BrowserPage $exe ($prefix + 'settings/help')
                            Write-Host "  → help 페이지가 '최신 버전'이면 끝입니다." -ForegroundColor Green
                        } else {
                            Write-Host "  → 선생님 화면에서 help 페이지의 [다시 시작]을 눌러 적용하세요." -ForegroundColor DarkYellow
                        }
                    } else {
                        Write-Host "  건너뜀 - help 페이지의 [다시 시작]을 눌러야 적용됩니다." -ForegroundColor DarkYellow
                    }
                    $done = $true; break
                }
            }
            if (-not $done) {
                Write-Host ""
                Write-Host "  120초 안에 새 버전이 안 보였습니다 = 이미 최신이거나 다운로드가 느린 상태." -ForegroundColor DarkGray
                Write-Host "     help 페이지에 [다시 시작] 버튼이 보이면 누르고, '최신 버전'이면 끝입니다." -ForegroundColor DarkGray
            }
        } else {
            Write-Host "     실행파일 버전을 못 읽어 대기하지 않습니다. help 페이지에서 직접 확인하세요." -ForegroundColor DarkYellow
        }
    }

    # [6] 자동 HTTPS (Edge, v3.6.11) - 맨 끝에 둔다. 위 단계들이 브라우저를 닫고 다시 열기 때문.
    #  실측 2026-10-02: 스위치 ON + 재시작 → http 강의 창 주소가 https 로 열림.
    #  정책 HttpsUpgradesEnabled=1 은 스위치도 안 켜고 동작도 안 바꿨다(실측) → 스위치를 직접 켜게 한다.
    if ($isEdge) {
        Write-Host "`n[6] 자동 HTTPS 켜기 (http 주소를 https 로 열기)" -ForegroundColor Yellow
        Write-Host "  강의채널 강의 창이 http 로 열리면 Agent 가 정상이어도 재생이 안 됩니다." -ForegroundColor DarkGray
        Write-Host "  설정의 '자동 HTTPS로 더 안전한 연결로 자동 전환' 스위치를 켜고 Edge 를 재시작하면 https 로 열립니다." -ForegroundColor DarkGray
        Write-Host "  ※ 정책으로는 안 켜집니다 - 스위치를 직접 켤 것" -ForegroundColor DarkGray
        if ((Read-Host "  설정 페이지 열기? (y/n)") -eq 'y') {
            Open-BrowserPage $exe 'edge://settings/?search=https'
            Write-Host "  → 스위치를 켠 뒤 Edge 를 완전히 닫았다가 다시 여세요." -ForegroundColor Green
        }
    }
    Write-Host ""
}

# DLL 경로의 '소유 프로그램' 을 찾는다.
#  주의: 파일의 회사명(FileVersionInfo)을 쓰면 안 된다 - PengcaStudio 가 재배포한
#  obs-virtualcam-module 도 회사명은 OBS 로 찍히므로 정확히 반대로 속는다.
#  설치 프로그램의 InstallLocation 이 DLL 경로의 상위인지로 판정한다(가장 깊게 일치하는 것).
function Get-DllOwnerName([string]$dll) {
    $paths = @('HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Uninstall\*',
               'HKLM:\SOFTWARE\WOW6432Node\Microsoft\Windows\CurrentVersion\Uninstall\*',
               (Get-UserRegPath 'SOFTWARE\Microsoft\Windows\CurrentVersion\Uninstall\*')) | Where-Object { $_ }
    $best = $null; $len = 0
    foreach ($p in $paths) {
        Get-ItemProperty $p -ErrorAction SilentlyContinue |
        Where-Object { $_.DisplayName -and $_.InstallLocation } |
        ForEach-Object {
            $loc = $_.InstallLocation.Trim().TrimEnd('\')
            # 드라이브 루트(C:\)로 등록된 프로그램이 있다 - 그걸 허용하면 모든 DLL이 그 프로그램 소유가 된다.
            # (실측 2026-08-20: 그래서 obs-studio 의 DLL 이 엉뚱한 프로그램 소유로 나왔다)
            # -like 는 경로 안의 [ ] 를 와일드카드로 먹으므로 StartsWith 로 정확히 비교한다.
            if ($loc.Length -gt 3 -and $loc.Length -gt $len -and
                $dll.StartsWith(($loc + '\'), [StringComparison]::OrdinalIgnoreCase)) {
                $best = $_.DisplayName; $len = $loc.Length
            }
        }
    }
    if ($best) { return $best }
    # 등록 정보가 없으면 Program Files 바로 아래 폴더명으로 대체
    # 작은따옴표라 백슬래시가 그대로 정규식으로 간다 - 반드시 이스케이프할 것.
    # v2.8 은 '\Program'(=불완전 \p{} 이스케이프) + '[^\]'(=미종결 문자클래스)라 예외가 났다.
    $m = [regex]::Match($dll, '(?i)^[A-Za-z]:\\Program Files( \(x86\))?\\([^\\]+)')
    if ($m.Success) { return ($m.Groups[2].Value + ' (설치등록 없음·폴더명)') }
    return ((Split-Path (Split-Path $dll -Parent) -Leaf) + ' (폴더명)')
}

# ── 6) 장치·드라이버·서비스 확인 (XSplit/VCam 등, 삭제는 수동) ──────
function Show-DeviceCheck {
    Write-Host "`n=== 장치·드라이버·서비스 확인 (삭제 자동화 없음. 목록 확인 후 수동 처리) ===" -ForegroundColor Cyan

    # (1) 유령 가상카메라 장치 - XSplit VCam 등
    Write-Host "`n[1] 카메라 클래스 장치 (XSplit/VCam 유령장치 확인)" -ForegroundColor Yellow
    # v3.4: -Class 'Camera','Image' 를 걷어냈다. 그 클래스가 등록된 적 없는 PC 에서는
    #  에러 레코드가 난다(v3.2 가 메뉴10 에서 고친 그 자리인데 여기만 남아 있었다).
    #  그리고 메뉴10 은 이름 매칭까지 하는데 여기는 안 해서, 같은 세션에서 두 메뉴가
    #  서로 다른 카메라 목록을 냈다 → 기준을 메뉴10 과 맞추고 Class 도 같이 찍는다.
    try {
        $cams = Get-PnpDevice -ErrorAction Stop |
                Where-Object { $_.Class -in @('Camera','Image') -or $_.FriendlyName -match 'camera|웹캠|webcam' } |
                Select-Object Status, Class, FriendlyName, InstanceId
        if ($cams) {
            $cams | ForEach-Object {
                # 'Windows Virtual Camera Device'(Class=SoftwareDevice, c_swdevice.inf)는
                #  Win11 기본 구성요소다. 이름에 Virtual 이 들어간다고 유령으로 몰면
                #  선생님 PC 의 정상 구성요소를 지우라고 안내하게 된다(2026-09-08 실측).
                $ghost = ($_.FriendlyName -match 'XSplit|VCam|Virtual|가상') -and
                         ($_.FriendlyName -notmatch '^Windows Virtual Camera')
                $tag = if ($ghost) { '  ← 유령의심(수동삭제 검토)' } else { '' }
                Write-Host ("  [{0}/{1}] {2}{3}" -f $_.Class, $_.Status, $_.FriendlyName, $tag) -ForegroundColor $(if($ghost){'Red'}else{'Gray'})
            }
        } else { Write-Host "  카메라 장치 없음" -ForegroundColor DarkGray }
    } catch { Write-Host "  조회 실패(Get-PnpDevice 미지원)" -ForegroundColor DarkYellow }
    Write-Host "  → 장치관리자에서 유령의심 항목 우클릭 [디바이스 제거] +" -ForegroundColor DarkGray
    Write-Host "     '이 장치의 드라이버 소프트웨어를 삭제합니다' 체크 권장" -ForegroundColor DarkGray

    # (1-2) DirectShow 비디오 입력 장치 - PnP 가 아니라 Get-PnpDevice 로는 원리적으로 안 잡힌다.
    #  2026-08-20 교사K 교사 건: 화상수업앱 카메라 목록의 'OBS Virtual Camera' 가 위 [1] 에는
    #  전혀 안 나왔다(XSplit VCam 은 나왔다). 가상카메라는 DirectShow 필터로 등록되기 때문이다.
    #  그리고 그 필터의 주인은 OBS Studio 가 아니라 PengcaStudio 였다 - OBS 가 GPL 이라
    #  파생 프로그램이 obs-virtualcam-module*.dll 을 그대로 재배포한다.
    #  ★ 이름이 아니라 InprocServer32 의 DLL 경로가 소유자다. 이름으로 단정하지 말 것.
    Write-Host "`n[1-2] DirectShow 비디오 입력 장치 (가상카메라 - 소유 프로그램 대조)" -ForegroundColor Yellow
    $dsCat = '{860BB310-5D01-11d0-BD3B-00A0C911CE86}'   # CLSID_VideoInputDeviceCategory
    $dsAny = $false
    foreach ($view in @('', 'WOW6432Node\')) {
        $bit  = if ($view) { '32bit' } else { '64bit' }
        $base = "HKLM:\SOFTWARE\Classes\$($view)CLSID\$dsCat\Instance"
        if (-not (Test-Path $base)) { continue }
        foreach ($k in (Get-ChildItem $base -ErrorAction SilentlyContinue)) {
            $dsAny = $true
            $nm  = (Get-ItemProperty $k.PSPath -ErrorAction SilentlyContinue).FriendlyName
            if (-not $nm) { $nm = '(이름없음)' }
            $cls = $k.PSChildName
            $dll = (Get-ItemProperty "HKLM:\SOFTWARE\Classes\$($view)CLSID\$cls\InprocServer32" -ErrorAction SilentlyContinue).'(default)'
            if ($dll) {
                $dll = $dll.Trim('"')
                if (Test-Path $dll) {
                    $owner = Get-DllOwnerName $dll
                    Write-Host ("  [{0}] {1}   ← 소유: {2}" -f $bit, $nm, $owner) -ForegroundColor Gray
                } else {
                    Write-Host ("  [{0}] {1}   ← 유령등록(DLL 없음)" -f $bit, $nm) -ForegroundColor Red
                }
                Write-Host ("        {0}" -f $dll) -ForegroundColor DarkGray
            } else {
                Write-Host ("  [{0}] {1}   ← InprocServer32 없음" -f $bit, $nm) -ForegroundColor DarkYellow
            }
        }
    }
    if (-not $dsAny) { Write-Host "  DirectShow 가상카메라 등록 없음" -ForegroundColor DarkGray }
    Write-Host "  ※ 'OBS Virtual Camera' 라도 OBS Studio 설치를 뜻하지 않는다. 소유자는 위 DLL 경로다." -ForegroundColor DarkGray
    Write-Host '  → 등록 해제:  regsvr32 /u "DLL경로"' -ForegroundColor DarkGray
    Write-Host '     32bit 모듈은  C:\Windows\SysWOW64\regsvr32.exe /u "DLL경로"   (되돌리기는 /u 빼고 실행)' -ForegroundColor DarkGray

    # (2) 잔존 드라이버 패키지 (체크박스로 지워야 할 드라이버가 남았는지)
    Write-Host "`n[2] 잔존 서드파티 드라이버 패키지 (pnputil)" -ForegroundColor Yellow
    try {
        $drv = pnputil /enum-drivers 2>$null | Out-String
        $found = $false; $foundCam = $false; $foundSec = $false
        foreach ($m in [regex]::Matches($drv, '(?s)(oem\d+\.inf).*?(?=oem\d+\.inf|$)')) {
            $blk = $m.Value
            if ($blk -match 'XSplit|VCam|Virtual Cam|nProtect|TouchEn|NXISAS|AhnLab|Veraport|WIZVERA|MarkAny|IPinside') {
                $inf = ($blk -split '\s')[0]
                $found = $true
                $isCam = ($blk -match 'XSplit|VCam|Virtual Cam')
                if ($isCam) { $foundCam = $true } else { $foundSec = $true }
                Write-Host ("  잔존 드라이버: {0} ({1})" -f $inf, $(if ($isCam) { '가상카메라 계열' } else { '보안모듈 계열' })) -ForegroundColor Red
            }
        }
        if (-not $found) { Write-Host "  관련 잔존 드라이버 패키지 없음(또는 미검출)" -ForegroundColor DarkGray }
        # v3.6.13 (외부 QA H2): 보안모듈 드라이버를 pnputil 로 끊으라고 안내했었다. 네트워크 스택 보안모듈을
        #  드라이버 단위로 끊었다가 인터넷 불통이 난 실측(2026-09-07) → 정식 제거만 안내한다.
        if ($foundCam) { Write-Host "  → 가상카메라 드라이버 삭제(수동): pnputil /delete-driver oemXX.inf /uninstall /force" -ForegroundColor DarkGray }
        if ($foundSec) {
            Write-Host "  → 보안모듈 드라이버는 직접 삭제 금지 - 프로그램 추가/제거에서 정식 제거 후 재부팅, 이 메뉴로 잔존만 재확인" -ForegroundColor Yellow
            Write-Host "     (네트워크 스택 보안모듈을 드라이버 단위로 끊었다가 인터넷 불통이 난 실측 사례 있음)" -ForegroundColor DarkGray
        }
    } catch { Write-Host "  조회 실패" -ForegroundColor DarkYellow }

    # (3) 잔존 서비스 (앱 제거 후에도 남은 보안 서비스)
    Write-Host "`n[3] 잔존 보안 관련 서비스" -ForegroundColor Yellow
    $svcPat = @('nProtect','TouchEn','AhnLab','ASDSvc','Veraport','wizvera','INISAFE',
                'Delfino','IPinside','Interezen','MarkAny','KeySharp','MagicLine','INNORIX','XSplit','NXISAS','nxKey')
    $svcs = Get-Service -ErrorAction SilentlyContinue | Where-Object {
        $n=$_.Name+$_.DisplayName; ($svcPat | Where-Object { $n -like "*$_*" })
    }
    if ($svcs) {
        $svcs | ForEach-Object { Write-Host ("  [{0}] {1} ({2})" -f $_.Status, $_.DisplayName, $_.Name) -ForegroundColor Red }
        Write-Host "  → sc.exe delete 로 직접 지우지 말 것 - 해당 프로그램을 프로그램 추가/제거에서 정식 제거 후 재부팅, 잔존만 재확인" -ForegroundColor Yellow
    } else { Write-Host "  잔존 보안 서비스 없음" -ForegroundColor DarkGray }

    # (4) 재부팅 필요 여부 힌트
    Write-Host "`n[4] 재부팅 대기 여부" -ForegroundColor Yellow
    $pending = Test-Path 'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Component Based Servicing\RebootPending'
    if ($pending) { Write-Host "  재부팅 대기 상태 감지 → 제거 완전 반영 위해 재부팅 권장" -ForegroundColor Red }
    else { Write-Host "  재부팅 대기 없음(단, 드라이버 제거 후엔 재부팅 권장)" -ForegroundColor DarkGray }
    Write-Host ""
}

# ── 7) 시스템 정보 (원격 시작 시 파악용) ────────────────────────────
# ── 실제 인터넷 경로의 IP 구성 (v3.6.10) ──────────────────────────────
# 메뉴7·9·18 공용. 예전엔 '게이트웨이를 가진 어댑터'를 경로 메트릭으로만 정렬해 골랐는데,
# 2026-10-02 실측에서 USB 유선으로 통신 중인 PC 의 미연결 와이파이를 골랐다.
# OS 의 실제 선택(경로 메트릭 + 인터페이스 메트릭)을 Find-NetRoute 로 그대로 받는다.
function Get-PrimaryIPConfig {
    $idx = $null
    try {
        $fr = @(Find-NetRoute -RemoteIPAddress 8.8.8.8 -ErrorAction Stop)
        if ($fr.Count -gt 0) { $idx = $fr[0].InterfaceIndex }
    } catch {}
    if ($idx) {
        $c = Get-NetIPConfiguration -InterfaceIndex $idx -ErrorAction SilentlyContinue
        if ($c -and $c.IPv4Address) { return $c }
    }
    # 폴백: 연결(Up)된 어댑터 중 게이트웨이를 가진 것, 메트릭 합이 가장 작은 것
    Get-NetIPConfiguration -ErrorAction SilentlyContinue |
        Where-Object { $_.IPv4Address -and $_.IPv4DefaultGateway -and $_.NetAdapter.Status -eq 'Up' } |
        Sort-Object { [int](@($_.IPv4DefaultGateway)[0].RouteMetric) + [int]$_.NetIPv4Interface.InterfaceMetric } |
        Select-Object -First 1
}

function Show-SysInfo {
    Write-Host "`n[ 시스템 정보 ]" -ForegroundColor Cyan
    try {
        $os = Get-CimInstance Win32_OperatingSystem
        $cs = Get-CimInstance Win32_ComputerSystem
        # IP는 '기본 게이트웨이를 가진 어댑터'에서 뽑아야 한다. 그냥 첫 번째를 집으면
        # WSL2/Hyper-V/VMware 가 만든 가상 어댑터(172.x 등)가 먼저 잡힌다
        # (실측: 172.19.32.1(vEthernet)이 나오고 실제 LAN 192.168.0.3 은 안 나왔음).
        # CRM 공인IP 차단 건에서 이 값을 인프라팀에 넘기면 조회가 통째로 헛돈다.
        $ip = '(조회 실패)'; $others = @()
        $cfg = Get-PrimaryIPConfig
        if ($cfg) {
            $ip = '{0}  ({1}, GW {2})' -f @($cfg.IPv4Address)[0].IPAddress, $cfg.InterfaceAlias, @($cfg.IPv4DefaultGateway)[0].NextHop
            # 169.254.* 는 주소를 못 받은 어댑터(APIPA)라 노이즈다. 빼야 목록이 읽힌다.
            $others = @(Get-NetIPAddress -AddressFamily IPv4 -ErrorAction SilentlyContinue |
                        Where-Object { $_.IPAddress -notlike '127.*' -and $_.IPAddress -notlike '169.254.*' -and
                                       $_.IPAddress -ne @($cfg.IPv4Address)[0].IPAddress } |
                        ForEach-Object { '{0}({1})' -f $_.IPAddress, $_.InterfaceAlias })
        }
        Write-Host ("  컴퓨터명 : {0}" -f $env:COMPUTERNAME)
        Write-Host ("  사용자   : {0}" -f $env:USERNAME)
        Write-Host ("  Windows  : {0} ({1})" -f $os.Caption, $os.Version)
        Write-Host ("  메모리   : {0:N1} GB" -f ($cs.TotalPhysicalMemory/1GB))
        Write-Host ("  IP       : {0}" -f $ip)
        # 가상 어댑터가 있다는 걸 보여줘야 나중에 IP가 두 개로 보일 때 헷갈리지 않는다
        if ($others) { Write-Host ("  기타 IP  : {0}  ← 가상/보조 어댑터(실제 통신 경로 아님)" -f ($others -join ', ')) -ForegroundColor DarkGray }
    } catch { Write-Host "  일부 정보 조회 실패" -ForegroundColor DarkYellow }
    Write-Host ""
}

# ── 8) 이벤트 로그 확인 (System+Application / 30일 / 위험·경고·오류) ──
function Show-EventLog {
    Write-Host "`n[ 이벤트 로그 - 최근 30일, 위험/경고/오류 ]" -ForegroundColor Cyan
    $after = (Get-Date).AddDays(-30)
    # Level: 1=위험(Critical), 2=오류(Error), 3=경고(Warning)
    $all = @()
    foreach ($log in 'System','Application') {
        Write-Host "`n--- $log ---" -ForegroundColor Yellow
        try {
            # 진단 대상 3000건 / 화면 표시 50건.
            # v2.6이 50→500으로 올렸지만 노이즈가 많은 PC는 500도 금방 채워져 옛 오류가 밀려났다
            # (실측: System 로그가 정확히 500건 = 상한에 걸림). 아래 디스크 신호는 상한과 무관하게
            # ProviderName 지정으로 따로 조회하므로, 이 숫자에 안 걸린다.
            $ev = Get-WinEvent -FilterHashtable @{ LogName=$log; Level=1,2,3; StartTime=$after } -MaxEvents 3000 -ErrorAction Stop
            if (-not $ev) { Write-Host "  해당 없음" -ForegroundColor DarkGray; continue }
            $all += $ev
            $capped = if (@($ev).Count -ge 3000) { ' (상한 도달 - 더 있을 수 있음)' } else { '' }
            Write-Host ("  30일 내 {0}건{1} (표시는 최근 50건)" -f @($ev).Count, $capped) -ForegroundColor DarkGray
            $ev | Select-Object -First 50 |
                  Select-Object @{n='시간';e={$_.TimeCreated.ToString('MM-dd HH:mm')}},
                                 @{n='수준';e={switch($_.Level){1{'위험'}2{'오류'}3{'경고'}default{$_.Level}}}},
                                 @{n='원본';e={$_.ProviderName}}, Id |
                  Format-Table -AutoSize
        } catch { Write-Host "  조회 실패 또는 해당 없음" -ForegroundColor DarkGray }
    }

    # ── 자동 진단: 신호 분류 → 어느 메뉴로 조치할지 안내 ──
    Write-Host "`n===== 자동 진단 · 권장 조치 =====" -ForegroundColor Cyan
    # [손상] 진짜 구성요소/시스템파일 손상 신호만 (WindowsUpdateClient는 제외 → 아래 [업데이트]로 분리)
    #  v3.4: WER-SystemErrorReporting 을 뺐다. 이 provider 의 1001 은 '구성요소 손상'이 아니라
    #   '컴퓨터가 bugcheck 에서 다시 부팅됨'(=블루스크린)이다. 여기 섞여 있어서 블루스크린이
    #   DISM+SFC 로 안내됐고, 그건 S5 의 자기 안내와 정반대였다 → 아래 [블루스크린]으로 분리.
    # v3.6.12: SideBySide 는 뺀다. 대개 개별 앱의 VC++ 런타임·매니페스트 문제라 DISM 근거가 아니다(아래 참고 표시).
    $corrupt = @($all | Where-Object { $_.ProviderName -match 'Servicing' -or $_.ProviderName -match '-CBS' })
    $sxs     = @($all | Where-Object { $_.ProviderName -match 'SideBySide' })
    # [블루스크린/비정상종료] 손상·느림과 다른 계열. 미니덤프로 가야 하는 신호다.
    $bug   = @($all | Where-Object { $_.ProviderName -match 'WER-SystemErrorReporting' -and $_.Id -eq 1001 })
    $power = @($all | Where-Object { $_.ProviderName -match 'Kernel-Power' -and $_.Id -eq 41 })
    # [업데이트] 업데이트 설치 실패 - '반복'되면 손상 의심(약한 신호)
    $update  = @($all | Where-Object { $_.ProviderName -match 'WindowsUpdateClient' -and $_.Id -in 20,25,31 })
    # [디스크] 상한과 무관하게 잡으려고 ProviderName 을 지정해 따로 조회한다.
    # 그리고 상위(disk)와 하위계층(Ntfs·stornvme·storahci·Storport)을 나눠 센다 -
    # disk 만 대량이고 하위가 0건이면 스토리지 하드웨어 근거가 아니라 상위 필터 드라이버(보안모듈)다.
    # (2026-08-12 교사I 건에서 disk ID 7 대량을 하드웨어로 오독해 chkdsk 로 몰 뻔했다)
    $diskUp = @(); $diskLow = @()
    try { $diskUp  = @(Get-WinEvent -FilterHashtable @{LogName='System';Level=1,2,3;StartTime=$after;ProviderName='disk'} -ErrorAction Stop |
                       Where-Object { $_.Id -in 7,11,51,52 }) } catch {}
    try { $diskLow = @(Get-WinEvent -FilterHashtable @{LogName='System';Level=1,2,3;StartTime=$after;
                       ProviderName=@('Ntfs','volmgr','volsnap','stornvme','storahci','Storport')} -ErrorAction Stop) } catch {}
    $svc     = @($all | Where-Object { $_.ProviderName -match 'Service Control Manager' -and $_.Id -in 7000,7009,7011,7023,7024,7031,7034 })
    $appcr   = @($all | Where-Object { $_.ProviderName -match 'Application Error|Application Hang|\.NET Runtime' })
    # [노이즈] 어느 PC에나 있는 무해한 잡음 (DCOM 10010/10016, Perflib, WMI, VBScript, Telemetry)
    # v3.4: Kernel-Power 41 을 노이즈에서 뺐다. Level=1(위험)으로 올라오는 '비정상 종료'인데
    #  "무시(정상)"로 찍혀 S5 안내와 어긋났다 → 위 $power 로 옮겨 [블루스크린]에서 같이 본다.
    $noise   = @($all | Where-Object { ($_.ProviderName -match 'DistributedCOM' -and $_.Id -in 10010,10016) -or $_.ProviderName -match 'Perflib|Microsoft-Windows-WMI|VBScriptDeprecation|Telemetry' })

    # [하드웨어] 무엇보다 먼저 본다. 하드웨어로 확정되면 아래 조치가 전부 무의미하고,
    # 가이드상 '윈도우 또는 PC 주변기기 오류 → 제조사 서비스 안내'라 원격 처리 범위 밖이다
    # (= 판별되는 순간 세션을 끝낼 수 있으므로 일을 줄이는 카드다).
    # ※ DISM/SFC 는 Windows 시스템 파일 전용이라 하드웨어를 배제하지 못한다.
    #   'SFC 가 깨끗하니 하드웨어는 아니다'는 성립하지 않는다 - 그건 시스템 파일만 배제한 것.
    #   하드웨어는 WHEA-Logger(하드웨어 오류 전용 provider)와 디스크 HealthStatus 로 본다.
    # WHEA 는 등급을 갈라야 한다. ID 17 은 '정정된 오류'라 정상 PC 에도 흔하고,
    # ID 1/18/19 만 치명적이다. 그마저도 1회성이면 제조사로 보낼 근거가 못 된다
    # (실측: 이 PC에 ID 1 이 3주 전 1건 있었으나 이후 무재발·정상 가동).
    # → 치명적이면서 '반복 또는 최근 7일 내'일 때만 제조사 안내로 올린다.
    $whea = @(); $badDisk = @()
    try { $whea = @(Get-WinEvent -FilterHashtable @{LogName='System';
                    ProviderName='Microsoft-Windows-WHEA-Logger'; StartTime=$after} -ErrorAction Stop) } catch {}
    # v3.6.3 F11: ID 만으로 19 를 치명적으로 분류했다. 19 는 '정정된(corrected) 하드웨어
    #  오류'로 기록되는 경우가 많다 - 정정됐다는 건 시스템이 스스로 처리했다는 뜻이라
    #  그 자체로 제조사 안내 근거가 못 된다. 최근 1건만으로 wStrong=true 가 되던 자리.
    #  → ID 대신 '정정 표기'와 이벤트 수준을 함께 본다.
    # v3.6.5 R3: 'corrected' 는 'uncorrected' 안에도 들어 있고, '정정' 은 '정정할 수 없는'
    #  안에도 들어 있다. 그래서 치명적 오류(ID18)가 '정정됨'으로 분류됐다.
    #  → 부정 표현을 먼저 걸러낸다. 부정이 보이면 정정된 것이 아니다.
    $isUncorrected = {
        param($e)
        $m = [string]$e.Message
        ($m -match '(?i)un-?corrected|uncorrectable|정정할\s*수\s*없|복구할\s*수\s*없|치명')
    }
    $isCorrected = {
        param($e)
        if (& $isUncorrected $e) { return $false }
        ($e.Id -in 17,19,47) -or ([string]$e.Message -match '(?i)corrected|정정')
    }
    $wCorr  = @($whea | Where-Object { & $isCorrected $_ })
    $wFatal = @($whea | Where-Object { (& $isUncorrected $_) -or (-not (& $isCorrected $_) -and $_.Level -le 2) })
    $wStrong = ($wFatal.Count -ge 3) -or ($wFatal -and $wFatal[0].TimeCreated -gt (Get-Date).AddDays(-7))
    # HealthStatus 'Unknown' 은 USB/가상 디스크에서 흔한 값이라 오탐이 된다 → Warning/Unhealthy 만 본다
    # v3.6.12: 조회 실패를 '정상'으로 표시하지 않게 성공 여부를 따로 둔다.
    $diskQueryOk = $true; $badDisk = @()
    try { $badDisk = @(Get-PhysicalDisk -ErrorAction Stop | Where-Object { $_.HealthStatus -in 'Warning','Unhealthy' }) } catch { $diskQueryOk = $false }

    if ($badDisk -or $wStrong) {
        Write-Host "  [하드웨어] ★ 하드웨어 오류 - 원격 조치로는 해결되지 않습니다" -ForegroundColor Red
        foreach ($d in $badDisk) { Write-Host ("     디스크 [{0}] {1} / {2}" -f $d.HealthStatus, $d.FriendlyName, $d.OperationalStatus) -ForegroundColor Red }
        if ($wStrong) { Write-Host ("     WHEA 치명적 오류 {0}건 (최근 {1}) - 반복 또는 최근 발생" -f $wFatal.Count, $wFatal[0].TimeCreated) -ForegroundColor Red }
        Write-Host "     → 제조사 서비스센터 안내 후 종결 (가이드 「원격 처리 불가 항목」)" -ForegroundColor Yellow
    }
    elseif ($wFatal) {
        # 오래된 1~2건. 임의 재부팅·멈춤 증상과 같이 있을 때만 의미가 있다.
        Write-Host ("  [하드웨어] WHEA 치명적 오류 {0}건 (최근 {1}) - 1회성" -f $wFatal.Count, $wFatal[0].TimeCreated) -ForegroundColor DarkYellow
        Write-Host "     → 이것만으로 제조사 안내는 과합니다. 임의 재부팅·멈춤이 같이 있으면 그때 안내." -ForegroundColor DarkGray
    }
    else {
        $dTxt = if ($diskQueryOk) { '디스크 상태 정상' } else { '디스크 상태 조회 실패(미검증)' }
        Write-Host ("  [하드웨어] WHEA 치명적 오류 없음 / {0} → 하드웨어 근거 없음" -f $dTxt) -ForegroundColor Green
        if ($wCorr) {
            Write-Host ("     (정정된 오류 {0}건 - 시스템이 스스로 처리한 것. 정상 PC에도 흔하다)" -f $wCorr.Count) -ForegroundColor DarkGray
            Write-Host  "      다만 짧은 기간에 수십 건씩 몰리면 메모리·CPU 점검 근거가 될 수 있다." -ForegroundColor DarkGray
        }
    }

    # [블루스크린] 하드웨어 다음, 손상 앞. 이게 있으면 '느림'이 아니라 다른 계열이고
    #  DISM/SFC 로 가는 길도 아니다(1001 을 [손상]에 섞어둔 게 v3.3 까지의 오분류).
    if ($bug -or $power) {
        Write-Host ("  [블루스크린/비정상종료] BugCheck {0}건 / Kernel-Power41 {1}건" -f $bug.Count, $power.Count) -ForegroundColor Red
        if ($bug)   { Write-Host ("     최근 BugCheck  : {0}" -f $bug[0].TimeCreated) -ForegroundColor Red }
        if ($power) { Write-Host ("     최근 비정상종료: {0}" -f $power[0].TimeCreated) -ForegroundColor Yellow }
        Write-Host "     → DISM/SFC 로 가는 길이 아닙니다. 미니덤프부터 확인: C:\Windows\Minidump" -ForegroundColor Yellow
        Write-Host "       Kernel-Power41 단독이면 전원 강제차단(멀티탭·정전·전원버튼 길게)일 수 있습니다." -ForegroundColor DarkGray
    }
    if ($corrupt) { Write-Host ("  [손상] 구성요소/시스템파일 오류 {0}건  → 메뉴14 (DISM+SFC) 권장" -f $corrupt.Count) -ForegroundColor Red }
    if ($sxs) {
        Write-Host ("  [참고] SideBySide(앱 구성) 오류 {0}건 - 대개 특정 앱의 VC++ 런타임·매니페스트 문제. DISM 근거 아님" -f $sxs.Count) -ForegroundColor DarkYellow
        Write-Host  "     → 오류 난 앱 재설치 / Visual C++ 재배포 패키지 재설치 쪽" -ForegroundColor DarkGray
    }
    if ($diskUp -or $diskLow) {
        if ($diskLow) {
            Write-Host ("  [디스크] disk {0}건 + 하위계층(Ntfs/stornvme/storahci 등) {1}건  → 근거 확인 후 메뉴15 (chkdsk)  ※DISM 아님" -f $diskUp.Count, $diskLow.Count) -ForegroundColor Red
            # v3.6.13 (외부 QA M6): 공급자 이름만으로 /r(수 시간)을 권하지 않게 무엇이 몇 건인지 먼저 보여준다.
            $diskLow | Group-Object ProviderName, Id | Sort-Object Count -Descending | Select-Object -First 5 | ForEach-Object {
                Write-Host ("     {0}  {1}건" -f $_.Name, $_.Count) -ForegroundColor DarkGray
            }
            Write-Host "     ※ 이벤트 ID·메시지로 파일시스템/배드블록 근거를 확인한 뒤 실행 (근거 없으면 /r 은 시간 낭비)" -ForegroundColor DarkGray
        } else {
            Write-Host ("  [디스크] disk {0}건인데 하위계층(Ntfs/stornvme/storahci/Storport)은 0건" -f $diskUp.Count) -ForegroundColor Yellow
            Write-Host "           → 스토리지 하드웨어 근거가 아닙니다. chkdsk(메뉴15) 돌리지 마세요." -ForegroundColor Yellow
            Write-Host "             상위 필터 드라이버(보안모듈) 의심 → 메뉴1·메뉴6 으로 확인" -ForegroundColor Yellow
        }
    }
    if ($update)  { Write-Host ("  [업데이트] Windows Update 설치실패 {0}건  → '계속' 실패하면 메뉴14. 몇 건이면 특정 업데이트 문제일 수도(무해)" -f $update.Count) -ForegroundColor Yellow }
    if ($svc)     { Write-Host ("  [서비스] 서비스 실패 {0}건  → 메뉴14 또는 해당 서비스 점검" -f $svc.Count) -ForegroundColor Yellow }
    if ($appcr)   { Write-Host ("  [앱크래시] {0}건  → '반복'되고 오류모듈이 시스템DLL이면 메뉴14, 아니면 해당 앱 재설치" -f $appcr.Count) -ForegroundColor Yellow }
    if ($noise)   { Write-Host ("  [노이즈] DCOM/Perflib/WMI/Telemetry 등 {0}건  → 무시(정상)" -f $noise.Count) -ForegroundColor DarkGray }
    # 강한 신호 = 손상 또는 '하위계층까지 확인된' 디스크. disk 단독은 강한 신호가 아니다.
    if (-not ($corrupt -or $diskLow -or $bug)) { Write-Host "  → 강한 손상/디스크 신호 없음. DISM/chkdsk 급하지 않음(업데이트·앱크래시는 '반복'일 때만 의미)." -ForegroundColor Green }
    Write-Host ""
}

# ── 9) 네트워크 진단 (특정 사이트만 접속 불가 - 차단 지점 자동 판별) ──
# 근거: 2026-07 LMS CRM 사례. 서버측 방화벽이 회선 공인IP를 차단
#       → tracert로 백본 이후 유실 확인 → MAC 변경으로 공인IP 재할당하여 해결
function Invoke-NetDiag {
    Write-Host "`n=== 네트워크 진단: 특정 사이트만 접속 불가 ===" -ForegroundColor Cyan
    Write-Host "(다른 사이트는 되는데 특정 사이트만 타임아웃일 때 사용)" -ForegroundColor DarkGray
    $target = Read-Host "대상 도메인 (Enter=crm.lms.example.com)"
    if ([string]::IsNullOrWhiteSpace($target)) { $target = 'crm.lms.example.com' }

    # [1] 네트워크 구성 (공유기 NAT vs 공인IP 직결) - 조치 방법이 갈리는 분기점
    Write-Host "`n[1] 네트워크 구성" -ForegroundColor Yellow
    $myip = $null; $gw = '-'; $direct = $false
    try {
        $cfg = Get-PrimaryIPConfig
        # @(...)[0] 필수. 어댑터에 IPv4 가 2개면 배열이 되고, 아래 $priv 도 배열이 되어
        # -not 이 뒤집힌다 → 공인IP 직결인데 '공유기 뒤'로 판정하고 MAC 변경 안내를 건너뛴다.
        if ($cfg) { $myip = @($cfg.IPv4Address)[0].IPAddress; $gw = @($cfg.IPv4DefaultGateway)[0].NextHop }
    } catch {}
    if ($myip) {
        $priv = ($myip -like '192.168.*' -or $myip -like '10.*' -or $myip -like '169.254.*' -or
                 $myip -match '^172\.(1[6-9]|2[0-9]|3[01])\.' -or
                 $myip -match '^100\.(6[4-9]|[7-9][0-9]|1[01][0-9]|12[0-7])\.')   # v3.6.12: 통신사 CGNAT(100.64/10) - 공인IP 아님
        $direct = -not $priv
        Write-Host ("  IPv4: {0} / 게이트웨이: {1}" -f $myip, $gw)
        if ($direct) {
            Write-Host "  → 공인IP 직결 구성(공유기 NAT 아님). 이 IP가 곧 공인IP." -ForegroundColor Cyan
            Write-Host "    IP 재할당 필요 시: 랜카드 MAC 변경 방식 (아래 판정에서 안내)" -ForegroundColor Cyan
        } else {
            Write-Host "  → 공유기(NAT) 뒤 구성. IP 재할당 필요 시: 공유기/모뎀 5분 전원차단" -ForegroundColor DarkGray
        }
    } else { Write-Host "  IPv4 구성 조회 실패" -ForegroundColor DarkYellow }

    # [2] DNS 해석
    Write-Host "`n[2] DNS 해석" -ForegroundColor Yellow
    $dstIp = $null
    try {
        $dstIp = ([System.Net.Dns]::GetHostAddresses($target) |
                  Where-Object { $_.AddressFamily -eq 'InterNetwork' } |
                  Select-Object -First 1).IPAddressToString
    } catch {}
    if ($dstIp) { Write-Host ("  {0} → {1}  (정상)" -f $target, $dstIp) -ForegroundColor Green }
    else {
        Write-Host "  DNS 해석 실패 → DNS 문제" -ForegroundColor Red
        Write-Host "  → ipconfig /flushdns 후 재시도, 계속 실패 시 어댑터 DNS를 8.8.8.8로 변경`n" -ForegroundColor DarkGray
        return
    }

    # [3] hosts 파일 (보안프로그램이 심어놓은 잔재 확인)
    Write-Host "`n[3] hosts 파일" -ForegroundColor Yellow
    $hostsHit = Get-Content "$env:SystemRoot\System32\drivers\etc\hosts" -ErrorAction SilentlyContinue |
                Where-Object { $_ -match [regex]::Escape($target) -and $_ -notmatch '^\s*#' }
    if ($hostsHit) {
        Write-Host "  의심 항목 발견 → 메모장(관리자)으로 아래 줄 삭제 필요:" -ForegroundColor Red
        $hostsHit | ForEach-Object { Write-Host "    $_" -ForegroundColor Red }
    } else { Write-Host "  이상 없음" -ForegroundColor Green }

    # [4] winsock 서드파티 잔재 (보안프로그램 삭제 후 LSP 찌꺼기)
    Write-Host "`n[4] winsock 서드파티 잔재" -ForegroundColor Yellow
    $wsDirty = $false
    $cat = (netsh winsock show catalog 2>$null | Out-String)
    if ($cat -match 'AhnLab|nProtect|INISAFE|iniLINE|IPinside|WIZVERA|TouchEn|Delfino|MarkAny|Interezen') {
        $wsDirty = $true
        Write-Host "  서드파티 LSP 잔재 발견 → 진단 종료 후 winsock 리셋 권장" -ForegroundColor Red
    } else { Write-Host "  이상 없음" -ForegroundColor Green }

    # [5] TCP 연결 (443)
    Write-Host "`n[5] TCP 연결 테스트 (443)" -ForegroundColor Yellow
    $ok443 = $false
    try { $ok443 = (Test-NetConnection $target -Port 443 -WarningAction SilentlyContinue).TcpTestSucceeded } catch {}
    if ($ok443) {
        Write-Host "  443 연결 성공 → 이 시점 해당 서버까지 TCP 도달은 정상 (TLS·HTTP 응답·브라우저 쪽은 별개)" -ForegroundColor Green
        Write-Host "  → 브라우저에서 안 열리면 브라우저/보안프로그램 문제 (메뉴 1~5로 처리)`n" -ForegroundColor DarkGray
        return
    }
    Write-Host "  443 연결 실패 → 경로 추적으로 차단 지점 확인" -ForegroundColor Red

    # [6] 경로 추적 + 자동 판독
    Write-Host "`n[6] 경로 추적 (tracert -d, 최대 12홉, 1~2분 소요)" -ForegroundColor Yellow
    $lastGood = 0; $reached = $false
    $lines = tracert -d -w 1000 -h 12 $dstIp 2>$null
    foreach ($ln in $lines) {
        Write-Host "  $ln" -ForegroundColor Gray
        # 홉 번호를 먼저 확정할 것. 두 조건을 -and로 묶으면 뒤쪽 -match가
        # $matches를 덮어써 $matches[1]이 $null(=0)이 된다.
        if ($ln -match '^\s*(\d+)\s') {
            $hop = [int]$matches[1]
            if ($ln -match '\sms\s') {
                if ($hop -gt $lastGood) { $lastGood = $hop }
                if ($ln -match [regex]::Escape($dstIp)) { $reached = $true }
            }
        }
    }

    # [7] 판정
    Write-Host "`n[7] 판정" -ForegroundColor Cyan
    if ($reached) {
        Write-Host "  서버까지 경로는 도달하나 443 포트만 실패" -ForegroundColor Yellow
        Write-Host "  → 서버측 포트/서비스 문제 가능성. 지원자 PC에서 동일 사이트 접속해 서버 생사 확인." -ForegroundColor DarkGray
    }
    elseif ($lastGood -ge 3) {
        Write-Host ("  {0}홉까지는 ICMP 응답이 오고 그 이후로는 응답이 없습니다" -f $lastGood) -ForegroundColor Yellow
        # v3.6.3 F12: '패킷 유실 = 회선 차단'으로 단정했었다. tracert 는 ICMP/TTL 만료 응답에
        #  의존하는데, 보안상 ICMP 에 응답하지 않는 라우터가 흔하다. 무응답 홉이 곧
        #  서비스 트래픽(443/TCP)의 차단 지점은 아니다. 위 [5]의 443 결과가 진짜 근거다.
        Write-Host "  ※ 중간 라우터가 ICMP 에 응답하지 않는 경우가 흔합니다. 무응답 홉 = 차단 지점이 아닙니다." -ForegroundColor DarkYellow
        Write-Host "     확실한 근거는 위 [5]의 443 연결 실패입니다. tracert 는 참고 자료로만 쓰세요." -ForegroundColor DarkYellow
        if ($hostsHit -or $wsDirty) {
            Write-Host "  → 위 hosts·winsock 점검에서 이상이 나왔습니다. 그것부터 정리하고 다시 보세요. 그 외 후보:" -ForegroundColor Yellow
        } else {
            Write-Host "  → PC 로컬 설정(hosts·winsock)에는 이상이 없었습니다. 남은 후보:" -ForegroundColor Yellow
        }
        Write-Host "     ①서버측 방화벽의 회선 공인IP 차단  ②구간 라우팅  ③서버측 포트/서비스 상태" -ForegroundColor Yellow
        Write-Host ""
        Write-Host "  [대응 순서]" -ForegroundColor Cyan
        Write-Host "   0. 먼저 다른 회선(폰 테더링)에서 같은 주소로 접속 → 되면 이 회선 문제로 좁혀집니다" -ForegroundColor White
        Write-Host "   1. 지원자 PC에서 동일 사이트 접속 → 되면 서버는 살아 있음(회선 쪽으로 좁혀짐)"
        if ($direct) {
            $mac = '02' + (-join (1..5 | ForEach-Object { '{0:X2}' -f (Get-Random -Maximum 256) }))
            Write-Host "   2. 공인IP 직결 구성이므로 MAC 변경으로 IP 재할당:" -ForegroundColor Cyan
            Write-Host "      ① 장치관리자 → 네트워크 어댑터 → 이더넷 우클릭 → 속성 → 고급 탭"
            Write-Host ("      ② Network Address(네트워크 주소) → '값' 선택 → {0} 입력 → 확인" -f $mac)
            Write-Host "      ③ 어댑터를 재시작하면 원격 연결이 잠시 끊깁니다" -ForegroundColor Yellow
            Write-Host "      ④ 재접속 후 ipconfig로 IP 변경 확인 → 접속 재테스트"
            Write-Host "      ⑤ 인터넷 자체가 안 붙으면(MAC인증 회선) '없음'으로 원복시키게 안내"
            Write-Host "      ⑥ 해결되면 설정 그대로 유지 (원복 시 차단된 기존 IP 재할당 → 재발)" -ForegroundColor Yellow
        } else {
            Write-Host "   2. 공유기(NAT) 구성이므로: 공유기+모뎀 전원 뽑고 5분 대기 후 재투입"
            Write-Host "      → 재연결 후 네이버 '내 IP' 검색으로 공인IP 변경 여부 확인"
        }
        Write-Host "   3. IP 변경 후에도 실패 → 대역 차단/경로 문제. 인프라(서버 담당)에"
        Write-Host "      해당 공인IP 방화벽 차단 여부 조회 요청. 그동안 핫스팟 테더링 임시 우회."
    }
    elseif ($lastGood -ge 1) {
        # v3.6.5 R5: ICMP 무응답을 그대로 '유실'로 단정했다. 여기도 미확인이다.
        Write-Host ("  {0}홉까지만 ICMP 응답이 옵니다" -f $lastGood) -ForegroundColor Yellow
        Write-Host  "  ※ ICMP 에 응답하지 않는 라우터가 흔합니다 - 이것만으로 구간을 특정할 수 없습니다." -ForegroundColor DarkYellow
        Write-Host  "  → 공유기/모뎀 재부팅 후 [5]의 443 테스트를 다시 해보세요. 그게 판단 근거입니다." -ForegroundColor DarkGray
    }
    else {
        # v3.6.5 R5: 1홉 무응답만으로 'PC 로컬 문제'라 하고 winsock 리셋을 권했다.
        #  공유기가 ICMP 를 막아둔 경우에도 똑같이 보인다. 근거 없이 스택을 초기화하면 안 된다.
        Write-Host "  1홉(게이트웨이)부터 ICMP 응답이 없습니다" -ForegroundColor Yellow
        Write-Host "  ※ 공유기가 ICMP 를 차단하는 경우에도 같은 모양입니다 - 로컬 장애로 단정할 수 없습니다." -ForegroundColor DarkYellow
        Write-Host "  → 먼저 확인: 다른 사이트는 열리는지 / ping 게이트웨이 / ipconfig 로 IP·GW 정상 여부" -ForegroundColor DarkGray
        Write-Host "     인터넷 자체가 안 되면 랜선·공유기부터. 다른 사이트가 되면 네트워크 리셋은 근거 부족입니다." -ForegroundColor DarkGray
    }

    # [8] 선택 조치: 네트워크 스택 리셋
    # v3.6.5 R5: 'lastGood -eq 0' 만으로 리셋을 제안했다(= ICMP 무응답만으로 스택 초기화 권고).
    #  서드파티 LSP 잔재가 실제로 확인됐을 때만 제안한다.
    if ($wsDirty) {
        Write-Host ""
        if ((Read-Host "winsock 재설정을 지금 실행할까요? (이후 재부팅 필요) (y/n)") -eq 'y') {
            # v3.6.13 (외부 QA H3): LSP 잔재 대응은 winsock reset 이 핵심이다. int ip reset(고정 IP·DNS 초기화)과
            #  winhttp reset proxy(업무망 프록시 삭제)는 근거 없이 같이 돌리던 것 → 뺐다. 종료코드도 확인한다.
            & netsh.exe winsock reset | Out-Null; $wsRc = $LASTEXITCODE
            & ipconfig.exe /flushdns  | Out-Null; $dnsRc = $LASTEXITCODE
            if ($wsRc -eq 0) {
                Write-Host ("  winsock 재설정 완료(DNS 캐시 삭제 코드 {0}). 애니서포트 [재부팅] 후 재확인하세요." -f $dnsRc) -ForegroundColor Green
                Log-Action "winsock 재설정(LSP 잔재)"
            } else {
                Write-Host ("  winsock 재설정 실패(netsh 코드 {0}) - 완료로 기록하지 않음" -f $wsRc) -ForegroundColor Red
            }

        }
    }
    Write-Host ""
}


# ── 기본 오디오 장치 음소거/볼륨 조회 (v3.6.8) ─────────────────────────
#  Get-PnpDevice 는 장치가 '있다(OK)'까지만 알려준다. 기본 장치가 무엇인지, 음소거인지,
#  볼륨이 0 인지는 Core Audio(IMMDeviceEnumerator / IAudioEndpointVolume)로만 읽힌다.
#  실측 2026-09-28: Headphones 가 기본 장치·OK 인데 장치 자체가 음소거 → 학생 목소리 안 들림.
#  서드파티 모듈 없이 Add-Type 인라인 C# 로 호출한다. C# 5 문법만 쓸 것(PS 5.1 의 csc 기준).
#  COM 메서드는 전부 [PreserveSig] 로 HRESULT 를 직접 받는다. 안 쓰는 vtable 칸도 순서대로 선언해야
#  뒤 메서드(GetMute 는 13번째)가 제 칸을 가리킨다.
$RstAudioSrc = @'
using System;
using System.Runtime.InteropServices;
namespace RstAudio {
    [ComImport, Guid("BCDE0395-E52F-467C-8E3D-C4579291692E")]
    public class MMDeviceEnumeratorCo { }

    [ComImport, Guid("A95664D2-9614-4F35-A746-DE8DB63617E6"), InterfaceType(ComInterfaceType.InterfaceIsIUnknown)]
    public interface IMMDeviceEnumerator {
        [PreserveSig] int EnumAudioEndpoints(int dataFlow, int stateMask, out IntPtr devices);
        [PreserveSig] int GetDefaultAudioEndpoint(int dataFlow, int role, out IMMDevice device);
    }

    [ComImport, Guid("D666063F-1587-4E43-81F1-B948E807363F"), InterfaceType(ComInterfaceType.InterfaceIsIUnknown)]
    public interface IMMDevice {
        [PreserveSig] int Activate(ref Guid iid, int clsCtx, IntPtr activationParams, [MarshalAs(UnmanagedType.IUnknown)] out object iface);
        [PreserveSig] int OpenPropertyStore(int access, out IntPtr props);
        [PreserveSig] int GetId([MarshalAs(UnmanagedType.LPWStr)] out string id);
    }

    [ComImport, Guid("5CDF2C82-841E-4546-9722-0CF74078229A"), InterfaceType(ComInterfaceType.InterfaceIsIUnknown)]
    public interface IAudioEndpointVolume {
        [PreserveSig] int RegisterControlChangeNotify(IntPtr notify);
        [PreserveSig] int UnregisterControlChangeNotify(IntPtr notify);
        [PreserveSig] int GetChannelCount(out uint count);
        [PreserveSig] int SetMasterVolumeLevel(float levelDB, ref Guid ctx);
        [PreserveSig] int SetMasterVolumeLevelScalar(float level, ref Guid ctx);
        [PreserveSig] int GetMasterVolumeLevel(out float levelDB);
        [PreserveSig] int GetMasterVolumeLevelScalar(out float level);
        [PreserveSig] int SetChannelVolumeLevel(uint channel, float levelDB, ref Guid ctx);
        [PreserveSig] int SetChannelVolumeLevelScalar(uint channel, float level, ref Guid ctx);
        [PreserveSig] int GetChannelVolumeLevel(uint channel, out float levelDB);
        [PreserveSig] int GetChannelVolumeLevelScalar(uint channel, out float level);
        [PreserveSig] int SetMute([MarshalAs(UnmanagedType.Bool)] bool mute, ref Guid ctx);
        [PreserveSig] int GetMute([MarshalAs(UnmanagedType.Bool)] out bool mute);
    }

    public class EndpointState {
        public int Hr;
        public string Id;
        public bool Muted;
        public int VolumePct;
    }

    public static class Core {
        const int CLSCTX_ALL = 23;
        static IAudioEndpointVolume Open(int flow, int role, out string id, out int hr) {
            id = null;
            IMMDeviceEnumerator en = (IMMDeviceEnumerator)(new MMDeviceEnumeratorCo());
            IMMDevice dev;
            hr = en.GetDefaultAudioEndpoint(flow, role, out dev);
            if (hr != 0 || dev == null) return null;
            string s;
            if (dev.GetId(out s) == 0) id = s;
            Guid iid = typeof(IAudioEndpointVolume).GUID;
            object o;
            hr = dev.Activate(ref iid, CLSCTX_ALL, IntPtr.Zero, out o);
            if (hr != 0 || o == null) return null;
            return (IAudioEndpointVolume)o;
        }
        public static EndpointState Get(int flow, int role) {
            EndpointState r = new EndpointState();
            string id; int hr;
            IAudioEndpointVolume v = Open(flow, role, out id, out hr);
            r.Id = id; r.Hr = hr; r.VolumePct = -1;
            if (v == null) return r;
            bool m = false; float lv = -1f;
            if (v.GetMute(out m) == 0) r.Muted = m;
            if (v.GetMasterVolumeLevelScalar(out lv) == 0) r.VolumePct = (int)Math.Round(lv * 100);
            return r;
        }
        public static int Unmute(int flow, int role) {
            string id; int hr;
            IAudioEndpointVolume v = Open(flow, role, out id, out hr);
            if (v == null) return (hr != 0) ? hr : -1;
            Guid g = Guid.Empty;
            return v.SetMute(false, ref g);
        }
    }
}
'@
function Get-DefaultAudioState {
    if (-not ('RstAudio.Core' -as [type])) {
        try { Add-Type -TypeDefinition $RstAudioSrc -Language CSharp -ErrorAction Stop }
        catch { return $null }
    }
    $names = @{}
    try { Get-PnpDevice -Class AudioEndpoint -ErrorAction Stop | ForEach-Object { $names[$_.InstanceId.ToUpper()] = $_.FriendlyName } } catch {}
    $rows = @()
    # flow 0=재생 1=녹음 / role 0=기본 장치 2=기본 통신 장치
    foreach ($spec in @(@(0,0,'재생-기본'), @(0,2,'재생-통신'), @(1,0,'녹음-기본'), @(1,2,'녹음-통신'))) {
        $st = $null
        try { $st = [RstAudio.Core]::Get($spec[0], $spec[1]) } catch { }
        if (-not $st) { continue }
        $nm = $null
        if ($st.Id) {
            $key = ('SWD\MMDEVAPI\' + $st.Id).ToUpper()
            if ($names.ContainsKey($key)) { $nm = $names[$key] }
        }
        $rows += [PSCustomObject]@{ Flow=$spec[0]; Role=$spec[1]; Label=$spec[2]; Id=$st.Id; Name=$nm; Muted=$st.Muted; Vol=$st.VolumePct; Hr=$st.Hr }
    }
    ,$rows
}

# ── 10) 오디오/카메라 장치 확인 (화상수업앱 소리·화면 - 조치빈도 12%) ──
# 기본 장치 "변경" 자동화는 서드파티 모듈 필요 → 원격 환경 부적합.
# 대신 현황 출력 + mmsys.cpl 열어서 클릭 2번으로 끝나게 안내.
function Show-AudioDevices {
    Write-Host "`n=== 오디오/카메라 장치 확인 (화상수업앱 소리 안 들림/화면 안 나옴) ===" -ForegroundColor Cyan

    # ─────────────────────────────────────────────────────────────
    # [1] 오디오 장치
    # ─────────────────────────────────────────────────────────────
    Write-Host "`n[1] 오디오 장치 (OK=활성)" -ForegroundColor Yellow
    try {
        $eps = Get-PnpDevice -Class AudioEndpoint -ErrorAction Stop | Sort-Object Status -Descending
        if ($eps) {
            $eps | ForEach-Object {
                $c = if ($_.Status -eq 'OK') { 'Gray' } else { 'DarkGray' }
                Write-Host ("  [{0}] {1}" -f $_.Status, $_.FriendlyName) -ForegroundColor $c
            }
        } else { Write-Host "  오디오 장치 없음" -ForegroundColor Red }
    } catch { Write-Host "  조회 실패(구버전 OS) → mmsys.cpl에서 직접 확인" -ForegroundColor DarkYellow }


    # [1-1] 기본 장치 · 음소거 · 볼륨 (v3.6.8)
    #  장치가 OK 여도 '장치 자체 음소거'면 소리가 안 난다(2026-09-28 실측). 녹음 쪽 음소거는
    #  반대 방향(학생이 선생님 목소리를 못 들음) 원인이다. 둘 다 여기서 한 번에 본다.
    Write-Host "`n[1-1] 기본 장치 · 음소거 · 볼륨 (Windows 가 실제로 쓰는 장치)" -ForegroundColor Yellow
    $das = Get-DefaultAudioState
    if ($null -eq $das) {
        Write-Host "  조회 실패 → mmsys.cpl > 장치 [속성] > [수준] 탭에서 스피커 아이콘 빨간 금지 표시 직접 확인" -ForegroundColor DarkYellow
    } elseif (-not $das) {
        Write-Host "  기본 장치 없음 (활성 재생/녹음 장치가 하나도 없음)" -ForegroundColor Red
    } else {
        $mutedList = @()
        foreach ($d in $das) {
            if (-not $d.Id) { Write-Host ("  {0}: 없음 (0x{1:X8})" -f $d.Label, $d.Hr) -ForegroundColor DarkYellow; continue }
            $nm  = if ($d.Name) { $d.Name } else { $d.Id }
            $vol = if ($d.Vol -ge 0) { '{0}%' -f $d.Vol } else { '?' }
            $tag = ''; $col = 'Gray'
            if ($d.Muted) { $tag = '  ← ★ 음소거'; $col = 'Red'; $mutedList += $d }
            elseif ($d.Vol -ge 0 -and $d.Vol -lt 10) { $tag = '  ← ★ 볼륨 거의 0'; $col = 'Yellow' }
            elseif ($d.Flow -eq 1 -and $d.Vol -ge 0 -and $d.Vol -lt 80) { $tag = '  ← 가이드 기준 80 미만(p.24)'; $col = 'Yellow' }   # v3.6.19
            Write-Host ("  {0}: {1}  볼륨 {2}{3}" -f $d.Label, $nm, $vol, $tag) -ForegroundColor $col
        }
        $defR = @($das | Where-Object { $_.Flow -eq 0 -and $_.Role -eq 0 })[0]
        $comR = @($das | Where-Object { $_.Flow -eq 0 -and $_.Role -eq 2 })[0]
        if ($defR -and $comR -and $defR.Id -and $comR.Id -and $defR.Id -ne $comR.Id) {
            Write-Host "  ※ 기본 장치와 기본 통신 장치가 다르다 - 화상수업 소리가 통신 장치로 갈 수 있음" -ForegroundColor Yellow
            Write-Host "     mmsys.cpl 재생/녹음 탭에서 실사용 장치를 [기본 장치]·[기본 통신 장치] 둘 다로 지정" -ForegroundColor DarkGray
        }
        if ($mutedList) {
            $uniq = @($mutedList | Sort-Object Id -Unique)
            Write-Host ("  ★ 장치 음소거 {0}개 - 재생이면 '선생님이 학생 소리를 못 들음', 녹음이면 '학생이 선생님 소리를 못 들음'" -f $uniq.Count) -ForegroundColor Red
            if ((Read-Host "  음소거 해제할까요? (y/n)") -eq 'y') {
                foreach ($d in $uniq) {
                    $hr = -1
                    try { $hr = [RstAudio.Core]::Unmute($d.Flow, $d.Role) } catch {}
                    $nm = if ($d.Name) { $d.Name } else { $d.Id }
                    $after = $null
                    try { $after = [RstAudio.Core]::Get($d.Flow, $d.Role) } catch {}
                    if ($hr -eq 0 -and $after -and -not $after.Muted) {
                        Write-Host ("  √ 음소거 해제: {0}" -f $nm) -ForegroundColor Green
                        Log-Action ("{0} 장치 음소거 해제({1})" -f $(if ($d.Flow -eq 0) { '재생' } else { '녹음' }), $nm)
                    } else {
                        Write-Host ("  해제 실패: {0} (0x{1:X8}) → mmsys.cpl > [속성] > [수준] 탭에서 직접 해제" -f $nm, $hr) -ForegroundColor Red
                    }
                }
            }
        }
    }

    # [1-2] 녹음 장치 [사용] 개수 (v3.6.14)
    #  근거: 2025 원격 처리 현황 마이크 건의 약 63% 가 '기본 마이크 변경 + 안 쓰는 마이크 [사용 안 함]' 으로 끝났다.
    #  가이드 p.19: 여러 개를 [사용]으로 두면 화상수업앱 중 장치가 바뀌어 학생에게 목소리가 안 들린다.
    #  상태: v3.6.18 부터 PnP AudioEndpoint 의 Status OK 로 센다([1] 과 같은 근거).
    #   레지스트리 DeviceState 하위 4비트로 세던 v3.6.14~17 은 [사용 안 함] Stereo Mix 를 [사용]으로 셌다(2026-10-06 실측).
    #  읽기만 한다. 기본 장치 변경 자동화는 하지 않는 기존 방침 유지 → [7] 에서 녹음 탭을 열어 사람이 처리.
    Write-Host "`n[1-2] 녹음 장치 [사용] 개수 (가이드 p.19 - 쓰는 마이크 1개만 사용)" -ForegroundColor Yellow
    $micActive = @()
    $micRegOK  = $false
    $defMicId  = $null
    if ($das) {
        $dmic = @($das | Where-Object { $_.Flow -eq 1 -and $_.Role -eq 0 })[0]
        if ($dmic -and $dmic.Id) { $defMicId = ([string]$dmic.Id).ToLower() }
    }
    $pnpOK = $false
    try {
        $capPnp = @(Get-PnpDevice -Class AudioEndpoint -ErrorAction Stop |
                    Where-Object { ([string]$_.InstanceId).StartsWith('SWD\MMDEVAPI\{0.0.1.', [StringComparison]::OrdinalIgnoreCase) })
        $pnpOK = $true; $micRegOK = $true
        foreach ($d in $capPnp) {
            if ([string]$d.Status -ne 'OK') { continue }
            $g   = (([string]$d.InstanceId) -replace '^.*\.', '').ToLower()
            $lbl = if ($d.FriendlyName) { [string]$d.FriendlyName } else { $g }
            $micActive += [PSCustomObject]@{ Guid = $g; Name = $lbl; IsDefault = [bool]($defMicId -and $defMicId.EndsWith($g)) }
        }
    } catch {}
    # PnP 조회 실패 시에만 레지스트리로 대체. DeviceState 가 정확히 1(ACTIVE)인 것만 센다(상위 비트 있으면 제외).
    $capRoot = 'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\MMDevices\Audio\Capture'
    if (-not $pnpOK) { try {
        $capKeys = @(Get-ChildItem -LiteralPath $capRoot -ErrorAction Stop)
        $micRegOK = $true
        Write-Host "  (PnP 조회 실패 - 레지스트리 기준으로 셈)" -ForegroundColor DarkGray
        foreach ($k in $capKeys) {
            $stv = $null
            try { $stv = (Get-ItemProperty -LiteralPath $k.PSPath -ErrorAction Stop).DeviceState } catch { continue }
            if ($null -eq $stv -or [int64]$stv -ne 1) { continue }
            $pp  = Get-ItemProperty -LiteralPath ($k.PSPath + '\Properties') -ErrorAction SilentlyContinue
            $nm  = if ($pp) { [string]$pp.'{a45c254e-df1c-4efd-8020-67d146a850e0},2' } else { '' }
            $adp = if ($pp) { [string]$pp.'{b3f8fa53-0004-438e-9003-51a46e139bfc},6' } else { '' }
            $g   = ([string]$k.PSChildName).ToLower()
            $lbl = if ($nm -and $adp) { '{0} ({1})' -f $nm, $adp } elseif ($nm) { $nm } else { $g }
            $micActive += [PSCustomObject]@{ Guid = $g; Name = $lbl; IsDefault = [bool]($defMicId -and $defMicId.EndsWith($g)) }
        }
    } catch {} }
    if (-not $micRegOK) {
        Write-Host "  조회 실패 → mmsys.cpl 녹음 탭에서 [사용] 장치 수를 직접 확인" -ForegroundColor DarkYellow
    } elseif (-not $micActive) {
        Write-Host "  [사용] 상태 녹음 장치 없음 → 녹음 탭 빈 곳 우클릭 > [사용 안 함 장치 표시] 후 마이크 [사용]" -ForegroundColor Red
    } else {
        foreach ($m in $micActive) {
            $tg  = if ($m.IsDefault) { '  ← 기본 장치' } else { '' }
            $col = if ($m.IsDefault) { 'Green' } else { 'Gray' }
            Write-Host ("  [사용] {0}{1}" -f $m.Name, $tg) -ForegroundColor $col
        }
        if ($micActive.Count -ge 2) {
            Write-Host ("  ★ [사용] 녹음 장치 {0}개 - 화상수업앱 중 장치가 바뀌어 학생에게 목소리가 안 들릴 수 있음" -f $micActive.Count) -ForegroundColor Yellow
            Write-Host  "     쓰는 마이크 1개만 [사용] + [기본 장치]·[기본 통신 장치], 나머지(웹캠 마이크 포함) [사용 안 함]" -ForegroundColor DarkGray
        } else {
            Write-Host "  1개 - 정상 (가이드 기준)" -ForegroundColor DarkGray
        }
    }

    # ─────────────────────────────────────────────────────────────
    # [2] 카메라 장치 - Class 가 판정의 핵심
    #  Camera = 표준 UVC(usbvideo.sys). Media Foundation(카메라앱/브라우저) 사용 가능
    #  Image  = WIA(스캐너용). 장치는 OK 여도 화상수업앱에서 못 쓴다  ← 2026-09-08 교사H 교사 건
    #  ※ -Class 'Camera','Image' 는 Camera 클래스 미등록 PC 에서 에러가 난다. 전체 조회 후 필터.
    # ─────────────────────────────────────────────────────────────
    Write-Host "`n[2] 카메라 장치 (Class 확인 - Camera=정상 / Image=드라이버 오등록)" -ForegroundColor Yellow
    $allPnp = @()
    try { $allPnp = Get-PnpDevice -ErrorAction Stop } catch { Write-Host "  Get-PnpDevice 미지원" -ForegroundColor DarkYellow }

    $cams = $allPnp | Where-Object {
        $_.Class -in @('Camera','Image') -or $_.FriendlyName -match 'camera|웹캠|webcam'
    }
    $camOK    = @($cams | Where-Object { $_.Status -eq 'OK' })
    # v3.6.19: 코드 22 = 장치 관리자에서 [사용 안 함]. 고장·물리 문제가 아니다(2026-10-07 교사 PC 실측 - LG 내장 웹캠).
    $camDisabled = @($cams | Where-Object { [int]$_.ConfigManagerErrorCode -eq 22 })
    $camImage = @($camOK | Where-Object { $_.Class -eq 'Image' })

    if ($cams) {
        $cams | Sort-Object Status | ForEach-Object {
            $ghost = ($_.FriendlyName -match 'XSplit|VCam|Virtual|가상') -and
                     ($_.FriendlyName -notmatch '^Windows Virtual Camera')   # Win11 기본 구성요소
            $tag = ''
            $col = 'Gray'
            if ($ghost)                                  { $tag = '  ← 유령의심(메뉴6 참고)'; $col = 'Red' }
            elseif ($_.Status -eq 'OK' -and $_.Class -eq 'Image')  { $tag = '  ← 드라이버 오등록(아래 [4] 확인)'; $col = 'Yellow' }
            elseif ($_.Status -eq 'OK' -and $_.Class -eq 'Camera') { $tag = '  ← 정상(표준 UVC)'; $col = 'Green' }
            elseif ([int]$_.ConfigManagerErrorCode -eq 22) { $tag = '  ← 장치 관리자 [사용 안 함](코드 22)'; $col = 'Yellow' }   # v3.6.19
            elseif ($_.Status -eq 'Unknown')             { $tag = '  (미연결 잔여등록 - 무시)'; $col = 'DarkGray' }
            Write-Host ("  [{0}/{1}] {2}{3}" -f $_.Class, $_.Status, $_.FriendlyName, $tag) -ForegroundColor $col
        }
    } else { Write-Host "  카메라 장치 없음" -ForegroundColor Red }

    # [2-1] DirectShow 가상카메라 (v3.6.19)
    #  PRISM Lens·OBS Virtual Camera 등은 PnP 가 아니라 DirectShow 필터라 [2] 에 안 나온다(메뉴6 [1-2] 와 같은 근거).
    #  2026-10-07 교사 PC: 화상수업앱 카메라 목록에 PRISM Lens 1·2·3·PRISM Live Studio 가 있었는데 메뉴10 에는 안 보였다.
    #  여기서는 이름만 보여준다. 소유 프로그램(DLL)·등록 해제는 메뉴6. 선생님이 쓰는 카메라일 수 있어 무단 삭제 금지.
    Write-Host "`n[2-1] 가상카메라 (DirectShow - 화상수업앱 카메라 목록에만 보이는 것)" -ForegroundColor Yellow
    $dsCams = @()
    $dsCatV = '{860BB310-5D01-11d0-BD3B-00A0C911CE86}'   # CLSID_VideoInputDeviceCategory
    foreach ($view in @('', 'WOW6432Node\')) {
        $base = "HKLM:\SOFTWARE\Classes\$($view)CLSID\$dsCatV\Instance"
        if (-not (Test-Path -LiteralPath $base)) { continue }
        foreach ($k in @(Get-ChildItem -LiteralPath $base -ErrorAction SilentlyContinue)) {
            $nm = (Get-ItemProperty -LiteralPath $k.PSPath -ErrorAction SilentlyContinue).FriendlyName
            if ($nm -and ($dsCams -notcontains [string]$nm)) { $dsCams += [string]$nm }
        }
    }
    if ($dsCams) {
        $dsCams | ForEach-Object { Write-Host ("  {0}" -f $_) -ForegroundColor Gray }
        if ($dsCams.Count -ge 3) {
            Write-Host ("  ※ 가상카메라 {0}개 - 화상수업앱 로딩 지연·장치 인식 오류 시 우선 의심(가이드 XSplit 항목과 같은 유형)" -f $dsCams.Count) -ForegroundColor DarkYellow
        }
        Write-Host "  ※ 선생님이 카메라로 쓰는 것일 수 있음 - 무단 삭제 금지. 소유 프로그램·해제는 메뉴6" -ForegroundColor DarkGray
    } else { Write-Host "  없음" -ForegroundColor DarkGray }

    # ─────────────────────────────────────────────────────────────
    # [3] 오류 장치 - USB 열거 실패 탐지
    #  '알 수 없는 USB 장치(장치 설명자 요청 실패)' / 코드43 / VID_0000&PID_0002
    #  → 물리 계층(포트·케이블·장비). 소프트웨어 조치 전부 무의미
    # ─────────────────────────────────────────────────────────────
    Write-Host "`n[3] 오류 상태 장치 (USB 열거 실패 = 물리 문제)" -ForegroundColor Yellow
    # v3.6.19: 코드 22([사용 안 함])는 오류·물리 문제가 아니다 → 이 목록에서 뺀다.
    $errDev = @($allPnp | Where-Object { $_.Status -eq 'Error' -and [int]$_.ConfigManagerErrorCode -ne 22 })
    $usbEnumFail = @($errDev | Where-Object { $_.InstanceId -match 'VID_0000' -or $_.FriendlyName -match '알 수 없는 USB|Unknown USB' })
    if ($errDev) {
        $errDev | ForEach-Object {
            Write-Host ("  [{0}] {1}" -f $_.Class, $_.FriendlyName) -ForegroundColor Red
            Write-Host ("        {0}" -f $_.InstanceId) -ForegroundColor DarkGray
        }
    } else { Write-Host "  없음" -ForegroundColor Green }
    if ($camDisabled) { Write-Host ("  (카메라 [사용 안 함] {0}개는 오류가 아니라 꺼 둔 상태 - [6] 참고)" -f $camDisabled.Count) -ForegroundColor DarkGray }

    # ─────────────────────────────────────────────────────────────
    # [4] 카메라 드라이버 - Service 가 usbvideo 여야 표준 UVC
    # ─────────────────────────────────────────────────────────────
    Write-Host "`n[4] 카메라 드라이버" -ForegroundColor Yellow
    # v3.6.1: $badInf 를 단일 변수로 덮어써서, 카메라가 여러 대면 마지막 것만 남고
    #  그 INF 가 어느 장치 것인지 화면에서 알 수 없었다. 장치명과 짝지어 모은다.
    $badInf = $null
    $badInfList = @()
    if ($camOK) {
        foreach ($c in $camOK) {
            try {
                $props = $c | Get-PnpDeviceProperty -KeyName 'DEVPKEY_Device_Service','DEVPKEY_Device_DriverInfPath' -ErrorAction Stop
                $svc = ($props | Where-Object KeyName -eq 'DEVPKEY_Device_Service').Data
                $inf = ($props | Where-Object KeyName -eq 'DEVPKEY_Device_DriverInfPath').Data
                if ($svc -eq 'usbvideo') {
                    Write-Host ("  {0}`n     Service={1} / INF={2}  ← 표준 UVC" -f $c.FriendlyName, $svc, $inf) -ForegroundColor Green
                } elseif ($inf -match '^oem\d+\.inf$') {
                    Write-Host ("  {0}`n     Service={1} / INF={2}  ← 서드파티 드라이버" -f $c.FriendlyName, $svc, $inf) -ForegroundColor Yellow
                    $badInf = $inf
                    $badInfList += [PSCustomObject]@{ Inf = $inf; Device = $c.FriendlyName
                                                      Class = $c.Class; InstanceId = $c.InstanceId }
                } else {
                    # oem*.inf 가 아니면 Windows 내장 INF(c_swdevice.inf 등)다.
                    #  v3.4: 여기를 '서드파티 드라이버'로 찍는 바람에 Windows 기본 구성요소가
                    #  제거 대상처럼 보였다(실측: Windows Virtual Camera Device, Service 비어 있음).
                    Write-Host ("  {0}`n     Service={1} / INF={2}  ← Windows 내장(서드파티 아님)" -f $c.FriendlyName, $svc, $inf) -ForegroundColor DarkGray
                }
            } catch { Write-Host ("  {0} - 드라이버 속성 조회 실패" -f $c.FriendlyName) -ForegroundColor DarkYellow }
        }
    } else { Write-Host "  연결된 카메라 없음" -ForegroundColor DarkGray }

    # ─────────────────────────────────────────────────────────────
    # [5] 카메라/마이크 권한 + Frame Server
    # ─────────────────────────────────────────────────────────────
    Write-Host "`n[5] 권한 / 서비스" -ForegroundColor Yellow
    $denied = @(); $permUnverified = @()
    # v3.6.13 (외부 QA H4·H5): HKCU 는 선생님 계정 하이브로 읽는다. 값이 없는 키는 '거부'가 아니다 → 명시적 Deny 만 센다.
    $roots = @(@{ L = 'HKLM'; R = 'HKLM:' }, @{ L = 'HKCU'; R = $script:TargetHKCU })
    foreach ($dev in 'webcam','microphone') {
        foreach ($rt in $roots) {
            $h = $rt.L
            if (-not $rt.R) { Write-Host ("  {0,-6} {1,-26} 선생님 계정 레지스트리 못 읽음 - 미검증" -f $h, $dev) -ForegroundColor DarkYellow; $permUnverified += $dev; continue }
            foreach ($k in @($dev, "$dev\NonPackaged")) {
                $p = $rt.R.TrimEnd('\') + "\SOFTWARE\Microsoft\Windows\CurrentVersion\CapabilityAccessManager\ConsentStore\$k"
                # v3.6.16 (외부 QA 재검수): 조회 오류를 '값 없음'으로 처리했다 → 키 없음과 조회 오류를 구분.
                $rk = $null; $rkErr = $null
                try { $rk = Get-Item -LiteralPath $p -ErrorAction Stop } catch { $rkErr = $_ }
                if ($rkErr -and -not ($rkErr.Exception -is [System.Management.Automation.ItemNotFoundException])) {
                    Write-Host ("  {0,-6} {1,-26} 조회 오류 - 미검증 ({2})" -f $h, $k, $rkErr.Exception.Message) -ForegroundColor DarkYellow
                    $permUnverified += $dev
                    continue
                }
                if ($rk) {
                    $v = $null
                    try { $v = $rk.GetValue('Value') } catch {
                        Write-Host ("  {0,-6} {1,-26} 값 읽기 오류 - 미검증" -f $h, $k) -ForegroundColor DarkYellow
                        $permUnverified += $dev
                        continue
                    }
                    if ($v -ieq 'Deny') {
                        $denied += "$h\$k"
                        Write-Host ("  {0,-6} {1,-26} Deny" -f $h, $k) -ForegroundColor Red
                    } elseif ($v -ieq 'Allow') {
                        Write-Host ("  {0,-6} {1,-26} Allow" -f $h, $k) -ForegroundColor Gray
                    } else {
                        Write-Host ("  {0,-6} {1,-26} (값 없음 - 거부로 보지 않음)" -f $h, $k) -ForegroundColor DarkGray
                    }
                }
            }
        }
    }
    $fs = Get-Service FrameServer -ErrorAction SilentlyContinue
    if ($fs) { Write-Host ("  FrameServer  {0} / {1}  (Manual+Stopped 는 정상 - 사용 시 자동 시작)" -f $fs.Status, $fs.StartType) -ForegroundColor Gray }

    # [5-1] 브라우저 마이크 (v3.6.14)
    #  가이드 p.22 브라우저 권한: ① 자물쇠 > 마이크 허용 ② 하단 장치 목록에서 쓰는 마이크 선택.
    #  메뉴5 는 [*.]lms.example.com 마이크 허용을 넣기만 하고 지금 상태를 보여주지 않았다. 여기서는 읽기만 한다.
    #  브라우저가 고른 마이크(Preferences 의 media.default_audio_capture_device)는 값이 엔드포인트 ID 원문이라는
    #  가정으로 [1-2] 목록과 맞춰 본다(미검증). 안 맞으면 '직접 확인'만 띄우고 단정하지 않는다.
    Write-Host "`n[5-1] 브라우저 마이크 (차단 여부 / 브라우저가 고른 마이크)" -ForegroundColor Yellow
    $micBlocked = @(); $micPick = @(); $micBrowserChecked = $false
    if ($script:UserScope -ne 'same' -and $script:UserScope -ne 'mapped') {
        Write-Host "  선생님 프로필 확정 못 함 - 미검증 (화상수업앱 창 자물쇠에서 직접 확인)" -ForegroundColor DarkYellow
    } else {
        $broots = [ordered]@{ Chrome = (Join-Path $script:TargetLocalAppData 'Google\Chrome\User Data')
                              Edge   = (Join-Path $script:TargetLocalAppData 'Microsoft\Edge\User Data') }
        $anyB = $false; $anyBFail = $false
        foreach ($b in $broots.Keys) {
            $broot = $broots[$b]
            if (-not (Test-Path -LiteralPath $broot)) { continue }
            $pds = @(Get-ChildItem -LiteralPath $broot -Directory -ErrorAction SilentlyContinue |
                     Where-Object { $_.Name -eq 'Default' -or $_.Name -like 'Profile*' })
            foreach ($pd in $pds) {
                $pref = Join-Path $pd.FullName 'Preferences'
                if (-not (Test-Path -LiteralPath $pref)) { continue }
                $j = $null
                try { $j = Get-Content -LiteralPath $pref -Raw -Encoding UTF8 -ErrorAction Stop | ConvertFrom-Json -ErrorAction Stop }
                catch { Write-Host ("  {0}/{1}: Preferences 읽기 실패" -f $b, $pd.Name) -ForegroundColor DarkYellow; $anyBFail = $true; continue }
                $anyB = $true
                $ptag = '{0}/{1}' -f $b, $pd.Name
                $parts = @(); $bad = $false
                $dv = $null
                try { $dv = $j.profile.default_content_setting_values.media_stream_mic } catch {}
                if ($dv -eq 2) { $parts += '마이크 기본값 차단'; $micBlocked += ('{0} 마이크 기본값' -f $ptag); $bad = $true }
                $mex = $null
                try { $mex = $j.profile.content_settings.exceptions.media_stream_mic } catch {}
                if ($mex) {
                    foreach ($p in $mex.PSObject.Properties) {
                        if ($p.Name -notmatch 'lms') { continue }
                        $sv = $null
                        try { $sv = $p.Value.setting } catch {}
                        if ($sv -eq 2) { $parts += ('{0} 차단' -f $p.Name); $micBlocked += ('{0} {1}' -f $ptag, $p.Name); $bad = $true }
                        elseif ($sv -eq 1) { $parts += ('{0} 허용' -f $p.Name) }
                    }
                }
                $pick = $null
                try { $pick = [string]$j.media.default_audio_capture_device } catch {}
                if ($pick -and $pick -notmatch '^(default|communications)$') {
                    $pl  = $pick.ToLower()
                    $hit = @($micActive | Where-Object { $pl.EndsWith($_.Guid) })[0]
                    if ($hit) {
                        $parts += ('고른 마이크 {0}' -f $hit.Name)
                        if (-not $hit.IsDefault) { $micPick += ('{0} → {1} (Windows 기본 장치 아님)' -f $ptag, $hit.Name); $bad = $true }
                    } else {
                        $parts += '고른 마이크가 [사용] 장치와 안 맞음(값 형식 미검증)'
                        $micPick += ('{0} → 고른 마이크 직접 확인' -f $ptag)
                    }
                }
                if (-not $parts) { $parts = @('차단 없음 / 마이크 = Windows 기본 장치') }
                $col = if ($bad) { 'Red' } else { 'Gray' }
                Write-Host ("  {0}: {1}" -f $ptag, ($parts -join ' / ')) -ForegroundColor $col
            }
        }
        if (-not $anyB -and -not $anyBFail) { Write-Host "  크롬·엣지 프로필 없음" -ForegroundColor DarkGray }
        # v3.6.16 (외부 QA 재검수): 하나도 못 읽었는데 검사 완료로 쳤다 → 읽기 성공 + 실패 없음일 때만 완료.
        $micBrowserChecked = ($anyB -and -not $anyBFail)
        if ($anyBFail) { Write-Host "  ※ 읽지 못한 프로필이 있어 브라우저 마이크는 미검증으로 판정합니다." -ForegroundColor DarkYellow }
    }

    # ─────────────────────────────────────────────────────────────
    # [6] 자동 판정 - 다음 조치를 계층별로 지정
    # ─────────────────────────────────────────────────────────────
    Write-Host "`n[6] 판정" -ForegroundColor Cyan
    if ($usbEnumFail) {
        Write-Host "  ▶ 물리 계층 - USB 열거 실패 (코드43 / VID_0000)" -ForegroundColor Red
        Write-Host "     1) 웹캠을 본체 '반대편' USB 포트에 직결 (허브 제거)" -ForegroundColor White
        Write-Host "        ※ 장치 속성 [일반] 탭의 '위치' 값이 바뀌어야 실제로 포트가 바뀐 것" -ForegroundColor DarkGray
        Write-Host "     2) 완전 종료 → 본체 전원선 분리 30초 → 재연결 (재시작은 효과 없음)" -ForegroundColor White
        Write-Host "     3) 위 2회 후에도 동일하면 케이블/웹캠 교체" -ForegroundColor White
        Write-Host "     ※ 보안프로그램·브라우저 정리는 이 증상과 무관. 시간 쓰지 말 것" -ForegroundColor DarkYellow
    }
    elseif ($camImage) {
        # v3.6.6 QC: '오등록됨' 이라고 단정했다. Image 클래스는 스캐너·디지털카메라의
        #  정상 분류이기도 하다. 사실(어떤 클래스로 잡혔는지)만 적고 판단은 아래에서 사람이 한다.
        Write-Host "  ▶ 카메라 후보가 Image(WIA) 클래스로 등록돼 있습니다" -ForegroundColor Yellow
        Write-Host "     Image 는 스캐너·디지털카메라의 정상 분류이기도 합니다 - 이것만으로 오등록은 아닙니다." -ForegroundColor DarkGray
        Write-Host "     장치는 정상이나 Media Foundation(카메라앱·브라우저)이 접근 불가" -ForegroundColor DarkGray
        if ($badInfList) {
            # ★ /uninstall /force 는 그 드라이버 패키지를 쓰는 '모든' 장치에서 제거한다.
            #   내장 카메라와 외장 웹캠이 같은 패키지를 쓰거나 복합 장치(카메라+마이크)면
            #   멀쩡한 장치까지 같이 날아간다. 안내 전에 공유 장치를 전수 조회한다.
            # v3.6.2 F02: badInfList 에는 Camera 클래스의 정상 웹캠까지 들어온다.
            #  오등록 분기의 대상은 'Image 클래스로 잡힌 카메라'뿐이다. 그 밖의 INF 를
            #  제거 대상으로 안내하면 멀쩡한 웹캠 드라이버까지 지우게 된다.
            #  ※ Image 클래스에는 스캐너·디지털카메라도 포함된다. Image 라는 사실만으로
            #    오등록이라고 단정하지 말 것 - 장치 이름을 눈으로 확인한 뒤 진행한다.
            $imgTargets = @($badInfList | Where-Object { $_.Class -eq 'Image' } | Sort-Object Inf -Unique)
            $other = @($badInfList | Where-Object { $_.Class -ne 'Image' })
            if ($other) {
                Write-Host "     (참고) 아래는 Image 오등록이 아니므로 제거 대상이 아니다:" -ForegroundColor DarkGray
                $other | ForEach-Object { Write-Host ("        {0} [{1}] - {2}" -f $_.Device, $_.Class, $_.Inf) -ForegroundColor DarkGray }
            }
            if (-not $imgTargets) {
                Write-Host "     Image 클래스로 오등록된 카메라가 없다 - 제거 안내를 만들지 않는다." -ForegroundColor DarkGray
            }
            foreach ($bi in $imgTargets) {
                $script:__probeFail = 0
                # v3.6.5 R2: Image 클래스라는 이유만으로 오등록으로 확정하고 제거 명령까지
                #  만들었다. Image 에는 정상 스캐너·디지털카메라가 들어간다.
                #  → 이 장치가 '지금 문제인 그 카메라'가 맞는지 사람이 확인해야 진행한다.
                Write-Host ("     대상 장치 : {0}" -f $bi.Device) -ForegroundColor White
                Write-Host ("     InstanceId: {0}" -f $bi.InstanceId) -ForegroundColor DarkGray
                Write-Host  "     ※ Image 클래스에는 정상 스캐너·디지털카메라도 들어갑니다." -ForegroundColor DarkYellow
                if ((Read-Host "     이 장치가 지금 문제인 '카메라'가 맞습니까? (y=맞음 / n=건너뜀)") -ne 'y') {
                    Write-Host "     건너뜁니다 - 제거 명령을 만들지 않습니다." -ForegroundColor DarkGray
                    continue
                }
                Write-Host ("     대상 INF : {0}   (장치: {1})" -f $bi.Inf, $bi.Device) -ForegroundColor White
                $users = @()
                try {
                    # v3.6.5 R2: 개별 장치의 INF 조회 실패를 SilentlyContinue 로 삼켰다.
                    #  두 장치가 같은 INF 를 쓰는데 한쪽 조회가 실패하면 '1개 확인'이 되어
                    #  '이 장치에만 영향'과 강제 제거 명령이 나갔다. 실패 건수를 센다.
                    $probeFail = 0
                    $users = @(Get-PnpDevice -ErrorAction Stop | ForEach-Object {
                        $dv = $_
                        $ip = $null
                        try { $ip = ($dv | Get-PnpDeviceProperty -KeyName 'DEVPKEY_Device_DriverInfPath' -ErrorAction Stop).Data }
                        catch { $script:__probeFail++ ; return }
                        if ($ip -eq $bi.Inf) { '{0} [{1}]' -f $dv.FriendlyName, $dv.Class }
                    } | Where-Object { $_ })
                    $probeFail = $script:__probeFail
                } catch {}
                if ($probeFail -gt 0 -and $users.Count -le 1) {
                    # 조회에 실패한 장치가 있으면 '단독 사용'이라고 말할 수 없다.
                    Write-Host ("     ★ 장치 {0}개의 드라이버 정보를 읽지 못했다 - 공유 여부 미확인." -f $probeFail) -ForegroundColor Red
                    Write-Host  "     → 패키지 강제 제거 명령을 만들지 않는다. 장치관리자에서 직접 확인할 것." -ForegroundColor Yellow
                    Write-Host  "        대안: 장치관리자 > 해당 카메라 > 드라이버 업데이트 >" -ForegroundColor Yellow
                    Write-Host  "              목록에서 직접 선택 > 'USB 비디오 장치'" -ForegroundColor Yellow
                } elseif ($users.Count -gt 1) {
                    Write-Host ("     ★ 이 INF 를 {0}개 장치가 공유한다 - 제거하면 전부 영향받는다:" -f $users.Count) -ForegroundColor Red
                    $users | ForEach-Object { Write-Host ("          {0}" -f $_) -ForegroundColor Red }
                    Write-Host  "     → 공유 장치가 있으면 드라이버 패키지 제거 대신 아래를 먼저 쓸 것:" -ForegroundColor Yellow
                    Write-Host  "        장치관리자 > 해당 카메라 > 드라이버 업데이트 > 목록에서 직접 선택 > 'USB 비디오 장치'" -ForegroundColor Yellow
                } elseif ($users.Count -eq 1) {
                    Write-Host ("     사용 장치 1개 확인 ({0}) - 이 장치에만 영향" -f $users[0]) -ForegroundColor DarkGray
                    Write-Host "     조치: 관리자 권한으로 아래 실행 후 재부팅" -ForegroundColor White
                    Write-Host ("            pnputil /delete-driver {0} /uninstall /force" -f $bi.Inf) -ForegroundColor Green
                } else {
                    # v3.6.2 F02: 조회 실패(0건)를 '단독 사용'으로 처리하면 안 된다.
                    #  어느 장치가 이 패키지를 쓰는지 모르는 상태에서 /force 를 안내하는 셈이 된다.
                    Write-Host "     ★ 사용 장치를 조회하지 못했다 - 제거 명령을 만들지 않는다." -ForegroundColor Red
                    Write-Host  "     → 장치관리자에서 이 INF 를 쓰는 장치를 눈으로 확인한 뒤 판단할 것." -ForegroundColor Yellow
                    Write-Host  "        대안(패키지를 지우지 않는 방법): 장치관리자 > 해당 카메라 >" -ForegroundColor Yellow
                    Write-Host  "        드라이버 업데이트 > 목록에서 직접 선택 > 'USB 비디오 장치'" -ForegroundColor Yellow
                }
            }
        } else {
            Write-Host "     조치: 장치관리자 > 드라이버 업데이트 > 목록에서 직접 선택 > 'USB 비디오 장치'" -ForegroundColor White
        }
        Write-Host "     재부팅 후 Class 가 Camera 로 바뀌면 성공" -ForegroundColor DarkGray
    }
    elseif ($denied) {
        Write-Host "  ▶ 권한 계층 - 아래 항목이 Deny" -ForegroundColor Yellow
        $denied | ForEach-Object { Write-Host ("     {0}" -f $_) -ForegroundColor White }
        $dk = @()
        if ($denied -match 'webcam')     { $dk += "'카메라 개인'" }
        if ($denied -match 'microphone') { $dk += "'마이크 개인'" }
        Write-Host ("     조치: Win+S > {0} > 3개 토글 모두 켬" -f ($dk -join ' / ')) -ForegroundColor White
        Write-Host "            (장치 액세스 / 앱 액세스 / 데스크톱 앱 액세스)" -ForegroundColor DarkGray
    }
    elseif ($camOK | Where-Object Class -eq 'Camera') {
        if ($permUnverified -contains 'webcam') {
            # v3.6.15 (외부 QA): 권한을 못 읽었는데 '권한 정상'으로 말했다.
            Write-Host "  ▶ 장치·드라이버 정상 / 카메라 권한은 선생님 계정을 못 읽어 미검증" -ForegroundColor Yellow
            Write-Host "     Win+S > '카메라 개인' 3개 토글을 선생님 화면에서 직접 확인" -ForegroundColor White
        } else {
            Write-Host "  ▶ 장치·드라이버·권한 모두 정상" -ForegroundColor Green
        }
        Write-Host "     남은 확인 순서:" -ForegroundColor White
        Write-Host "     1) 화상수업앱 화면 좌상단 카메라 아이콘 빗금 여부" -ForegroundColor White
        Write-Host "     2) Windows 카메라 앱 테스트 후 반드시 종료 (점유하면 화상수업앱 실패)" -ForegroundColor White
        Write-Host "     3) 브라우저 자물쇠 > 카메라 [허용] + 장치 목록에서 올바른 카메라 선택" -ForegroundColor White
    }
    elseif ($camDisabled) {
        # v3.6.19: 코드 22 를 '카메라 미연결'로 안내했다(2026-10-07 실측).
        Write-Host ("  ▶ 카메라가 장치 관리자에서 [사용 안 함](코드 22): {0}" -f (($camDisabled | ForEach-Object { $_.FriendlyName }) -join ', ')) -ForegroundColor Yellow
        Write-Host "     고장이 아니라 꺼 둔 상태. 선생님이 일부러 끈 것일 수 있음 → 수업에 이 카메라를 쓰는지 먼저 확인" -ForegroundColor White
        Write-Host "     쓰신다면: 장치 관리자 > 해당 카메라 > [장치 사용] → 화상수업앱 다시 입장 후 카메라 선택" -ForegroundColor White
        if ($dsCams) { Write-Host ("     ※ 가상카메라({0})를 대신 쓰고 있을 수 있음 - [2-1]" -f ($dsCams -join ', ')) -ForegroundColor DarkGray }
    }
    elseif ($dsCams) {
        Write-Host "  ▶ 실제 카메라는 없고 가상카메라만 있음 - [2-1]" -ForegroundColor Yellow
        Write-Host "     선생님이 휴대폰·PRISM 등을 카메라로 쓰는지 확인. 웹캠을 쓰신다면 꽂혀 있는지 확인" -ForegroundColor White
    }
    else {
        Write-Host "  ▶ 카메라 미연결 - 웹캠이 PC 에 꽂혀 있는지 먼저 확인" -ForegroundColor Red
        Write-Host "     노트북이면 제조사 보안SW 확인: 삼성 Samsung Security(녹화/녹음 방지)," -ForegroundColor White
        Write-Host "     LG Security Center / Smart Assistant(Fn+F4), 레노버 Vantage(카메라 프라이버시)" -ForegroundColor White
    }

    # v3.6.14: 마이크 판정 (카메라 판정과 별개)
    $micDenied = @($denied | Where-Object { $_ -match 'microphone' })
    # v3.6.19: 기본 녹음 장치 볼륨이 가이드 기준(80) 미만이면 판정에 올린다(2026-10-07 실측: 30%).
    $micLow = $null
    if ($das) { $micLow = @($das | Where-Object { $_.Flow -eq 1 -and $_.Role -eq 0 -and $_.Vol -ge 0 -and $_.Vol -lt 80 -and -not $_.Muted })[0] }
    if ($micActive.Count -ge 2 -or $micBlocked -or $micPick -or $micDenied -or $micLow) {
        Write-Host "  ▶ 마이크" -ForegroundColor Yellow
        if ($micLow) {
            $mlName = if ($micLow.Name) { $micLow.Name } else { '기본 녹음 장치' }
            Write-Host ("     {0} 볼륨 {1}% → 속성 > 수준 80 이상 (가이드 p.20·p.24)" -f $mlName, $micLow.Vol) -ForegroundColor White
        }
        if ($micDenied) {
            Write-Host ("     마이크 권한 Deny: {0} → Win+S > '마이크 개인' 3개 토글 켬 (가이드 p.22)" -f ($micDenied -join ', ')) -ForegroundColor White
        }
        if ($micActive.Count -ge 2) {
            Write-Host ("     녹음 장치 {0}개 [사용] → 녹음 탭: 쓰는 마이크 1개만 [사용] + 기본 장치·기본 통신 장치 (가이드 p.19)" -f $micActive.Count) -ForegroundColor White
        }
        if ($micBlocked) {
            Write-Host ("     브라우저 마이크 차단: {0}" -f ($micBlocked -join ', ')) -ForegroundColor White
            Write-Host  "       → 화상수업앱 창 자물쇠 > 마이크 [허용] (가이드 p.22 ①, Q041)" -ForegroundColor DarkGray
        }
        if ($micPick) {
            Write-Host ("     브라우저가 고른 마이크: {0}" -f ($micPick -join ', ')) -ForegroundColor White
            Write-Host  "       → chrome://settings/content/microphone (엣지 edge://...) 에서 쓰는 마이크 선택 (가이드 p.22 ②)" -ForegroundColor DarkGray
        }
    } elseif ($micRegOK -and $micActive.Count -eq 1) {
        # v3.6.15: [5-1] 을 건너뛰었거나 권한을 못 읽었으면 '차단 없음'이라고 말하지 않는다.
        $mUnv = @()
        if (-not $micBrowserChecked) { $mUnv += '브라우저 설정' }
        if ($permUnverified -contains 'microphone') { $mUnv += '마이크 개인정보 권한' }
        if ($mUnv) {
            Write-Host ("  ▶ 마이크: 녹음 장치 1개 / {0} 미검증 - 선생님 화면에서 직접 확인" -f ($mUnv -join '·')) -ForegroundColor Yellow
        } else {
            Write-Host "  ▶ 마이크: 녹음 장치 1개·브라우저 차단 없음" -ForegroundColor Green
        }
        Write-Host "     남은 확인: 화상수업앱 우측 상단 톱니 [설정]에서 마이크 재선택(Q047·Q072)" -ForegroundColor White
        Write-Host "               소리 설정 > 입력 > 장치 속성 > 테스트 시작 (관찰값 10 이하면 볼륨·설정 재점검, 가이드 p.24)" -ForegroundColor White
    }

    # ─────────────────────────────────────────────────────────────
    # [7] 소리 설정
    # ─────────────────────────────────────────────────────────────
    Write-Host "`n[7] 소리 설정을 엽니다 (mmsys.cpl)" -ForegroundColor Yellow
    Write-Host "  (1) 재생/녹음 탭 > 실사용 장치 우클릭 > [기본 장치로 설정]" -ForegroundColor DarkGray
    Write-Host "  (2) 미사용 장치 우클릭 > [사용 안 함]  ← 장치 뒤바뀜 재발 방지 핵심" -ForegroundColor DarkGray
    Write-Host "  (3) 녹음 탭 마이크 [속성]>[고급/향상] > 오디오 향상 끄기 (잡음 사례)" -ForegroundColor DarkGray
    if ($micActive.Count -ge 2) {
        Write-Host "  → 녹음 장치가 2개 이상이라 녹음 탭으로 엽니다" -ForegroundColor Yellow
        try { Start-Process control.exe -ArgumentList 'mmsys.cpl,,1' -ErrorAction Stop } catch { Start-Process mmsys.cpl }
    } else {
        Start-Process mmsys.cpl
    }
    Write-Host ""
}

# ── 11) 강의채널 재생 점검 (v3.6.11 확장: http 강의 창 + Agent 버전 + 캡처 프로그램) ──
# 실측 패턴: Agent 신버전(1.4.x/1.5.x) 오류 → v1.3.19.8 재설치로 해결 반복.
# v3.6.11 (2026-10-02 실측):
#   · 원인이 '강의 창 http' 였다. Agent·버전 정상인데 주소만 https 로 바꾸자 즉시 재생.
#     → 버전보다 먼저 본다(확인 10초).
#   · StarPlayer 본체 1.5.27.61 + Agent 1.3.19.8 공존 상태로 정상 재생 → 버전 판정은 Agent 에만.
#     가이드 Q052 도 'StarPlayer 가 아니라 StarPlayerAgent v1.3.19.8 이상'.
#   · ALCapture(알캡처)가 실행 중이었는데 설치 목록에 이름이 안 보였다 → 프로세스로 본다(가이드 Q057).
function Check-StarPlayer {
    Write-Host "`n=== 강의채널 재생 점검 ===" -ForegroundColor Cyan

    # [1] 강의 창 주소
    Write-Host "`n[1] 강의 창 주소가 http:// 인가?  ← 먼저 확인" -ForegroundColor Yellow
    Write-Host "  증상: Agent 가 정상인데도 '스타플레이어를 구동하려면 설치 프로그램을 다운로드' 문구" -ForegroundColor DarkGray
    Write-Host "  ① 강의 창 주소의 http:// 를 https:// 로 고쳐 재생 → 재생되면 원인 확정" -ForegroundColor Gray
    Write-Host "  ② 재발 방지: Edge 설정 '자동 HTTPS로 더 안전한 연결로 자동 전환' 켜기 → Edge 재시작" -ForegroundColor Gray
    Write-Host "     (크롬은 chrome://settings/security 의 '항상 보안 연결 사용' - 미검증)" -ForegroundColor DarkGray
    Write-Host "  ③ CRM 즐겨찾기·새 탭 바로가기를 https://crm.lms.example.com/ 로 (서버는 첫 화면만 https 로 보냄)" -ForegroundColor Gray
    $spEdge = Get-BrowserExe edge
    if ($spEdge) {
        if ((Read-Host "  Edge 자동 HTTPS 설정 페이지 열기? (y/n)") -eq 'y') {
            Open-BrowserPage $spEdge 'edge://settings/?search=https'
            Write-Host "  → 스위치를 켠 뒤 Edge 를 완전히 닫았다가 다시 여세요." -ForegroundColor Green
        }
    }

    # [2] Agent 버전
    Write-Host "`n[2] StarPlayerAgent 버전" -ForegroundColor Yellow
    $paths = @(
        'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Uninstall\*',
        'HKLM:\SOFTWARE\WOW6432Node\Microsoft\Windows\CurrentVersion\Uninstall\*',
        (Get-UserRegPath 'SOFTWARE\Microsoft\Windows\CurrentVersion\Uninstall\*')
    ) | Where-Object { $_ }
    $sp = foreach ($p in $paths) {
        Get-ItemProperty $p -ErrorAction SilentlyContinue |
        Where-Object { $_.DisplayName -match 'StarPlayer|스타플레이어' }
    }
    $sp     = @($sp | Sort-Object DisplayName -Unique)
    $agents = @($sp | Where-Object { $_.DisplayName -match 'Agent|에이전트' })
    $bodies = @($sp | Where-Object { $_.DisplayName -notmatch 'Agent|에이전트' })
    if (-not $agents) {
        Write-Host "  StarPlayerAgent 미설치 → 강의채널 입장 시 설치 안내가 뜸 (가이드 Q052)" -ForegroundColor Yellow
    }
    foreach ($s in $agents) {
        # v3.6.11: 레지스트리 DisplayVersion 이 '1,3,19,8'(쉼표)로 들어 있는 PC 가 있다(실측 2026-10-02).
        #  '1.3.19.8' 과 문자열 그대로 비교하면 정상 버전을 빨간색 '불일치'로 띄운다 → 쉼표를 점으로 바꿔 비교.
        $spVer = ([string]$s.DisplayVersion) -replace ',', '.'
        if ($spVer -eq $VerifiedStarPlayer) {
            Write-Host ("  {0}  v{1}  = 검증 버전 (버전 무혐의)" -f $s.DisplayName, $spVer) -ForegroundColor Green
        } else {
            Write-Host ("  {0}  v{1}  ≠ 검증 버전 v{2}" -f $s.DisplayName, $spVer, $VerifiedStarPlayer) -ForegroundColor Red
            Write-Host ("  → 재생 오류 시: 현재 버전 삭제 후 v{0} 관리자 권한 재설치" -f $VerifiedStarPlayer) -ForegroundColor Yellow
        }
    }
    foreach ($s in $bodies) {
        Write-Host ("  {0}  v{1}  (참고 - 판정 대상 아님. 본체 1.5.x 공존 상태로 정상 재생 확인됨)" -f $s.DisplayName, $s.DisplayVersion) -ForegroundColor DarkGray
    }

    # [3] 캡처·녹화 프로그램 실행 여부
    Write-Host "`n[3] 캡처·녹화 프로그램 실행 여부 (가이드 Q057 '불법적인 시도가 감지')" -ForegroundColor Yellow
    $capPat = 'ALCapture|bdcam|Bandicam|^obs(32|64)?$|XSplit|Camtasia|CamRecorder|Snagit|CamStudio|^PDR$|ShareX|GomCam|^oCam$|PicPick|Lightshot|^GameBar$'
    $caps = @(Get-Process -ErrorAction SilentlyContinue | Where-Object { $_.Name -match $capPat })
    if ($caps) {
        foreach ($c in $caps) {
            $cp = $null
            try { $cp = $c.Path } catch { }
            Write-Host ("  ★ {0} (PID {1}) {2}" -f $c.Name, $c.Id, $cp) -ForegroundColor Red
        }
        Write-Host "  → 실행 중이면 '불법적인 시도가 감지되었습니다'로 재생이 막힐 수 있음. 종료 후 재생 확인" -ForegroundColor Yellow
        Write-Host "     선생님 개인 도구일 수 있어 삭제는 확인 후 (설치 목록에 없으면 위 경로 폴더의 uninstall)" -ForegroundColor DarkGray
        if ((Read-Host "  지금 종료? (y/n)") -eq 'y') {
            $caps | ForEach-Object { Stop-Process -Id $_.Id -Force -ErrorAction SilentlyContinue }
            Write-Host "  종료함 (재부팅·로그인 시 다시 뜰 수 있음)" -ForegroundColor Green
            Log-Action ("캡처 프로그램 종료({0})" -f ((@($caps | ForEach-Object { $_.Name }) | Select-Object -Unique) -join ', '))
        }
    } else {
        Write-Host "  없음" -ForegroundColor DarkGray
    }

    Write-Host "`n  ※ 그 밖에: 버퍼링이면 하드웨어 가속 끄기(가이드 Q059) / 사이트 권한 '디바이스의 앱' 허용 / Adblock류 확장 삭제`n" -ForegroundColor DarkGray
}

# ── 12) 시간 동기화 (OTP 반복 오류의 숨은 원인 - 재설치보다 먼저) ─────
# 실측: "OTP 재설치해도 오류 반복" → 윈도우 시간 설정으로 해결.
# OTP는 시간 기반(TOTP)이라 PC 시계가 어긋나면 무조건 실패.
function Sync-Time {
    Write-Host "`n=== 윈도우 시간 동기화 (OTP 오류 시 1순위) ===" -ForegroundColor Cyan
    try {
        $svc = Get-Service W32Time -ErrorAction Stop
        if ($svc.Status -ne 'Running') {
            Start-Service W32Time -ErrorAction SilentlyContinue; Start-Sleep 1
            Write-Host "  W32Time 서비스 시작함" -ForegroundColor DarkGray
        }
    } catch {}
    Write-Host "`n[현재 동기화 상태]" -ForegroundColor Yellow
    w32tm /query /status 2>$null | ForEach-Object { Write-Host "  $_" -ForegroundColor Gray }
    if ((Read-Host "`n지금 동기화(resync) 실행? (y/n)") -eq 'y') {
        $r = (w32tm /resync 2>&1 | Out-String).Trim()
        $tsRc = $LASTEXITCODE
        Write-Host "  $r" -ForegroundColor Gray
        # v3.6.13 (외부 QA L4): 종료코드를 먼저 본다(표시 언어에 따라 문구가 다르다).
        if ($tsRc -eq 0 -or $r -match '성공|success') {
            Write-Host "  완료" -ForegroundColor Green
            Log-Action "윈도우 시간 동기화(w32tm)"
        } else {
            Write-Host "  실패 → 설정 창에서 [지금 동기화] 수동 클릭" -ForegroundColor Yellow
            Start-Process "ms-settings:dateandtime"
        }
    }
    Write-Host ""
}

# ── 메인 루프 ───────────────────────────────────────────────────────
# ── 13) eISP 2.0 강제 제거 (자체 언인스톨러 없음 → 서비스/폴더/레지스트리 직접 정리) ──
# 근거: eISP(VP 전자결제)는 UI/일반 제거 불가. VPWalletService 중지·삭제 + VP 폴더 + Uninstall 키 제거.
function Remove-eISP {
    Write-Host "`n=== eISP 2.0 강제 제거 (CMD) ===" -ForegroundColor Cyan
    Write-Host "  eISP는 자체 언인스톨러가 없어 UI/일반 제거로 안 지워집니다. 서비스+폴더+레지스트리를 직접 정리합니다." -ForegroundColor DarkGray

    # 삭제해도 되는 경로인지 판정한다.
    #  v3.6.1: InstallLocation 을 그대로 믿고 Remove-Item -Recurse -Force 하던 자리.
    #  레지스트리 InstallLocation 에 드라이브 루트(C:\)나 'C:\Program Files' 자체가
    #  등록된 프로그램이 실재한다 - v3.0 Get-DllOwnerName 주석에 같은 실측이 적혀 있다.
    #  그런 값이 걸리면 그 폴더를 통째로 날린다. 되돌릴 수 없다.
    #  → 드라이브 루트·시스템 상위 폴더를 막고, 폴더명이 VP/eISP 계열일 때만 허용한다.
    #  v3.6.2: v3.6.1 의 Test-SafeDeleteDir 에 세 가지 구멍이 있었다.
    #   (1) 정규화한 경로로 검사해놓고 삭제는 '원본 문자열'로 했다 - 검사 대상과 삭제 대상이 달랐다.
    #   (2) Remove-Item 을 -Path 로 호출해 와일드카드가 해석됐다.
    #       'C:\QA\VP[12]' 는 검사를 통과하고 -Path 에서 VP1·VP2 에 매칭된다.
    #   (3) 접두사 매칭이라 VPNClient 같은 무관한 제품 폴더도 통과했다.
    #  → 정규화한 '단일 절대경로'를 돌려주고, 같은 값을 -LiteralPath 로 삭제한다.
    #    와일드카드 문자가 든 경로는 아예 거부하고, 폴더명은 정확히 맞을 때만 허용한다.
    function Resolve-SafeDeleteDir([string]$raw) {
        if ([string]::IsNullOrWhiteSpace($raw)) { return $null }
        $s = $raw.Trim().Trim('"')
        if ($s -match '[\*\?\[\]]') { return $null }                  # 와일드카드/대괄호 경로 거부
        $full = $null
        try { $full = [IO.Path]::GetFullPath($s) } catch { return $null }
        $full = $full.TrimEnd('\')
        if ($full.Length -le 3) { return $null }                      # C:\ 등 드라이브 루트
        if (($full -split '\\').Count -lt 3) { return $null }         # 최소 2단계 깊이
        # v3.6.5 R4: '\\\\' 는 PowerShell 작은따옴표에서 '역슬래시 4개' 리터럴이다.
        #  StartsWith 는 정규식이 아니므로 UNC 시작(역슬래시 2개)과 절대 일치하지 않았다.
        #  → 로컬 드라이브 문자로 시작하는 경로만 통과시킨다(화이트리스트).
        if ($full -notmatch '^[A-Za-z]:\\') { return $null }           # UNC·상대경로·장치경로 전부 거부
        $deny = @($env:SystemRoot, $env:ProgramFiles, ${env:ProgramFiles(x86)}, $env:ProgramData,
                  $env:USERPROFILE, (Join-Path $env:SystemDrive 'Users'), $env:SystemDrive) |
                Where-Object { $_ } | ForEach-Object { $_.TrimEnd('\') }
        foreach ($d in $deny) { if ($full -ieq $d) { return $null } }  # 상위 폴더 자체는 금지
        # 접두사가 아니라 전체 일치. 'VP' 단독 또는 'eISP…' 형태만 eISP 제품 폴더로 본다.
        if ((Split-Path $full -Leaf) -notmatch '(?i)^(VP|eISP[\w.\- ]*)$') { return $null }
        return $full
    }

    # eISP 레지스트리 키(DisplayName으로 탐색) + 설치경로
    $eispKeys = @(); $instLoc = @()
    foreach ($base in 'HKLM:\SOFTWARE\WOW6432Node\Microsoft\Windows\CurrentVersion\Uninstall','HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Uninstall') {
        Get-ChildItem $base -ErrorAction SilentlyContinue | ForEach-Object {
            $pp = Get-ItemProperty $_.PSPath -ErrorAction SilentlyContinue
            if ($pp.DisplayName -like 'eISP*') { $eispKeys += $_.PSPath; if ($pp.InstallLocation) { $instLoc += $pp.InstallLocation } }
        }
    }
    $svc  = Get-Service -Name 'VPWalletService' -ErrorAction SilentlyContinue
    $scRc = $null
    $dirs = @()
    $rejected = @()
    if ($eispKeys -or $svc) {
        $cands = @($instLoc + "$env:ProgramFiles\VP" + "${env:ProgramFiles(x86)}\VP") |
                 Where-Object { $_ -and (Test-Path $_) } | Select-Object -Unique
        foreach ($c in $cands) {
            $safe = Resolve-SafeDeleteDir $c
            if ($safe) { $dirs += $safe } else { $rejected += $c }   # 정규화된 경로만 담는다
        }
        $dirs = @($dirs | Select-Object -Unique)
    }

    if (-not $svc -and -not $dirs -and -not $eispKeys) {
        Write-Host "  eISP 흔적 없음 (미설치이거나 이미 제거됨).`n" -ForegroundColor Green; return
    }
    Write-Host ("  - 서비스   : {0}" -f $(if ($svc) { "VPWalletService($($svc.Status))" } else { '없음' })) -ForegroundColor Gray
    Write-Host  "  - 삭제 폴더:" -ForegroundColor Gray
    if ($dirs) { $dirs | ForEach-Object { Write-Host "      $_" -ForegroundColor Gray } } else { Write-Host "      없음" -ForegroundColor Gray }
    if ($rejected) {
        Write-Host "  - 삭제 제외(안전장치):" -ForegroundColor Yellow
        $rejected | ForEach-Object { Write-Host ("      {0}   ← 드라이브 루트/시스템 상위 폴더이거나 VP·eISP 폴더가 아님" -f $_) -ForegroundColor Yellow }
        Write-Host  "      이 경로는 자동 삭제하지 않는다. 필요하면 눈으로 확인하고 직접 지울 것." -ForegroundColor DarkYellow
    }
    Write-Host ("  - 레지스트리: {0}개" -f $eispKeys.Count) -ForegroundColor Gray

    Write-Host "`n  ★ 위 폴더/서비스/레지스트리를 실제로 삭제합니다 (되돌릴 수 없음)." -ForegroundColor Red
    if ((Read-Host "  진행할까요? (y/n)") -ne 'y') { Write-Host "  취소됨.`n"; return }
    # v3.6.13 (외부 QA H1): 지우기 전에 Uninstall 레지스트리 키를 .reg 로 백업(되돌리기: reg import). 폴더는 용량 때문에 백업 안 함.
    $eispBak = @()
    foreach ($k in $eispKeys) {
        $native = ([string]$k) -replace '^.*?::', ''
        $bf = Join-Path $env:TEMP ("RST_eISP_{0}_{1}.reg" -f (Get-Date -Format yyyyMMdd_HHmmss), $eispBak.Count)
        & reg.exe export $native $bf /y 2>&1 | Out-Null
        if ($LASTEXITCODE -eq 0 -and (Test-Path -LiteralPath $bf)) { $eispBak += $bf }
    }
    if ($eispBak) {
        Write-Host ("  레지스트리 백업 {0}개 (되돌리기: reg import ""파일경로"")" -f $eispBak.Count) -ForegroundColor DarkGray
        $eispBak | ForEach-Object { Write-Host ("     {0}" -f $_) -ForegroundColor DarkGray }
    } elseif ($eispKeys) {
        if ((Read-Host "  레지스트리 백업 실패. 그래도 진행? (y/n)") -ne 'y') { Write-Host "  취소됨.`n"; return }
    }


    Get-Process -Name 'VPWalletService' -ErrorAction SilentlyContinue | ForEach-Object { try { Stop-Process -Id $_.Id -Force -ErrorAction SilentlyContinue } catch {} }
    if ($svc) {
        try { Stop-Service 'VPWalletService' -Force -ErrorAction SilentlyContinue } catch {}
        & sc.exe delete VPWalletService | Out-Null
        $scRc = $LASTEXITCODE
        if ($scRc -eq 0) { Write-Host "  서비스 삭제: VPWalletService" -ForegroundColor Green }
        else { Write-Host ("  서비스 삭제 실패: VPWalletService (sc.exe 코드 {0})" -f $scRc) -ForegroundColor Yellow }
    }
    foreach ($d in $dirs) {
        # -LiteralPath: 경로를 패턴이 아니라 글자 그대로 쓴다(v3.6.2 F01)
        try { Remove-Item -LiteralPath $d -Recurse -Force -ErrorAction Stop; Write-Host "  폴더 삭제: $d" -ForegroundColor Green }
        catch {
            # v3.6.1: 예전엔 무조건 '사용중'이라고 찍었다. 권한 거부·경로 문제일 수도 있어
            #  실제 예외를 그대로 보여준다(원인을 못 가리면 다음 조치를 못 정한다).
            Write-Host ("  폴더 삭제 실패: {0}" -f $d) -ForegroundColor Yellow
            Write-Host ("     사유: {0}" -f $_.Exception.Message) -ForegroundColor DarkRed
        }
    }
    foreach ($k in $eispKeys) {
        try { Remove-Item $k -Recurse -Force -ErrorAction Stop; Write-Host "  레지스트리 삭제 완료" -ForegroundColor Green } catch {}
    }

    # v3.3: 삭제 후 실제로 사라졌는지 재조회한다. 이전에는 확인 없이 '완료'로 찍어서
    #  폴더가 사용중이라 남았는데도 처리내역에는 제거 성공으로 기록됐다.
    Start-Sleep 1
    $leftSvc  = Get-Service -Name 'VPWalletService' -ErrorAction SilentlyContinue
    $leftDirs = @($dirs | Where-Object { Test-Path $_ })
    $leftKeys = @($eispKeys | Where-Object { Test-Path $_ })
    $leftAll  = @()
    # sc.exe delete 가 0 을 냈는데도 조회에 잡히면 '삭제 표시됨'(핸들이 남은 상태)이다.
    #  재부팅하면 사라지므로 실패가 아니다 - 부분실패로 세면 멀쩡한 제거가 오기록된다.
    $svcMarked = ($leftSvc -and $scRc -eq 0)
    if ($leftSvc -and -not $svcMarked) { $leftAll += "서비스(VPWalletService)" }
    if ($leftDirs) { $leftAll += ("폴더 {0}개" -f $leftDirs.Count) }
    if ($leftKeys) { $leftAll += ("레지스트리 {0}개" -f $leftKeys.Count) }

    if (-not $leftAll) {
        Log-Action "eISP 2.0 강제 제거 완료(서비스/폴더/레지스트리)"
        if ($svcMarked) {
            Write-Host "`n  완료 - 폴더·레지스트리 잔존 없음. 서비스는 '삭제 표시됨' 상태입니다." -ForegroundColor Cyan
            Write-Host "     재부팅하면 사라집니다. sc.exe delete 를 다시 칠 필요 없습니다.`n" -ForegroundColor DarkGray
        } else {
            Write-Host "`n  완료 - 잔존 없음 확인.`n" -ForegroundColor Cyan
        }
    } else {
        Log-Action ("eISP 2.0 강제 제거 부분실패(잔존: {0})" -f ($leftAll -join ', '))
        Write-Host ("`n  ★ 부분 실패 - 잔존: {0}" -f ($leftAll -join ', ')) -ForegroundColor Red
        $leftDirs | ForEach-Object { Write-Host ("     남은 폴더: {0}" -f $_) -ForegroundColor Yellow }
        if ($leftSvc -and -not $svcMarked) { Write-Host ("     서비스 상태: {0} / sc.exe 코드 {1} (재부팅 후 재시도)" -f $leftSvc.Status, $scRc) -ForegroundColor Yellow }
        Write-Host "     재부팅 후 메뉴13 재실행으로 마무리하세요.`n" -ForegroundColor DarkYellow
    }
}

# ── 14) Windows 시스템 파일 검사/복구 (DISM RestoreHealth → SFC) ──────
# 용도: PC 전반 불안정/느림, 윈도우 업데이트 실패, 원인불명 오류 지속 시(OS 파일 손상 복구).
# 하드웨어 아님 = 윈도우 시스템 파일 무결성 복구. 오래 걸림(10~30분)+DISM은 인터넷 필요.
function Repair-SystemFiles {
    Write-Host "`n=== Windows 시스템 파일 검사/복구 (DISM + SFC) ===" -ForegroundColor Cyan
    Write-Host "  용도: PC 전반 불안정/느림, 윈도우 업데이트 실패, 원인불명 오류 지속 시" -ForegroundColor DarkGray
    Write-Host "  ※ 하드웨어가 아니라 '윈도우 시스템 파일' 무결성 복구입니다." -ForegroundColor DarkGray
    Write-Host "  ※ 오래 걸립니다(10~30분) + DISM은 인터넷(윈도우 업데이트) 필요. 원격 세션 길게 잡힘." -ForegroundColor Yellow
    if ((Read-Host "  실행할까요? (y/n)") -ne 'y') { Write-Host "  취소됨.`n"; return }

    # v3.3: 종료코드를 확인한다. v3.2까지는 실패해도 '완료'로 찍고 처리내역까지 남겼다.
    #  DISM  : 0=성공, 3010=성공(재부팅 필요). 그 외는 실패(87=인자오류, 0x800f081f=소스없음 등)
    #  SFC   : 0=성공(위반 없음 또는 복구 완료). 그 외 실패
    Write-Host "`n[1/2] DISM 이미지 복구 (구성요소 저장소, 수분~수십분)..." -ForegroundColor Yellow
    DISM /Online /Cleanup-Image /RestoreHealth
    $dismRc = $LASTEXITCODE
    $dismOk = ($dismRc -eq 0 -or $dismRc -eq 3010)
    if ($dismOk) { Write-Host ("  DISM 성공 (코드 {0})" -f $dismRc) -ForegroundColor Green }
    else {
        Write-Host ("  DISM 실패 (코드 {0})" -f $dismRc) -ForegroundColor Red
        Write-Host "     0x800f081f/0x800f0906 = 복구 소스 없음. 인터넷(윈도우 업데이트) 연결 확인" -ForegroundColor DarkGray
        Write-Host "     로그: C:\Windows\Logs\DISM\dism.log" -ForegroundColor DarkGray
    }

    Write-Host "`n[2/2] SFC 시스템 파일 검사/복구..." -ForegroundColor Yellow
    sfc /scannow
    $sfcRc = $LASTEXITCODE
    $sfcOk = ($sfcRc -eq 0)
    if ($sfcOk) {
        Write-Host ("  SFC 실행 완료 (코드 {0})" -f $sfcRc) -ForegroundColor Green
        Write-Host "     ※ 코드 0 은 '끝까지 돌았다'까지입니다. 위 화면의 '복구했습니다 / 복구할 수" -ForegroundColor DarkGray
        Write-Host "        없습니다' 문구를 반드시 읽을 것 - 복구 실패도 0 으로 끝나는 경우가 있습니다." -ForegroundColor DarkGray
    }
    else {
        Write-Host ("  SFC 실패 (코드 {0})" -f $sfcRc) -ForegroundColor Red
        Write-Host "     로그: C:\Windows\Logs\CBS\CBS.log" -ForegroundColor DarkGray
    }

    # v3.6.3 F09: 종료코드 두 개만 보고 '복구 완료'로 기록했다. SFC 는 복구에 실패해도
    #  0 으로 끝나는 경우가 있어서, 화면에는 그 경고를 띄워놓고 로그에는 '완료'를 남기는
    #  모순이 있었다. 실행 결과와 복구 결과를 나누고, 복구 결과는 화면을 본 사람이 고른다.
    if ($dismOk -and $sfcOk) {
        Write-Host "`n  두 명령 모두 끝까지 실행됐습니다. 이제 SFC 가 화면에 뭐라고 했는지 고르세요." -ForegroundColor Cyan
        Write-Host "   1) 무결성 위반을 찾지 못했습니다          (손상 없음)" -ForegroundColor Gray
        Write-Host "   2) 손상된 파일을 찾아 복구했습니다        (복구됨 - 재부팅 권장)" -ForegroundColor Gray
        Write-Host "   3) 손상된 파일을 찾았으나 복구 못 했습니다 (복구 실패 - CBS.log 확인)" -ForegroundColor Gray
        Write-Host "   4) 모르겠음 / 화면을 놓침" -ForegroundColor Gray
        switch (Read-Host "  선택 (1~4)") {
            '1' { Log-Action "DISM+SFC 실행 - 무결성 위반 없음"
                  Write-Host "  → 시스템 파일 손상은 원인이 아닙니다. 다른 축을 보세요.`n" -ForegroundColor Green }
            '2' { Log-Action "DISM+SFC 실행 - 손상 파일 복구됨"
                  Write-Host "  → 재부팅 권장(애니서포트 [재부팅]). 재부팅 후 증상 재확인.`n" -ForegroundColor Cyan }
            '3' { Log-Action "DISM+SFC 실행 - 손상 발견, 복구 실패"
                  Write-Host "  → C:\Windows\Logs\CBS\CBS.log 의 [SR] 항목 확인. 복구 안 된 파일이 남았습니다.`n" -ForegroundColor Red }
            default { Log-Action "DISM+SFC 실행 완료 - 복구 결과 미확인"
                  Write-Host "  → 복구 여부는 미확인으로 남깁니다. 결과를 못 봤으면 다시 실행해 화면을 확인하세요.`n" -ForegroundColor DarkYellow }
        }
    } else {
        Log-Action ("Windows 시스템 파일 복구 시도(DISM={0}/SFC={1}) - 미완료" -f $dismRc, $sfcRc)
        Write-Host "`n  ★ 복구가 완료되지 않았습니다. 위 코드/로그 확인 후 재시도하세요." -ForegroundColor Red
        Write-Host "     DISM 실패 시 SFC 만 성공해도 손상이 남아 있을 수 있습니다.`n" -ForegroundColor DarkYellow
    }
}

# ── 15) 디스크 검사 (chkdsk) — 이벤트 로그 disk/Ntfs 오류 시 ──────────
# DISM/SFC(시스템파일)와 다름. 불량섹터·파일시스템 손상 복구. C:는 다음 부팅 시 예약 실행.
function Invoke-Chkdsk {
    Write-Host "`n=== 디스크 검사 (chkdsk) ===" -ForegroundColor Cyan
    Write-Host "  용도: 이벤트 로그에 disk/Ntfs 오류(불량섹터·파일시스템 손상)가 있을 때." -ForegroundColor DarkGray
    Write-Host "  ※ 시스템 드라이브(C:)는 즉시 불가 → 다음 부팅 때 실행 예약(재부팅 필요)." -ForegroundColor Yellow
    Write-Host "  ※ /r(불량섹터 복구)은 매우 오래 걸립니다(수십분~수시간)." -ForegroundColor Yellow
    $drv = Read-Host "  검사할 드라이브 (기본 C)"
    if ([string]::IsNullOrWhiteSpace($drv)) { $drv = 'C' }
    $drv = ($drv -replace '[:\\]','').ToUpper()
    # v3.3: 영문 한 글자만 허용. 이전에는 콜론/역슬래시만 걷어내고 cmd 문자열에 그대로 넣어서
    #  'C&calc' 같은 입력이 명령 연결로 실행될 수 있었다.
    if ($drv -notmatch '^[A-Z]$') {
        Write-Host ("  잘못된 드라이브 입력: '{0}' - 영문 한 글자만 됩니다 (예: C)`n" -f $drv) -ForegroundColor Red
        return
    }
    if (-not (Test-Path -LiteralPath ("{0}:\" -f $drv))) {
        Write-Host ("  {0}: 드라이브가 없습니다.`n" -f $drv) -ForegroundColor Red
        return
    }
    if ((Read-Host ("  {0}: 에 chkdsk /f /r 실행/예약할까요? (y/n)" -f $drv)) -ne 'y') { Write-Host "  취소됨.`n"; return }
    # v3.6.12: 시스템 드라이브는 '다음 부팅 때 예약?' 이라 Y 자동 응답이 맞다. 그 외 드라이브는 같은 Y 가
    #  '지금 강제 분리(dismount)?' 의 답이 된다 → 열린 파일 핸들이 끊겨 저장 안 된 작업이 날아갈 수 있다.
    $sysDrv = ("$env:SystemDrive" -replace '[:\\]','').ToUpper()
    if ($drv -eq $sysDrv) {
        & cmd.exe /c "echo Y| chkdsk ${drv}: /f /r"
    } else {
        Write-Host ("  ※ {0}: 는 시스템 드라이브가 아닙니다. '강제로 분리할까요? (Y/N)'가 나오면" -f $drv) -ForegroundColor Yellow
        Write-Host  "     그 드라이브 파일을 열어둔 프로그램이 없을 때만 Y. 모르면 N (분리되면 저장 안 된 작업 손실)" -ForegroundColor Yellow
        & chkdsk.exe "${drv}:" /f /r
    }
    $ckRc = $LASTEXITCODE
    # v3.6.13 (외부 QA M4): 종료코드를 본다. 0=이상없음 1=오류 수정 2=정리 수행 3=검사 못함/미수정 (예약 시 코드는 미검증)
    Log-Action ("chkdsk {0}: /f /r 실행/예약 요청(종료코드 {1})" -f $drv, $ckRc)
    if ($ckRc -le 2) {
        Write-Host ("`n  종료코드 {0} - 완료(또는 다음 재부팅 시 실행 예약). 예약됐으면 애니서포트 [재부팅]으로 시작.`n" -f $ckRc) -ForegroundColor Cyan
    } else {
        Write-Host ("`n  종료코드 {0} - 검사를 못 했거나 오류가 남았을 수 있음. 위 원문을 확인하세요.`n" -f $ckRc) -ForegroundColor Yellow
    }
}


# ── 16) 느림 진단 (v2.7 신설) ────────────────────────────────────────
# 근거: 2026-08-14 교사 PC에서 메뉴1이 보안모듈 42건을 잡았는데 '느림'의 실제 원인은
#       하나도 못 잡았다. 원인은 토렌트 2개와 하이재커·PUP 9종이었다.
#       메뉴1은 '이름을 아는 것'만 잡으므로, 이름을 몰라도 잡히는 축이 따로 필요하다.
#       → 여기서는 이름이 아니라 '지금 자원을 먹고 있는 놈'을 본다. 전부 조회만 함(삭제 없음).
function Show-SlowDiagnosis {
    Write-Host "`n=== 느림 진단 (조회 전용 - 삭제/변경 없음) ===" -ForegroundColor Cyan

    # (1) 디스크 여유. 10% 미만이면 다른 무엇보다 이게 먼저다.
    Write-Host "`n[1] 디스크 여유 공간" -ForegroundColor Yellow
    Get-CimInstance Win32_LogicalDisk -Filter 'DriveType=3' -ErrorAction SilentlyContinue | ForEach-Object {
        if (-not $_.Size) { return }
        $pct = [math]::Round($_.FreeSpace / $_.Size * 100, 1)
        $col = if ($pct -lt 10) { 'Red' } elseif ($pct -lt 20) { 'Yellow' } else { 'Gray' }
        Write-Host ("  {0} {1,6:N1}GB / {2,6:N1}GB  여유 {3}%{4}" -f $_.DeviceID,
            ($_.FreeSpace/1GB), ($_.Size/1GB), $pct,
            $(if ($pct -lt 10) { '  ← ★여유 부족이 느림의 직접 원인' } else { '' })) -ForegroundColor $col
    }

    # (2) 메모리 압박. 물리 메모리가 꽉 차면 디스크 스왑으로 전부 느려진다.
    Write-Host "`n[2] 메모리" -ForegroundColor Yellow
    $os = Get-CimInstance Win32_OperatingSystem -ErrorAction SilentlyContinue
    if ($os) {
        $usedPct = [math]::Round(($os.TotalVisibleMemorySize - $os.FreePhysicalMemory) / $os.TotalVisibleMemorySize * 100, 1)
        $col = if ($usedPct -ge 90) { 'Red' } elseif ($usedPct -ge 80) { 'Yellow' } else { 'Gray' }
        Write-Host ("  총 {0:N1}GB / 사용률 {1}%{2}" -f ($os.TotalVisibleMemorySize/1MB), $usedPct,
            $(if ($usedPct -ge 90) { '  ← ★메모리 압박 구간(스왑 가능성)' } else { '' })) -ForegroundColor $col
    }

    # (3) 자원 상위 프로세스. CPU 는 누적 사용시간이라 '오래 갈아먹은 놈'이 위로 온다.
    Write-Host "`n[3] 메모리 상위 10" -ForegroundColor Yellow
    Get-Process -ErrorAction SilentlyContinue | Sort-Object WS -Descending | Select-Object -First 10 |
        ForEach-Object { Write-Host ("  {0,10:N0} MB  {1}" -f ($_.WS/1MB), $_.ProcessName) -ForegroundColor Gray }
    Write-Host "`n[4] 누적 CPU 상위 10" -ForegroundColor Yellow
    Get-Process -ErrorAction SilentlyContinue | Where-Object CPU | Sort-Object CPU -Descending | Select-Object -First 10 |
        ForEach-Object { Write-Host ("  {0,10:N0} 초  {1}" -f $_.CPU, $_.ProcessName) -ForegroundColor Gray }

    # (5) ★ 핵심: 프로세스별 TCP 연결 수.
    #     토렌트·그리드딜리버리는 수십~수백 개의 연결을 동시에 유지한다. 이름을 몰라도 여기서 튄다.
    #     (2026-08-14 교사 PC의 µTorrent + uTorrent Web 이 이 축으로 잡혔을 케이스)
    Write-Host "`n[5] TCP 연결 수 상위 (토렌트·그리드 탐지)" -ForegroundColor Yellow
    try {
        $conn = Get-NetTCPConnection -State Established -ErrorAction Stop |
                Group-Object OwningProcess | Sort-Object Count -Descending | Select-Object -First 8
        if (-not $conn) { Write-Host "  연결 없음" -ForegroundColor DarkGray }
        foreach ($g in $conn) {
            $p = Get-Process -Id $g.Name -ErrorAction SilentlyContinue
            $nm = if ($p) { $p.ProcessName } else { "PID $($g.Name)" }
            $flag = if ($g.Count -ge 30) { '  ← ★토렌트/그리드 의심' } elseif ($g.Count -ge 15) { '  ← 확인' } else { '' }
            $col = if ($g.Count -ge 30) { 'Red' } elseif ($g.Count -ge 15) { 'Yellow' } else { 'Gray' }
            Write-Host ("  {0,4}개  {1}{2}" -f $g.Count, $nm, $flag) -ForegroundColor $col
        }
        Write-Host "  ※ 브라우저는 원래 연결이 많습니다. 브라우저가 아닌 것이 30개 이상이면 의심." -ForegroundColor DarkGray
    } catch { Write-Host "  조회 실패(구버전 OS)" -ForegroundColor DarkYellow }

    # (6) 자동시작 항목. 부팅 느림과 상시 상주의 출처.
    Write-Host "`n[6] 자동시작 (Run 레지스트리)" -ForegroundColor Yellow
    $runKeys = 'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Run',
               'HKLM:\SOFTWARE\WOW6432Node\Microsoft\Windows\CurrentVersion\Run',
               (Get-UserRegPath 'SOFTWARE\Microsoft\Windows\CurrentVersion\Run')
    $runKeys = @($runKeys | Where-Object { $_ })   # v3.6.13: 선생님 계정 하이브. 못 읽으면 빠진다
    $n = 0
    foreach ($k in $runKeys) {
        $p = Get-ItemProperty $k -ErrorAction SilentlyContinue
        if (-not $p) { continue }
        $p.PSObject.Properties | Where-Object { $_.Name -notlike 'PS*' } | ForEach-Object {
            $n++; Write-Host ("  {0}`n      {1}" -f $_.Name, $_.Value) -ForegroundColor Gray
        }
    }
    if ($n -eq 0) { Write-Host "  없음" -ForegroundColor DarkGray }

    # (7) 서드파티 자동시작 서비스. System32 밖에서 도는 것만.
    Write-Host "`n[7] 자동시작 서비스 중 서드파티 (실행 중)" -ForegroundColor Yellow
    $svc = Get-CimInstance Win32_Service -ErrorAction SilentlyContinue |
           Where-Object { $_.StartMode -eq 'Auto' -and $_.State -eq 'Running' -and
                          $_.PathName -and $_.PathName -notmatch [regex]::Escape("$env:SystemRoot\system32") }
    if ($svc) {
        $svc | Sort-Object DisplayName | ForEach-Object {
            Write-Host ("  {0}" -f $_.DisplayName) -ForegroundColor Gray
        }
        Write-Host ("  ({0}개 - 부팅 시 전부 올라옵니다)" -f @($svc).Count) -ForegroundColor DarkGray
    } else { Write-Host "  없음" -ForegroundColor DarkGray }

    # (8) 메뉴1 패턴 중 PUP 계열만 다시 강조. 느림 관점에서는 보안모듈보다 이쪽이 직접적이다.
    Write-Host "`n[8] 설치 목록 중 PUP/토렌트 계열" -ForegroundColor Yellow
    $pup = @(Get-Targets | Where-Object { $_.분류 -like 'PUP*' -or $_.분류 -like '*그리드*' -or $_.분류 -like '동영상*' })
    if ($pup) {
        $pup | ForEach-Object { Write-Host ("  [{0}] {1}" -f $_.분류, $_.이름) -ForegroundColor Red }
        Write-Host "  → 확인 후 제거하세요." -ForegroundColor DarkYellow
    } else { Write-Host "  없음" -ForegroundColor DarkGray }

    Write-Host "`n  ※ 이름 기반 탐지(메뉴1)가 못 잡는 것을 [5]와 [7]이 잡습니다." -ForegroundColor DarkGray
    Write-Host "     [5]에서 브라우저 아닌 프로세스가 연결 30개 이상이면 그게 우선 확인 후보입니다.`n" -ForegroundColor DarkGray
}

# ══════════════════════════════════════════════════════════════════
#  시나리오 레이어 (v3.2 신규)
#  2025-01 ~ 2026-09 처리 현황 548건 집계로 뽑은 실제 빈발 유형이다.
#    화상수업앱 마이크/스피커/카메라 115건, 오디오/비디오 29건  → 합 144건(26%)
#    CRM 콘텐츠 45 / CRM·익스·하이웍스·북클럽 로그인계 82건(15%)
#    강의채널 학습·재생 25건, 화상수업앱 XSplit 13건
#  조치 빈도: 캐시·쿠키 41% / 보안프로그램 제거 31% / 재부팅 24% /
#            브라우저 초기화 22% / 팝업해제 20% / 업데이트 18% / OTP·시간 10%
#  ※ 기능은 기존 메뉴 함수를 그대로 호출한다. 시나리오는 '순서'만 정해준다.
#    순서를 틀려서 시간을 버린 사례가 있어(2026-09-07 교사H 교사) 진입점을 만든 것.
# ══════════════════════════════════════════════════════════════════

function Invoke-Scenario-AV {
    Write-Host "`n##### [S1] 화상수업앱 카메라/마이크 안 됨 #####" -ForegroundColor Magenta
    Write-Host " 이 증상은 '계층'부터 가른다. 브라우저·보안프로그램 정리를 먼저 하지 말 것." -ForegroundColor DarkYellow

    Show-AudioDevices     # [6] 판정 블록이 다음 조치를 지정한다

    Write-Host "`n----- 판정 결과에 따라 -----" -ForegroundColor Cyan
    Write-Host " 물리(USB 열거 실패) : 포트 변경 -> 콜드 부팅. 소프트웨어 조치 불필요" -ForegroundColor White
    Write-Host " 드라이버(Image)     : 위에 출력된 pnputil 명령 실행 후 재부팅" -ForegroundColor White
    Write-Host " 권한 Deny           : Win+S > '카메라 개인' 3개 토글" -ForegroundColor White
    Write-Host " 전부 정상           : 화상수업앱 화면 좌상단 카메라 토글 -> 브라우저 사이트 권한" -ForegroundColor White
    Write-Host " 마이크(장치 2개 이상): 녹음 탭 1개만 [사용] + 기본 장치 -> 브라우저 고른 마이크 -> 화상수업앱 톱니 설정" -ForegroundColor White
    Write-Host " 카메라 [사용 안 함]  : 선생님께 사용 여부 확인 후 장치 관리자 [장치 사용]" -ForegroundColor White
    Write-Host "`n 가상카메라(XSplit/OBS/VCam) 의심이면 메뉴 6 을 추가로 볼 것" -ForegroundColor DarkGray

    if ((Read-Host "`n가상카메라 확인까지 이어서 볼까요? (y/n)") -eq 'y') { Show-DeviceCheck }
    Write-Host ""
}

function Invoke-Scenario-Login {
    Write-Host "`n##### [S2] 로그인/인증 안 됨 (CRM·익스트라넷·하이웍스·북클럽) #####" -ForegroundColor Magenta

    Write-Host "`n[1/4] OTP 반복 오류면 시간 동기화부터" -ForegroundColor Yellow
    if ((Read-Host "  시간 동기화 실행? (y/n)") -eq 'y') { Sync-Time }

    Write-Host "`n[2/4] 브라우저 정리" -ForegroundColor Yellow
    if ((Read-Host "  브라우저 정리 메뉴 열기? (y/n)") -eq 'y') { Browser-Menu }

    Write-Host "`n[3/4] 확장 프로그램 - OTP 자동입력·보안 확장 충돌" -ForegroundColor Yellow
    if ((Read-Host "  확장 목록 확인? (y/n)") -eq 'y') { Show-Extensions }

    Write-Host "`n[4/4] 보안/입력간섭 프로그램" -ForegroundColor Yellow
    if ((Read-Host "  탐지 실행? (y/n)") -eq 'y') { Invoke-Detect }

    Write-Host "`n  ※ 여기까지 해도 안 되면 계정 잠금·서버측 문제. 담당자 확인 요청." -ForegroundColor DarkGray
    Write-Host ""
}

function Invoke-Scenario-CrmView {
    Write-Host "`n##### [S3] CRM 화면/기능 이상 (목록 안 보임·버튼 무반응·발송 실패) #####" -ForegroundColor Magenta

    Write-Host "`n[1/3] 브라우저 정리" -ForegroundColor Yellow
    if ((Read-Host "  브라우저 정리 메뉴 열기? (y/n)") -eq 'y') { Browser-Menu }

    Write-Host "`n[2/3] 확장 프로그램 충돌 확인" -ForegroundColor Yellow
    if ((Read-Host "  확장 목록 확인? (y/n)") -eq 'y') { Show-Extensions }

    Write-Host "`n[3/3] 특정 사이트만 안 되면 네트워크 차단 지점 판별" -ForegroundColor Yellow
    if ((Read-Host "  네트워크 진단 실행? (y/n)") -eq 'y') { Invoke-NetDiag }
    Write-Host ""
}

function Invoke-Scenario-Player {
    Write-Host "`n##### [S4] 강의채널/녹강 재생 안 됨 #####" -ForegroundColor Magenta

    Write-Host "`n[1/3] 강의채널 재생 점검 (http 주소·Agent 버전·캡처 프로그램)" -ForegroundColor Yellow
    Check-StarPlayer

    Write-Host "`n[2/3] 브라우저 정리 (팝업 차단이 원인인 경우 다수)" -ForegroundColor Yellow
    if ((Read-Host "  브라우저 정리 메뉴 열기? (y/n)") -eq 'y') { Browser-Menu }

    Write-Host "`n[3/3] 재생 중 끊김·버퍼링이면 회선/자원" -ForegroundColor Yellow
    Write-Host "  업/다운 100Mbps 내외 필요 - https://www.speedtest.net" -ForegroundColor DarkGray
    if ((Read-Host "  느림 진단 실행? (y/n)") -eq 'y') { Show-SlowDiagnosis }
    Write-Host ""
}

function Invoke-Scenario-Slow {
    Write-Host "`n##### [S5] PC 느림/멈춤/갑자기 꺼짐 #####" -ForegroundColor Magenta
    Write-Host " 이벤트 로그를 먼저 본다. 블루스크린·비정상 종료가 있으면 원인이 다르다." -ForegroundColor DarkGray

    Write-Host "`n[1/3] 이벤트 로그 (BugCheck 1001 / Kernel-Power 41 확인)" -ForegroundColor Yellow
    Show-EventLog

    Write-Host "`n  ※ BugCheck·Kernel-Power 41 이 있으면 느림 문제가 아니다." -ForegroundColor DarkYellow
    Write-Host "     미니덤프 확인: C:\Windows\Minidump  (있으면 회수해서 분석)" -ForegroundColor DarkGray

    Write-Host "`n[2/3] 자원 점유·자동시작·PUP 탐지" -ForegroundColor Yellow
    if ((Read-Host "  느림 진단 실행? (y/n)") -eq 'y') { Show-SlowDiagnosis }

    Write-Host "`n[3/3] 시스템 파일 손상 의심 시 (오래 걸림)" -ForegroundColor Yellow
    if ((Read-Host "  DISM+SFC 실행? (y/n)") -eq 'y') { Repair-SystemFiles }
    Write-Host ""
}

function Invoke-Scenario-VideoCall {
    Write-Host "`n##### [S6] 화상수업 끊김·지연 (화면 전달 느림/페이지 늦게 넘어감/소리 끊김) #####" -ForegroundColor Magenta
    Write-Host " 회선 구간·와이파이·전원·자원부터 가른다. 브라우저·보안프로그램 정리는 그 다음." -ForegroundColor DarkYellow
    Write-Host " 학생 쪽 문제인지는 CRM > 학습생 정보 > 학습생 환경 > 접속상태 > 이력 으로 따로 확인." -ForegroundColor DarkGray

    Write-Host "`n[1/3] 화상수업 품질 진단 (연결·와이파이·회선 구간·전원·CPU)" -ForegroundColor Yellow
    Show-VideoCallCheck

    Write-Host "`n[2/3] 업로드·자원 점유 (토렌트·그리드·자동시작)" -ForegroundColor Yellow
    if ((Read-Host "  느림 진단 실행? (y/n)") -eq 'y') { Show-SlowDiagnosis }

    Write-Host "`n[3/3] 소리만 끊기거나 작으면 오디오 장치" -ForegroundColor Yellow
    if ((Read-Host "  오디오/카메라 진단 실행? (y/n)") -eq 'y') { Show-AudioDevices }

    Write-Host "`n  ※ 다 정상인데 수업 중에만 끊기면: 수업 시간대에 메뉴18 재측정 /" -ForegroundColor DarkGray
    Write-Host "     표준 순서(메뉴1 보안프로그램 → 메뉴5 브라우저)로 넘어간다." -ForegroundColor DarkGray
    Write-Host ""
}

# ── 17) 하이웍스 메신저 점검 (v3.6 신설) ─────────────────────────────
# 근거: 8/27 교사E · 8/28 교사F · 9/15 교사B · 9/15 교사C2 · 9/16 교사A —
#       하이웍스 업데이트 실패가 5건째다. 9/16 교사A 건에서 원인 규명에 2시간이 걸렸는데,
#       그 2시간은 전부 '따로따로 조회하느라' 쓴 시간이었다. 여기서 한 화면에 모은다.
#
# ★ 이 메뉴는 판정하지 않는다. 사실을 모으고, 표본을 쌓는다.
#
# [ProgDir/ProgVer 가설의 현재 상태 — 정확히 적어둔다]
#   교사B 노트에 'HKCU\SOFTWARE\Hiworks\Messenger 의 ProgDir·ProgVer 공란이 원인'이라고
#   적어뒀다. 2026-09-16 실측에서 담당자 PC(정상·알림 안 뜸·exe 3.4.0.2)에도 그 두 값이
#   없다는 것이 확인됐다.
#   → 밝혀진 것: '값이 없으면 반드시 루프가 돈다'는 거짓이다. 값의 부재는 필요조건이 아니다.
#   → 아직 모르는 것: 값이 '있을 때' 하이웍스가 그걸 판정에 쓰는지는 검증 안 됐다.
#     (교사A 건은 수동 재설치로 이미 정상화된 뒤에 값을 넣어서 인과가 분리되지 않았다)
#   → 그래서 가설을 폐기하지 않고 보류한다. 표본이 1대뿐이라 일반화할 수 없다.
#     이 메뉴는 하이웍스 건마다 값을 수집해 표본을 쌓는 것이 목적 중 하나다.
#
# 실측 확정값 (2026-09-16 update.hiworks.com/messenger/Messenger.txt 직접 조회):
#   FileVersion 3.4.0.2 / HiworksMessengerSetup.exe 8,527,768 bytes / CRC bbd2d318
#   레지스트리 루트 HKCU, 키 SOFTWARE\Hiworks\Messenger
#   MessengerHistory.txt 14,447 bytes / CRC f5b875fa
# 조회 전용. 아무것도 바꾸지 않는다(쓰기 테스트 파일만 만들었다 즉시 지운다).
function Show-HiworksCheck {
    $regPath = Get-UserRegPath 'SOFTWARE\Hiworks\Messenger'   # v3.6.13: 선생님 계정 하이브. 못 읽으면 `$null
    $txtUrl  = 'https://update.hiworks.com/messenger/Messenger.txt'
    $setUrl  = 'https://update.hiworks.com/messenger/HiworksMessengerSetup.exe'

    Write-Host "`n=== 하이웍스 메신저 점검 (진단 전용) ===" -ForegroundColor Cyan
    # QC: '조회 전용'이라고 썼지만 실제로는 TEMP 임시파일 쓰기([6]), 설치 폴더 쓰기 테스트([7]),
    #  클립보드 변경([10])을 한다. 설정·프로그램은 바꾸지 않지만 '아무것도 안 쓴다'는 건 사실이 아니다.
    Write-Host "  설정·프로그램은 바꾸지 않습니다. 단 아래 세 가지는 씁니다:" -ForegroundColor DarkGray
    Write-Host "   · TEMP 에 설치본 임시 다운로드(즉시 삭제)  · 설치 폴더에 빈 파일 쓰기 테스트(즉시 삭제)" -ForegroundColor DarkGray
    Write-Host "   · 마지막 요약 한 줄을 클립보드에 복사" -ForegroundColor DarkGray
    Write-Host "  업데이트 반복 / 다운로드 실패 / 로그인 진입 불가 증상일 때." -ForegroundColor DarkGray
    Write-Host "  ※ 정상 PC(담당자 PC 포함)에서도 돌려 표본을 쌓을 것. 표본 1대로는 단정 못 한다." -ForegroundColor DarkYellow

    # ── [1] 실행 계정 · 권한 · UAC ──────────────────────────────────
    # 9/16 교사A 건: 원격 PowerShell 을 다른 관리자 계정으로 승격하면 HKCU 와 %APPDATA% 가
    # 교사 것이 아니게 된다. 아래 값을 교사 것으로 읽고 있는지부터 확인해야 한다.
    Write-Host "`n[1] 실행 계정 · UAC" -ForegroundColor Yellow
    $me = "$env:USERDOMAIN\$env:USERNAME"
    Write-Host ("  실행 계정 : {0}" -f $me)
    Write-Host  "  → 계정이 달라도 [2] 레지스트리는 선생님 계정 하이브로 읽는다(못 읽으면 미검증). 문서 폴더·로그 경로는 실행 계정 기준일 수 있다." -ForegroundColor DarkYellow
    $isAdmin = $false
    try {
        $wp = New-Object Security.Principal.WindowsPrincipal([Security.Principal.WindowsIdentity]::GetCurrent())
        $isAdmin = $wp.IsInRole([Security.Principal.WindowsBuiltInRole]::Administrator)
    } catch {}
    Write-Host ("  관리자 그룹: {0}" -f $(if ($isAdmin) { '예' } else { '아니오 ← Program Files 쓰기 불가' })) `
        -ForegroundColor $(if ($isAdmin) { 'Gray' } else { 'Red' })
    $uac = Get-ItemProperty 'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Policies\System' -ErrorAction SilentlyContinue
    $lua = if ($uac) { $uac.EnableLUA } else { '?' }
    if ($uac) {
        Write-Host ("  EnableLUA={0} / PromptAdmin={1} / PromptUser={2} / SecureDesktop={3}" -f `
            $uac.EnableLUA, $uac.ConsentPromptBehaviorAdmin, $uac.ConsentPromptBehaviorUser, $uac.PromptOnSecureDesktop) -ForegroundColor Gray
        if ($uac.EnableLUA -eq 0) {
            Write-Host "  ※ EnableLUA=0 : UAC 꺼짐. 관리자 계정이면 항상 전체 권한(권한 제약 없음)." -ForegroundColor DarkYellow
            Write-Host "     단 표준 사용자면 승격 경로 자체가 없어 프롬프트 없이 조용히 실패한다." -ForegroundColor DarkYellow
        }
        if ($uac.ConsentPromptBehaviorUser -eq 0) {
            Write-Host "  ※ PromptUser=0 : 표준 사용자의 승격 요청을 프롬프트 없이 거부. 교사 눈엔 '실패'만 보인다." -ForegroundColor DarkYellow
        }
    } else { Write-Host "  UAC 정책 조회 실패" -ForegroundColor DarkYellow }

    # ── [2] 레지스트리 ──────────────────────────────────────────────
    Write-Host "`n[2] HKCU\SOFTWARE\Hiworks\Messenger" -ForegroundColor Yellow
    $regProgDir = $null; $regProgVer = $null; $subCnt = 0; $subs = @()
    if (-not $regPath) {
        Write-Host "  선생님 계정 레지스트리를 못 읽음(계정 불일치·하이브 미로드) - 이 항목은 미검증" -ForegroundColor DarkYellow
    } elseif (Test-Path $regPath) {
        $props = Get-ItemProperty -Path $regPath -ErrorAction SilentlyContinue
        $names = @((Get-Item -Path $regPath).Property)
        if ($names.Count -eq 0) { Write-Host "  (이름 있는 값 없음)" -ForegroundColor DarkYellow }
        foreach ($n in $names) {
            $v = [string]$props.$n
            Write-Host ("  {0,-16} = {1}" -f $n, $(if ([string]::IsNullOrWhiteSpace($v)) { '<비어 있음>' } else { $v })) -ForegroundColor Gray
        }
        $dv = (Get-Item -Path $regPath).GetValue('')
        if ($dv) { Write-Host ("  {0,-16} = {1}" -f '(기본값)', $dv) -ForegroundColor Gray }
        $regProgDir = [string]$props.ProgDir
        $regProgVer = [string]$props.ProgVer
        $subs   = @(Get-ChildItem $regPath -Recurse -ErrorAction SilentlyContinue | Select-Object -ExpandProperty PSPath |
                    ForEach-Object { $_ -replace '^.*\\Hiworks\\Messenger\\?', '' } | Where-Object { $_ })
        $subCnt = $subs.Count
        Write-Host ("  서브키 {0}개: {1}" -f $subCnt, $(if ($subs) { ($subs | Select-Object -First 12) -join ', ' } else { '없음' })) -ForegroundColor Gray
        Write-Host "  ※ 서브키 0개 = 이 계정에서 하이웍스가 제대로 초기화된 적이 없을 수 있다." -ForegroundColor DarkGray
        Write-Host "     정상 PC에는 Setting\USER(계정정보)와 창 위치 키들이 있다(9/16 담당자 PC 실측)." -ForegroundColor DarkGray
    } else {
        Write-Host "  키 자체가 없음" -ForegroundColor Red
    }

    # ── [3] 설치된 실행파일 ─────────────────────────────────────────
    Write-Host "`n[3] 설치된 HiworksMessenger.exe" -ForegroundColor Yellow
    $cand = New-Object System.Collections.ArrayList
    $proc = Get-Process -Name 'HiworksMessenger' -ErrorAction SilentlyContinue | Select-Object -First 1
    if ($proc -and $proc.Path) { [void]$cand.Add($proc.Path) }
    if (-not [string]::IsNullOrWhiteSpace($regProgDir)) { [void]$cand.Add((Join-Path $regProgDir 'HiworksMessenger.exe')) }
    if ($dv) { [void]$cand.Add((Join-Path ([string]$dv) 'HiworksMessenger.exe')) }
    foreach ($root in @(${env:ProgramFiles(x86)}, $env:ProgramFiles, $script:TargetLocalAppData, $script:TargetAppData)) {
        if ($root) { [void]$cand.Add((Join-Path $root 'Hiworks\Messenger\HiworksMessenger.exe')) }
    }
    $exePath = $null
    foreach ($c in $cand) { if ($c -and (Test-Path -LiteralPath $c)) { $exePath = $c; break } }
    $exeVer = $null; $instDir = $null
    if ($exePath) {
        $fi = Get-Item -LiteralPath $exePath
        $exeVer  = $fi.VersionInfo.FileVersion
        $instDir = Split-Path $exePath -Parent
        Write-Host ("  경로        : {0}" -f $exePath) -ForegroundColor Gray
        Write-Host ("  FileVersion : {0}" -f $exeVer) -ForegroundColor Green
        Write-Host ("  수정일      : {0:yyyy-MM-dd HH:mm}" -f $fi.LastWriteTime) -ForegroundColor Gray
    } else {
        Write-Host "  못 찾음 (미설치 또는 제거 상태)" -ForegroundColor Red
    }
    Write-Host ("  프로세스    : {0}" -f $(if ($proc) { "실행 중 (PID $($proc.Id))" } else { '실행 안 함' })) -ForegroundColor Gray
    if ($proc -and $proc.MainWindowHandle -eq 0) {
        Write-Host "  ※ 프로세스는 사는데 메인 창 핸들이 없다 - 창이 화면 밖/최소화로 안 보이는 유형." -ForegroundColor DarkYellow
    }

    # ── [4] 하이웍스 폴더 전수 — 로그 찾기 ──────────────────────────
    # 9/16 교사A 건에서 '*.log,*.txt' 로만 훑었더니 MessengerHistory.txt 하나만 나왔다.
    # 하이웍스 로그는 확장자가 .log 가 아닐 수 있다(날짜 파일명·확장자 없음·.dat 등).
    # → 확장자를 가리지 말고 최근 수정순으로 전부 본다. 로그가 있으면 여기서 반드시 드러난다.
    Write-Host "`n[4] 하이웍스 폴더 - 최근 수정 파일 (로그 탐색)" -ForegroundColor Yellow
    Write-Host "  ※ 아래 로그 줄에 계정·메시지 내용이 나올 수 있음(level=INFO). 캡쳐·세션 로그 공유 시 개인정보 주의." -ForegroundColor DarkYellow
    $logRoots = @()
    if ($instDir) { $logRoots += $instDir }
    foreach ($b in @($script:TargetAppData, $script:TargetLocalAppData, $env:ProgramData)) {
        if (-not $b) { continue }
        foreach ($n in @('Hiworks', 'HiworksMessenger')) {
            $p = Join-Path $b $n
            if (Test-Path -LiteralPath $p) { $logRoots += $p }
        }
    }
    $logRoots = @($logRoots | Select-Object -Unique)
    if (-not $logRoots) { Write-Host "  하이웍스 폴더를 못 찾음" -ForegroundColor DarkYellow }
    $files = @()
    foreach ($r in $logRoots) {
        Write-Host ("  [{0}]" -f $r) -ForegroundColor DarkGray
        $files += @(Get-ChildItem -LiteralPath $r -Recurse -File -Force -ErrorAction SilentlyContinue)
    }
    # TEMP 는 파일이 많으니 이름에 Hiworks/Messenger 가 들어간 것만
    $files += @(Get-ChildItem -LiteralPath $env:TEMP -File -Force -ErrorAction SilentlyContinue |
                Where-Object { $_.Name -match 'Hiworks|Messenger' })
    if ($files) {
        $files | Sort-Object LastWriteTime -Descending | Select-Object -First 15 | ForEach-Object {
            Write-Host ("  {0:yyyy-MM-dd HH:mm}  {1,10:N0}  {2}" -f $_.LastWriteTime, $_.Length, $_.FullName) -ForegroundColor Gray
        }
        $hist = $files | Where-Object { $_.Name -eq 'MessengerHistory.txt' } | Select-Object -First 1
        if ($hist) {
            $age = ((Get-Date) - $hist.LastWriteTime).Days
            if ($age -ge 1) {
                Write-Host ("  ※ MessengerHistory.txt 가 {0}일째 안 바뀜. 그동안 업데이트를 시도했다면" -f $age) -ForegroundColor DarkYellow
                Write-Host  "     파일이 하나도 안 써진 것이다 - 과거 사례에서 결정적 단서였던 지점." -ForegroundColor DarkYellow
            }
        }
    } else { Write-Host "  파일 없음" -ForegroundColor DarkGray }

    # ── [4-2] 메신저 로그 (log4net) ─────────────────────────────────
    # 2026-09-16 확정. 설치 폴더에 log4net 설정이 '두 개' 있고 서로 다르다.
    #
    #  (A) HiworksMessenger.exe.config  ← .NET 앱이 자동으로 읽는 본체 설정. 이쪽이 실제다.
    #      <param name="File" type="log4net.Util.PatternString"
    #             value="%envFolderPath{MyDocuments}\LogFile\MessengerLog.txt" />
    #      <lockingModel .. MinimalLock />   ← 독점 잠금 아님. 실행 중에도 그냥 읽힌다
    #      <root><level value="INFO" />
    #      <layout ConversionPattern="[%d{MM/dd-HH:mm:ss}][%level]-%m%n" />
    #        → 실제 출력:  [09/16-17:33:27][INFO]-(Login)Get Settings Information
    #        → 교사B 건에서 본 그 포맷과 정확히 일치한다. 이 파일이 맞다.
    #
    #  (B) log4net.config  ← 별도 파일. <file value="C:\LogFile\Messenger.log" />
    #      Launcher.exe 등 다른 컴포넌트용이거나 미사용. 둘 다 본다.
    #
    # ★ MyDocuments 는 OneDrive 문서 백업이 켜져 있으면 OneDrive 밑으로 리다이렉트된다.
    #   경로를 문자열로 박지 말고 GetFolderPath 로 구할 것.
    # ※ level=INFO 라 계정·메시지 내용이 남을 수 있다. 화면 캡쳐 시 개인정보 주의.
    Write-Host "`n[4-2] 메신저 로그 (log4net)" -ForegroundColor Yellow
    $logPaths = New-Object System.Collections.ArrayList
    # v3.6.3 F03: GetFolderPath 는 '실행 계정'의 문서 폴더다. 계정이 다르면 선생님 프로필로 잡는다.
    #  단 OneDrive 리다이렉트 여부는 그 계정의 HKCU 에 있어 여기서는 알 수 없다 - 아래 경고 참조.
    $myDoc = [Environment]::GetFolderPath('MyDocuments')
    if ($script:UserMismatch -and $script:TargetProfile -ne $env:USERPROFILE) {
        $myDoc = Join-Path $script:TargetProfile 'Documents'
        Write-Host ("  ※ 계정 불일치 - 선생님 문서 폴더로 추정: {0}" -f $myDoc) -ForegroundColor DarkYellow
        Write-Host  "     OneDrive 문서 백업이 켜져 있으면 실제 경로가 다르다(그 계정 HKCU 를 못 읽음)." -ForegroundColor DarkYellow
    }
    if ($myDoc) { [void]$logPaths.Add((Join-Path $myDoc 'LogFile\MessengerLog.txt')) }
    if ($instDir) {
        foreach ($cf in @('HiworksMessenger.exe.config', 'log4net.config')) {
            $cfgFile = Join-Path $instDir $cf
            if (-not (Test-Path -LiteralPath $cfgFile)) { continue }
            $rawCfg = [string](Get-Content -LiteralPath $cfgFile -Raw -ErrorAction SilentlyContinue)
            foreach ($mm in [regex]::Matches($rawCfg, '(?i)(?:<file\s+value|name="File"[^>]*?value)\s*=\s*"([^"]+)"')) {
                $v = $mm.Groups[1].Value
                # log4net PatternString: %envFolderPath{MyDocuments} 를 실제 경로로 바꾼다
                # 치환문자열 이스케이프 꼬임을 피하려고 split/join 으로 박는다
                if ($v -match '(?i)%envFolderPath\{MyDocuments\}') {
                    $v = ([regex]::Split($v, '(?i)%envFolderPath\{MyDocuments\}')) -join $myDoc
                }
                $v = [Environment]::ExpandEnvironmentVariables($v)
                if ($v -notmatch '%') { [void]$logPaths.Add($v) }
            }
        }
    }
    [void]$logPaths.Add('C:\LogFile\Messenger.log')
    $logPaths = @($logPaths | Where-Object { $_ } | Select-Object -Unique)

    $anyLog = $false
    foreach ($lp in $logPaths) {
        $ld = Split-Path $lp -Parent
        if (-not (Test-Path -LiteralPath $lp)) {
            $why = if (Test-Path -LiteralPath $ld) { '파일 없음(기록된 적 없음)' } else { '폴더 자체가 없음' }
            Write-Host ("  [없음] {0}  - {1}" -f $lp, $why) -ForegroundColor DarkGray
            continue
        }
        $anyLog = $true
        $lfi = Get-Item -LiteralPath $lp
        Write-Host ("  [있음] {0}" -f $lp) -ForegroundColor Cyan
        Write-Host ("         {0:N0} bytes / {1:yyyy-MM-dd HH:mm}" -f $lfi.Length, $lfi.LastWriteTime) -ForegroundColor Gray
        if ($lfi.Length -gt 100MB) { Write-Host "         ※ 롤링이 없어 계속 누적된다. 커지면 메신저가 느려질 수 있다." -ForegroundColor DarkYellow }
        # MinimalLock 이지만 안전하게 공유 모드로 연다. 큰 파일은 뒤 1MB 만.
        $lines = $null
        try {
            $fs = [System.IO.File]::Open($lp, [IO.FileMode]::Open, [IO.FileAccess]::Read, [IO.FileShare]::ReadWrite)
            try {
                if ($fs.Length -gt 1MB) { [void]$fs.Seek(-1MB, [IO.SeekOrigin]::End) }
                $sr  = New-Object IO.StreamReader($fs, [Text.Encoding]::UTF8)
                $txt = $sr.ReadToEnd(); $sr.Close()
            } finally { $fs.Close() }
            $lines = @($txt -split "`r?`n" | Where-Object { $_.Trim() })
        } catch { Write-Host ("         읽기 실패: {0}" -f $_.Exception.Message) -ForegroundColor Red }
        if (-not $lines) { continue }
        # 포맷이 [MM/dd-HH:mm:ss] 라 연도가 없다. 오늘/어제는 월일로 찾는다.
        $td = Get-Date -Format 'MM/dd'
        $yd = (Get-Date).AddDays(-1).ToString('MM/dd')
        Write-Host ("         오늘({0}) {1}줄 / 어제({2}) {3}줄" -f `
            $td, @($lines | Where-Object { $_ -like "[[]$td*" }).Count,
            $yd, @($lines | Where-Object { $_ -like "[[]$yd*" }).Count) -ForegroundColor Gray
        # v3.6.3 F05: 로그 전체에서 'Check Update' 를 세어 루프로 단정했다. appendToFile 이라
        #  몇 달치가 한 파일에 쌓이므로, 서로 다른 달의 기록 5줄만 있어도 '루프'가 됐다.
        #  → 오늘·어제 기록만 센다. 그 안에서 반복돼야 지금 벌어지는 일이다.
        $chkRecent = @($lines | Where-Object { ($_ -like "[[]$td*" -or $_ -like "[[]$yd*") -and $_ -match '(?i)Check Update' })
        $chkAll    = @($lines | Where-Object { $_ -match '(?i)Check Update' })
        # v3.6.5 R6: 최근 2일 5회만으로 '루프'라고 단정했다. 정상적으로 5번 켜고 로그인해도
        #  Check Update 는 5회 찍힌다. 로그인까지 갔는지를 같이 본다.
        $loginOk = @($lines | Where-Object { ($_ -like "[[]$td*" -or $_ -like "[[]$yd*") -and
                                             $_ -match '(?i)login\s*(success|complete|ok)|로그인\s*(성공|완료)' })
        if ($chkRecent.Count -ge 5 -and $loginOk.Count -eq 0) {
            Write-Host ("         ★ 최근 2일 'Check Update' {0}회 + 로그인 성공 기록 0건 = 업데이트 게이트 루프 의심" -f $chkRecent.Count) -ForegroundColor Red
        } elseif ($chkRecent.Count -ge 5) {
            Write-Host ("         최근 2일 'Check Update' {0}회 - 다만 로그인 성공 기록도 {1}건 있다." -f $chkRecent.Count, $loginOk.Count) -ForegroundColor DarkYellow
            Write-Host  "         반복은 확인됐지만 루프로 단정할 수 없다(정상 실행에서도 매번 확인한다)." -ForegroundColor DarkYellow
        } elseif ($chkAll.Count -ge 5) {
            Write-Host ("         'Check Update' 총 {0}회(최근 2일 {1}회) - 과거 기록이 섞여 있다. 현재 루프로 단정하지 말 것." -f $chkAll.Count, $chkRecent.Count) -ForegroundColor DarkYellow
        }
        $keep = @($lines | Where-Object { $_ -match '(?i)update|login|error|fail|download|version|exception|denied' } | Select-Object -Last 20)
        if (-not $keep) { $keep = @($lines | Select-Object -Last 12) }
        Write-Host "         --- 관련 라인 ---" -ForegroundColor DarkGray
        foreach ($l in $keep) { Write-Host ("           {0}" -f $l.Trim()) -ForegroundColor Gray }
        Write-Host ("         전체 보기:  notepad '{0}'" -f $lp) -ForegroundColor DarkGray
    }
    if (-not $anyLog) {
        # QC: '한 번도 기록 못 남겼다'로 단정했었다. 경로를 잘못 짚었을 수도 있고(계정 불일치·
        #  OneDrive 리다이렉트), 정리됐을 수도 있다. 못 찾았다는 사실만 적는다.
        Write-Host "  ※ 위 경로에서는 로그를 찾지 못했다. 기록이 없다는 뜻은 아니다." -ForegroundColor DarkYellow
        Write-Host "     가능성: ①경로를 잘못 짚음(계정 불일치·OneDrive 리다이렉트) ②파일이 정리됨" -ForegroundColor DarkYellow
        Write-Host "             ③문서 폴더 쓰기 권한 없음" -ForegroundColor DarkYellow
        Write-Host "     선생님 계정으로 실행 중이라면 탐색기 주소창에 %USERPROFILE%\LogFile 을 넣어 직접 확인." -ForegroundColor DarkGray
    }

    # ── [5] 서버 Messenger.txt ──────────────────────────────────────
    Write-Host "`n[5] 서버 Messenger.txt" -ForegroundColor Yellow
    $srvVer = $null; $srvSize = $null
    try {
        [Net.ServicePointManager]::SecurityProtocol = [Net.SecurityProtocolType]::Tls12
        $raw = (Invoke-WebRequest -Uri $txtUrl -UseBasicParsing -TimeoutSec 15).Content
        $ic  = [System.Text.RegularExpressions.RegexOptions]::IgnoreCase
        $sl  = $ic -bor [System.Text.RegularExpressions.RegexOptions]::Singleline
        $m   = [regex]::Match($raw, 'FileVersion[^0-9]{0,10}(\d+[.,]\d+[.,]\d+[.,]\d+)', $ic)
        if ($m.Success) { $srvVer = $m.Groups[1].Value; Write-Host ("  FileVersion : {0}" -f $srvVer) -ForegroundColor Green }
        else { Write-Host "  FileVersion 파싱 실패 - 원문 앞부분:" -ForegroundColor Red
               Write-Host ($raw.Substring(0, [Math]::Min(300, $raw.Length))) -ForegroundColor DarkGray }
        $ms = [regex]::Match($raw, '(?:FileSize|Size)\D{0,12}(\d{6,10})', $ic)
        if (-not $ms.Success) { $ms = [regex]::Match($raw, 'Setup\.exe.{0,300}?(\d{6,10})', $sl) }
        if ($ms.Success) { $srvSize = [int64]$ms.Groups[1].Value; Write-Host ("  설치본 크기 : {0:N0} bytes" -f $srvSize) -ForegroundColor Gray }
    } catch {
        Write-Host ("  조회 실패: {0}" -f $_.Exception.Message) -ForegroundColor Red
        Write-Host "  → 교사 PC 방화벽/백신/프록시에 막혔을 수 있다. 담당자 PC 값으로 대체." -ForegroundColor DarkYellow
    }

    # ── [6] 다운로드 실증 ───────────────────────────────────────────
    # '다운로드 실패' 메시지가 네트워크 문제인지 아닌지를 여기서 가른다.
    # TEMP 에 받고 즉시 지운다 - 선생님 PC에 흔적을 안 남기는 방침.
    Write-Host "`n[6] 설치본 다운로드 실증" -ForegroundColor Yellow
    # v3.6.2 F04: 전송 성공($dlOk)과 설치본 검증($dlVerified)을 나눈다.
    #  이전에는 크기를 확인하기도 전에 $dlOk=$true 를 세우고, 요약에는 실제 수신량과
    #  무관하게 '8MB 수신 성공'을 찍었다(123바이트를 받아도 같은 문장이 나왔다).
    $dlOk = $null; $dlBytes = $null; $dlVerified = $null; $dlFailKind = $null
    if ((Read-Host "  약 8MB를 실제로 받아 확인할까요? (y/n)") -eq 'y') {
        $tmp = Join-Path $env:TEMP ("HiworksSetup_{0}.tmp" -f (Get-Date -Format HHmmss))
        try {
            Invoke-WebRequest -Uri $setUrl -OutFile $tmp -UseBasicParsing -TimeoutSec 120 -ErrorAction Stop
            $len = (Get-Item -LiteralPath $tmp).Length
            $dlOk = $true; $dlBytes = $len
            Write-Host ("  수신 {0:N0} bytes" -f $len) -ForegroundColor Green
            if (-not $srvSize) {
                $dlVerified = $null
                Write-Host "  ※ 서버 명시 크기를 못 읽어 설치본 검증은 미확정." -ForegroundColor DarkYellow
            } elseif ($len -ne $srvSize) {
                $dlVerified = $false
                Write-Host ("  ★ 서버 명시 크기({0:N0})와 다르다 - 전송은 됐지만 설치본 검증 실패." -f $srvSize) -ForegroundColor Red
                Write-Host  "     프록시/캐시가 오류 페이지를 대신 준 경우일 수 있다. 이 파일로 설치하지 말 것." -ForegroundColor Red
            } else {
                $dlVerified = $true
                Write-Host "  크기 일치 (서버 명시 크기와 같음 - 해시 무결성은 미검증)" -ForegroundColor Green
            }
            # v3.6.1: 여기서 '메신저 쪽 문제다'로 단정했었다. 과했다.
            #  이 요청은 관리자로 승격된 PowerShell 이 Invoke-WebRequest 로 받은 것이고,
            #  메신저는 다른 계정 컨텍스트·다른 프록시 설정·다른 프로세스 정책에서 돈다.
            #  백신은 프로세스별로 다르게 동작하고 메신저가 쓰는 URL/포트도 이것과 같다는 보장이 없다.
            Write-Host "  → 이 세션(관리자 PowerShell)에서는 받아진다." -ForegroundColor Cyan
            Write-Host ("     ※ 메신저도 같은 조건이라는 뜻은 아니다 - 실행 계정({0})·프록시·백신의" -f $env:USERNAME) -ForegroundColor DarkYellow
            Write-Host  "       프로세스별 정책이 다를 수 있다. 네트워크 차단을 '배제'하지 말고 후순위로만 둘 것." -ForegroundColor DarkYellow
        } catch {
            $dlOk = $false
            $ex = $_.Exception
            Write-Host ("  실패: {0}" -f $ex.Message) -ForegroundColor Red
            # v3.6.2 F04: 실패를 무조건 네트워크로 몰지 않는다. 로컬 디스크 부족·권한 거부는
            #  네트워크와 무관한데도 '백신부터 보라'고 안내하던 자리.
            # v3.6.5 R7: 메시지에 'denied' 가 있으면 로컬로 몰았다. HTTP 403 Access Denied 가
            #  네트워크 실패인데도 '네트워크 문제가 아니다'로 나갔다.
            #  → 예외 '유형'으로 먼저 가른다. 웹 예외는 무조건 네트워크 쪽이다.
            $isWebEx = ($ex -is [System.Net.WebException]) -or
                       ($ex.GetType().FullName -match 'HttpRequestException|WebException') -or
                       ($ex.Response -ne $null)
            if (-not $isWebEx -and (
                $ex -is [System.IO.IOException] -or $ex -is [System.UnauthorizedAccessException] -or
                $ex.Message -match '(?i)there is not enough space|디스크 공간|공간이 부족')) {
                $dlFailKind = 'local'
                Write-Host "  → 로컬 쓰기 단계 실패로 보인다(디스크 공간·권한). 네트워크 문제가 아니다." -ForegroundColor Red
                Write-Host ("     저장 위치: {0}" -f $env:TEMP) -ForegroundColor DarkGray
                Write-Host  "     메뉴16 [1] 디스크 여유 공간부터 확인할 것." -ForegroundColor Yellow
            } else {
                $dlFailKind = 'network'
                $httpCode = $null
                try { if ($ex.Response) { $httpCode = [int]$ex.Response.StatusCode } } catch {}
                if ($httpCode) {
                    Write-Host ("  → HTTP {0} 응답. 서버까지는 닿았고 서버가 거절했다는 뜻이다." -f $httpCode) -ForegroundColor Red
                    Write-Host  "     403/407 이면 프록시·게이트웨이가 가로챘을 가능성이 높다(백신 차단과 구분할 것)." -ForegroundColor DarkYellow
                }
                Write-Host "  → 이 세션에서 못 받는다. 네트워크/백신/방화벽 차단이 1순위 후보다." -ForegroundColor Red
                Write-Host  "     (일시 장애·DNS·프록시·TLS 도 같은 모양이니 1회 재시도 후 판단할 것)" -ForegroundColor DarkYellow
                Write-Host  "     메뉴1·메뉴3으로 백신부터 볼 것." -ForegroundColor Red
            }
        } finally { Remove-Item -LiteralPath $tmp -Force -ErrorAction SilentlyContinue }
    } else { Write-Host "  건너뜀" -ForegroundColor DarkGray }

    # ── [7] 설치 폴더 쓰기 권한 실증 ────────────────────────────────
    # 업데이트는 설치 폴더에 써야 끝난다. 권한이 없으면 받아놓고도 '다운로드 실패'로 보인다.
    Write-Host "`n[7] 설치 폴더 쓰기 권한" -ForegroundColor Yellow
    $writeOk = $null
    if ($instDir) {
        $probe = Join-Path $instDir ("_rst_{0}.tmp" -f (Get-Random))
        try {
            [System.IO.File]::WriteAllText($probe, 'x')
            Remove-Item -LiteralPath $probe -Force -ErrorAction SilentlyContinue
            $writeOk = $true
            Write-Host ("  쓰기 가능 : {0}  (실행 계정 {1} 기준)" -f $instDir, $env:USERNAME) -ForegroundColor Green
            # v3.6.1: 이 툴킷은 관리자 권한을 강제하므로 관리자 세션에서 Program Files 쓰기는
            #  거의 항상 성공한다. 그건 '교사 계정도 쓸 수 있다'는 증명이 전혀 아니다.
            #  교사가 표준 사용자면 교사 컨텍스트에서는 못 쓴다 - 그게 업데이트 실패의 원인일 수 있다.
            if ($isAdmin) {
                Write-Host  "  ※ 관리자 세션이라 성공하는 게 정상이다. 교사 계정의 권한을 증명하지 못한다." -ForegroundColor DarkYellow
                Write-Host ("     교사 계정이 이 세션({0})과 다르거나 표준 사용자면 아래로 따로 확인할 것:" -f $env:USERNAME) -ForegroundColor DarkYellow
                Write-Host ("        icacls '{0}'" -f $instDir) -ForegroundColor DarkGray
                Write-Host  "     교사 계정에 (M) 수정 권한이 없으면 그게 업데이트 실패의 직접 원인일 수 있다." -ForegroundColor DarkYellow
            }
        } catch {
            $writeOk = $false
            Write-Host ("  쓰기 불가 : {0}" -f $instDir) -ForegroundColor Red
            Write-Host ("     사유: {0}" -f $_.Exception.Message) -ForegroundColor DarkRed
            Write-Host  "     → 이게 '다운로드 실패'의 직접 원인일 수 있다. 교사 계정에 수정 권한 부여 검토:" -ForegroundColor Yellow
            Write-Host ("        icacls '{0}' /grant '<교사계정>:(OI)(CI)M' /T" -f $instDir) -ForegroundColor DarkGray
        }
    } else { Write-Host "  설치 폴더를 몰라 건너뜀" -ForegroundColor DarkGray }

    # ── [8] 백신 ────────────────────────────────────────────────────
    # 8/27·8/28·9/15 교사C2 세 건이 McAfee 제거로 풀렸다. 9/15 교사B·9/16 교사A는 Defender 단독이었다.
    Write-Host "`n[8] 보안센터 등록 백신" -ForegroundColor Yellow
    $avNames = @()
    try {
        $av = @(Get-CimInstance -Namespace 'root\SecurityCenter2' -ClassName AntiVirusProduct -ErrorAction Stop)
        $avNames = @($av | ForEach-Object { $_.displayName })
        foreach ($p in $avNames) { Write-Host ("  - {0}" -f $p) -ForegroundColor Gray }
        if ($avNames.Count -ge 2) {
            Write-Host "  ※ 백신 2종 이상 공존. 8/27·8/28·9/15 건은 McAfee(MCPR) 제거로 풀렸다." -ForegroundColor DarkYellow
        } elseif ($avNames.Count -eq 1 -and $avNames[0] -match 'Defender') {
            # QC: Defender 단독이라고 '차단 아님'이 되지 않는다. Defender 도 SmartScreen·
            #  실시간 보호·제어된 폴더 액세스로 막는다. 서드파티 백신 충돌이 아닐 뿐이다.
            Write-Host "  ※ 서드파티 백신 충돌은 아니다(Defender 단독)." -ForegroundColor DarkGray
            Write-Host "     단 Defender 자체도 차단할 수 있다 - 격리 기록을 확인할 것:" -ForegroundColor DarkGray
            Write-Host "     Get-MpThreatDetection | Select -Last 5 InitialDetectionTime,ThreatID,Resources" -ForegroundColor DarkGray
            Write-Host "     제어된 폴더 액세스: Get-MpPreference | Select EnableControlledFolderAccess" -ForegroundColor DarkGray
        }
    } catch { Write-Host "  조회 실패" -ForegroundColor DarkYellow }

    # ── [9] 최근 7일 하이웍스 관련 이벤트 ───────────────────────────
    # v3.6.2 F06: 조회 예외를 조용히 삼키고 '크래시가 아니다'로 넘어갔었다.
    #  조회 실패 / 검출 0건 / 검출됨 은 서로 다른 상태다. 섞으면 없는 사실을 만든다.
    Write-Host "`n[9] 최근 7일 하이웍스 관련 오류 이벤트" -ForegroundColor Yellow
    $hit = $false; $evQueryOk = $false
    try {
        $ev = @(Get-WinEvent -FilterHashtable @{ LogName='Application'; Level=1,2; StartTime=(Get-Date).AddDays(-7) } -ErrorAction Stop |
                Where-Object { $_.Message -match 'Hiworks' } | Select-Object -First 5)
        $evQueryOk = $true
        foreach ($e in $ev) {
            $hit = $true
            Write-Host ("  {0:MM-dd HH:mm}  ID {1}  {2}" -f $e.TimeCreated, $e.Id, $e.ProviderName) -ForegroundColor DarkYellow
            Write-Host ("    {0}" -f (($e.Message -split "`r?`n")[0])) -ForegroundColor DarkGray
        }
    } catch {
        # 'No events were found' 도 예외로 온다. 그건 조회 성공 + 0건이다.
        if ($_.Exception.Message -match '(?i)No events were found|일치하는 이벤트') { $evQueryOk = $true }
        else { Write-Host ("  조회 실패: {0}" -f $_.Exception.Message) -ForegroundColor DarkYellow }
    }
    if ($hit) {
        Write-Host "  ※ 하이웍스 이름이 들어간 오류가 있다. 위 내용을 캡쳐할 것." -ForegroundColor DarkYellow
    } elseif ($evQueryOk) {
        Write-Host "  검출 0건" -ForegroundColor Gray
        Write-Host "  ※ 최근 7일 Application 로그에 하이웍스 오류가 없다는 뜻이다." -ForegroundColor DarkGray
        Write-Host "     다른 앱의 .NET 오류를 하이웍스와 엮지 말 것" -ForegroundColor DarkGray
        Write-Host "     (과거 다른 앱의 .NET 오류를 하이웍스 원인으로 오판한 사례가 있다)" -ForegroundColor DarkGray
    } else {
        Write-Host "  ★ 조회 자체가 실패했다 - 크래시 여부는 '미확인'이다. 없다고 판단하지 말 것." -ForegroundColor Red
        Write-Host "     이벤트 뷰어를 직접 열어 Application 로그를 확인할 것." -ForegroundColor Yellow
    }

    # ── [9-2] 파일 세트 무결성 대조 ─────────────────────────────────
    # 기준선: 2026-09-16 담당자 PC(정상 동작, exe 3.4.0.2) 실측 39개 파일.
    # 교사B 건에서 '설치 폴더 파일 세트 깨짐' 가설을 세웠다가 재설치로 반증했는데,
    # 그때는 확인할 방법이 없었다. 이제 크기+MD5 로 직접 본다.
    # ★ 하이웍스가 3.4.0.2 보다 올라가면 이 기준선을 새로 떠야 한다(담당자 PC에서 재추출).
    # ※ 교사B 건 크래시 지점이 SharpRaven.dll(Sentry 클라이언트)이었다.
    #   .NET Runtime 1026 / Messenger.Commons.SentryLogger..ctor() FileNotFoundException.
    #   그 DLL 이 없거나 다르면 실행 직후 종료된다 - 여기서 바로 드러난다.
    Write-Host "`n[9-2] 파일 세트 무결성 (기준: 2026-09-16 담당자 PC 3.4.0.2)" -ForegroundColor Yellow
    $BASE = @{
        'AVScanner.ini' = '31|ce6b88a408c192d5e253cc7d28cf7b70'
        'AttachedCommandBehavior.dll' = '16384|a588b85e7ab418f358fec8fe8254aff0'
        'DotNetProjects.SVGImage.dll' = '108032|cd0f4b9dfa5c17879a4afe9370852431'
        'Emoji.Wpf.dll' = '636928|eec3fac8e77beb8476d931cbc291a69e'
        'GongSolutions.Wpf.DragDrop.dll' = '29696|ceaa32d84f5022a4f4bd38ea2c37c1bf'
        'HiworksMessenger.exe' = '7309304|d4334c9ad0adb033110d90d42751ff81'
        'HiworksMessenger.exe.config' = '3798|c348d37084efd410500c97f7d800964d'
        'HtmlAgilityPack.dll' = '116224|c4361484d06d75c46f74f941f9154985'
        'Launcher.exe' = '2136848|9bd1fcbb22eef1aa34d6c8ed109dcb44'
        'MessengerHistory.txt' = '14447|ba38a74710ffea46308bc56a781f5bc0'
        'Microsoft.Expression.Interactions.dll' = '91648|6a3b9e46c41e42e7b8e1479468d892af'
        'Microsoft.Threading.Tasks.Extensions.Desktop.dll' = '47424|e548a93d16964e52868c47cef1c98f2e'
        'Microsoft.Threading.Tasks.Extensions.dll' = '31520|6aa2393ff1fde1a61d0cf51730428f74'
        'Microsoft.Threading.Tasks.dll' = '37104|d01819bfe03222dfa9e35a36555b6b6c'
        'Newtonsoft.Json.dll' = '510976|abd9c387aaba000866f8ccb82313635f'
        'RestSharp.dll' = '168960|9a8c61802dbe935b29375ecd9ddc99bd'
        'SharpRaven.dll' = '80896|1969bb473ebdabb8a5650a659c9931d8'
        'SuperSocket.ClientEngine.dll' = '45056|1d6f7633c3a7dd5963e404789b8bc0a7'
        'System.IO.dll' = '21168|05aa69dfc063cd17312348bcb08a1f4f'
        'System.Runtime.dll' = '22208|7b864dd560373e17f38338dfdc299182'
        'System.Threading.Tasks.dll' = '34528|1183ca0085c8b22276342c342a4f2e02'
        'System.ValueTuple.dll' = '79496|5bc0380d837273cfd37545d80db14c4e'
        'System.Windows.Interactivity.dll' = '39936|3ab57a33a6e3a1476695d5a6e856c06a'
        'Typography.GlyphLayout.dll' = '27648|3301fd842ac418cf18bc96fa52d2d497'
        'Typography.OpenFont.dll' = '655360|7f500b1427952699a572695c22bb042b'
        'Uninstall.exe' = '84063|5137be0a691c0154283f7a6297af58d7'
        'WpfAnimatedGif.dll' = '39424|0db30d359725874e3fdd00f45bd82330'
        'dotNetFx40_Client_setup.exe' = '887896|61446fdd76788229d3ebaeabe84df38c'
        'install.ico' = '15086|ca65e8fa2904dbd18a9e7ff2cbb3d664'
        'left.bmp' = '163072|e4775b319c5da7b8847740504f738e30'
        'link.ico' = '15086|7779610392993220b94183876ec7eba6'
        'log4net.config' = '840|c9d2f2f6e6e7c7c84328052c6dfff743'
        'log4net.dll' = '299520|07556d19032645902bbb1b3805a3f9d5'
        'logUploaderSettings.ini' = '108|4c5b83693f63f5afa94fccb9d58a16e9'
        'logUploaderSettings_temp.ini' = '108|4c5b83693f63f5afa94fccb9d58a16e9'
        'messenger.ico' = '15086|7779610392993220b94183876ec7eba6'
        'noti.wav' = '105906|dad3eac3e7ef0bd05c749287ee31f948'
        'top.bmp' = '25820|2df8df0912b8fb2413bb81691e5399a9'
        'uninstall.ico' = '15086|3090a7bfb65d2dd577235862eeb7064d'
    }
    # v3.6.12: MessengerHistory.txt 는 업데이트 때 바뀌는 파일이라 ★핵심 파일에서 뺀다(다르다고 재설치 근거가 되면 안 됨).
    $CORE = @('HiworksMessenger.exe', 'HiworksMessenger.exe.config', 'Launcher.exe', 'Newtonsoft.Json.dll', 'RestSharp.dll', 'SharpRaven.dll', 'SuperSocket.ClientEngine.dll', 'log4net.config', 'log4net.dll')
    if (-not $instDir) {
        Write-Host "  설치 폴더를 몰라 건너뜀" -ForegroundColor DarkGray
    } elseif ($exeVer -and ($exeVer -replace '[^\d.]','') -ne '3.4.0.2') {
        # v3.6.3 F07: 기준선은 3.4.0.2 전용이다. 다른 버전에 대조하면 정상 파일이 전부
        #  '다름'으로 나오고, 그걸 보고 재설치를 안내하면 멀쩡한 PC를 건드리게 된다.
        Write-Host ("  ★ 이 PC 의 exe 는 {0} 인데 기준선은 3.4.0.2 전용이다 - 대조를 건너뛴다." -f $exeVer) -ForegroundColor Yellow
        Write-Host  "     하이웍스가 올라갔다면 담당자 PC(정상)에서 기준선을 새로 떠서 교체할 것." -ForegroundColor DarkYellow
    } elseif (-not $exeVer) {
        Write-Host "  exe 버전을 못 읽어 기준선 적용 여부를 판단할 수 없다 - 대조를 건너뛴다." -ForegroundColor DarkYellow
    } elseif ((Read-Host "  39개 파일 해시 대조를 할까요? (수 초) (y/n)") -ne 'y') {
        Write-Host "  건너뜀" -ForegroundColor DarkGray
    } else {
        $miss = @(); $diff = @(); $extra = @(); $unread = @(); $ok = 0
        foreach ($k in $BASE.Keys) {
            $fp = Join-Path $instDir $k
            if (-not (Test-Path -LiteralPath $fp)) { $miss += $k; continue }
            $parts = $BASE[$k] -split '\|'
            $wantSz = [int64]$parts[0]; $wantMd5 = $parts[1]
            $gotSz = (Get-Item -LiteralPath $fp).Length
            $gotMd5 = $null; $hashErr = $null
            try { $gotMd5 = (Get-FileHash -LiteralPath $fp -Algorithm MD5 -ErrorAction Stop).Hash.ToLower() }
            catch { $hashErr = $_.Exception.Message }
            # v3.6.3 F07: 해시를 '못 읽은 것'과 '달라진 것'을 구분한다. 잠긴 파일을 변조로 몰면 안 된다.
            if (-not $gotMd5) {
                $unread += ('{0}  (읽기 실패: {1})' -f $k, $hashErr)
            } elseif ($gotSz -eq $wantSz -and $gotMd5 -eq $wantMd5) { $ok++ }
            else { $diff += ('{0}  (기준 {1:N0}/{2} → 현재 {3:N0}/{4})' -f $k, $wantSz, $wantMd5.Substring(0,8), $gotSz, $gotMd5.Substring(0,8)) }
        }
        $here = @(Get-ChildItem -LiteralPath $instDir -File -Force -ErrorAction SilentlyContinue | Select-Object -ExpandProperty Name)
        $extra = @($here | Where-Object { -not $BASE.ContainsKey($_) })

        Write-Host ("  일치 {0} / 다름 {1} / 없음 {2} / 읽기실패 {3} / 기준에 없는 파일 {4}" -f $ok, $diff.Count, $miss.Count, $unread.Count, $extra.Count) `
            -ForegroundColor $(if ($diff.Count -eq 0 -and $miss.Count -eq 0 -and $unread.Count -eq 0) { 'Green' } else { 'Yellow' })
        foreach ($u in $unread) { Write-Host ("  [읽기실패] {0}" -f $u) -ForegroundColor DarkYellow }
        foreach ($m in $miss)  {
            $tag = if ($CORE -contains $m) { '  ← ★핵심 파일' } else { '' }
            Write-Host ("  [없음] {0}{1}" -f $m, $tag) -ForegroundColor $(if ($tag) { 'Red' } else { 'DarkYellow' })
        }
        foreach ($d in $diff)  {
            $nm = ($d -split '  ')[0]
            $tag = if ($CORE -contains $nm) { '  ← ★핵심 파일' } else { '' }
            Write-Host ("  [다름] {0}{1}" -f $d, $tag) -ForegroundColor $(if ($tag) { 'Red' } else { 'DarkYellow' })
        }
        foreach ($e in $extra) { Write-Host ("  [추가] {0}  ← 기준선에 없는 파일(받다 만 임시파일일 수 있음)" -f $e) -ForegroundColor DarkYellow }
        if ($diff.Count -eq 0 -and $miss.Count -eq 0 -and $unread.Count -eq 0) {
            Write-Host "  → 파일 세트는 정상 PC와 동일하다. '설치본 손상' 축은 배제하고 넘어갈 것." -ForegroundColor Green
        } elseif ($unread.Count -gt 0 -and $diff.Count -eq 0 -and $miss.Count -eq 0) {
            Write-Host "  → 읽지 못한 파일이 있어 '손상 없음'이라고 단정할 수 없다(미확정)." -ForegroundColor Yellow
        } else {
            Write-Host "  → 핵심 파일이 없거나 다르면 재설치가 답이다. 기타 파일만 다르면 버전 차이일 수 있다." -ForegroundColor Yellow
        }
    }

    # ── [10] 표본 한 줄 (클립보드 복사 → 여러 PC 대조용) ────────────
    # 이 한 줄을 PC 마다 모아 옵시디언 노트에 쌓으면, 정상 PC와 증상 PC의 차이가
    # 표본 수가 늘수록 드러난다. 한 대만 보고 원인을 단정한 것이 9/16 건의 실수였다.
    Write-Host "`n[10] 표본 한 줄 (정상 PC에서도 뽑아 모을 것)" -ForegroundColor Cyan
    function _N($s) { if ($null -eq $s) { '' } else { ([string]$s).Trim().Replace(',', '.') } }
    $a = _N $regProgVer; $b = _N $exeVer; $c = _N $srvVer
    $line = '[하이웍스] {0} / PC={1} / 계정={2} / 관리자={3} / LUA={4} / ProgVer={5} / ProgDir={6} / 서브키={7}개 / exe={8} / 서버={9} / 다운로드={10} / 쓰기={11} / 백신={12}' -f `
        (Get-Date -Format 'yyyy-MM-dd'), $env:COMPUTERNAME, $env:USERNAME,
        $(if ($isAdmin) { 'Y' } else { 'N' }), $lua,
        $(if ($a) { $a } else { '없음' }), $(if (_N $regProgDir) { '있음' } else { '없음' }),
        $subCnt, $(if ($b) { $b } else { '없음' }), $(if ($c) { $c } else { '조회실패' }),
        $(if ($null -eq $dlOk) { '미실시' } elseif (-not $dlOk) { '실패' }
          elseif ($dlVerified -eq $true) { "OK($dlBytes)" } elseif ($dlVerified -eq $false) { "크기불일치($dlBytes)" }
          else { "수신됨($dlBytes)·검증미확정" }),
        $(if ($null -eq $writeOk) { '미실시' } elseif ($writeOk) { 'OK' } else { '불가' }),
        $(if ($avNames) { $avNames -join '+' } else { '?' })
    Write-Host ("  " + $line) -ForegroundColor White
    try { Set-Clipboard -Value $line; Write-Host "  (클립보드에 복사됨 - 애니서포트 클립보드 공유로 바로 회수 가능)" -ForegroundColor Green } catch {}

    # ── [11] 읽는 법 ────────────────────────────────────────────────
    Write-Host "`n[11] 읽는 법" -ForegroundColor Cyan
    # v3.6.2 F08: 문자열 -eq 로만 비교하고 '같지 않으면 exe 가 낮다'고 단정했다.
    #  3.5.0.0 과 3.4.0.2 를 비교해도 '낮다'가 나왔다. [version] 으로 파싱해 네 갈래로 나눈다.
    $vb = $null; $vc = $null
    try { if ($b) { $vb = [version]($b -replace '[^\d.]','') } } catch {}
    try { if ($c) { $vc = [version]($c -replace '[^\d.]','') } } catch {}
    if ($vb -and $vc) {
        if ($vb -eq $vc) {
            Write-Host ("  · exe({0}) = 서버({1}) → '버전이 낮아서'는 아니다." -f $b, $c) -ForegroundColor Cyan
        } elseif ($vb -lt $vc) {
            Write-Host ("  · exe({0}) < 서버({1}) → 업데이트 안내가 뜨는 것은 정상 동작." -f $b, $c) -ForegroundColor Cyan
        } else {
            Write-Host ("  · exe({0}) > 서버({1}) → 서버보다 높다. 서버값 파싱이나 설치본 출처를 의심할 것." -f $b, $c) -ForegroundColor Yellow
        }
    } elseif ($b -or $c) {
        Write-Host ("  · 버전 비교 미확정 (exe={0} / 서버={1})" -f $(if($b){$b}else{'?'}), $(if($c){$c}else{'?'})) -ForegroundColor DarkYellow
    }
    # v3.6.1: 아래 두 줄은 '→ 아님' 으로 단정했었다. 관리자로 승격된 이 세션의 결과일 뿐이라
    #  교사 컨텍스트를 대변하지 못한다. 사실만 적고 배제는 하지 않는다.
    if ($dlOk -eq $true) {
        $vtxt = if ($dlVerified -eq $true) { '크기 일치' } elseif ($dlVerified -eq $false) { '★크기 불일치 - 설치본 검증 실패' } else { '검증 미확정' }
        Write-Host ("  · 이 세션({0})에서 {1:N0} bytes 수신 ({2}). 메신저도 된다는 뜻은 아님." -f $env:USERNAME, $dlBytes, $vtxt) -ForegroundColor Cyan
    }
    if ($dlOk -eq $false) {
        if ($dlFailKind -eq 'local') { Write-Host "  · 수신 실패(로컬 쓰기 단계). 디스크 공간·권한부터 볼 것 - 네트워크 아님." -ForegroundColor Cyan }
        else { Write-Host "  · 이 세션에서 수신 실패. 네트워크·백신이 1순위 후보." -ForegroundColor Cyan }
    }
    if ($writeOk -eq $true) { Write-Host ("  · 이 세션({0}, 관리자={1})에서 설치 폴더 쓰기 성공. 교사 계정 권한은 icacls 로 별도 확인." -f $env:USERNAME, $(if ($isAdmin) { 'Y' } else { 'N' })) -ForegroundColor Cyan }
    if ($writeOk -eq $false){ Write-Host "  · 설치 폴더 쓰기 실패. 관리자 세션에서도 막혔다면 강한 신호." -ForegroundColor Cyan }
    Write-Host ""
    Write-Host "  ★ 여기까지는 사실이다. 원인 단정은 정상 PC 표본과 대조한 뒤에 할 것." -ForegroundColor Yellow
    Write-Host "  ※ ProgDir/ProgVer 가 없다는 것만으로 원인이라고 하지 말 것 -" -ForegroundColor DarkYellow
    Write-Host "     2026-09-16 실측에서 정상 담당자 PC(exe 3.4.0.2, 알림 없음)에도 그 두 값이 없었다." -ForegroundColor DarkYellow
    Write-Host "     다만 표본이 1대뿐이라 가설이 폐기된 것은 아니다. 값이 '있을 때' 판정에 쓰이는지는" -ForegroundColor DarkYellow
    Write-Host "     아직 미검증이다. 정상 PC를 더 모아야 결론이 난다 - [10] 한 줄을 계속 쌓을 것." -ForegroundColor DarkYellow
    Write-Host ""
}

# ── 18) 화상수업 품질 진단 (v3.6.9 신설) ─────────────────────────────
# 근거: 2026-10-01 접수 유아 화상수업 건 - "화면 전달 느림·페이지 늦게 넘어감·소리 끊김".
#       교사는 통신사 점검 '이상 없음'을 받고 통신사 변경까지 예정한 상태였다.
#       통신사 점검은 대개 다운로드 속도만 본다(가정). 화상수업은 업로드·지연 편차·와이파이·
#       노트북 전원 제한에 더 민감한데, 툴킷에 그걸 한 번에 보는 메뉴가 없었다.
#       메뉴9 는 '특정 사이트 접속 불가'용이라 443 이 붙으면 '정상'으로 끝난다(품질은 안 본다).
#
# ★ 핵심 분기: 공유기(게이트웨이)까지와 외부까지 ping 을 따로 잰다.
#   외부가 정상이면 회선 정상이다. 이때 게이트웨이 수치가 튀는 건 공유기가 ICMP 를
#   후순위로 처리해서일 수 있으므로 무시한다. 외부가 나쁠 때만 게이트웨이로 구간을 가른다.
#     외부 나쁨 + 게이트웨이 나쁨 = 집 안(와이파이·공유기) → 통신사를 바꿔도 안 풀릴 가능성
#     외부 나쁨 + 게이트웨이 정상 = 공유기 밖(통신사 회선) → 통신사 점검·변경이 맞는 방향
#   기준치(손실 5% / 지터 30ms / 평균 100ms, 게이트웨이는 5% / 15ms / 30ms)는
#   일반 화상통화 권장치를 바탕으로 잡은 가정값이다. 실측 표본이 쌓이면 조정할 것.
#
# 조회 전용. 설정을 바꾸지 않는다(전원 설정 화면만 y 일 때 연다).
# 미검증(교사 PC 실측 전):
#   · netsh wlan 은 Win11 24H2 이후 위치 권한이 꺼져 있으면 신호값을 안 준다는 보고가 있다.
#     → 신호를 못 읽으면 원문을 그대로 보여주고 위치 권한을 안내한다.
#   · 오버레이 전원 모드(Win11 '전원 모드') GUID 대조값.
#   · Win32_PerfFormattedData_Counters_ProcessorInformation 의 성능% 값.
# 한계: 원격 접속 중에 재므로 애니서포트 트래픽이 섞인다. 수치가 약간 나쁘게 나올 수 있다.
#       부하 없는 순간의 10초 스냅숏이다. 업로드 대역폭 자체는 못 잰다(speedtest 로 따로).
function Measure-PingQuality([string]$Target, [int]$Count = 40) {
    $ping = New-Object System.Net.NetworkInformation.Ping
    $rtt  = New-Object System.Collections.Generic.List[double]
    $lost = 0; $sent = 0
    for ($i = 0; $i -lt $Count; $i++) {
        $sent++
        try {
            $r = $ping.Send($Target, 1000)
            if ($r.Status -eq [System.Net.NetworkInformation.IPStatus]::Success) { $rtt.Add([double]$r.RoundtripTime) }
            else { $lost++ }
        } catch { $lost++ }
        # ICMP 를 막아둔 대상이면 40번 x 1초를 기다리게 된다. 처음 5번이 전부 무응답이면 끊는다.
        if ($sent -eq 5 -and $rtt.Count -eq 0) { break }
        Start-Sleep -Milliseconds 200
    }
    $ping.Dispose()
    $o = [ordered]@{ Target = $Target; Sent = $sent; Lost = $lost
                     LossPct = [math]::Round($lost / $sent * 100, 1)
                     Min = $null; Avg = $null; Max = $null; Jitter = $null }
    if ($rtt.Count -gt 0) {
        $m = $rtt | Measure-Object -Minimum -Maximum -Average
        $o.Min = $m.Minimum; $o.Max = $m.Maximum; $o.Avg = [math]::Round($m.Average, 1)
        # 지터 = 연속한 두 응답시간 차이의 평균(RFC 3550 식 평활은 생략한 단순 평균)
        $o.Jitter = 0
        if ($rtt.Count -gt 1) {
            $d = 0.0
            for ($k = 1; $k -lt $rtt.Count; $k++) { $d += [math]::Abs($rtt[$k] - $rtt[$k - 1]) }
            $o.Jitter = [math]::Round($d / ($rtt.Count - 1), 1)
        }
    }
    [PSCustomObject]$o
}

# 'none' = 응답 없음(ICMP 차단 가능) / 'bad' / 'ok'
function Get-PingVerdict($q, [double]$lossMax, [double]$jitMax, [double]$avgMax) {
    if (-not $q -or $null -eq $q.Avg) { return 'none' }
    if ($q.LossPct -ge $lossMax -or $q.Jitter -ge $jitMax -or $q.Avg -ge $avgMax) { return 'bad' }
    return 'ok'
}

function Write-PingLine([string]$label, $q, [string]$verdict) {
    if ($verdict -eq 'none') {
        Write-Host ("  {0,-22} 응답 없음 ({1}회 시도) - ICMP 를 막아둔 대상일 수 있음" -f $label, $q.Sent) -ForegroundColor DarkYellow
        return
    }
    $col = if ($verdict -eq 'bad') { 'Red' } else { 'Gray' }
    $tag = if ($verdict -eq 'bad') { '  ← ★불량' } else { '' }
    Write-Host ("  {0,-22} 손실 {1,4}% ({2}/{3})  평균 {4,5}ms  최대 {5,5}ms  지터 {6,5}ms{7}" -f `
        $label, $q.LossPct, $q.Lost, $q.Sent, $q.Avg, $q.Max, $q.Jitter, $tag) -ForegroundColor $col
}

# netsh 출력은 OS 언어에 따라 항목명이 다르다(한글/영문). 항목명 대신 값의 모양으로 읽는다.
# 네이티브 명령 출력을 바이트로 받아 인코딩을 판별한다(v3.6.10).
# 2026-10-02 실측: netsh 출력이 UTF-8 로 나왔는데 PowerShell 이 CP949 로 읽어 한글이 전부 깨졌다.
# PC 마다 어느 쪽으로 나올지 모르므로 UTF-8(엄격) 로 먼저 읽고, 실패하면 CP949 로 읽는다.
function Get-NativeText([string]$exe, [string]$argLine) {
    try {
        $psi = New-Object System.Diagnostics.ProcessStartInfo
        $psi.FileName = $exe; $psi.Arguments = $argLine
        $psi.UseShellExecute = $false; $psi.CreateNoWindow = $true
        $psi.RedirectStandardOutput = $true; $psi.RedirectStandardError = $true
        $p = [System.Diagnostics.Process]::Start($psi)
        $ms = New-Object System.IO.MemoryStream
        # v3.6.15 (외부 QA): 동기 CopyTo 가 끝날 때까지 막혀 10초 제한이 안 먹었다(stderr 가 차면 교착도 가능).
        #  → stdout·stderr 를 비동기로 받고, 10초 안에 안 끝나면 프로세스를 종료한다.
        $outTask = $p.StandardOutput.BaseStream.CopyToAsync($ms)
        $errTask = $p.StandardError.ReadToEndAsync()
        if (-not $p.WaitForExit(10000)) { try { $p.Kill() } catch {} }
        try { [void]$outTask.Wait(1000) } catch {}
        try { [void]$errTask.Wait(500) } catch {}
        $b = $ms.ToArray()
    } catch { return @() }
    if ($b.Length -eq 0) { return @() }
    $txt = $null
    try { $txt = (New-Object System.Text.UTF8Encoding($false, $true)).GetString($b) }
    catch { $txt = [System.Text.Encoding]::GetEncoding(949).GetString($b) }
    return @($txt -split "\r?\n")
}

function Get-WlanInfo {
    $raw = @(Get-NativeText 'netsh.exe' 'wlan show interfaces')
    $info = [ordered]@{ Raw = $raw; SSID = $null; Signal = $null; Channel = $null; Band = $null
                        Radio = $null; RxMbps = $null; TxMbps = $null; State = $null }
    foreach ($ln in $raw) {
        if ($ln -notmatch '^\s*(.+?)\s+:\s?(.*)$') { continue }
        $k = $matches[1].Trim(); $v = $matches[2].Trim()
        if ($k -eq 'SSID')                       { $info.SSID = $v }
        elseif ($k -match '(?i)^(상태|State)$')   { $info.State = $v }
        elseif ($v -match '^(\d{1,3})\s*%$')      { $info.Signal = [int]$matches[1] }
        elseif ($k -match '(?i)^(채널|Channel)$') { if ($v -match '^(\d+)') { $info.Channel = [int]$matches[1] } }
        elseif ($k -match '(?i)^(밴드|Band)$')    { $info.Band = $v }
        elseif ($k -match '(?i)Mbps') {
            $n = $null; if ($v -match '^([\d.]+)') { $n = [double]$matches[1] }
            if ($k -match '(?i)수신|Receive') { $info.RxMbps = $n }
            elseif ($k -match '(?i)송신|Transmit') { $info.TxMbps = $n }
        }
        elseif ($v -match '^802\.11\w*$')         { $info.Radio = $v }
    }
    # 구버전 Windows 는 '밴드' 줄이 없다. 채널 번호로 추정한다(1~14 = 2.4GHz).
    # 6GHz(Wi-Fi 6E)도 채널 번호가 1부터라 구분이 안 되므로 '추정'을 붙인다.
    if (-not $info.Band -and $info.Channel) {
        $info.Band = if ($info.Channel -le 14) { '2.4 GHz (채널로 추정)' } else { '5 GHz (채널로 추정)' }
    }
    [PSCustomObject]$info
}

function Show-VideoCallCheck {
    Write-Host "`n=== 화상수업 품질 진단 (조회 전용 - 약 30초) ===" -ForegroundColor Cyan
    Write-Host "  화면 전달 지연·소리 끊김을 연결 방식 / 와이파이 / 회선 구간 / 전원 / CPU / 메모리 로 가른다." -ForegroundColor DarkGray
    Write-Host "  ※ 원격 접속 중 측정이라 원격 트래픽이 섞인다. 수치가 실제보다 약간 나쁠 수 있다." -ForegroundColor DarkGray
    Write-Host "  ※ 가능하면 화상수업앱 테스트방·CRM 을 수업처럼 띄워둔 상태에서 실행할 것(CPU·메모리 부하 재현)." -ForegroundColor DarkGray
    $flags = New-Object System.Collections.Generic.List[string]
    $sum   = [ordered]@{}

    # [1] 실제 통신 경로 - OS 가 8.8.8.8 로 실제 보내는 어댑터(Get-PrimaryIPConfig, 메뉴7·9 와 공용)
    Write-Host "`n[1] 연결 방식 (실제 통신 경로)" -ForegroundColor Yellow
    $cfg = $null; $na = $null; $gw = $null; $isWifi = $false
    try {
        $cfg = Get-PrimaryIPConfig
        if ($cfg) {
            $gw = @($cfg.IPv4DefaultGateway)[0].NextHop
            $na = Get-NetAdapter -InterfaceIndex $cfg.InterfaceIndex -ErrorAction SilentlyContinue
        }
    } catch {}
    if ($na) {
        # NdisPhysicalMedium: 9 = Native 802.11(무선), 14 = 802.3(유선). 언어와 무관한 숫자라 이걸 쓴다.
        $isWifi = ($na.NdisPhysicalMedium -eq 9) -or ($na.InterfaceDescription -match '(?i)Wi-?Fi|Wireless|WLAN|802\.11')
        $kind = if ($isWifi) { 'Wi-Fi(무선)' }
                elseif ($na.InterfaceDescription -match '(?i)Remote NDIS|RNDIS') { '휴대폰 USB 테더링' }
                elseif ($na.NdisPhysicalMedium -eq 14) { '유선(LAN)' }
                else { '기타' }
        $spd = if ($na.ReceiveLinkSpeed) { '{0:N0} Mbps' -f ($na.ReceiveLinkSpeed / 1e6) } else { $na.LinkSpeed }
        Write-Host ("  {0}  - {1} ({2})" -f $kind, $na.Name, $na.InterfaceDescription) -ForegroundColor Gray
        Write-Host ("  링크 속도 {0} / 게이트웨이 {1}" -f $spd, $gw) -ForegroundColor Gray
        $sum['연결'] = $kind
        # 유선인데 100Mbps 이하 링크 = 랜선(Cat5 이하·단선)이나 공유기 포트 문제일 수 있다
        if (-not $isWifi -and $na.ReceiveLinkSpeed -and $na.ReceiveLinkSpeed -le 100e6) {
            Write-Host "  ← 유선인데 100Mbps 이하 링크. 랜선·공유기 포트 확인" -ForegroundColor Yellow
            $flags.Add('유선 링크 100Mbps 이하 - 랜선·포트 확인')
        }
    } else {
        Write-Host "  기본 게이트웨이를 가진 어댑터를 못 찾음 (인터넷 연결 자체 확인 필요)" -ForegroundColor Red
        $flags.Add('기본 게이트웨이 어댑터 없음')
    }
    # 같이 켜져 있는 다른 어댑터. VPN 이 켜져 있으면 트래픽이 우회돼 지연이 붙는다.
    $vpnPat  = '(?i)VPN|TAP-|WireGuard|Wintun|Fortinet|FortiClient|AnyConnect|PANGP|GlobalProtect|Juniper|Pulse|SonicWall|ZeroTier|Tailscale|Hamachi|OpenVPN'
    $virtPat = '(?i)Hyper-V|VMware|VirtualBox|vEthernet|Loopback|Bluetooth'
    $others = @(Get-NetAdapter -ErrorAction SilentlyContinue |
                Where-Object { $_.Status -eq 'Up' -and (-not $na -or $_.ifIndex -ne $na.ifIndex) })
    foreach ($o in $others) {
        if (-not $isWifi -and $o.NdisPhysicalMedium -eq 9) { continue }   # 와이파이는 아래에서 따로 표시
        if ($o.InterfaceDescription -match $vpnPat -or $o.Name -match $vpnPat) {
            Write-Host ("  ★ VPN 어댑터 켜짐: {0} ({1})" -f $o.Name, $o.InterfaceDescription) -ForegroundColor Red
            $flags.Add(("VPN 활성({0}) - 수업 중 끄고 비교" -f $o.Name))
        } elseif ($o.InterfaceDescription -notmatch $virtPat) {
            Write-Host ("  같이 연결됨: {0} ({1})" -f $o.Name, $o.InterfaceDescription) -ForegroundColor DarkGray
        }
    }
    # 경로가 와이파이가 아니면 와이파이 어댑터 상태를 따로 보여준다.
    # 2026-10-02 건: 측정은 유선이었는데 수업도 유선인지는 따로 물어봐야 했다 → 화면에 남긴다.
    if ($na -and -not $isWifi) {
        $wa = @(Get-NetAdapter -ErrorAction SilentlyContinue |
                Where-Object { $_.NdisPhysicalMedium -eq 9 -and $_.InterfaceDescription -notmatch '(?i)Virtual|Direct' })
        foreach ($x in $wa) {
            $st = if ($x.Status -eq 'Up') { '연결됨(통신 경로는 아님)' } elseif ($x.Status -eq 'Disconnected') { '연결 안 됨' } else { [string]$x.Status }
            Write-Host ("  와이파이 어댑터: {0} - {1}" -f $x.Name, $st) -ForegroundColor DarkGray
        }
        if ($wa) {
            Write-Host "  ※ 이번 측정은 위 경로(유선 등) 기준. 수업을 와이파이로 한다면 와이파이로 붙인 뒤 다시 측정." -ForegroundColor DarkYellow
            $sum['와이파이'] = '미사용(측정 경로 아님)'
        }
    }

    # [2] 와이파이 상태 - 무선일 때만
    if ($isWifi) {
        Write-Host "`n[2] 와이파이" -ForegroundColor Yellow
        $w = Get-WlanInfo
        if ($null -ne $w.Signal) {
            $sc = if ($w.Signal -lt 50) { 'Red' } elseif ($w.Signal -lt 70) { 'Yellow' } else { 'Gray' }
            Write-Host ("  SSID {0} / {1} / 채널 {2} / {3}" -f $w.SSID, $w.Band, $w.Channel, $w.Radio) -ForegroundColor Gray
            Write-Host ("  신호 {0}%{1}" -f $w.Signal, $(if ($w.Signal -lt 50) { '  ← ★약함' } elseif ($w.Signal -lt 70) { '  ← 보통' } else { '' })) -ForegroundColor $sc
            if ($w.RxMbps -or $w.TxMbps) {
                $rc = if (($w.TxMbps -and $w.TxMbps -lt 50) -or ($w.RxMbps -and $w.RxMbps -lt 50)) { 'Yellow' } else { 'Gray' }
                Write-Host ("  연결 속도 수신 {0} / 송신 {1} Mbps (무선 링크 값이지 인터넷 속도가 아님)" -f $w.RxMbps, $w.TxMbps) -ForegroundColor $rc
            }
            $sum['와이파이'] = ('{0} / 신호 {1}%' -f $w.Band, $w.Signal)
            if ($w.Signal -lt 50) { $flags.Add(('와이파이 신호 약함({0}%) - 공유기 가까이 또는 유선 연결' -f $w.Signal)) }
            if ($w.Band -match '^2\.4') {
                Write-Host "  ※ 2.4GHz: 벽 통과는 좋지만 간섭이 많고 느리다. 5GHz: 빠르지만 거리·벽에 약하다." -ForegroundColor DarkGray
                Write-Host "     신호가 약하지 않은데 끊기면 5GHz SSID 로 바꿔 비교해 볼 것." -ForegroundColor DarkGray
            }
        } else {
            # 신호값을 못 읽었다 = 미연결 / 위치 권한(Win11 24H2+) / wlansvc 문제. 원문을 그대로 보여준다.
            if ($w.State) { Write-Host ("  상태: {0}" -f $w.State) -ForegroundColor DarkYellow }
            Write-Host "  신호값을 읽지 못함. netsh 원문:" -ForegroundColor DarkYellow
            $w.Raw | Where-Object { $_.Trim() } | Select-Object -First 12 | ForEach-Object { Write-Host "    $_" -ForegroundColor DarkGray }
            Write-Host "  → '위치' 권한 문구가 보이면: 설정 > 개인 정보 및 보안 > 위치 를 켜고 다시 실행" -ForegroundColor DarkGray
        }
    }

    # [3] 회선 구간 - 게이트웨이 vs 외부
    Write-Host "`n[3] 회선 구간 (공유기까지 / 외부까지, 각 40회)" -ForegroundColor Yellow
    $qGw = $null; $vGw = 'none'
    if ($gw) {
        Write-Host "  측정 중 (공유기)..." -ForegroundColor DarkGray
        $qGw = Measure-PingQuality $gw 40
        $vGw = Get-PingVerdict $qGw 5 15 30
    }
    Write-Host "  측정 중 (외부)..." -ForegroundColor DarkGray
    $qEx = Measure-PingQuality '8.8.8.8' 40
    $vEx = Get-PingVerdict $qEx 5 30 100
    if ($vEx -eq 'none') {
        $qEx = Measure-PingQuality '1.1.1.1' 40
        $vEx = Get-PingVerdict $qEx 5 30 100
    }
    if ($qGw) { Write-PingLine ("공유기 " + $gw) $qGw $vGw }
    Write-PingLine ("외부 " + $qEx.Target) $qEx $vEx
    Write-Host "  (불량 기준 가정치 - 외부: 손실 5%·지터 30ms·평균 100ms / 공유기: 5%·15ms·30ms)" -ForegroundColor DarkGray

    Write-Host ""
    if ($vEx -eq 'ok') {
        Write-Host "  → 외부까지 ping 지연·손실 정상(이 시점·ICMP 기준). 수업 중 품질은 수업 부하에서 다시 봐야 한다." -ForegroundColor Green
        if ($vGw -eq 'bad') { Write-Host "     (공유기 수치만 튀는 건 공유기가 ping 을 후순위로 처리하는 탓일 수 있어 무시)" -ForegroundColor DarkGray }
        Write-Host "     업로드 속도는 따로 확인: https://www.speedtest.net (가이드 기준 업/다운 100Mbps 내외)" -ForegroundColor DarkGray
        $sum['회선'] = ('정상 (외부 손실 {0}% / 지터 {1}ms)' -f $qEx.LossPct, $qEx.Jitter)
    } elseif ($vEx -eq 'bad' -and $vGw -eq 'bad') {
        Write-Host "  → ★ 공유기까지부터 불안정 = 집 안 구간(와이파이·공유기) 문제." -ForegroundColor Red
        Write-Host "     통신사를 바꿔도 해결되지 않을 가능성이 큼. 유선 연결 / 공유기 가까이 / 공유기 재부팅부터." -ForegroundColor Yellow
        $flags.Add('집 안 구간(와이파이·공유기) 불안정 - 통신사 변경으로 안 풀릴 가능성')
        $sum['회선'] = '불량 - 집 안 구간(공유기까지부터)'
    } elseif ($vEx -eq 'bad' -and $vGw -eq 'none') {
        # v3.6.15 (외부 QA): 공유기 결과가 없는데 '공유기까지는 정상'으로 단정했다.
        Write-Host "  → ★ 외부 구간 불량. 단 공유기 응답이 없어(또는 게이트웨이 없음) 집 안/통신사 구간은 판정 보류." -ForegroundColor Yellow
        Write-Host "     유선 연결 또는 공유기 바로 옆에서 다시 측정해 비교할 것." -ForegroundColor DarkGray
        $flags.Add('외부 회선 불량 - 공유기 무응답이라 구간 판정 보류')
        $sum['회선'] = '불량 - 구간 판정 보류(공유기 무응답)'
    } elseif ($vEx -eq 'bad') {
        Write-Host "  → ★ 공유기까지는 정상, 그 바깥이 불안정 = 통신사 회선 구간." -ForegroundColor Red
        Write-Host "     통신사 점검·변경이 맞는 방향. 측정값을 캡처해 두면 통신사에 근거로 쓸 수 있음." -ForegroundColor Yellow
        $flags.Add('공유기 밖(통신사 회선) 구간 불안정')
        $sum['회선'] = '불량 - 공유기 밖(통신사 회선)'
    } else {
        Write-Host "  → 외부 ping 무응답 - ICMP 차단 환경일 수 있어 회선 판정 보류." -ForegroundColor DarkYellow
        $sum['회선'] = '판정 보류(외부 ping 무응답)'
    }

    # [4] 전원 - 배터리 구동·절전 모드면 CPU 가 제한돼 인코딩이 밀린다(가정)
    Write-Host "`n[4] 전원" -ForegroundColor Yellow
    $onAC = $null; $batt = $null; $hasBatt = $false
    try {
        Add-Type -AssemblyName System.Windows.Forms -ErrorAction Stop
        $ps = [System.Windows.Forms.SystemInformation]::PowerStatus
        if ($ps.PowerLineStatus -eq [System.Windows.Forms.PowerLineStatus]::Online)      { $onAC = $true }
        elseif ($ps.PowerLineStatus -eq [System.Windows.Forms.PowerLineStatus]::Offline) { $onAC = $false }
        # 128 = NoSystemBattery. 플래그 enum 이라 정수로 바꿔서 비교한다(enum 의 참/거짓 변환에 기대지 않는다).
        $hasBatt = (([int]$ps.BatteryChargeStatus -band 128) -eq 0)
        if ($hasBatt) { $batt = [int]($ps.BatteryLifePercent * 100) }
    } catch {}
    if ($hasBatt) {
        $acTxt = if ($onAC -eq $true) { '충전기 연결됨' } elseif ($onAC -eq $false) { '★배터리로 구동 중(충전기 미연결)' } else { '전원 상태 불명' }
        Write-Host ("  배터리 {0}% / {1}" -f $batt, $acTxt) -ForegroundColor $(if ($onAC -eq $false) { 'Red' } else { 'Gray' })
        $sum['전원'] = ('배터리 {0}% / {1}' -f $batt, $(if ($onAC -eq $true) { '충전기 연결' } elseif ($onAC -eq $false) { '충전기 미연결' } else { '불명' }))
        if ($onAC -eq $false) { $flags.Add('배터리 구동 중 - 충전기 연결 후 수업') }
    } else {
        Write-Host "  배터리 없음(데스크톱)" -ForegroundColor Gray
        $sum['전원'] = '데스크톱'
    }
    # 전원 구성표(제어판) - 절전이면 문제
    $schTxt = (powercfg /getactivescheme 2>$null | Out-String)
    $schGuid = $null; $schName = $null
    if ($schTxt -match '([0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12})\s*\(([^)]*)\)') {
        $schGuid = $matches[1].ToLower(); $schName = $matches[2]
    }
    # 이름은 powercfg 출력(콘솔 코드페이지)에서 깨질 수 있어 기본 구성표는 GUID 로 이름을 붙인다
    $schMap = @{ '381b4222-f694-41f0-9685-ff5bb260df2e' = '균형 조정'
                 '8c5e7fda-e8bf-4a96-9a85-a6e23a8c635c' = '고성능'
                 'a1841308-3bcb-4fd1-8a6a-a1cf2c7b0cfa' = '절전'
                 'e9a42b02-d5df-448d-aa00-03f14749eb61' = '최고의 성능' }
    if ($schGuid -and $schMap.ContainsKey($schGuid)) { $schName = $schMap[$schGuid] }
    if ($schGuid) {
        $isSaver = ($schGuid -eq 'a1841308-3bcb-4fd1-8a6a-a1cf2c7b0cfa')
        Write-Host ("  전원 구성표: {0}{1}" -f $schName, $(if ($isSaver) { '  ← ★절전' } else { '' })) -ForegroundColor $(if ($isSaver) { 'Red' } else { 'Gray' })
        if ($isSaver) { $flags.Add('전원 구성표가 절전') }
    }
    # Win11 '전원 모드'(오버레이). 제어판 구성표와 별개로 CPU 를 제한한다.
    # GUID 대조는 미검증 - 모르는 값이면 GUID 를 그대로 보여준다.
    $ovMap = @{ '961cc777-2547-4f9d-8174-7d86181b8a7a' = '최고 전원 효율'
                '00000000-0000-0000-0000-000000000000' = '균형'
                '3af9b8d9-7c97-431d-ad78-34a8bfea439f' = '더 나은 성능'
                'ded574b5-45a0-4f42-8737-46345c09c238' = '최고 성능' }
    try {
        $pk = Get-ItemProperty 'HKLM:\SYSTEM\CurrentControlSet\Control\Power\User\PowerSchemes' -ErrorAction Stop
        $ovName = if ($onAC -eq $false) { 'ActiveOverlayDcPowerScheme' } else { 'ActiveOverlayAcPowerScheme' }
        $ov = [string]$pk.$ovName
        if ($ov) {
            $ov = $ov.ToLower()
            $ovTxt = if ($ovMap.ContainsKey($ov)) { $ovMap[$ov] } else { $ov }
            $isEff = ($ov -eq '961cc777-2547-4f9d-8174-7d86181b8a7a')
            Write-Host ("  전원 모드({0}): {1}{2}" -f $(if ($onAC -eq $false) { '배터리' } else { '전원 연결' }), $ovTxt,
                $(if ($isEff) { '  ← ★최고 효율 = CPU 제한' } else { '' })) -ForegroundColor $(if ($isEff) { 'Red' } else { 'Gray' })
            if ($isEff) { $flags.Add('전원 모드가 최고 전원 효율') }
            $sum['전원'] = $sum['전원'] + ' / ' + $ovTxt
        }
    } catch {}

    # [5] CPU - 지금 이 순간의 부하와 '정격 대비 실제 성능'
    Write-Host "`n[5] CPU (3초 측정)" -ForegroundColor Yellow
    $cores = [Environment]::ProcessorCount
    $snap = @{}
    Get-Process -ErrorAction SilentlyContinue | ForEach-Object { if ($_.CPU) { $snap[$_.Id] = $_.CPU } }
    # 성능 카운터(Formatted)는 첫 조회 값이 0 으로 나오는 경우가 있어 3초 뒤 두 번째 값을 쓴다
    $perfQ = { try { Get-CimInstance Win32_PerfFormattedData_Counters_ProcessorInformation -Filter "Name='_Total'" -ErrorAction Stop } catch { $null } }
    [void](& $perfQ)
    $load1 = (Get-CimInstance Win32_Processor -ErrorAction SilentlyContinue | Measure-Object LoadPercentage -Average).Average
    Start-Sleep -Seconds 3
    $load2 = (Get-CimInstance Win32_Processor -ErrorAction SilentlyContinue | Measure-Object LoadPercentage -Average).Average
    $lv = @(@($load1, $load2) | Where-Object { $null -ne $_ })
    $load = if ($lv.Count) { [int][math]::Round(($lv | Measure-Object -Average).Average, 0) } else { $null }
    $perf = $null
    $pi = & $perfQ
    # 0 은 '아직 계산 안 됨'일 가능성이 커서 버린다(실제로 0% 성능으로 도는 CPU 는 없다)
    if ($pi -and $pi.PercentProcessorPerformance) { $perf = [int]$pi.PercentProcessorPerformance }
    if ($null -ne $load) {
        $lc = if ($load -ge 80) { 'Red' } elseif ($load -ge 60) { 'Yellow' } else { 'Gray' }
        Write-Host ("  현재 부하 {0}%{1}" -f $load, $(if ($load -ge 80) { '  ← ★높음' } else { '' })) -ForegroundColor $lc
    } else { Write-Host "  현재 부하 조회 실패" -ForegroundColor DarkYellow }
    if ($null -ne $perf) {
        # 100% = 정격 클럭. 부스트 중이면 100 을 넘는다. 한참 밑이면 전원 제한·발열로 깎인 것(가정).
        $pc = if ($perf -lt 60) { 'Red' } else { 'Gray' }
        Write-Host ("  실제 성능 {0}% (정격 대비){1}" -f $perf, $(if ($perf -lt 60) { '  ← ★전원 제한·발열로 깎였을 수 있음' } else { '' })) -ForegroundColor $pc
        if ($perf -lt 60) { $flags.Add(('CPU 실제 성능 {0}% - 전원 제한·발열 의심' -f $perf)) }
    }
    if ($null -ne $load -and $load -ge 80) { $flags.Add(('CPU 부하 {0}% - 아래 상위 프로세스 확인' -f $load)) }
    $sum['CPU'] = ('부하 {0}{1}' -f $(if ($null -ne $load) { "$load%" } else { '?' }), $(if ($null -ne $perf) { " / 성능 $perf%" } else { '' }))
    Write-Host "  지금 CPU 를 쓰는 프로세스 상위 5:" -ForegroundColor DarkGray
    Get-Process -ErrorAction SilentlyContinue |
        Where-Object { $_.CPU -and $snap.ContainsKey($_.Id) } |
        ForEach-Object { [PSCustomObject]@{ Name = $_.ProcessName; Pct = [math]::Round(($_.CPU - $snap[$_.Id]) / 3 / $cores * 100, 1) } } |
        Where-Object { $_.Pct -gt 0 } | Sort-Object Pct -Descending | Select-Object -First 5 |
        ForEach-Object { Write-Host ("    {0,5}%  {1}" -f $_.Pct, $_.Name) -ForegroundColor Gray }

    # [6] 메모리 - v3.6.10 추가. 2026-10-02 건 노트북이 RAM 4GB(Win11 최소)였는데 v3.6.9 는 이걸 안 봤다.
    #     화상 송출 + 브라우저 + 메신저가 겹치면 4GB 는 스왑으로 넘어간다(가정). 기준 4GB·85% 도 가정값.
    Write-Host "`n[6] 메모리" -ForegroundColor Yellow
    try {
        $osm = Get-CimInstance Win32_OperatingSystem -ErrorAction Stop
        $totGB  = [math]::Round($osm.TotalVisibleMemorySize / 1MB, 1)
        $usePct = [int][math]::Round(($osm.TotalVisibleMemorySize - $osm.FreePhysicalMemory) / $osm.TotalVisibleMemorySize * 100, 0)
        $small  = ($osm.TotalVisibleMemorySize -le 4.5MB)   # 4GB 장착 = 사용 가능 3.7GB 안팎
        $mc = if ($usePct -ge 85 -or $small) { 'Red' } elseif ($usePct -ge 75) { 'Yellow' } else { 'Gray' }
        Write-Host ("  총 {0}GB / 사용률 {1}%{2}" -f $totGB, $usePct,
            $(if ($small) { '  ← ★4GB 이하 - 화상수업 여유 적음' } elseif ($usePct -ge 85) { '  ← ★부족' } else { '' })) -ForegroundColor $mc
        if ($small)          { $flags.Add(('메모리 {0}GB - 수업 중 다른 프로그램 종료 안내, 재발 시 증설 검토' -f $totGB)) }
        if ($usePct -ge 85)  { $flags.Add(('메모리 사용률 {0}% - 아래 상위 프로그램 확인' -f $usePct)) }
        $sum['메모리'] = ('{0}GB / 사용 {1}%' -f $totGB, $usePct)
        # 크롬·엣지는 프로세스가 수십 개로 쪼개져 있어 이름별로 합산해야 실제 크기가 보인다
        Write-Host "  프로그램별 사용량 상위 5 (같은 이름 합산):" -ForegroundColor DarkGray
        Get-Process -ErrorAction SilentlyContinue | Group-Object ProcessName |
            ForEach-Object { [PSCustomObject]@{ Name = $_.Name; MB = [math]::Round(($_.Group | Measure-Object WorkingSet64 -Sum).Sum / 1MB, 0) } } |
            Sort-Object MB -Descending | Select-Object -First 5 |
            ForEach-Object { Write-Host ("    {0,6:N0} MB  {1}" -f $_.MB, $_.Name) -ForegroundColor Gray }
    } catch { Write-Host "  조회 실패" -ForegroundColor DarkYellow }

    # [7] 업로드를 같이 쓰는 동기화 프로그램 - 수업 중 동기화가 돌면 화면 전달이 밀린다
    Write-Host "`n[7] 동기화·업로드 프로그램 (실행 중)" -ForegroundColor Yellow
    $syncPat = 'OneDrive','Dropbox','GoogleDriveFS','MYBOX*','NaverMYBOX*','iCloud*','Box','BoxSync'
    $sync = @(Get-Process -ErrorAction SilentlyContinue |
              Where-Object { $n = $_.ProcessName; ($syncPat | Where-Object { $n -like $_ }) } |
              Select-Object -ExpandProperty ProcessName -Unique)
    if ($sync) {
        Write-Host ("  {0}" -f ($sync -join ', ')) -ForegroundColor Yellow
        Write-Host "  → 큰 파일을 올리는 중이면 업로드를 점유한다. 수업 중엔 '동기화 일시 중지' 안내." -ForegroundColor DarkGray
    } else { Write-Host "  없음" -ForegroundColor DarkGray }
    Write-Host "  ※ 토렌트·그리드처럼 이름을 모르는 업로드는 메뉴16 [5] TCP 연결 수로 잡힌다." -ForegroundColor DarkGray

    # 요약 - 화면 캡처 한 장으로 끝나게
    Write-Host "`n===== 요약 (캡처용) =====" -ForegroundColor Cyan
    foreach ($k in $sum.Keys) { Write-Host ("  {0,-6}: {1}" -f $k, $sum[$k]) -ForegroundColor White }
    if ($flags.Count -gt 0) {
        Write-Host "  [확인 필요]" -ForegroundColor Yellow
        $flags | ForEach-Object { Write-Host ("   ★ {0}" -f $_) -ForegroundColor Yellow }
    } else {
        Write-Host "  [확인 필요] 없음 - 측정 시점엔 PC·회선 쪽 근거가 안 보인다." -ForegroundColor Green
        Write-Host "   수업 중에만 끊기면 수업 시간대에 다시 측정하거나 CRM 접속상태 이력의 교사 스코어 확인." -ForegroundColor DarkGray
    }

    if ($onAC -eq $false -or ($flags | Where-Object { $_ -match '전원|CPU' })) {
        if ((Read-Host "`n전원 설정 화면을 열까요? (y/n)") -eq 'y') { Start-Process 'ms-settings:powersleep' }
    }
    Write-Host ""
}

:main while ($true) {
    Write-Host "======================================" -ForegroundColor Blue
    Write-Host "  원격지원 툴킷 v3.6.20 (2026-10-14)" -ForegroundColor Blue
    Write-Host "======================================" -ForegroundColor Blue
    Write-Host " [증상별 점검]" -ForegroundColor Magenta
    Write-Host " S1. 화상수업앱 카메라/마이크 안 됨" -ForegroundColor White
    Write-Host " S2. 로그인/인증 안 됨 (CRM·익스·하이웍스)" -ForegroundColor White
    Write-Host " S3. CRM 화면·기능 이상 (목록/버튼/발송)" -ForegroundColor White
    Write-Host " S4. 강의채널·녹강 재생 안 됨" -ForegroundColor White
    Write-Host " S5. PC 느림/멈춤/갑자기 꺼짐" -ForegroundColor White
    Write-Host " S6. 화상수업 끊김·지연 (화면 전달 느림/소리 끊김)" -ForegroundColor White
    Write-Host "--------------------------------------" -ForegroundColor Blue
    Write-Host " [개별 도구]" -ForegroundColor DarkCyan
    Write-Host " 1. 보안/입력간섭 프로그램 탐지"
    Write-Host " 2. 보안프로그램 CMD 제거 (UI 제거불가한 것만 - 확인 후)"
    Write-Host " 3. 백신 진단 (알약/V3 제거→Defender 전환 확인)"
    Write-Host " 4. 확장 프로그램 목록 (OTP 보호 · 백신/쇼핑 확장 ★제거 표시)"
    Write-Host " 5. 브라우저 자동 정리 (캐시/쿠키/LMS 권한/IE모드/업데이트)"
    Write-Host " 6. 장치·드라이버·서비스 확인 (XSplit/VCam·DirectShow 가상카메라 - 삭제는 수동)"
    Write-Host " 7. 시스템 정보"
    Write-Host " 8. 이벤트 로그 확인 (30일/위험·경고·오류)"
    Write-Host " 9. 네트워크 진단 (특정 사이트만 접속불가 - 차단지점 판별)"
    Write-Host "10. 오디오/카메라 진단 (계층 자동판정 - S1 과 동일)"
    Write-Host "11. 강의채널 재생 점검 (http 주소·Agent 버전·캡처 프로그램)"
    Write-Host "12. 시간 동기화 (OTP 반복 오류)"
    Write-Host "13. eISP 2.0 강제 제거 (UI로 안 지워지는 결제보안 - CMD)"
    Write-Host "14. Windows 시스템 파일 복구 (DISM+SFC / PC 불안정·업데이트 실패 시, 오래 걸림)"
    Write-Host "15. 디스크 검사 chkdsk (이벤트 로그 disk/Ntfs 오류 시)"
    Write-Host "16. 느림 진단 (자원 점유·자동시작·토렌트/그리드 탐지 - 조회 전용)"
    Write-Host "17. 하이웍스 점검 (업데이트 반복·다운로드 실패 - 진단 전용)"
    Write-Host "18. 화상수업 품질 진단 (회선 구간·와이파이·전원·CPU·메모리 - 조회 전용)"
    Write-Host " 0. 종료 (처리내역 요약 출력)"
    Write-Host "======================================" -ForegroundColor Blue
    switch (Read-Host "선택") {
        # switch 는 기본이 대소문자 무시다. 's1' 과 'S1' 을 둘 다 두면 매칭되는 분기가
        #  전부 실행돼 시나리오가 두 번 돌았다(v3.2~v3.3, 실측). 소문자 하나로 'S1' 도 잡힌다.
        's1' { Invoke-Scenario-AV }
        's2' { Invoke-Scenario-Login }
        's3' { Invoke-Scenario-CrmView }
        's4' { Invoke-Scenario-Player }
        's5' { Invoke-Scenario-Slow }
        's6' { Invoke-Scenario-VideoCall }
        '1' { Invoke-Detect }; '2' { Invoke-Remove }; '3' { Show-AntiVirus }
        '4' { Show-Extensions }; '5' { Browser-Menu }; '6' { Show-DeviceCheck }
        '7' { Show-SysInfo }; '8' { Show-EventLog }; '9' { Invoke-NetDiag }
        '10' { Show-AudioDevices }; '11' { Check-StarPlayer }; '12' { Sync-Time }
        '13' { Remove-eISP }; '14' { Repair-SystemFiles }; '15' { Invoke-Chkdsk }; '16' { Show-SlowDiagnosis }; '17' { Show-HiworksCheck }
        '18' { Show-VideoCallCheck }
        '0' {
            # ① 처리내역 요약 (엑셀 처리내역 열 붙여넣기용)
            Write-Host "`n===== 처리내역 요약 =====" -ForegroundColor Cyan
            if ($script:ActionLog.Count -gt 0) {
                $summary = "• " + (($script:ActionLog | Select-Object -Unique) -join '/')
                Write-Host $summary -ForegroundColor White
                # 원격 PC 클립보드에 복사됨 - 애니서포트 클립보드 공유 켜져 있으면 그대로 붙여넣기 가능
                try { Set-Clipboard -Value $summary; Write-Host "(클립보드에 복사됨)" -ForegroundColor Green } catch {}
            } else {
                Write-Host "기록된 자동 조치 없음 (조회/수동 안내만 수행)" -ForegroundColor DarkGray
            }
            # ② 트랜스크립트 정리
            if ($script:TranscriptPath) {
                try { Stop-Transcript | Out-Null } catch {}
                Write-Host ("세션 전체 로그: {0}" -f $script:TranscriptPath) -ForegroundColor DarkGray
                Write-Host "(필요 시 이 파일을 회수한 뒤 아래에서 삭제)" -ForegroundColor DarkGray
            }
            # ③ 자기 삭제 (선생님 PC에 툴/로그 안 남김)
            #  삭제 대상 경로는 실행 형태마다 다르다.
            #   · 단일파일(.bat 폴리글롯) = $env:RST_SELF  ← 헤더가 심어준다
            #   · 2파일(powershell -File) = $PSCommandPath
            #  v2.8은 $PSCommandPath 만 봤다 → 단일파일 모드에선 값이 비어 아무것도 안 지워졌고,
            #  2파일 모드에서도 Run-Toolkit.bat 은 그대로 남았다.
            # 부모 프로세스를 한 번만 조회해 둔다. 아래 두 곳에서 쓴다.
            #  · 런처 판별 : 부모가 cmd 여야 Run-Toolkit.bat 이 우리를 띄운 것이다.
            #                (PowerShell 창에서 .ps1 을 직접 돌렸으면 그건 남의 파일이다)
            #  · 삭제 시점 : 그 cmd 가 끝난 뒤에 지워야 런처의 pause 가 안 날아간다.
            $parentPid = 0; $parentName = ''
            try {
                $parentPid  = [int](Get-CimInstance Win32_Process -Filter "ProcessId=$PID" -ErrorAction Stop).ParentProcessId
                $parentName = (Get-Process -Id $parentPid -ErrorAction Stop).ProcessName
            } catch {}

            # 단일파일 모드인지 여기서 확정해 둔다. 아래에서 $env:RST_SELF 를 덮어쓰기 때문에
            #  나중에 다시 보면 2파일 모드도 단일파일로 보인다(v3.3 이 그랬다 - 마지막 Read-Host 가
            #  두 모드에서 다 떠서 런처 pause 와 겹쳤다).
            $singleFile = [bool]$env:RST_SELF
            $selfFile   = if ($env:RST_SELF) { $env:RST_SELF } else { $PSCommandPath }

            # 2파일 배포(.bat + .ps1)에서는 런처 .bat 도 같이 지운다.
            #  v3.4: 대상을 '우리를 실행한 Run-Toolkit.bat' 하나로 좁혔다. v3.3 은 같은 폴더의
            #   원격지원.bat(단일파일 배포본)까지 지워서 빌드 산출물이 날아갔다.
            $launcher = $null
            if (-not $singleFile -and $PSCommandPath -and $parentName -eq 'cmd') {
                $lp = Join-Path (Split-Path -Parent $PSCommandPath) 'Run-Toolkit.bat'
                if (Test-Path -LiteralPath $lp) { $launcher = $lp }
            }
            if ((Read-Host "`n스크립트+세션로그를 이 PC에서 삭제하고 종료? (y/n)") -eq 'y') {
                if ($script:TranscriptPath) { Remove-Item $script:TranscriptPath -Force -ErrorAction SilentlyContinue }
                if ($selfFile -and (Test-Path -LiteralPath $selfFile)) {
                    # 실행 중인 자기 자신은 직접 못 지운다(.bat 은 cmd 가 붙잡고 있다).
                    # → 지우는 프로세스를 떼어놓고 나간다.
                    # 경로를 문자열로 끼워넣지 않고 환경변수로 넘긴다. 선생님 PC 경로엔
                    # 한글·공백·대괄호가 흔한데, 따옴표로 감싸는 방식은 그때마다 깨진다.
                    # v3.4: '몇 초 뒤'가 아니라 '부모 cmd 가 끝난 뒤'에 지운다. 시간으로 재면
                    #  cmd 가 살아 있는 동안 파일이 사라져서, 그 뒤 줄을 못 읽고 죽는다.
                    #  (삭제 시점이 마지막 줄이어도 EOF 에서 "배치 파일을 찾을 수 없습니다"가 뜬다 - 실측)
                    $env:RST_SELF    = $selfFile
                    $env:RST_SELF2   = $launcher                                        # 2파일 모드가 아니면 빈 값
                    $env:RST_WAITPID = $(if ($parentPid -gt 0) { $parentPid } else { '' })
                    Start-Process powershell.exe -WindowStyle Hidden -ArgumentList @(
                        '-NoProfile','-Command',
                        'if($env:RST_WAITPID){ Wait-Process -Id ([int]$env:RST_WAITPID) -Timeout 600 -ErrorAction SilentlyContinue }; Start-Sleep 2; Remove-Item -LiteralPath $env:RST_SELF -Force -ErrorAction SilentlyContinue; if($env:RST_SELF2){ Remove-Item -LiteralPath $env:RST_SELF2 -Force -ErrorAction SilentlyContinue }')
                    Write-Host ("삭제 예약(이 창이 닫히면): {0}" -f $selfFile) -ForegroundColor Green
                    if ($launcher) { Write-Host ("삭제 예약(이 창이 닫히면): {0}" -f $launcher) -ForegroundColor Green }
                }
                Write-Host "종료합니다." -ForegroundColor Green
            } else {
                Write-Host ("파일 유지한 채 종료합니다: {0}" -f $selfFile) -ForegroundColor DarkGray
            }
            # 단일파일 모드는 여기서 창이 바로 닫힌다(.bat 의 pause 가 없음)
            # → 위 처리내역 요약을 읽을 시간을 준다.
            if ($singleFile) { Read-Host "`nEnter 를 누르면 창이 닫힙니다" | Out-Null }
            break main   # ★ v2.4 수정: switch 안 break는 루프 탈출이 안 됨(v2.3 버그)
        }
        default { Write-Host "잘못된 입력`n" -ForegroundColor DarkYellow }
    }
}
